-- MOTOR GLOBAL DE SCROLL CINÉTICO (DRAG TO SCROLL & WHEEL)
-- ==========================================
GUI = GUI or {} -- Pré-declaração global para silenciar o aviso Luau(1001)

task.spawn(function()
    -- Aguarda silenciosamente a interface existir antes de injetar a física
    while not GUI.ScreenGui do task.wait(0.5) end

    local uis = game:GetService("UserInputService")
    local ts = game:GetService("TweenService")
    
    local activeScrollFrame = nil
    local dragStartY = 0
    local canvasStartY = 0

    local function ApplyKineticScroll(frame)
        if frame:IsA("ScrollingFrame") then
            -- Força o motor do Roblox a calcular a rolagem sem bugar e habilita o scroll do mouse nativo
            frame.AutomaticCanvasSize = Enum.AutomaticSize.Y
            frame.CanvasSize = UDim2.new(0, 0, 0, 0)
            frame.ScrollingDirection = Enum.ScrollingDirection.Y

            -- Gatilho de início do arraste no painel específico
            frame.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    activeScrollFrame = frame
                    dragStartY = input.Position.Y
                    canvasStartY = frame.CanvasPosition.Y
                end
            end)
        end
    end

    -- [ O SEGREDO DO ZERO LAG ]: Em vez de multiplicar eventos, usamos 1 Conexão Global
    uis.InputChanged:Connect(function(input)
        if activeScrollFrame and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local deltaY = dragStartY - input.Position.Y
            pcall(function()
                -- Interpolação suave para não agarrar a tela igual os UIs amadores
                ts:Create(activeScrollFrame, TweenInfo.new(0.12, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
                    CanvasPosition = Vector2.new(0, canvasStartY + deltaY)
                }):Play()
            end)
        end
    end)

    -- Soltou o dedo/mouse = zera a trava
    uis.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            activeScrollFrame = nil
        end
    end)

    -- Aplica a física em todas as abas e menus (TabMenu) que já existem
    for _, v in ipairs(GUI.ScreenGui:GetDescendants()) do
        pcall(function() ApplyKineticScroll(v) end)
    end

    -- Escuta ativamente: se uma nova aba, lista ou Dropdown for gerado, aplica a correção nela instantaneamente
    GUI.ScreenGui.DescendantAdded:Connect(function(descendant)
        pcall(function() ApplyKineticScroll(descendant) end)
    end)
end)

-- ==========================================
-- SISTEMA DE ARRASTE TÁTIL UNIVERSAL (SMOOTH DRAG 2.0 PRO)
-- ==========================================
task.spawn(function()
    while not GUI or not GUI.MainFrame do task.wait(0.5) end

    GUI.MainFrame.Draggable = false 
    GUI.MainFrame.Active = true

    local dragToggle = false
    local dragStartPos = nil
    local frameStartPos = nil
    local targetPos = GUI.MainFrame.Position
    local dragSpeed = 0.25 -- Suavidade do arraste (Lerp)

    GUI.MainFrame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragToggle = true
            dragStartPos = input.Position
            frameStartPos = GUI.MainFrame.Position
            targetPos = frameStartPos
        end
    end)

    game:GetService("UserInputService").InputChanged:Connect(function(input)
        if dragToggle and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStartPos
            -- Apenas define o ALVO matemático. Quem move a interface é o RenderStepped abaixo.
            targetPos = UDim2.new(
                frameStartPos.X.Scale, frameStartPos.X.Offset + delta.X, 
                frameStartPos.Y.Scale, frameStartPos.Y.Offset + delta.Y
            )
        end
    end)

    game:GetService("UserInputService").InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if dragToggle then
                dragToggle = false
                _G.S7xPanelTargetPos = targetPos
            end
        end
    end)

    -- O SEGREDO DO ZERO LAG: Movimento interpolado cravado na taxa de atualização da tela
    game:GetService("RunService").RenderStepped:Connect(function()
        if dragToggle then
            GUI.MainFrame.Position = GUI.MainFrame.Position:Lerp(targetPos, dragSpeed)
        end
    end)
end)

