            pcall(function()
                local deltaY = input.Position.Y - scaleStartPos
                -- Calcula a nova escala (mínimo de 40% e máximo de 150% do tamanho original)
                local newScale = math.clamp(initialScale + (deltaY / 300), 0.40, 1.5)
                S7xScale.Scale = newScale
            end)
        end
    end)
end)
