task.spawn(function()
    local RunService = game:GetService("RunService")
    local Workspace = game:GetService("Workspace")
    local Network = settings():GetService("Network")

    -- 1. OTIMIZAÇÃO DE REDE E INTERPOLAÇÃO
    pcall(function() Network.IncomingReplicationLag = 0 end)
    pcall(function() Workspace.InterpolationThrottling = Enum.InterpolationThrottlingMode.Enabled end)
    pcall(function() Workspace.ClientAnimatorThrottling = Enum.ClientAnimatorThrottlingMode.Enabled end)

    -- 2. LIMPEZA PROFUNDA FRACIONADA (ZERO LAG SPIKES)
    while task.wait(15) do
        pcall(function()
            local fallenLimit = Workspace.FallenPartsDestroyHeight + 50
            local partsProcessed = 0
            
            for _, v in ipairs(Workspace:GetChildren()) do
                if v:IsA("BasePart") and not v.Anchored and v.Position.Y < fallenLimit then
                    if not game:GetService("Players"):GetPlayerFromCharacter(v.Parent) then
                        v:Destroy()
                    end
                end
                
                partsProcessed = partsProcessed + 1
                -- O SEGREDO: A cada 50 peças lidas, o script pausa por 1 frame.
                -- Isso impede que o jogo congele se o mapa tiver 10.000 peças jogadas no void.
                if partsProcessed % 50 == 0 then
                    RunService.Heartbeat:Wait()
                end
            end
        end)
    end
end)

