local SUPABASE_URL = "https://huznxdkewouklwkjcttl.supabase.co/rest/v1"
local SUPABASE_KEY = "sb_publishable_WbP0_QlqU1OBOmM0-BTlgA_oIlxMftX"
local SupabaseCache = {}
local LastTagsData = ""
local LastAurasData = ""

-- Filtro limpador de lixo JSON (Remove aspas duplas e simples que quebram as cores)
local function CleanVal(v)
    if type(v) == "string" then return string.gsub(v, '["\']', "") end
    return v
end

-- Interpretador Global de Cores Seguro
_G.S7xParseColor = function(c, defaultColor)
    if typeof(c) == "Color3" then return c end
    if type(c) == "string" then
        c = string.gsub(c, '["\' %[%]{}]', "") 
        local s, res = pcall(function() return Color3.fromHex(c) end)
        if s and res then return res end
        
        local hex = string.match(c, "%x%x%x%x%x%x")
        if hex then
            local r = tonumber(string.sub(hex, 1, 2), 16)
            local g = tonumber(string.sub(hex, 3, 4), 16)
            local b = tonumber(string.sub(hex, 5, 6), 16)
            if r and g and b then return Color3.fromRGB(r, g, b) end
        end
    end
    return defaultColor or Color3.fromRGB(255, 255, 255)
end

-- Motor HTTP Blindado V3 (ANTI-CACHE GLOBAL EXTREMO COM FIX DE TIPAGEM)
_G.S7xLocalLock = _G.S7xLocalLock or 0

_G.SupabaseReq = function(endpoint, method, body)
    local cacheBuster = ""
    if method == "GET" then
        local sep = string.find(endpoint, "?") and "&" or "?"
        
        -- FIX PROFISSIONAL: Se for a tabela de chaves, usa a coluna 'code' (texto) para o cache.
        -- Se for as outras tabelas, usa a coluna 'id'. Isso evita o erro Type Mismatch (int8 vs text) do PostgreSQL!
        if string.find(endpoint, "s7x_keys") then
            cacheBuster = sep .. "code=neq.S7xCacheBuster_" .. tostring(math.floor(tick() * 1000)) .. tostring(math.random(100, 999))
        else
            cacheBuster = sep .. "id=neq.S7xCacheBuster_" .. tostring(math.floor(tick() * 1000)) .. tostring(math.random(100, 999))
        end
    end

    local options = {
        Url = SUPABASE_URL .. endpoint .. cacheBuster,
        Method = method or "GET",
        Headers = {
            ["apikey"] = SUPABASE_KEY,
            ["Authorization"] = "Bearer " .. SUPABASE_KEY,
            ["Content-Type"] = "application/json",
            ["Prefer"] = (method == "POST" or method == "PATCH") and "resolution=merge-duplicates" or "return=representation",
            ["Cache-Control"] = "no-cache, no-store, must-revalidate",
            ["Pragma"] = "no-cache"
        }
    }
    if body then options.Body = game:GetService("HttpService"):JSONEncode(body) end
    
    local reqFunc = (syn and syn.request) or http_request or request or (fluxus and fluxus.request)
    if not reqFunc then return nil end
    local success, result = pcall(function() return reqFunc(options) end)
    return success and result or nil
end

-- ==========================================
-- OTIMIZADOR DE NUVEM (AUTO-SYNC PROMOTION & DEMOTION)
-- ==========================================
UpdateSupabase = function()
    local HttpService = game:GetService("HttpService")
    local myUid = tostring(game.Players.LocalPlayer.UserId)
    local isLocalLocked = tick() < _G.S7xLocalLock

    pcall(function()
        local res = _G.SupabaseReq("/users?select=id,role", "GET")
        if res and res.Body then
            local decoded = HttpService:JSONDecode(res.Body)
            if type(decoded) == "table" and not decoded.error then
                local newCache = {}
                for _, row in ipairs(decoded) do 
                    local r = CleanVal(row.role)
                    
                    -- Normaliza os nomes de cargos para evitar duplicação no painel
                    if r == "Developers" or r == "Dev" then r = "Developer" end
                    if r == "Creator" then r = "Owner" end
                    if r == "Members" then r = "Member" end
                    
                    newCache[tostring(row.id)] = r 
                    
                    -- [ MOTOR DE IDENTIFICAÇÃO DE REBAIXAMENTO E PROMOÇÃO ]
                    if tostring(row.id) == myUid then
                        if _G.S7xLastKnownRank ~= nil and _G.S7xLastKnownRank ~= r then
                            -- Detecta se o cargo do jogador mudou no banco de dados
                            _G.S7xLastKnownRank = r
                            
                            -- Se o painel já estiver carregado, força a recriação da UI e equipa a nova Tag
                            if _G.S7xIsFullyLoaded and type(_G.S7xRefreshMyTagsUI) == "function" then
                                _G.S7xRefreshMyTagsUI() 
                                if type(S7xNotify) == "function" then 
                                    S7xNotify("NETWORK SYNC", "Hierarquia atualizada para: " .. string.upper(r)) 
                                end
                            end
                        elseif _G.S7xLastKnownRank == nil then
                            _G.S7xLastKnownRank = r -- Salva a leitura primária
                        end
                    end
                end
                SupabaseCache = newCache
            end
        end
    end)
    
    pcall(function()
        local res = _G.SupabaseReq("/tags?select=id,payload", "GET")
        if res and res.Body then
            local decoded = HttpService:JSONDecode(res.Body)
            if type(decoded) == "table" and not decoded.error then
                local parsedConfig = _G.CustomTagsConfig or {}
                for _, row in ipairs(decoded) do
                    local rowUid = tostring(row.id)
                    local payload = row.payload
                    if type(payload) == "string" then pcall(function() payload = HttpService:JSONDecode(payload) end) end
                    
                    if type(payload) == "table" then
                        if rowUid == myUid and isLocalLocked and parsedConfig[myUid] then
                            -- Preserva salvamento local temporário (Anti-Conflito)
                        else
                            parsedConfig[rowUid] = {
                                CustomName = CleanVal(payload.CustomName), Effect = CleanVal(payload.Effect),
                                Color1 = CleanVal(payload.Color1 or payload.Color), 
                                Color2 = CleanVal(payload.Color2),
                                Color3 = CleanVal(payload.Color3),
                                Color4 = CleanVal(payload.Color4),
                                Color5 = CleanVal(payload.Color5),
                                StrokeColor = CleanVal(payload.StrokeColor), 
                                StrokeTransparency = tonumber(payload.StrokeTransparency),
                                BgColor = CleanVal(payload.BgColor),               
                                BgTransparency = tonumber(payload.BgTransparency), 
                                BorderEnabled = payload.BorderEnabled,             
                                LineRemoved = payload.LineRemoved,                 -- [FIX PROFISSIONAL: MEMÓRIA DA LINHA]
                                TextSize = tonumber(payload.TextSize),             
                                Font = CleanVal(payload.Font) or "GothamBlack",
                                IsActive = payload.IsActive, Equipped = CleanVal(payload.Equipped), Unlocked = payload.Unlocked
                            }
                        end
                    end
                end
                _G.CustomTagsConfig = parsedConfig
            end
        end
    end)
end

UpdateSupabase()

GetFirebaseRank = function(targetPlayer)
    if not targetPlayer then return nil end
    return SupabaseCache[tostring(targetPlayer.UserId)]
end

