_G.LastPresenceSync = 0
_G.LastTagSent = ""
_G.LastAuraSent = ""

SendPresence = function(forceUpdate)
    if not _G.MyTagPublic then return end
    
    local fRank = (type(GetFirebaseRank) == "function" and GetFirebaseRank(game.Players.LocalPlayer)) or "User"
    local myCurrentTag = _G.EquippedTag or fRank
    local myCurrentAura = _G.EquippedAura or "None"
    
    -- BLOQUEIO DE SPAM: Evita POSTs desnecessários no Supabase
    local timeSinceLastSync = os.time() - _G.LastPresenceSync
    if not forceUpdate and timeSinceLastSync < 60 and _G.LastTagSent == myCurrentTag and _G.LastAuraSent == myCurrentAura then
        return -- Nada mudou e ainda não deu o tempo limite, economiza a cota.
    end

    _G.LastPresenceSync = os.time()
    _G.LastTagSent = myCurrentTag
    _G.LastAuraSent = myCurrentAura

    task.spawn(function()
        pcall(function()
           local payloadData = {
                j = tostring(game.JobId), 
                t = os.time(),
                tg = myCurrentTag, 
                a = myCurrentAura
            }
            
           _G.SupabaseReq("/presence?on_conflict=id", "POST", { id = tostring(game.Players.LocalPlayer.UserId), payload = payloadData })
        end)
    end)
end

-- Ajuste também o Gatilho Instantâneo para forçar o envio
_G.BroadcastInstantUpdate = function()
    _G.S7xLocalLock = tick() + 3 
    if type(SendPresence) == "function" then SendPresence(true) end -- Envio Forçado
    task.delay(0.4, function()
        if type(SendP2PPing) == "function" then SendP2PPing() end
    end)
end

-- ==========================================
-- 🧹 1. REMOÇÃO DE SAÍDA NATIVA (CLIENT-SIDE)
-- ==========================================
RemovePresence = function()
    if not _G.SupabaseReq then return end
    -- Usamos task.spawn para rodar em paralelo sem travar o fechamento do jogo
    task.spawn(function()
        pcall(function()
            local myIdStr = tostring(game.Players.LocalPlayer.UserId)
            -- Deleta Presença e Comandos Pendentes de uma vez
            _G.SupabaseReq("/presence?id=eq." .. myIdStr, "DELETE")
            _G.SupabaseReq("/live_commands?id=eq." .. myIdStr, "DELETE")
            _G.SupabaseReq("/auras?id=eq." .. myIdStr, "DELETE")
        end)
    end)
end

-- Tenta garantir a exclusão em todos os cenários possíveis de saída:
game:GetService("Players").LocalPlayer.OnTeleport:Connect(RemovePresence)
game:GetService("Players").PlayerRemoving:Connect(function(plr)
    if plr == game.Players.LocalPlayer then RemovePresence() end
end)
pcall(function() game.Close:Connect(RemovePresence) end)

-- ==========================================
-- ☢️ 2. GARBAGE COLLECTOR & LEITURA (ZELADOR COLABORATIVO)
-- ==========================================
_G.LastServerSync = 0

SyncServerPresence = function(forceSync)
    if not _G.S7xTagVisible then return end
    
    -- Debounce (Anti-Network Storm)
    if not forceSync and (tick() - _G.LastServerSync) < 10 then return end
    _G.LastServerSync = tick()

    task.spawn(function()
        pcall(function()
            local res = _G.SupabaseReq("/presence?select=id,payload", "GET")
            if res and res.Body then
                local decoded = game:GetService("HttpService"):JSONDecode(res.Body)
                if type(decoded) == "table" and not decoded.error then
                    local currentTime = os.time()
                    
                    for _, row in ipairs(decoded) do
                        local payload = row.payload
                        if type(payload) == "string" then pcall(function() payload = game:GetService("HttpService"):JSONDecode(payload) end) end
                        
                        if type(payload) == "table" then
                            local uid = tonumber(row.id)
                            local lastSeen = payload.Time or 0
                            local timeDiff = currentTime - lastSeen
                            
                            -- [ GARBAGE COLLECTOR ENTRY ]
                            -- Se o sinal do jogador tiver mais de 5 minutos (300 segundos), ele é um FANTASMA!
                            if timeDiff > 300 then
                                -- Apenas o jogador mais antigo da sala apaga para evitar que 30 caras enviem o DELETE juntos
                                if game.Players.LocalPlayer.UserId % 3 == 0 or timeDiff > 400 then
                                    _G.SupabaseReq("/presence?id=eq." .. tostring(uid), "DELETE")
                                end
                                continue -- Pula para o próximo, não renderiza esse fantasma
                            end

                            -- [ LÓGICA NORMAL DE RENDERIZAÇÃO ]
                            -- Filtra apenas quem está no SEU Servidor atual (JobId)
                            if payload.job_id == tostring(game.JobId) then
                                if uid and uid ~= game.Players.LocalPlayer.UserId and timeDiff <= 90 then
                                    local targetPlr = game:GetService("Players"):GetPlayerByUserId(uid)
                                    if targetPlr then
                                        _G.PresenceTags[uid] = payload.Tag 
                                        _G.PresenceAuras[uid] = payload.Aura 
                                        _G.S7xUsers[uid] = true 

                                        task.spawn(function()
                                            if ApplyOrUpdateTag then ApplyOrUpdateTag(targetPlr) end
                                            if ApplyS7xAura then ApplyS7xAura(targetPlr) end
                                        end)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)
    end)
end

ApplyOrUpdateTag = function(targetPlayer)
    if not targetPlayer then return end
    local char_tgt = targetPlayer.Character
    if not char_tgt or not char_tgt.Parent or (char_tgt:FindFirstChild("Humanoid") and char_tgt.Humanoid.Health <= 0) then return end
    
    local head_tgt = char_tgt:FindFirstChild("Head") or char_tgt:FindFirstChild("HumanoidRootPart")
    if not head_tgt then return end

    -- [ PROTEÇÃO ANTI-GLITCH: HIDE TAGS ]
    if targetPlayer == game.Players.LocalPlayer and _G.MyTagPublic == false then
        local existing = head_tgt:FindFirstChild("S7x_ProTag")
        if existing then existing:Destroy() end
        return
    end

    local fRank = (type(GetFirebaseRank) == "function" and GetFirebaseRank(targetPlayer)) or "User"
    if fRank == "Creator" then fRank = "Owner" end
    if fRank == "Developers" or fRank == "Dev" then fRank = "Developer" end

    local rankName_tgt = fRank
    local userCustomData_tgt = _G.CustomTagsConfig and _G.CustomTagsConfig[tostring(targetPlayer.UserId)]
    
    if targetPlayer == game.Players.LocalPlayer then
        rankName_tgt = _G.EquippedTag or fRank
    else
        local isActiveUser = (_G.S7xUsers and _G.S7xUsers[targetPlayer.UserId]) or (_G.PresenceTags and _G.PresenceTags[targetPlayer.UserId])
        if not isActiveUser then
            local existing = head_tgt:FindFirstChild("S7x_ProTag")
            if existing then existing:Destroy() end
            return 
        end
        
        local presenceTag = _G.PresenceTags and _G.PresenceTags[targetPlayer.UserId]
        if presenceTag and presenceTag ~= "User" then
            rankName_tgt = presenceTag
        else
            rankName_tgt = fRank 
        end
    end

    if rankName_tgt == "None" then
        local existing = head_tgt:FindFirstChild("S7x_ProTag")
        if existing then existing:Destroy() end
        return
    end

    local displayName_tgt = rankName_tgt
    local desiredFontName = "GothamBlack" 

    if rankName_tgt == "Custom" then
        if userCustomData_tgt then
            if userCustomData_tgt.CustomName and userCustomData_tgt.CustomName ~= "" then 
                displayName_tgt = userCustomData_tgt.CustomName 
            end
            if userCustomData_tgt.Font then desiredFontName = userCustomData_tgt.Font end
        else
            displayName_tgt = "Custom"
        end
    else
        local configForName_tgt = _G.CustomTagsConfig and _G.CustomTagsConfig[rankName_tgt]
        if configForName_tgt then
            if configForName_tgt.CustomName and configForName_tgt.CustomName ~= "" then
                displayName_tgt = configForName_tgt.CustomName 
            end
            if configForName_tgt.Font then desiredFontName = configForName_tgt.Font end
        end
    end

    local successFont, desiredFontEnum = pcall(function() return Enum.Font[desiredFontName] end)
    if not successFont or not desiredFontEnum then desiredFontEnum = Enum.Font.GothamBlack end

    -- [ 1. CAPTURA DE DADOS E VARIÁVEIS ISOLADAS ]
    local conf = (rankName_tgt == "Custom" and userCustomData_tgt) or (_G.CustomTagsConfig and _G.CustomTagsConfig[rankName_tgt]) or {}
    local cBgColor = _G.S7xParseColor(conf.BgColor, Color3.fromRGB(12, 12, 15))
    local cBgTransp = conf.BgTransparency ~= nil and tonumber(conf.BgTransparency) or 0.25

    local rawBorder = conf.BorderEnabled
    if rawBorder == nil and conf.BorderRemoved ~= nil then rawBorder = not conf.BorderRemoved end
    if type(rawBorder) == "string" then rawBorder = (rawBorder == "true") end
    local cBorder = rawBorder ~= nil and rawBorder or true

    -- VARIÁVEL INDEPENDENTE PARA A LINHA (STROKE)
    local rawLine = conf.LineRemoved
    if type(rawLine) == "string" then rawLine = (rawLine == "true") end
    local cLineEnabled = rawLine == nil and true or not rawLine

    -- LIMITE AUMENTADO PARA 30
    local cTextSize = tonumber(conf.TextSize) or ((rankName_tgt == "Developer" or rankName_tgt == "Supreme") and 13 or 15)
    if cTextSize > 35 then cTextSize = 35 end

    local needsRebuild = true
    local existingTag = head_tgt:FindFirstChild("S7x_ProTag")
    
    -- [ 2. MOTOR DE ATUALIZAÇÃO EM TEMPO REAL ]
    if existingTag then
        local lbl = existingTag:FindFirstChild("Label", true)
        if lbl and lbl.Text == displayName_tgt and lbl.Font == desiredFontEnum and SpecialTags[targetPlayer.UserId] and SpecialTags[targetPlayer.UserId].Rank == rankName_tgt then
            needsRebuild = false
            
            local bgFrame = existingTag:FindFirstChild("TagBackground")
            if bgFrame then
                bgFrame.BackgroundColor3 = cBgColor
                bgFrame.BackgroundTransparency = cBgTransp
                
                local bgStroke = bgFrame:FindFirstChild("TagStroke")
                if bgStroke then
                    bgStroke.Enabled = cLineEnabled -- APENAS A LINHA
                    bgStroke.Transparency = cLineEnabled and 0.1 or 1
                end
            end -- <- ESTE É O END QUE FOI APAGADO POR ACIDENTE
            
            if rankName_tgt == "Custom" and conf.TextSize ~= nil then
                lbl.TextScaled = false
                lbl.TextSize = cTextSize
            else
                lbl.TextScaled = true
            end
        end
    end

    -- [ 3. CONSTRUÇÃO INICIAL DA TAG ]
    if needsRebuild then
        for _, v in ipairs(head_tgt:GetChildren()) do
            if v.Name == "S7x_ProTag" then v:Destroy() end
        end

        local newTag = Instance.new("BillboardGui")
        newTag.Name = "S7x_ProTag"
        newTag.Adornee = head_tgt
        newTag.Size = UDim2.new(3.8, 0, 0.9, 0) 
        newTag.StudsOffset = Vector3.new(0, 3.8, 0) 
        newTag.AlwaysOnTop = false 
        newTag.MaxDistance = 100 
        newTag.Enabled = _G.S7xTagVisible
        newTag.LightInfluence = 0
        newTag.Parent = head_tgt

        local bgFrame = Instance.new("Frame", newTag)
        bgFrame.Name = "TagBackground"
        bgFrame.Size = UDim2.new(1, 0, 0.85, 0)
        bgFrame.Position = UDim2.new(0, 0, 0.075, 0)
        bgFrame.BackgroundColor3 = cBgColor
        bgFrame.BackgroundTransparency = cBgTransp 
        bgFrame.BorderSizePixel = 0
        Instance.new("UICorner", bgFrame).CornerRadius = UDim.new(1, 0)

        local bgStroke = Instance.new("UIStroke", bgFrame)
        bgStroke.Name = "TagStroke"
        bgStroke.Color = Color3.fromRGB(255, 255, 255)
        bgStroke.Thickness = 1.5
        bgStroke.Transparency = cLineEnabled and 0.1 or 1
        bgStroke.Enabled = cLineEnabled -- APENAS A LINHA
        
        local strokeGrad = Instance.new("UIGradient", bgStroke)
        strokeGrad.Name = "StrokeGradient"
        strokeGrad.Rotation = 45

        local textLabel_tgt = Instance.new("TextLabel", bgFrame)
        textLabel_tgt.Name = "Label"
        textLabel_tgt.Size = UDim2.new(1, -16, 1, 0)
        textLabel_tgt.Position = UDim2.new(0, 8, 0, 0)
        textLabel_tgt.BackgroundTransparency = 1
        textLabel_tgt.Font = desiredFontEnum
        
        if rankName_tgt == "Custom" and conf.TextSize ~= nil then
            textLabel_tgt.TextScaled = false
            textLabel_tgt.TextSize = cTextSize
        else
            textLabel_tgt.TextScaled = true
            local textConstraint_tgt = Instance.new("UITextSizeConstraint", textLabel_tgt)
            textConstraint_tgt.MaxTextSize = cTextSize
        end
        
        textLabel_tgt.TextStrokeTransparency = 0.6 
        textLabel_tgt.Text = displayName_tgt
        textLabel_tgt.AutoLocalize = false
        textLabel_tgt.ZIndex = 2
        
        local grad_tgt = Instance.new("UIGradient", textLabel_tgt)
        grad_tgt.Name = "ShineGradient"
        grad_tgt.Rotation = 45 

        local syncConn
        syncConn = game:GetService("RunService").RenderStepped:Connect(function()
            if not newTag or not newTag.Parent or not grad_tgt or not strokeGrad then
                if syncConn then syncConn:Disconnect() end
                return
            end
            strokeGrad.Color = grad_tgt.Color
            strokeGrad.Offset = grad_tgt.Offset
            bgStroke.Color = textLabel_tgt.TextColor3
        end)
        
        game:GetService("TweenService"):Create(newTag, TweenInfo.new(1.2, Enum.EasingStyle.Elastic, Enum.EasingDirection.Out), {StudsOffset = Vector3.new(0, 3.2, 0)}):Play()
        
        if SpecialTags[targetPlayer.UserId] and SpecialTags[targetPlayer.UserId].Label and SpecialTags[targetPlayer.UserId].Label.Parent then
            pcall(function()
                local oldBase = SpecialTags[targetPlayer.UserId].Label:FindFirstAncestor("S7x_ProTag")
                if oldBase then oldBase:Destroy() else SpecialTags[targetPlayer.UserId].Label.Parent:Destroy() end
            end)
        end
        
        SpecialTags[targetPlayer.UserId] = {Label = textLabel_tgt, Rank = rankName_tgt, Head = head_tgt}
     end -- <- ESTE END FECHA O "if needsRebuild then"
 end --
-----------------------------------------
--- SISTEMA DE ADMINISTRAÇÃO REMOTA V13 (ANTI-FALHAS)
-----------------------------------------
_G.S7xAdminFrozen = _G.S7xAdminFrozen or false
_G.lastMsgTime = _G.lastMsgTime or 0
_G.lastFreezeTime = _G.lastFreezeTime or 0

-- [ 1. DISPLAY DA MENSAGEM ]
_G.S7xShowAdminMessage = function(texto)
    pcall(function()
        local CoreGui = game:GetService("CoreGui")
        local sfx = Instance.new("Sound", CoreGui)
        sfx.SoundId = "rbxassetid://6063717277"; sfx.Volume = 3; sfx:Play()
        game:GetService("Debris"):AddItem(sfx, 5)

        local targetParent = CoreGui:FindFirstChild("S7xhub_Panel") or CoreGui
        local bg = Instance.new("Frame", targetParent)
        bg.Size = UDim2.new(1, 0, 0, 150)
        bg.Position = UDim2.new(0, 0, 0, -150)
        bg.BackgroundColor3 = Color3.fromRGB(15, 0, 0)
        bg.BackgroundTransparency = 0.1
        bg.BorderSizePixel = 0
        
        local stroke = Instance.new("UIStroke", bg)
        stroke.Color = Color3.fromRGB(255, 0, 0); stroke.Thickness = 3

        local title = Instance.new("TextLabel", bg)
        title.Size = UDim2.new(1, 0, 0, 40)
        title.Position = UDim2.new(0, 0, 0, 10)
        title.BackgroundTransparency = 1
        title.Text = "⚠️ SYSTEM DIRECT DIRECTIVE ⚠️"
        title.TextColor3 = Color3.fromRGB(255, 50, 50)
        title.Font = Enum.Font.GothamBlack; title.TextSize = 22

        local msg = Instance.new("TextLabel", bg)
        msg.Size = UDim2.new(0.8, 0, 0, 80)
        msg.Position = UDim2.new(0.1, 0, 0, 50)
        msg.BackgroundTransparency = 1
        msg.Text = tostring(texto)
        msg.TextColor3 = Color3.fromRGB(255, 255, 255)
        msg.Font = Enum.Font.GothamBold; msg.TextSize = 16; msg.TextWrapped = true

        game:GetService("TweenService"):Create(bg, TweenInfo.new(0.5, Enum.EasingStyle.Bounce), {Position = UDim2.new(0, 0, 0, 50)}):Play()
        task.delay(10, function()
            local t = game:GetService("TweenService"):Create(bg, TweenInfo.new(0.5, Enum.EasingStyle.Sine), {Position = UDim2.new(0, 0, 0, -150)})
            t:Play(); t.Completed:Wait(); if bg then bg:Destroy() end
        end)
    end)
end

-- [ LOOP IMORTAL DE COMANDOS - BLINDADO COM HIERARQUIA ]
if _G.LiveCommandLoop then task.cancel(_G.LiveCommandLoop) end
_G.LiveCommandLoop = task.spawn(function()
    local HttpService = game:GetService("HttpService")
    local myUid = tostring(game.Players.LocalPlayer.UserId)

    pcall(function()
        local res = _G.SupabaseReq("/live_commands?id=eq." .. myUid .. "&select=payload", "GET")
        if res and res.Body then
            local decoded = HttpService:JSONDecode(res.Body)
            if type(decoded) == "table" then
                if #decoded == 0 then
                    local initPayload = { sender_id = "", message_text = "", freeze = false, kill = false, kick = false, kick_reason = "", lock_screen = false, play_audio = "", pull_to = "" }
                    _G.SupabaseReq("/live_commands", "POST", { id = myUid, payload = initPayload })
                elseif decoded[1] and decoded[1].payload then
                    local payload = decoded[1].payload
                    if type(payload) == "string" then pcall(function() payload = HttpService:JSONDecode(payload) end) end
                    if type(payload) == "table" and (payload.message_text ~= "" or payload.kill == true or payload.kick == true or payload.play_audio ~= "" or payload.pull_to ~= "") then
                        payload.message_text = ""; payload.kill = false; payload.kick = false; payload.play_audio = ""; payload.pull_to = ""
                        _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = payload })
                    end
                end
            end
        end
    end)

    task.wait(1)

    while task.wait(3) do 
        pcall(function()
            local res = _G.SupabaseReq("/live_commands?id=eq." .. myUid .. "&select=payload", "GET")
            if res and res.Body then
                local decoded = HttpService:JSONDecode(res.Body)
                if type(decoded) == "table" and #decoded > 0 and decoded[1].payload then
                    local payload = decoded[1].payload
                    if type(payload) == "string" then pcall(function() payload = HttpService:JSONDecode(payload) end) end
                    
                    if type(payload) == "table" then
                        -- [ MOTOR DE SEGURANÇA E HIERARQUIA ]
                        local senderId = payload.sender_id
                        if senderId and senderId ~= "" and senderId ~= myUid then
                            local senderRank = "User"
                            if type(SupabaseCache) == "table" and SupabaseCache[tostring(senderId)] then
                                senderRank = SupabaseCache[tostring(senderId)]
                            end
                            local myRank = "User"
                            if type(GetFirebaseRank) == "function" then myRank = GetFirebaseRank(game.Players.LocalPlayer) or "User" end
                            
                            local RoleWeights = { ["User"]=0, ["Member"]=5, ["Tester"]=10, ["Friends"]=15, ["Influencer"]=20, ["Ultimate"]=30, ["Supreme"]=40, ["Helper"]=50, ["Contributor"]=60, ["Marketing"]=65, ["Designer"]=70, ["Supervisor"]=80, ["Manager"]=90, ["Developer"]=95, ["Dev"]=95, ["Co-Owner"]=99, ["Owner"]=100, ["Creator"]=100 }
                            local myWeight = RoleWeights[myRank] or 0
                            local senderWeight = RoleWeights[senderRank] or 0
                            
                            -- Se o Sender tiver peso menor ou igual, IGNORA O COMANDO! (Owner é imune a Supervisor)
                            if senderWeight <= myWeight and myWeight >= 80 then
                                -- Ameaça neutralizada! Limpa o payload de ataque sem executar nada
                                local resetPayload = payload
                                resetPayload.sender_id = ""; resetPayload.message_text = ""; resetPayload.freeze = false; resetPayload.kill = false; resetPayload.kick = false; resetPayload.lock_screen = false; resetPayload.play_audio = ""; resetPayload.pull_to = ""
                                _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                                return -- Bloqueio Absoluto
                            end
                        end

                        -- 1. Mensagem na Tela
                        local newMsg = tostring(payload.message_text or "")
                        if newMsg ~= "" then
                            _G.S7xShowAdminMessage(newMsg)
                            task.spawn(function()
                                local resetPayload = payload; resetPayload.message_text = ""
                                _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                            end)
                        end
                        
                        -- 2. Congelamento
                        local isFreeze = payload.freeze
                        if type(isFreeze) == "string" then isFreeze = (isFreeze == "true") end
                        if isFreeze ~= nil then
                            if isFreeze == true and not _G.S7xAdminFrozen then
                                _G.S7xAdminFrozen = true
                                if type(S7xNotify) == "function" then S7xNotify("SYSTEM", "You have been frozen.") end
                            elseif isFreeze == false and _G.S7xAdminFrozen then
                                _G.S7xAdminFrozen = false
                                local char = game.Players.LocalPlayer.Character
                                if char and char:FindFirstChild("HumanoidRootPart") then char.HumanoidRootPart.Anchored = false end
                                if type(S7xNotify) == "function" then S7xNotify("SYSTEM", "You have been unfrozen.") end
                            end
                        end

                        -- 3. Lock Screen (TELA PRETA)
                        local isLock = payload.lock_screen
                        if type(isLock) == "string" then isLock = (isLock == "true") end
                        if isLock ~= nil then
                            local core = game:GetService("CoreGui")
                            local lockGui = core:FindFirstChild("S7xLockScreen")
                            
                            if isLock == true and not lockGui then
                                lockGui = Instance.new("ScreenGui", core)
                                lockGui.Name = "S7xLockScreen"
                                lockGui.DisplayOrder = 999999999
                                lockGui.IgnoreGuiInset = true
                                
                                local bg = Instance.new("Frame", lockGui)
                                bg.Size = UDim2.new(1, 0, 1, 0)
                                bg.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
                                
                                local txt = Instance.new("TextLabel", bg)
                                txt.Size = UDim2.new(1, 0, 1, 0)
                                txt.BackgroundTransparency = 1
                                txt.Text = "S7X ENGINE"
                                txt.TextColor3 = Color3.fromRGB(255, 255, 255)
                                txt.Font = Enum.Font.GothamBlack
                                txt.TextSize = 60
                                
                                pcall(function()
                                    local controls = require(game:GetService("Players").LocalPlayer.PlayerScripts.PlayerModule):GetControls()
                                    controls:Disable()
                                end)

                                -- [ MOTOR DE DESTRAVAMENTO: MORTE E RESPAWN ]
                                if _G.S7xLockDeathConn then _G.S7xLockDeathConn:Disconnect() end
                                local char = game.Players.LocalPlayer.Character
                                local hum = char and char:FindFirstChild("Humanoid")
                                if hum then
                                    _G.S7xLockDeathConn = hum.Died:Connect(function()
                                        if lockGui then lockGui:Destroy() end
                                        
                                        -- Devolve os controles ao jogador
                                        pcall(function()
                                            local controls = require(game:GetService("Players").LocalPlayer.PlayerScripts.PlayerModule):GetControls()
                                            controls:Enable()
                                        end)
                                        
                                        -- Libera no Banco de Dados para não voltar preta ao nascer
                                        task.spawn(function()
                                            local resetPayload = payload
                                            resetPayload.lock_screen = false
                                            _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                                        end)
                                        
                                        if _G.S7xLockDeathConn then _G.S7xLockDeathConn:Disconnect(); _G.S7xLockDeathConn = nil end
                                    end)
                                end
                                
                            elseif isLock == false and lockGui then
                                lockGui:Destroy()
                                pcall(function()
                                    local controls = require(game:GetService("Players").LocalPlayer.PlayerScripts.PlayerModule):GetControls()
                                    controls:Enable()
                                end)
                                if _G.S7xLockDeathConn then _G.S7xLockDeathConn:Disconnect(); _G.S7xLockDeathConn = nil end
                            end
                        end

                       -- 4. Play Audio (REPRODUÇÃO AVANÇADA - TOCA ATÉ O FIM E STOP)
                        local audioId = payload.play_audio or ""
                        if audioId ~= "" then
                            pcall(function()
                                local core = game:GetService("CoreGui")
                                -- Apaga músicas antigas (Se o comando for "STOP", isso vai apenas desligar o som atual)
                                for _, v in ipairs(core:GetChildren()) do
                                    if v.Name == "S7x_AdminAudio" then v:Destroy() end
                                end
                                
                                if audioId ~= "STOP" then
                                    local sfx = Instance.new("Sound", core)
                                    sfx.Name = "S7x_AdminAudio"
                                    sfx.SoundId = "rbxassetid://" .. audioId:match("%d+")
                                    sfx.Volume = 3
                                    sfx:Play()
                                    
                                    -- O segredo: Fica tocando até acabar
                                    sfx.Ended:Connect(function() sfx:Destroy() end)
                                    game:GetService("Debris"):AddItem(sfx, 600) -- Limite de segurança de 10 minutos
                                end
                                
                                task.spawn(function()
                                    local resetPayload = payload; resetPayload.play_audio = ""
                                    _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                                end)
                            end)
                        end

                        -- 5. Pull (PUXAR ATÉ O ADMIN)
                        local pullTo = payload.pull_to or ""
                        if pullTo ~= "" then
                            pcall(function()
                                local senderPlr = game:GetService("Players"):FindFirstChild(pullTo)
                                if senderPlr and senderPlr.Character and senderPlr.Character:FindFirstChild("HumanoidRootPart") then
                                    local myChar = game.Players.LocalPlayer.Character
                                    if myChar and myChar:FindFirstChild("HumanoidRootPart") then
                                        myChar.HumanoidRootPart.CFrame = senderPlr.Character.HumanoidRootPart.CFrame * CFrame.new(0, 0, -4)
                                    end
                                end
                                task.spawn(function()
                                    local resetPayload = payload; resetPayload.pull_to = ""
                                    _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                                end)
                            end)
                        end

                        -- 6. Kill (Morte Física)
                        local isKill = payload.kill
                        if type(isKill) == "string" then isKill = (isKill == "true") end
                        if isKill == true then
                            local char = game.Players.LocalPlayer.Character
                            local hum = char and char:FindFirstChild("Humanoid")
                            if hum and hum.Health > 0 then
                                hum.Health = 0
                                if type(S7xNotify) == "function" then S7xNotify("SYSTEM", "Terminated by Admin.") end
                                task.spawn(function()
                                    local resetPayload = payload; resetPayload.kill = false
                                    _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                                end)
                            end
                        end
                        
                        -- 7. KICK REAL
                        local isKick = payload.kick
                        if type(isKick) == "string" then isKick = (isKick == "true") end
                        if isKick == true then
                            local reason = payload.kick_reason or "Removed by S7x Security Network."
                            task.spawn(function()
                                local resetPayload = payload; resetPayload.kick = false; resetPayload.kick_reason = ""
                                _G.SupabaseReq("/live_commands?id=eq." .. myUid, "PATCH", { payload = resetPayload })
                            end)
                            game.Players.LocalPlayer:Kick("\n⚠️ S7X NETWORK BAN ⚠️\n\nYou have been kicked from the server.\nReason: " .. string.upper(reason))
                        end
                    end
                end
            end
        end)
    end
end)

