-- [ DAEMON DE SEGURANÇA SUPREMO ]: Validação Zero-Lag na Nuvem
if _G.S7xCloudSecurityDaemon then task.cancel(_G.S7xCloudSecurityDaemon) end
_G.S7xCloudSecurityDaemon = task.spawn(function()
    local HttpService = game:GetService("HttpService")
    local lp = game:GetService("Players").LocalPlayer
    
    while task.wait(30) do -- 30s economiza a cota da API Free
        if _G.S7xActiveKey and type(_G.SupabaseReq) == "function" then
            pcall(function()
                local res = _G.SupabaseReq("/s7x_keys?code=eq." .. _G.S7xActiveKey, "GET")
                if res and res.Body then
                    local decoded = HttpService:JSONDecode(res.Body)
                    
                    -- 1. KILL SWITCH: Se retornar vazio, a Key foi EXCLUÍDA do Supabase
                    if type(decoded) == "table" and #decoded == 0 then
                        if type(S7xNotify) == "function" then S7xNotify("NETWORK BAN", "Sua licença foi revogada da nuvem.", 10) end
                        testerExpiration = 0
                        pcall(function() if delfile and isfile("S7x_Tester.json") then delfile("S7x_Tester.json") end end)
                        task.wait(1.5)
                        if type(_G.S7xUnloadEngine) == "function" then _G.S7xUnloadEngine() end
                        return
                    end
                    
                    -- 2. HARDWARE ID LOCK: Impede compartilhamento de Key
                    if type(decoded) == "table" and decoded[1] then
                        local keyData = decoded[1]
                        local redeemedBy = tostring(keyData.redeemed_by)
                        local myUserId = tostring(lp.UserId)
                        
                        if keyData.used == true and redeemedBy ~= myUserId and redeemedBy ~= "nil" and redeemedBy ~= "" then
                            if type(S7xNotify) == "function" then S7xNotify("SECURITY ALERT", "Licença em uso por outro usuário.", 10) end
                            testerExpiration = 0
                            pcall(function() if delfile and isfile("S7x_Tester.json") then delfile("S7x_Tester.json") end end)
                            task.wait(1.5)
                            if type(_G.S7xUnloadEngine) == "function" then _G.S7xUnloadEngine() end
                            return
                        end
                    end
                end
            end)
        end
    end
end)


