SaveS7xSettings = function()
    if not writefile then return end
    pcall(function()
        data_save = {}
        if isfile(configName) then
            s_save, res_save = pcall(function() return game:GetService("HttpService"):JSONDecode(readfile(configName)) end)
            if s_save and type(res_save) == "table" then data_save = res_save end
        end
        data_save.lastTag = _G.EquippedTag
        data_save.lastAura = _G.EquippedAura
        data_save.theme = _G.CurrentTheme
        data_save.flySpeed = flySpeedValue
        data_save.walkSpeed = walkSpeedValue
        data_save.jumpPower = jumpPowerValue
        data_save.hitboxSize = hitboxSizeValue
        data_save.spamEgg = spamEggValue
        data_save.espMinDistance = _G.S7xEspMinDistance or 40
        data_save.hitboxColor = {r = hbR, g = hbG, b = hbB, t = hbTransp}
        
        data_save.cursorId = _G.S7xCurrentCursor
        data_save.cursorSize = _G.S7xCursorSize
        data_save.cursorAnchorX = _G.S7xCursorAnchorX
        data_save.cursorAnchorY = _G.S7xCursorAnchorY
        
        -- [ AUTO-SAVE DOS ÁUDIOS CUSTOMIZADOS ]
        data_save.customSounds = _G.S7xCustomSounds
        
        data_save.binds = {}
        for k, v in pairs(bindKeys) do if v then data_save.binds[k] = v.Name end end
        
        writefile(configName, game:GetService("HttpService"):JSONEncode(data_save))
    end)
end

