_G.S7xUsers = _G.S7xUsers or {[game.Players.LocalPlayer.UserId] = true}
SpecialTags = SpecialTags or {} 
_G.PresenceTags = _G.PresenceTags or {} 
_G.PresenceAuras = _G.PresenceAuras or {}

local SIGNAL_ID_R6 = "rbxassetid://180436148"
local SIGNAL_ID_R15 = "rbxassetid://507770239"

SendPresence = function()
    if not _G.MyTagPublic then return end
    task.spawn(function()
        pcall(function()
            -- CORREÇÃO CRÍTICA: Usando GetFirebaseRank (nome real da função no seu código)
            local fRank = (type(GetFirebaseRank) == "function" and GetFirebaseRank(game.Players.LocalPlayer)) or "User"
            local myCurrentTag = _G.EquippedTag or fRank
            
            local payloadData = {
                job_id = tostring(game.JobId), 
                Time = os.time(),
                Tag = myCurrentTag, 
                Aura = _G.EquippedAura or "None"
            }
            
            -- Envia os dados para a rede com resolução de conflitos limpa (evita spam de delete)
           _G.SupabaseReq("/presence?on_conflict=id", "POST", { id = tostring(game.Players.LocalPlayer.UserId), payload = payloadData })
        end)
    end)
end

-- [ 2. GATILHO INSTANTÂNEO P2P (AVISA A ENGINE DO ROBLOX) ]
SendP2PPing = function()
    pcall(function()
        local char = game.Players.LocalPlayer.Character
        if not char then return end
        local hum = char:FindFirstChild("Humanoid")
        local animator = hum and hum:FindFirstChild("Animator")
        
        if animator then
            local targetId = hum.RigType == Enum.HumanoidRigType.R6 and SIGNAL_ID_R6 or SIGNAL_ID_R15
            local syncAnim = Instance.new("Animation")
            syncAnim.AnimationId = targetId
            local track = animator:LoadAnimation(syncAnim)
            track.Priority = Enum.AnimationPriority.Core
            -- Toca invisível por 0.1s só para disparar a rede instantaneamente para os outros
            track:Play(0, 0.0001, 0)
            task.delay(0.2, function() track:Stop() end)
        end
    end)
end

-- [ GATILHO DE BROADCAST INSTANTÂNEO ]
_G.BroadcastInstantUpdate = function()
    -- Trava o Supabase por 3 segundos para não apagar a sua tag da tela enquanto o servidor salva
    _G.S7xLocalLock = tick() + 3 
    
    if type(SendPresence) == "function" then SendPresence() end
    task.delay(0.4, function()
        if type(SendP2PPing) == "function" then SendP2PPing() end
    end)
end

-- [ 3. SINCRONIZADOR GLOBAL DO SERVIDOR ]
SyncServerPresence = function()
    if not _G.S7xTagVisible then return end
    task.spawn(function()
        pcall(function()
            local res = _G.SupabaseReq("/presence?select=id,payload", "GET")
            if res and res.Body then
                local decoded = game:GetService("HttpService"):JSONDecode(res.Body)
                if type(decoded) == "table" and not decoded.error then
                    local currentTime = os.time()
                    for _, row in ipairs(decoded) do
                        local payload = row.payload
                        if type(payload) == "string" then pcall(function() payload = game:GetService("HttpService"):JSONDecode(payload) end) end
                        
                        if type(payload) == "table" and payload.job_id == tostring(game.JobId) then
                            local uid = tonumber(row.id)
                            -- Aceita sinais dos últimos 35 segundos
                            if uid and uid ~= game.Players.LocalPlayer.UserId and payload.Time and (currentTime - payload.Time <= 35) then
                                local targetPlr = game:GetService("Players"):GetPlayerByUserId(uid)
                                if targetPlr then
                                    _G.PresenceTags[uid] = payload.Tag 
                                    _G.PresenceAuras[uid] = payload.Aura 
                                    
                                    if not _G.S7xUsers[uid] then
                                        _G.S7xUsers[uid] = true
                                        if type(NotifySignalReceived) == "function" then task.spawn(NotifySignalReceived, targetPlr) end
                                    end
                                    
                                    task.spawn(function()
                                        if ApplyOrUpdateTag then ApplyOrUpdateTag(targetPlr) end
                                        if ApplyS7xAura then ApplyS7xAura(targetPlr) end
                                    end)
                                end
                            elseif uid and _G.S7xUsers[uid] then
                                -- Limpa quem saiu ou desligou a tag
                                _G.S7xUsers[uid] = nil; _G.PresenceTags[uid] = nil; _G.PresenceAuras[uid] = nil
                                if SpecialTags[uid] then pcall(function() SpecialTags[uid].Label.Parent:Destroy() end); SpecialTags[uid] = nil end
                            end
                        end
                    end
                end
            end
        end)
    end)
end

-- [ 4. O ESCUTADOR P2P (A MÁGICA DA VELOCIDADE) ]
MonitorP2PPing = function(p, char)
    local hum = char:WaitForChild("Humanoid", 5)
    local animator = hum and hum:WaitForChild("Animator", 5)
    if animator then
        animator.AnimationPlayed:Connect(function(track)
            local animId = track.Animation and track.Animation.AnimationId or ""
            if animId == SIGNAL_ID_R6 or animId == SIGNAL_ID_R15 then
                -- ALGUÉM ACABOU DE INJETAR O SCRIPT NO MAPA!
                -- 1. Puxamos a tag dele do banco na mesma hora
                task.spawn(SyncServerPresence)
                -- 2. Devolvemos o nosso ping para ele carregar a nossa tag instantaneamente também
                task.delay(1.5, SendInstantSignal)
            end
        end)
    end
end

for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
    if p ~= game.Players.LocalPlayer then
        if p.Character then task.spawn(MonitorP2PPing, p, p.Character) end
        p.CharacterAdded:Connect(function(char) MonitorP2PPing(p, char) end)
    end
end
game:GetService("Players").PlayerAdded:Connect(function(p)
    p.CharacterAdded:Connect(function(char) MonitorP2PPing(p, char) end)
end)

