task.spawn(function()
    if _G.EquippedTag then ApplyOrUpdateTag(game.Players.LocalPlayer) end
    if _G.EquippedAura and _G.EquippedAura ~= "None" then ApplyS7xAura(game.Players.LocalPlayer) end
    
