local function createTabBtn(text, order)
    local btn = Instance.new("TextButton", GUI.TabMenu)
    btn.Size = UDim2.new(0.88, 0, 0, 36)
    local formattedText = string.gsub(string.lower(text), "(%a)([%w_']*)", function(first, rest) return string.upper(first) .. rest end)
    btn.Text = formattedText
    btn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    btn.BackgroundTransparency = 1 
    btn.TextColor3 = Color3.fromRGB(130, 130, 140) 
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 11
    btn.LayoutOrder = order
    btn.AutoButtonColor = false
    btn.TextXAlignment = Enum.TextXAlignment.Left
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)
    
    local padding = Instance.new("UIPadding", btn)
    padding.PaddingLeft = UDim.new(0, 18)
    
    local indicator = Instance.new("Frame", btn)
    indicator.Name = "Indicator"
    indicator.Size = UDim2.new(0, 0, 0.4, 0)
    indicator.Position = UDim2.new(0, -10, 0.3, 0)
    indicator.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    indicator.BorderSizePixel = 0
    Instance.new("UICorner", indicator).CornerRadius = UDim.new(1, 0)

    btn.MouseEnter:Connect(function()
        if not btn:GetAttribute("IsSelected") then
            pcall(function()
                game:GetService("TweenService"):Create(btn, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(220, 220, 220), BackgroundTransparency = 0.94}):Play()
                game:GetService("TweenService"):Create(indicator, TweenInfo.new(0.3, Enum.EasingStyle.Back), {Size = UDim2.new(0, 4, 0.4, 0)}):Play()
            end)
        end
    end)
    
    btn.MouseLeave:Connect(function()
        if not btn:GetAttribute("IsSelected") then 
            pcall(function()
                game:GetService("TweenService"):Create(btn, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(130, 130, 140), BackgroundTransparency = 1}):Play()
                game:GetService("TweenService"):Create(indicator, TweenInfo.new(0.3), {Size = UDim2.new(0, 0, 0.4, 0)}):Play()
            end)
        end
    end)
    
    return btn
end

