local function addUIGrid(parent, cellWidth)
    local layout = Instance.new("UIGridLayout", parent)
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.CellPadding = UDim2.new(0, 6, 0, 8)
    
    -- O Segredo Profissional: 1 coluna longa no mobile, 2 ou mais no PC
    local widthScale = isMobile and 0.95 or cellWidth
    layout.CellSize = UDim2.new(widthScale, 0, 0, 36) 
    
    local padding = Instance.new("UIPadding", parent)
    padding.PaddingTop = UDim.new(0, 10)
    return layout
end

local function addUIList(parent)
    local layout = Instance.new("UIListLayout", parent)
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 8)
    local padding = Instance.new("UIPadding", parent)
    padding.PaddingTop = UDim.new(0, 10)
    return layout
end

local function addTagUIGrid(parent)
    local layout = Instance.new("UIGridLayout", parent)
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.CellPadding = UDim2.new(0, 10, 0, 10)
    layout.CellSize = UDim2.new(0.44, 0, 0, 50) 
    local padding = Instance.new("UIPadding", parent)
    padding.PaddingTop = UDim.new(0, 10)
    return layout
end

