-- ==========================================
-- MOTOR DE VISIBILIDADE DINÂMICA (ABAS RESTRITAS PRO)
-- ==========================================
if _G.S7xTabVisibilityDaemon then task.cancel(_G.S7xTabVisibilityDaemon) end
_G.S7xTabVisibilityDaemon = task.spawn(function()
    local lastRankCheck = nil
    
    while task.wait(1.5) do -- Escaneamento rápido em tempo real
        pcall(function()
            local player = game.Players.LocalPlayer
            local rank = "User"
            
            if type(GetFirebaseRank) == "function" then 
                rank = GetFirebaseRank(player) or "User" 
            end
            
            -- Normalização de cargos
            if rank == "Developers" or rank == "Dev" then rank = "Developer" end
            if rank == "Creator" then rank = "Owner" end
            
            -- Otimização Zero-Lag: Só atualiza a interface se o cargo mudar
            if lastRankCheck == rank then return end 
            lastRankCheck = rank
            
            -- [ 1. LÓGICA DA ABA ADMIN ]
            local canSeeAdmin = { 
                ["Supervisor"] = true, ["Co-Owner"] = true, 
                ["Owner"] = true, ["Developer"] = true, ["Manager"] = true
            }
            if GUI.AdminTabBtn then 
                GUI.AdminTabBtn.Visible = canSeeAdmin[rank] or false 
            end
            
            local canSeeTagEdit = {
                ["Contributor"] = true, ["Marketing"] = true, ["Manager"] = true, 
                ["Supervisor"] = true, ["Co-Owner"] = true, ["Owner"] = true, 
                ["Developer"] = true, ["Helper"] = true, ["Frieds"] = true, ["Booster"] = true
            }
            
            local hasTagAccess = canSeeTagEdit[rank] or false
            
            -- Oculta ou mostra o botão lateral instantaneamente
            if GUI.TagEditTabBtn then
                GUI.TagEditTabBtn.Visible = hasTagAccess
            end
            
            -- [ 3. SISTEMA DE EXPULSÃO AUTOMÁTICA (AUTO-KICK) ]
            -- Se o usuário estiver dentro da aba Tag Edit no momento do rebaixamento, ele é expulso para a Home
            if not hasTagAccess and GUI.TagEditTabBtn and GUI.TagEditTabBtn:GetAttribute("IsSelected") then
                if GUI.InicioTabBtn then
                    GUI.InicioTabBtn.MouseButton1Click:Fire() -- Redireciona para a Home
                    if type(S7xNotify) == "function" then 
                        S7xNotify("ACCESS REVOKED", "Seu cargo foi alterado. Acesso à customização bloqueado.") 
                    end
                end
            end
            
            -- Expulsa da aba Admin caso perca o cargo correspondente
            if not canSeeAdmin[rank] and GUI.AdminTabBtn and GUI.AdminTabBtn:GetAttribute("IsSelected") then
                if GUI.InicioTabBtn then
                    GUI.InicioTabBtn.MouseButton1Click:Fire()
                end
            end
        end)
    end
end)

