local function switchServerTab(showExploits)
    local ts = game:GetService("TweenService")
    local tInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint)

    if showExploits then
        ExploitsContainer.Visible = true
        ServersContentContainer.Visible = false
        ts:Create(ExploitsNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(255, 255, 255), TextColor3 = Color3.fromRGB(0, 0, 0)}):Play()
        ts:Create(ServersNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(15, 15, 18), TextColor3 = Color3.fromRGB(150, 150, 160)}):Play()
    else
        ExploitsContainer.Visible = false
        ServersContentContainer.Visible = true
        ts:Create(ServersNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(255, 255, 255), TextColor3 = Color3.fromRGB(0, 0, 0)}):Play()
        ts:Create(ExploitsNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(15, 15, 18), TextColor3 = Color3.fromRGB(150, 150, 160)}):Play()
    end
end

ExploitsNavBtn.MouseButton1Click:Connect(function() switchServerTab(true) end)
