                EntrarBtn.MouseLeave:Connect(function() TweenService:Create(EntrarBtn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(170, 0, 255)}):Play() end)

                EntrarBtn.MouseButton1Click:Connect(function()
