                        if RemoteEvents then
                            pcall(function() firesignal(RemoteEvents.OnClientEvent, "Loading/Show", "Opening the portal!", "Teleporting...") end)
                        end

                        task.delay(0.5, function()
                            local tpPos
                            if isPlayer and staticPosOrPlayerData.Character then
                                tpPos = staticPosOrPlayerData.Character:GetPivot().Position + Vector3.new(0, 5, 0)
                            elseif not isPlayer then
                                tpPos = staticPosOrPlayerData + Vector3.new(0, 5, 0)
                            end
                            
                            if tpPos then LocalPlayer.Character:PivotTo(CFrame.new(tpPos)) end
                            
                            if RemoteEvents then
                                pcall(function()
                                    firesignal(RemoteEvents.OnClientEvent, "Loading/Hide")
                                    RemoteEvents:FireServer("Loading/Covered")
                                end)
                            end
                        end)
                    end
                end)
                return ItemFrame, DistLabel
            end

            local function AddIsland(id, name, position)
                if ILHAS_IGNORADAS[name] then return end 
                if ActiveIslands[id] then return end
                
                local ui, distLabel = AddEntryUI(id, false, name, position)
                ActiveIslands[id] = { Name = name, Position = position, UI = ui, DistLabel = distLabel }
                
                ShowNotification("Nova ilha gerada: " .. name)
            end

