                if ActivePlayers[userId] then
                    if ActivePlayers[userId].UI then ActivePlayers[userId].UI:Destroy() end
                    ActivePlayers[userId] = nil
                end
            end

            local function AddPlayerToRadar(player)
                if ActivePlayers[player.UserId] then return end
                local ui, distLabel = AddEntryUI(player.UserId, true, player.DisplayName, player)
                ActivePlayers[player.UserId] = { Player = player, UI = ui, DistLabel = distLabel }
            end

            task.spawn(function()
                while task.wait(1) do
                    for _, plr in pairs(Players:GetPlayers()) do
                        if plr ~= LocalPlayer and plr.Character then
                            local targetPos = plr.Character:GetPivot().Position
                            local distFromOrigin = targetPos.Magnitude
                            if distFromOrigin > DISTANCIA_FORA_DO_MAPA then
                                AddPlayerToRadar(plr)
                            else
                                RemovePlayerFromRadar(plr.UserId)
                            end
                        end
                    end
                end
            end)

            local lastUpdate = 0
            RunService.Heartbeat:Connect(function(dt)
                lastUpdate = lastUpdate + dt
                if lastUpdate < 0.2 then return end 
                lastUpdate = 0

                if not LocalPlayer.Character or not LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then return end
                local hrpPos = LocalPlayer.Character.HumanoidRootPart.Position

                for id, data in pairs(ActiveIslands) do
                    if data.DistLabel then
                        local dist = math.floor((hrpPos - data.Position).Magnitude)
                        data.DistLabel.Text = dist .. " Studs"
                    end
                end
                for id, data in pairs(ActivePlayers) do
                    if data.DistLabel and data.Player.Character then
                        local targetPos = data.Player.Character:GetPivot().Position
                        local dist = math.floor((hrpPos - targetPos).Magnitude)
                        data.DistLabel.Text = dist .. " Studs"
                    end
                end
            end)

            local BlinkRemote = ReplicatedStorage:WaitForChild("BLINK_RELIABLE_REMOTE", 10)
            if BlinkRemote then
                BlinkRemote.OnClientEvent:Connect(function(buff)
                    pcall(function()
                        local cursor = 0
                        local len = buffer.len(buff)
                        
                        while cursor < len do
                            local eventId = buffer.readu8(buff, cursor)
                            cursor = cursor + 1
                            
                            if eventId == 59 then 
                                local payloadStart = cursor
                                cursor = cursor + 34
                                local id = buffer.readu32(buff, payloadStart)
                                local nameLen = buffer.readu16(buff, payloadStart + 4)
                                
                                local name = buffer.readstring(buff, cursor, nameLen)
                                cursor = cursor + nameLen
                                
                                local x = buffer.readf32(buff, payloadStart + 10)
                                local y = buffer.readf32(buff, payloadStart + 14)
                                local z = buffer.readf32(buff, payloadStart + 18)
                                
                                AddIsland(id, name, Vector3.new(x, y, z))
                                
                            elseif eventId == 60 then
                                local id = buffer.readu32(buff, cursor)
                                cursor = cursor + 4
                                RemoveIsland(id) 
                            else
                                break
                            end
                        end
                    end)
                end)
            end
        end)
    end)

    -- Módulo Mushyo Instruments (Auto Play)
    createExploitBtn("Mushyo instruments", true, function()
        if _G.MushAutoPlayActive then 
            if type(S7xNotify) == "function" then S7xNotify("ALREADY LOADED", "The module is already open on your screen.") end
            return 
        end
        _G.MushAutoPlayActive = true
        
        task.spawn(function()
            local Players = game:GetService("Players")
            local Workspace = game:GetService("Workspace")
            local RunService = game:GetService("RunService")
            local CoreGui = game:GetService("CoreGui")
            local TweenService = game:GetService("TweenService")
            local UserInputService = game:GetService("UserInputService")
            local ReplicatedStorage = game:GetService("ReplicatedStorage")

            local LocalPlayer = Players.LocalPlayer
            local PlayerGui = LocalPlayer:WaitForChild("PlayerGui", 10)

            if _G.MushAutoPlayCleanup then pcall(_G.MushAutoPlayCleanup) end

            local VirtualInputManager = nil
            pcall(function() VirtualInputManager = game:GetService("VirtualInputManager") end)

            local MusicTool = nil
            local Musics = nil
            local MusicInterface = nil
            local constants = nil

            pcall(function() MusicTool = require(ReplicatedStorage.Client.Tools.Music) end)
            if MusicTool and getupvalue then
                pcall(function()
                    Musics = getupvalue(MusicTool.Play, 1)
                    MusicInterface = getupvalue(MusicTool.Play, 27)
                end)
            end
            if MusicInterface and getupvalue then pcall(function() constants = getupvalue(MusicInterface, 4) end) end
            -- [ CORREÇÕES DE SINTAXE: Adicionando ; para separar statements na mesma linha ]
            
            if not constants then pcall(function() constants = require(ReplicatedStorage.Configuration.Musics.constants) end) end

            local Settings = { Enabled = true, Mode = "Perfect", ToggleKey = Enum.KeyCode.E, TapHoldDuration = 0.045, CustomOffset = 0.000 }
            local State = { IsPlaying = false, ActiveSession = nil, SongName = "Nenhuma", TotalNotes = 0, NotesHit = 0, Combo = 0, Accuracy = 100, ActivePresses = {}, UpcomingNotes = {}, Connections = {} }

            local function Log(msg) print("[S7x AutoPlay] " .. tostring(msg)) end
            local function GetNoteStart(note) if constants and constants.GetStart then local s, res = pcall(constants.GetStart, note); if s and res then return res end end; if type(note) == "table" and note.Position then return note.Position[1] end; return 0 end
            local function GetNoteFinish(note) if constants and constants.GetFinish then local s, res = pcall(constants.GetFinish, note); if s and res then return res end end; if type(note) == "table" and note.Position then return note.Position[#note.Position] end; return GetNoteStart(note) end
            local function IsNoteHold(note) if constants and constants.IsHold then local s, res = pcall(constants.IsHold, note); if s then return res end end; if type(note) == "table" and note.Position then return #note.Position > 1 end; return false end
            
            local function PressKey(keyCode) if not keyCode then return end; if VirtualInputManager then pcall(function() VirtualInputManager:SendKeyEvent(true, keyCode, false, game) end) end end
            local function ReleaseKey(keyCode) if not keyCode then return end; if VirtualInputManager then pcall(function() VirtualInputManager:SendKeyEvent(false, keyCode, false, game) end) end end
            local function ReleaseAllKeys() for keyCode in pairs(State.ActivePresses) do ReleaseKey(keyCode) end; table.clear(State.ActivePresses) end

            local function EndCurrentSession()
                if not State.IsPlaying then return end
                State.IsPlaying = false; State.ActiveSession = nil
                ReleaseAllKeys(); table.clear(State.UpcomingNotes)
                if UpdateUI then pcall(UpdateUI) end
            end

            local function StartAutoPlaySession(sessionData)
                if not sessionData or not sessionData.Sheet then return end
                State.IsPlaying = true; State.ActiveSession = sessionData
                local songName = "Musica"
                if sessionData.Song then
                    if type(sessionData.Song) == "table" then songName = sessionData.Song.Name or sessionData.Song.Title or sessionData.Song.Label or "Musica" else songName = tostring(sessionData.Song) end
                end
                State.SongName = songName; State.TotalNotes = #sessionData.Sheet; State.NotesHit = 0; State.Combo = 0; State.Accuracy = 100
                ReleaseAllKeys()

                local notes = {}
                for i, note in ipairs(sessionData.Sheet) do
                    local key = note.Key
                    if typeof(key) == "string" then key = Enum.KeyCode[key] or Enum.KeyCode[key:upper()] end
                    table.insert(notes, { Index = i, Key = key, Start = GetNoteStart(note), Finish = GetNoteFinish(note), IsHold = IsNoteHold(note), Processed = false, Raw = note })
                end
                table.sort(notes, function(a, b) return a.Start < b.Start end)
                State.UpcomingNotes = notes
                if UpdateUI then pcall(UpdateUI) end
            end

            local function ProcessFrame()
                if not State.IsPlaying or not State.ActiveSession then return end
                local songTime = Workspace:GetServerTimeNow() - (State.ActiveSession.StartAt or 0)

                for keyCode, pressInfo in pairs(State.ActivePresses) do
                    if songTime >= pressInfo.ReleaseTime then ReleaseKey(keyCode); State.ActivePresses[keyCode] = nil end
                end

                if not Settings.Enabled then return end
                local nextIndex = 1
                while nextIndex <= #State.UpcomingNotes do
                    local note = State.UpcomingNotes[nextIndex]
                    if not note.Processed then
                        local targetTime = note.Start + Settings.CustomOffset
                        if Settings.Mode == "Legit" then targetTime = targetTime + (math.random() * 0.025 - 0.005) end
                        if songTime >= targetTime then
                            note.Processed = true
                            if note.Key then
                                PressKey(note.Key)
                                State.ActivePresses[note.Key] = { IsHold = note.IsHold, ReleaseTime = note.IsHold and (note.Finish + Settings.CustomOffset) or (songTime + Settings.TapHoldDuration) }
                                State.NotesHit = State.NotesHit + 1; State.Combo = State.Combo + 1
                                if UpdateUI then pcall(UpdateUI) end
                            end
                            table.remove(State.UpcomingNotes, nextIndex)
                        elseif targetTime - songTime > 0.5 then break else nextIndex = nextIndex + 1 end
                    else table.remove(State.UpcomingNotes, nextIndex) end
                end
            end

            if hookfunction and MusicInterface then
                local oldMusic
                oldMusic = hookfunction(MusicInterface, function(options)
                    if type(options) == "table" and options.Sheet then
                        task.spawn(function() pcall(StartAutoPlaySession, options) end)
                        local origOnFinish, origOnExit = options.OnFinish, options.OnExit
                        options.OnFinish = function(...) task.defer(function() pcall(EndCurrentSession) end); if origOnFinish then return origOnFinish(...) end end
                        options.OnExit = function(...) task.defer(function() pcall(EndCurrentSession) end); if origOnExit then return origOnExit(...) end end
                    end
                    return oldMusic(options)
                end)
            end

            local heartbeatConn = RunService.Heartbeat:Connect(ProcessFrame)
            table.insert(State.Connections, heartbeatConn)

            local scanConn = task.spawn(function()
                while true do
                    task.wait(0.5)
                    if not State.IsPlaying and getgc then
                        pcall(function()
                            for _, obj in ipairs(getgc(true)) do
                                if type(obj) == "table" and rawget(obj, "Sheet") and rawget(obj, "StartAt") and rawget(obj, "OnNote") then
                                    if #obj.Sheet > 0 and (Workspace:GetServerTimeNow() - obj.StartAt) < 300 then StartAutoPlaySession(obj); break end
                                end
                            end
                        end)
                    elseif State.IsPlaying and State.ActiveSession then
                        local hasMusicGui = false
                        for _, gui in ipairs(PlayerGui:GetChildren()) do if gui:IsA("ScreenGui") and gui.Enabled and (gui:FindFirstChild("Main") or gui:FindFirstChild("Hotbar", true)) then hasMusicGui = true; break end end
                        if not hasMusicGui and #State.UpcomingNotes == 0 then EndCurrentSession() end
                    end
                end
            end)

            local inputConn = UserInputService.InputBegan:Connect(function(input, processed)
                if not processed and input.KeyCode == Settings.ToggleKey then
                    Settings.Enabled = not Settings.Enabled; if UpdateUI then pcall(UpdateUI) end
                end
            end)
            table.insert(State.Connections, inputConn)

            -- INTERFACE ADAPTADA S7X STYLE
            pcall(function() if CoreGui:FindFirstChild("MushAutoPlayUI_V2") then CoreGui.MushAutoPlayUI_V2:Destroy() end end)
            local ScreenGui = Instance.new("ScreenGui"); ScreenGui.Name = "MushAutoPlayUI_V2"; ScreenGui.ResetOnSpawn = false; ScreenGui.Parent = CoreGui

            local MainFrame = Instance.new("Frame", ScreenGui)
            MainFrame.Size = UDim2.new(0, 320, 0, 260); MainFrame.Position = UDim2.new(0.7, 0, 0.25, 0)
            MainFrame.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
            MainFrame.Active = true; MainFrame.Draggable = true
            Instance.new("UICorner", MainFrame).CornerRadius = UDim.new(0, 8)
            Instance.new("UIStroke", MainFrame).Color = Color3.fromRGB(170, 0, 255); Instance.new("UIStroke", MainFrame).Thickness = 1.2

            local TopBar = Instance.new("Frame", MainFrame)
            TopBar.Size = UDim2.new(1, 0, 0, 42); TopBar.BackgroundColor3 = Color3.fromRGB(18, 18, 20)
            Instance.new("UICorner", TopBar).CornerRadius = UDim.new(0, 8)

