            local StatsLabel = Instance.new("TextLabel", StatusCard)
            StatsLabel.Size = UDim2.new(1, -16, 0, 24); StatsLabel.Position = UDim2.new(0, 10, 0, 30); StatsLabel.BackgroundTransparency = 1
            StatsLabel.Font = Enum.Font.GothamMedium; StatsLabel.Text = "Selecione uma musica na bateria/instrumento!"; StatsLabel.TextColor3 = Color3.fromRGB(150, 150, 150); StatsLabel.TextSize = 11; StatsLabel.TextXAlignment = Enum.TextXAlignment.Left

