            return 
        end
        _G.S7xAutoMetal_Loaded = true

        task.spawn(function()
            do
                local Players = game:GetService("Players")
                local ReplicatedStorage = game:GetService("ReplicatedStorage")
                local ReplicatedFirst = game:GetService("ReplicatedFirst")
                local Workspace = game:GetService("Workspace")
                local TweenService = game:GetService("TweenService")
                local UserInputService = game:GetService("UserInputService")
                local Events = require(ReplicatedStorage.Modules.Events)

                -- =========================================================================
                -- SISTEMA ANTI-DUPLICAGEM PROFISSIONAL
                -- =========================================================================
                if getgenv().AutoMetal_VS7x_Cleanup then
                    pcall(function() getgenv().AutoMetal_VS7x_Cleanup() end)
                end

                local UI_NAME = "EliteScannerUI_VS7x"
                local LocalPlayer = Players.LocalPlayer

                pcall(function()
                    local pgui = LocalPlayer:WaitForChild("PlayerGui", 999)
                    for _, g in ipairs(pgui:GetChildren()) do
                        if g.Name == UI_NAME or g.Name:match("EliteScanner") then
                            g:Destroy()
                        end
                    end
                end)

                local isGuiOpen = true
                local systemActive = false 
                local autoShovelActive = false
                local autoCollectActive = false
                local autoSellRaroActive = false  
                local autoSellGearActive = false
                local isSelling = false 
                local isDigging = false 
                local isCalculatingCenter = false
                local CurrentState = "red" 
                local scanCenter = nil

                getgenv().AutoMetal_VS7x_Cleanup = function()
                    isGuiOpen = false
                    systemActive = false
                    _G.S7xAutoMetal_Loaded = false
                    pcall(function()
                        local pgui = LocalPlayer:FindFirstChild("PlayerGui")
                        if pgui then
                            for _, g in ipairs(pgui:GetChildren()) do
                                if g.Name == UI_NAME or g.Name:match("EliteScanner") then
                                    g:Destroy()
                                end
                            end
                        end
                    end)
                end

                -- =========================================================================
                -- VARIÁVEIS DE CONTROLE E ITENS
                -- =========================================================================
                local treasureFound = false
                local treasurePosition = nil
                local treasureName = ""
                local itemCollected = false
                local rareItemSoldConfirmation = false 

                local ValidItems = {
                    ["metalsheet"] = {sell = false, isHoldable = false},
                    ["gear"]       = {sell = true,  isHoldable = false},
                    ["battery"]    = {sell = false, isHoldable = false},
                    ["lampp"]      = {sell = false, isHoldable = false},
                    ["nut"]        = {sell = false, isHoldable = false},
                    ["cup"]        = {sell = true,  isHoldable = true}, 
                    ["crown"]      = {sell = true,  isHoldable = true}, 
                    ["necklace"]   = {sell = true,  isHoldable = true}  
                }

                local RADIUS_STEP = 15     
                local ANGLE_STEP = 0.4     
                local MAX_RADIUS = 700     

                -- Posição do NPC Merchant
                local VIP_MERCHANT_CFRAME = CFrame.new(5238.36, 191.70, -101.31)

                -- =========================================================================
                -- FUNÇÕES AUXILIARES DE INVENTÁRIO E VENDA
                -- =========================================================================
                local function getRareTools()
                    local rares = {}
                    local backpack = LocalPlayer:FindFirstChild("Backpack")
                    local character = LocalPlayer.Character

                    local function checkContainer(container)
                        if not container then return end
                        for _, item in ipairs(container:GetChildren()) do
                            if item:IsA("Tool") then
                                local name = item.Name:lower():gsub("%s+", "")
                                local isRare = (name == "crown" or name == "cup" or name == "necklace" or item:GetAttribute("Hold") == true)
                                if isRare and not table.find(rares, item) then
                                    table.insert(rares, item)
                                end
                            end
                        end
                    end

                    checkContainer(backpack)
                    checkContainer(character)
                    return rares
                end

                -- =========================================================================
                -- INTERFACE GRÁFICA PROFISSIONAL (TEMA S7X BLACK-OUT)
                -- =========================================================================
                local ScreenGui = Instance.new("ScreenGui", LocalPlayer.PlayerGui)
                ScreenGui.Name = UI_NAME
                ScreenGui.ResetOnSpawn = false

                local MainFrame = Instance.new("Frame", ScreenGui)
                MainFrame.Size = UDim2.new(0, 260, 0, 265) 
                MainFrame.Position = UDim2.new(0, 20, 0.35, 0)
                MainFrame.BackgroundColor3 = Color3.fromRGB(12, 12, 12) -- Preto Absoluto
                MainFrame.BorderSizePixel = 0
                MainFrame.ClipsDescendants = true
                MainFrame.Active = true
                Instance.new("UICorner", MainFrame).CornerRadius = UDim.new(0, 8)
                
                local mfStroke = Instance.new("UIStroke", MainFrame)
                mfStroke.Color = Color3.fromRGB(255, 255, 255) -- Linha Branca
                mfStroke.Thickness = 1.2

                local Header = Instance.new("Frame", MainFrame)
                Header.Size = UDim2.new(1, 0, 0, 35)
                Header.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
                Header.BorderSizePixel = 0
                Header.Active = true
                Instance.new("UICorner", Header).CornerRadius = UDim.new(0, 8)

                local HeaderFix = Instance.new("Frame", Header)
                HeaderFix.Size = UDim2.new(1, 0, 0, 10)
                HeaderFix.Position = UDim2.new(0, 0, 1, -10)
                HeaderFix.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
                HeaderFix.BorderSizePixel = 0

                local Title = Instance.new("TextLabel", Header)
                Title.Size = UDim2.new(1, -70, 1, 0)
                Title.Position = UDim2.new(0, 15, 0, 0)
                Title.BackgroundTransparency = 1
                Title.Text = "AutoMetal S7x Pro"
                Title.TextColor3 = Color3.fromRGB(255, 255, 255) -- Letra Branca
                Title.Font = Enum.Font.GothamBlack
                Title.TextSize = 13
                Title.TextXAlignment = Enum.TextXAlignment.Left

                local MinBtn = Instance.new("TextButton", Header)
                MinBtn.Size = UDim2.new(0, 24, 0, 24)
                MinBtn.Position = UDim2.new(1, -56, 0.5, -12)
                MinBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
                MinBtn.Text = "-"
                MinBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                MinBtn.Font = Enum.Font.GothamBold
                MinBtn.TextSize = 14
                Instance.new("UICorner", MinBtn).CornerRadius = UDim.new(0, 6)

                local CloseBtn = Instance.new("TextButton", Header)
                CloseBtn.Size = UDim2.new(0, 24, 0, 24)
                CloseBtn.Position = UDim2.new(1, -28, 0.5, -12)
                CloseBtn.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
                CloseBtn.Text = "X"
                CloseBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                CloseBtn.Font = Enum.Font.GothamBold
                CloseBtn.TextSize = 12
                Instance.new("UICorner", CloseBtn).CornerRadius = UDim.new(0, 6)

                local ContentHolder = Instance.new("Frame", MainFrame)
                ContentHolder.Size = UDim2.new(1, 0, 1, -35)
                ContentHolder.Position = UDim2.new(0, 0, 0, 35)
                ContentHolder.BackgroundTransparency = 1

                local StatusText = Instance.new("TextLabel", ContentHolder)
                StatusText.Size = UDim2.new(1, -20, 0, 20)
                StatusText.Position = UDim2.new(0, 10, 0, 3)
                StatusText.BackgroundTransparency = 1
                StatusText.Text = "SISTEMA DESATIVADO"
                StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                StatusText.Font = Enum.Font.GothamBold
                StatusText.TextSize = 11

                local isMinimized = false
                MinBtn.Activated:Connect(function()
                    isMinimized = not isMinimized
                    MinBtn.Text = isMinimized and "+" or "-"
                    ContentHolder.Visible = not isMinimized
                    local targetSize = isMinimized and UDim2.new(0, 260, 0, 35) or UDim2.new(0, 260, 0, 265)
                    TweenService:Create(MainFrame, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = targetSize}):Play()
                end)

                -- Drag da Interface
                local isDragging = false
                local dragStartPos = nil
                local frameStartPos = nil

                Header.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        isDragging = true
                        dragStartPos = input.Position
                        frameStartPos = MainFrame.Position
                    end
                end)

                UserInputService.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        isDragging = false
                    end
                end)

                UserInputService.InputChanged:Connect(function(input)
                    if isDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                        local delta = input.Position - dragStartPos
                        MainFrame.Position = UDim2.new(
                            frameStartPos.X.Scale, frameStartPos.X.Offset + delta.X,
                            frameStartPos.Y.Scale, frameStartPos.Y.Offset + delta.Y
                        )
                    end
                end)

                UserInputService.InputBegan:Connect(function(input, gameProcessed)
                    if not gameProcessed and (input.KeyCode == Enum.KeyCode.RightShift or input.KeyCode == Enum.KeyCode.Insert) then
                        MainFrame.Visible = not MainFrame.Visible
                    end
                end)

                -- =========================================================================
                -- TOGGLES NO PADRÃO BLACK-OUT DA S7X
                -- =========================================================================
                local function CreateToggle(name, yPos, callback)
                    local Container = Instance.new("Frame", ContentHolder)
                    Container.Size = UDim2.new(1, -24, 0, 28)
                    Container.Position = UDim2.new(0, 12, 0, yPos - 35)
                    Container.BackgroundTransparency = 1
                    
                    local Label = Instance.new("TextLabel", Container)
                    Label.Size = UDim2.new(0, 180, 1, 0)
                    Label.BackgroundTransparency = 1
                    Label.Text = name
                    Label.TextColor3 = Color3.fromRGB(255, 255, 255)
                    Label.Font = Enum.Font.GothamBold
                    Label.TextSize = 11
                    Label.TextXAlignment = Enum.TextXAlignment.Left
                    
                    local ToggleBg = Instance.new("TextButton", Container)
                    ToggleBg.Size = UDim2.new(0, 42, 0, 22)
                    ToggleBg.Position = UDim2.new(1, -42, 0.5, -11)
                    ToggleBg.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
                    ToggleBg.Text = ""
                    ToggleBg.AutoButtonColor = false
                    Instance.new("UICorner", ToggleBg).CornerRadius = UDim.new(1, 0)
                    
                    local ToggleStroke = Instance.new("UIStroke", ToggleBg)
                    ToggleStroke.Color = Color3.fromRGB(255, 255, 255)
                    ToggleStroke.Thickness = 1.2
                    
                    local ToggleKnob = Instance.new("Frame", ToggleBg)
                    ToggleKnob.Size = UDim2.new(0, 14, 0, 14)
                    ToggleKnob.Position = UDim2.new(0, 4, 0.5, -7)
                    ToggleKnob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                    Instance.new("UICorner", ToggleKnob).CornerRadius = UDim.new(1, 0)
                    
                    local state = false
                    local function applyVisual(s)
                        local tInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                        if s then
                            TweenService:Create(ToggleKnob, tInfo, {Position = UDim2.new(1, -18, 0.5, -7), BackgroundColor3 = Color3.fromRGB(0, 0, 0)}):Play()
                            TweenService:Create(ToggleBg, tInfo, {BackgroundColor3 = Color3.fromRGB(255, 255, 255)}):Play()
                        else
                            TweenService:Create(ToggleKnob, tInfo, {Position = UDim2.new(0, 4, 0.5, -7), BackgroundColor3 = Color3.fromRGB(255, 255, 255)}):Play()
                            TweenService:Create(ToggleBg, tInfo, {BackgroundColor3 = Color3.fromRGB(15, 15, 15)}):Play()
                        end
                    end

                    ToggleBg.Activated:Connect(function()
                        state = not state
                        applyVisual(state)
                        callback(state)
                    end)

                    return {
                        SetState = function(newState)
                            if state ~= newState then
                                state = newState
                                applyVisual(state)
                                callback(state)
                            end
                        end,
                        GetState = function() return state end
                    }
                end

                -- =========================================================================
                -- ROTINA DE VENDA UNIVERSAL (RAROS + GEAR + COMUNS/MOCHILA)
                -- =========================================================================
                local function performSellRoutine(character, triggeredItemName)
                    if isSelling then return end
                    isSelling = true
                    
                    local root = character and character:FindFirstChild("HumanoidRootPart")
                    local hum = character and character:FindFirstChild("Humanoid")
                    if not (root and hum) then
                        isSelling = false
                        return
                    end
                    
                    local originalCFrame = root.CFrame
                    hum.PlatformStand = true
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.Velocity = Vector3.zero
                    
                    StatusText.Text = "TELEPORTANDO AO VENDEDOR VIP..."
                    StatusText.TextColor3 = Color3.fromRGB(0, 255, 150)
                    
                    root.CFrame = VIP_MERCHANT_CFRAME
                    task.wait(0.5)
                    
                    local canSellRaros = autoSellRaroActive or (triggeredItemName and (triggeredItemName == "crown" or triggeredItemName == "cup" or triggeredItemName == "necklace"))
                    if canSellRaros then
                        local rareItems = getRareTools()
                        for _, rareTool in ipairs(rareItems) do
                            if not isGuiOpen or not systemActive then break end
                            
                            local backpack = LocalPlayer:FindFirstChild("Backpack")
                            local isStillOwned = (rareTool.Parent == backpack or rareTool.Parent == character)
                            
                            if rareTool and isStillOwned then
                                local itemName = rareTool.Name:upper()
                                StatusText.Text = "EQUIPANDO E VENDENDO: " .. itemName
                                StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                                
                                hum:UnequipTools()
                                task.wait(0.15)
                                hum:EquipTool(rareTool)
                                task.wait(0.3)
                                
                                rareItemSoldConfirmation = false
                                local sellWait = tick()
                                while tick() - sellWait < 3.5 and isGuiOpen and systemActive do
                                    Events:Fire("SellTreasure")
                                    task.wait(0.35)
                                    if rareItemSoldConfirmation or rareTool.Parent == nil or rareTool.Parent ~= character then
                                        StatusText.Text = "VENDIDO: " .. itemName .. "!"
                                        StatusText.TextColor3 = Color3.fromRGB(0, 255, 100)
                                        task.wait(0.2)
                                        break
                                    end
                                end
                            end
                        end
                    end
                    
                    local canSellGear = autoSellGearActive or (triggeredItemName and (triggeredItemName == "gear" or triggeredItemName == "trash"))
                    if canSellGear then
                        pcall(function()
                            local RelStorage = ReplicatedStorage:FindFirstChild("ReliabilityStorage")
                            if RelStorage and RelStorage:FindFirstChild("Functions") then
                                local sellCommodity = RelStorage.Functions:FindFirstChild("SellCommodity")
                                local getCommodity = RelStorage.Functions:FindFirstChild("GetCommodityValue")
                                
                                if sellCommodity and getCommodity then
                                    local trashVal = getCommodity:InvokeServer("Trash") or 0
                                    local trashCount = LocalPlayer:GetAttribute("Trash") or 0
                                    
                                    if trashCount > 0 or (trashVal and tonumber(trashVal) and tonumber(trashVal) > 0) then
                                        StatusText.Text = "VENDENDO MOCHILA/GEAR ($" .. tostring(trashVal) .. ")"
                                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                                        sellCommodity:InvokeServer("Trash")
                                        task.wait(0.4)
                                    end
                                end
                            end
                        end)
                    end
                    
                    hum:UnequipTools()
                    task.wait(0.2)
                    
                    StatusText.Text = "VENDA CONCLUÍDA! RETORNANDO..."
                    StatusText.TextColor3 = Color3.fromRGB(0, 255, 100)
                    root.CFrame = originalCFrame
                    task.wait(0.4)
                    
                    Events:Fire("equipItem", "Metal Detector")
                    task.wait(0.3)
                    local det = LocalPlayer:WaitForChild("Backpack"):FindFirstChild("Metal Detector") or character:FindFirstChild("Metal Detector")
                    if det then
                        hum:EquipTool(det)
                        pcall(function() det:Activate() end)
                    end
                    
                    hum.PlatformStand = true
                    isSelling = false
                end

                -- =========================================================================
                -- ROTINA DE AUTO SELL BACKGROUND CONTÍNUO
                -- =========================================================================
                task.spawn(function()
                    while task.wait(3.5) do
                        if not isGuiOpen then break end
                        if systemActive and not isSelling and not isDigging and not isCalculatingCenter then
                            local shouldSell = false
                            
                            if autoSellRaroActive and #getRareTools() > 0 then
                                shouldSell = true
                            end
                            
                            if autoSellGearActive then
                                local trashCount = LocalPlayer:GetAttribute("Trash") or 0
                                if trashCount >= 1 then
                                    shouldSell = true
                                end
                            end
                            
                            if shouldSell and LocalPlayer.Character then
                                performSellRoutine(LocalPlayer.Character)
                            end
                        end
                    end
                end)

                -- =========================================================================
                -- LÓGICA CORE: HYPER TRIANGULATION & SURFACE NORMALIZATION
                -- =========================================================================
                local function getValidFloor(pos, char)
                    local params = RaycastParams.new()
                    params.FilterType = Enum.RaycastFilterType.Exclude
                    params.FilterDescendantsInstances = {char}
                    local res = Workspace:Raycast(pos + Vector3.new(0, 100, 0), Vector3.new(0, -200, 0), params)
                    if res and res.Material ~= Enum.Material.Water then
                        return res.Position + Vector3.new(0, 3.2, 0)
                    end
                    return nil
                end

                local function runTurboSpiral(character)
                    local Root = character:WaitForChild("HumanoidRootPart")
                    local Hum = character:WaitForChild("Humanoid", 999)
                    
                    Hum.PlatformStand = true
                    scanCenter = Root.Position
                    local angle = 0
                    local radius = 0
                    
                    local lastStuckCheckTime = tick()
                    local lastStuckPos = Root.Position
                    
                    while isGuiOpen and systemActive do
                        if isSelling then
                            Hum.PlatformStand = true
                            Root.AssemblyLinearVelocity = Vector3.zero
                            task.wait(0.5)
                            continue
                        end
                        
                        if tick() - lastStuckCheckTime > 10 and not isDigging and not isCalculatingCenter then
                            if (Root.Position - lastStuckPos).Magnitude < 15 and CurrentState ~= "green" then
                                scanCenter = Root.Position + Vector3.new(math.random(-250, 250), 0, math.random(-250, 250))
                                radius = 0
                                angle = 0
                            end
                            lastStuckCheckTime = tick()
                            lastStuckPos = Root.Position
                        end

                        if CurrentState == "green" then
                            Root.AssemblyLinearVelocity = Vector3.zero
                            Root.Velocity = Vector3.zero
                            Hum.PlatformStand = true
                            task.wait(0.2)
                            if CurrentState ~= "green" then continue end 

                            isCalculatingCenter = true
                            local absoluteSafeGreen = getValidFloor(Root.Position, character) or Root.Position
                            Root.CFrame = CFrame.new(absoluteSafeGreen)
                            
                            StatusText.Text = "GREEN CONFIRMADO! CALCULANDO..."
                            StatusText.TextColor3 = Color3.fromRGB(0, 255, 150)
                            
                            local startGreenPos = absoluteSafeGreen
                            local function scanAxis(axisDir)
                                local currentPos = startGreenPos
                                local lastValidGreen = currentPos
                                local steps = 0
                                while CurrentState == "green" and steps < 8 do
                                    currentPos = currentPos + (axisDir * 2)
                                    local g = getValidFloor(currentPos, character)
                                    if g then Root.CFrame = CFrame.new(g) end
                                    task.wait(0.08) 
                                    if CurrentState == "green" then lastValidGreen = g or currentPos end
                                    steps = steps + 1
                                end
                                local gStart = getValidFloor(startGreenPos, character)
                                if gStart then Root.CFrame = CFrame.new(gStart) end
                                task.wait(0.08) 
                                return lastValidGreen
                            end
                            
                            local maxX = scanAxis(Vector3.new(1, 0, 0))
                            local minX = scanAxis(Vector3.new(-1, 0, 0))
                            local midX = (maxX.X + minX.X) / 2
                            
                            startGreenPos = getValidFloor(Vector3.new(midX, absoluteSafeGreen.Y, absoluteSafeGreen.Z), character) or absoluteSafeGreen
                            Root.CFrame = CFrame.new(startGreenPos)
                            task.wait(0.1)
                            
                            local maxZ = scanAxis(Vector3.new(0, 0, 1))
                            local minZ = scanAxis(Vector3.new(0, 0, -1))
                            local midZ = (maxZ.Z + minZ.Z) / 2
                            
                            local finalCenter = Vector3.new(midX, absoluteSafeGreen.Y, midZ)
                            local groundFinal = getValidFloor(finalCenter, character) or finalCenter
                            Root.CFrame = CFrame.new(groundFinal)
                            Root.AssemblyLinearVelocity = Vector3.zero
                            task.wait(0.3) 
                            
                            if CurrentState ~= "green" then
                                Root.CFrame = CFrame.new(absoluteSafeGreen)
                                Root.AssemblyLinearVelocity = Vector3.zero
                                task.wait(0.3)
                            end
                            
                            if CurrentState == "green" then
                                isCalculatingCenter = false
                                if autoShovelActive then
                                    StatusText.Text = "NORMALIZANDO TERRENO..."
                                    Hum.PlatformStand = false 
                                    Root.AssemblyLinearVelocity = Vector3.zero
                                    Root.Velocity = Vector3.zero
                                    
                                    local surfacePos = getValidFloor(Root.Position, character)
                                    if surfacePos then Root.CFrame = CFrame.new(surfacePos + Vector3.new(0, 1.5, 0)) end
                                    
                                    local groundWait = tick()
                                    while Hum.FloorMaterial == Enum.Material.Air and tick() - groundWait < 1.5 do task.wait(0.05) end

                                    StatusText.Text = "ÁREA LIMPA! EQUIPANDO PÁ..."
                                    Events:Fire("equipItem", "Shovel")
                                    task.wait(0.4) 
                                    
                                    local Backpack = LocalPlayer:WaitForChild("Backpack")
                                    local shovel = Backpack:FindFirstChild("Shovel") or character:FindFirstChild("Shovel")
                                    
                                    if shovel then
                                        Hum:UnequipTools()
                                        task.wait(0.2)
                                        Hum:EquipTool(shovel)
                                        task.wait(0.4) 
                                        Root.AssemblyLinearVelocity = Vector3.zero
                                        
                                        isDigging = true
                                        treasureFound = false
                                        itemCollected = false
                                        treasurePosition = nil
                                        treasureName = ""
                                        
                                        local digStartTime = tick()
                                        while tick() - digStartTime < 17 and isDigging and isGuiOpen and systemActive do
                                            if treasureFound then break end
                                            Events:Fire("TryShovel", Root.Position)
                                            task.wait(1.5) 
                                        end
                                        
                                        if not treasureFound then
                                            StatusText.Text = "NADA AQUI. BUSCANDO NOVO GREEN..."
                                            StatusText.TextColor3 = Color3.fromRGB(255, 100, 100)
                                            scanCenter = Root.Position + Vector3.new(math.random(-150, 150), 0, math.random(-150, 150))
                                            radius = 0
                                            angle = 0
                                            Root.CFrame = CFrame.new(scanCenter) + Vector3.new(0, 20, 0)
                                            task.wait(0.5)
                                        else
                                            StatusText.Text = "AGUARDANDO COLETAR..."
                                            StatusText.TextColor3 = Color3.fromRGB(0, 255, 255)
                                            task.wait(2.5)
                                            
                                            if autoCollectActive and treasurePosition then
                                                local safeName = tostring(treasureName):gsub("%s+", ""):lower()
                                                local itemConfig = ValidItems[safeName]
                                                
                                                StatusText.Text = "COLETANDO: " .. safeName:upper()
                                                StatusText.TextColor3 = Color3.fromRGB(0, 255, 255)
                                                
                                                local collectWait = tick()
                                                while not itemCollected and tick() - collectWait < 6 and isGuiOpen and systemActive do
                                                    Events:Fire("ClaimTreasureItem", treasurePosition)
                                                    pcall(function()
                                                        for _, obj in ipairs(Workspace:GetDescendants()) do
                                                            if obj:IsA("ProximityPrompt") then
                                                                local aText = obj.ActionText:lower()
                                                                local oText = obj.ObjectText:lower()
                                                                local pName = obj.Name:lower()
                                                                if aText:match("coletar") or oText:match("coletar") or pName:match("coletar") or aText:match("collect") or oText:match("collect") then
                                                                    if obj.Parent and obj.Parent:IsA("BasePart") then
                                                                        if (obj.Parent.Position - treasurePosition).Magnitude < 15 then
                                                                            fireproximityprompt(obj)
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end)
                                                    task.wait(0.1) 
                                                end
                                                task.wait(0.3)

                                                local shouldSellItem = false
                                                if (safeName == "crown" or safeName == "cup" or safeName == "necklace") and autoSellRaroActive then
                                                    shouldSellItem = true
                                                elseif (safeName == "gear" or (itemConfig and itemConfig.sell)) and autoSellGearActive then
                                                    shouldSellItem = true
                                                end
                                                if shouldSellItem and character then performSellRoutine(character, safeName) end
                                            end
                                        end
                                        
                                        Hum:UnequipTools()
                                        task.wait(0.2)
                                        Events:Fire("equipItem", "Metal Detector")
                                        task.wait(0.4)
                                        local newDetector = LocalPlayer:WaitForChild("Backpack"):FindFirstChild("Metal Detector") or character:FindFirstChild("Metal Detector")
                                        if newDetector then 
                                            Hum:EquipTool(newDetector) 
                                            pcall(function() newDetector:Activate() end) 
                                        end
                                        StatusText.Text = "PROCURANDO NOVO GREEN..."
                                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                                        Hum.PlatformStand = true
                                    end
                                end
                            else
                                isCalculatingCenter = false
                                StatusText.Text = "ALVO PERDIDO! RETOMANDO..."
                            end
                            
                            isDigging = false
                            CurrentState = "red"
                            Hum.PlatformStand = true
                            lastStuckCheckTime = tick()
                            continue
                        end

                        if CurrentState == "yellow" then
                            scanCenter = Root.Position
                            radius = 1 
                            angle = 0
                            CurrentState = "searching_yellow" 
                        end

                        local currentStep = (CurrentState == "searching_yellow") and 0.5 or RADIUS_STEP
                        local currentAngleStep = (CurrentState == "searching_yellow") and 0.4 or ANGLE_STEP
                        local maxRad = (CurrentState == "searching_yellow") and 40 or MAX_RADIUS

                        if radius < maxRad then
                            local x = math.cos(angle) * radius
                            local z = math.sin(angle) * radius
                            
                            local checkPos = scanCenter + Vector3.new(x, 0, z)
                            local ground = getValidFloor(checkPos, character)
                            
                            if ground then
                                Root.AssemblyLinearVelocity = Vector3.zero
                                Root.CFrame = CFrame.new(ground) 
                                task.wait(0.05) 
                            end
                            
                            angle = angle + currentAngleStep
                            radius = radius + (currentStep / (6.28 / currentAngleStep))
                        else
                            scanCenter = Root.Position
                            radius = 0
                        end
                    end
                    Hum.PlatformStand = false
                end

                -- =========================================================================
                -- CONEXÕES DE BOTÕES E EVENTOS DE REDE
                -- =========================================================================
                CreateToggle("Master Scanner", 62, function(state)
                    systemActive = state
                    if systemActive then
                        StatusText.Text = "SISTEMA ATIVADO"
                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                        
                        Events:Fire("equipItem", "Metal Detector")
                        task.wait(0.5)
                        if LocalPlayer.Character then 
                            local Hum = LocalPlayer.Character:FindFirstChild("Humanoid")
                            local det = LocalPlayer:WaitForChild("Backpack"):FindFirstChild("Metal Detector") or LocalPlayer.Character:FindFirstChild("Metal Detector")
                            if Hum and det then
                                Hum:EquipTool(det)
                                pcall(function() det:Activate() end)
                            end
                            task.spawn(function() runTurboSpiral(LocalPlayer.Character) end) 
                        end
                    else
                        StatusText.Text = "SISTEMA DESATIVADO"
                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                        CurrentState = "red"
                        isCalculatingCenter = false
                    end
                end)

                CreateToggle("Auto Shovel (Cavar)", 98, function(state) autoShovelActive = state end)
                CreateToggle("Auto Collect (Coletar)", 134, function(state) autoCollectActive = state end)
                CreateToggle("Auto Sell (Coroa/Cup/Colar)", 170, function(state) autoSellRaroActive = state end)
                CreateToggle("Auto Sell (Engrenagens)", 206, function(state) autoSellGearActive = state end)

                CloseBtn.Activated:Connect(function()
                    if getgenv().AutoMetal_VS7x_Cleanup then getgenv().AutoMetal_VS7x_Cleanup() end
                end)

                Events:Bind("DetectorStateChanged", function(state)
                    if not systemActive then return end 
                    CurrentState = state
                    if state == "green" and not isDigging and not isCalculatingCenter then
                        StatusText.Text = "ALVO DETECTADO..."
                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                    elseif state == "yellow" and not isDigging and not isCalculatingCenter then
                        StatusText.Text = "ALVO PERTO! FILTRANDO..."
                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255)
                    elseif state == "red" and not isDigging and not isCalculatingCenter then
                        StatusText.Text = "PROCURANDO MAPA (RED)..."
                        StatusText.TextColor3 = Color3.fromRGB(255, 255, 255) 
                    end
                end)

                Events:Bind("VFX", function(vfxType, dropPos, dropPlayer, itemName)
                    if not systemActive then return end
                    if vfxType == "TreasureDrop" and dropPlayer == LocalPlayer then
                        treasureFound = true
                        treasurePosition = dropPos
                        treasureName = tostring(itemName) 
                    end
                end)

                Events:Bind("CollectTrash", function(collectedPos)
                    if not systemActive then return end
                    if treasurePosition and (collectedPos - treasurePosition).Magnitude < 15 then
                        itemCollected = true
                    end
                end)

                Events:Bind("notify", function(msg)
                    if not systemActive then return end
                    local matchItem, matchValue = string.match(tostring(msg), "Sold (.+) for (.+) silver credits!")
                    if matchItem and matchValue then
                        rareItemSoldConfirmation = true
                    end
                end)

                local function initCharacter(char)
                    if not isGuiOpen then return end
                    task.spawn(function()
                        task.wait(1) 
                        if systemActive then
                            Events:Fire("equipItem", "Metal Detector")
                            task.wait(0.5)
                            local Hum = char:WaitForChild("Humanoid", 999)
                            local det = LocalPlayer:WaitForChild("Backpack"):FindFirstChild("Metal Detector") or char:FindFirstChild("Metal Detector")
                            if det then
                                Hum:EquipTool(det)
                                pcall(function() det:Activate() end)
                            end
                            runTurboSpiral(char)
                        end
                    end)
                end
                LocalPlayer.CharacterAdded:Connect(initCharacter)
            end
        end)
    end)

else
    local emptyMsg = Instance.new("TextLabel", ExploitsContainer)
    emptyMsg.Size = UDim2.new(1, 0, 0, 50)
    emptyMsg.BackgroundTransparency = 1
    emptyMsg.Text = "There is nothing here.."
    emptyMsg.TextColor3 = Color3.fromRGB(150, 150, 150)
    emptyMsg.Font = Enum.Font.GothamMedium
    emptyMsg.TextSize = 14
end

