local function criarBotaoServer(txt, iconId)
    local btn = Instance.new("TextButton", GUI.HSCBtnContainer)
    btn.BackgroundColor3 = Color3.fromRGB(18, 18, 22)
    btn.Text = ""
    btn.AutoButtonColor = false
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)
    local strk = Instance.new("UIStroke", btn)
    strk.Color = Color3.fromRGB(255, 255, 255)
    strk.Transparency = 0.85
    strk.Thickness = 1.2
    
    local icon = Instance.new("ImageLabel", btn)
    icon.Size = UDim2.new(0, 14, 0, 14)
    icon.Position = UDim2.new(0, 10, 0.5, -7)
    icon.BackgroundTransparency = 1
    icon.Image = "rbxassetid://" .. iconId
    icon.ImageColor3 = Color3.fromRGB(255, 255, 255)
    
    local lbl = Instance.new("TextLabel", btn)
    lbl.Size = UDim2.new(1, -30, 1, 0)
    lbl.Position = UDim2.new(0, 30, 0, 0)
    lbl.BackgroundTransparency = 1
    lbl.Text = txt
    lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 10
    lbl.TextXAlignment = Enum.TextXAlignment.Left

    btn.MouseEnter:Connect(function() pcall(function() game:GetService("TweenService"):Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(255, 255, 255)}):Play(); game:GetService("TweenService"):Create(lbl, TweenInfo.new(0.2), {TextColor3 = Color3.fromRGB(0, 0, 0)}):Play(); game:GetService("TweenService"):Create(icon, TweenInfo.new(0.2), {ImageColor3 = Color3.fromRGB(0, 0, 0)}):Play() end) end)
    btn.MouseLeave:Connect(function() pcall(function() game:GetService("TweenService"):Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(18, 18, 22)}):Play(); game:GetService("TweenService"):Create(lbl, TweenInfo.new(0.2), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play(); game:GetService("TweenService"):Create(icon, TweenInfo.new(0.2), {ImageColor3 = Color3.fromRGB(255, 255, 255)}):Play() end) end)
    
    btn.MouseButton1Down:Connect(PlayServerClick)
    return btn, lbl
end

