GUI.HomeNextBtn.MouseButton1Click:Connect(function()
    if type(S7xNotify) == "function" then S7xNotify("SERVER", "Searching for active server...") end
    GUI.HomeNextLbl.Text = "SEARCHING..."
    task.spawn(function()
        local success, result = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Desc&limit=100") end)
        if success and result then
            local decoded = game:GetService("HttpService"):JSONDecode(result)
            if decoded and decoded.data then
                for _, server in ipairs(decoded.data) do
                    if server.id ~= game.JobId and server.playing > 0 and server.playing < server.maxPlayers then
                        GUI.HomeNextLbl.Text = "TELEPORTING..."
                        game:GetService("TeleportService"):TeleportToPlaceInstance(game.PlaceId, server.id, game.Players.LocalPlayer)
                        return
                    end
                end
            end
        end
        GUI.HomeNextLbl.Text = "NOT FOUND"
        task.delay(1.5, function() if GUI.HomeNextBtn then GUI.HomeNextLbl.Text = "NEXT" end end)
    end)
end)

