GUI.RenderServerCard = function(data, layoutOrder)
    local card = Instance.new("Frame", GUI.ServerListContainer)
    card.Size = UDim2.new(1, 0, 0, 85) 
    card.LayoutOrder = layoutOrder
    card.BackgroundColor3 = Color3.fromRGB(12, 12, 14)
    Instance.new("UICorner", card).CornerRadius = UDim.new(0, 12)
    local cardStroke = Instance.new("UIStroke", card)
    cardStroke.Color = Color3.fromRGB(255, 255, 255)
    cardStroke.Transparency = 0.85
    cardStroke.Thickness = 1.2
    
    local icon = Instance.new("ImageLabel", card)
    icon.Size = UDim2.new(0, 55, 0, 55)
    icon.Position = UDim2.new(0, 15, 0.5, -27.5)
    icon.BackgroundColor3 = Color3.fromRGB(5, 5, 5)
    Instance.new("UICorner", icon).CornerRadius = UDim.new(1, 0) -- Sempre redondo para padronizar
    Instance.new("UIStroke", icon).Color = Color3.fromRGB(255, 255, 255)
    
    if data.isFriend and data.friendId then
        icon.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(data.friendId) .. "&w=150&h=150"
    else
        icon.Image = "rbxthumb://type=Asset&id=" .. game.PlaceId .. "&w=150&h=150" 
    end
    
    local info = Instance.new("TextLabel", card)
    info.Size = UDim2.new(1, -190, 1, 0)
    info.Position = UDim2.new(0, 85, 0, 0)
    info.BackgroundTransparency = 1
    info.RichText = true
    
    if data.isFriend then
        info.Text = "<b><font color='#ffffff'>"..string.upper(data.friendDisplay).."</font></b> <font size='10' color='#888888'>(@"..data.friendUser..")</font>\nStatus: <font color='#aaaaaa'>"..data.locStr.."</font>\nServer ID: <font color='#666666'>"..string.sub(data.jobId, 1, 8).."...</font>"
    else
        info.Text = "<b><font color='#ffffff'>PUBLIC SERVER</font></b>\nPlayers: <font color='#aaaaaa'>"..data.playing.."/"..data.maxPlayers.."</font> | Ping: <font color='#aaaaaa'>"..data.ping.."ms</font>\nServer ID: <font color='#666666'>"..string.sub(data.jobId, 1, 8).."...</font>"
    end
    
    info.TextColor3 = Color3.fromRGB(255, 255, 255)
    info.Font = Enum.Font.GothamMedium
    info.TextSize = 11
    info.TextXAlignment = Enum.TextXAlignment.Left
    
    local joinBtn = Instance.new("TextButton", card)
    joinBtn.Size = UDim2.new(0, 80, 0, 36)
    joinBtn.Position = UDim2.new(1, -95, 0.5, -18)
    joinBtn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    joinBtn.Text = "JOIN"
    joinBtn.TextColor3 = Color3.fromRGB(0, 0, 0)
    joinBtn.Font = Enum.Font.GothamBlack
    joinBtn.TextSize = 11
    joinBtn.AutoButtonColor = false
    Instance.new("UICorner", joinBtn).CornerRadius = UDim.new(0, 8)
    
    joinBtn.MouseEnter:Connect(function() if SafeTween then SafeTween(joinBtn, 0.2, {BackgroundColor3 = Color3.fromRGB(200, 200, 200)}) end end)
    joinBtn.MouseLeave:Connect(function() if SafeTween then SafeTween(joinBtn, 0.2, {BackgroundColor3 = Color3.fromRGB(255, 255, 255)}) end end)
    
    joinBtn.MouseButton1Down:Connect(PlayServerClick)
    joinBtn.MouseButton1Click:Connect(function()
        joinBtn.Text = "..."
        if type(S7xNotify) == "function" then S7xNotify("TELEPORT", "Conectando ao servidor...") end
        game:GetService("TeleportService"):TeleportToPlaceInstance(game.PlaceId, data.jobId, game.Players.LocalPlayer)
    end)
end

PopulateServers = function()
    if GUI.IsFetchingServers then return end
    GUI.IsFetchingServers = true
    scanLbl.Text = "SCANNING..."
    for _, v in pairs(GUI.ServerListContainer:GetChildren()) do if v:IsA("Frame") then v:Destroy() end end
    
    task.spawn(function()
        local layoutCount = 1
        local s_friends, friendsList = pcall(function() return game.Players.LocalPlayer:GetFriendsOnline(200) end)
        if s_friends and friendsList then
            for _, friend in ipairs(friendsList) do
                if friend.PlaceId == game.PlaceId and friend.GameId ~= game.JobId and friend.GameId ~= "" then
                    GUI.RenderServerCard({isFriend = true, friendId = friend.VisitorId, friendName = friend.UserName, friendDisplay = friend.DisplayName, friendUser = friend.UserName, jobId = friend.GameId, locStr = friend.LastLocation or "Active Server"}, layoutCount)
                    layoutCount = layoutCount + 1
                end
            end
        end
        
        local s_public, result = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Desc&limit=100") end)
        if s_public and result then
            local decoded = game:GetService("HttpService"):JSONDecode(result)
            if decoded and decoded.data then
                for _, server in ipairs(decoded.data) do
                    if server.id ~= game.JobId and server.playing < server.maxPlayers then
                        GUI.RenderServerCard({isFriend = false, jobId = server.id, ping = server.ping, playing = server.playing, maxPlayers = server.maxPlayers}, layoutCount)
                        layoutCount = layoutCount + 1
                    end
                end
            end
        end
        scanLbl.Text = "SCAN SERVERS & FRIENDS"
        GUI.IsFetchingServers = false
    end)
end

GUI.RefreshServersBtn.MouseButton1Click:Connect(PopulateServers)

