    RedeemStatus.BackgroundTransparency = 1
    RedeemStatus.Text = "Add more time to your current session."
    RedeemStatus.TextColor3 = Color3.fromRGB(150, 150, 150)
    RedeemStatus.Font = Enum.Font.GothamMedium
    RedeemStatus.TextSize = 9
    RedeemStatus.TextXAlignment = Enum.TextXAlignment.Left

    local isAddingTime = false
    RedeemBtn.MouseButton1Click:Connect(function()
        if isAddingTime then return end
        local codeInput = KeyInput.Text:gsub("%s+", "")
        if codeInput == "" then 
            RedeemStatus.Text = "PLEASE ENTER A VALID KEY."
            RedeemStatus.TextColor3 = Color3.fromRGB(255, 50, 50)
            return 
        end
        
        isAddingTime = true
        RedeemBtn.Text = "..."
        RedeemStatus.Text = "VERIFYING IN SUPABASE..."
        RedeemStatus.TextColor3 = Color3.fromRGB(255, 255, 255)

        task.spawn(function()
            local HttpService = game:GetService("HttpService")
            local lp = game:GetService("Players").LocalPlayer

            if type(_G.SupabaseReq) ~= "function" then
                RedeemStatus.Text = "CONNECTION FAILED"
                RedeemStatus.TextColor3 = Color3.fromRGB(255, 50, 50)
                isAddingTime = false; RedeemBtn.Text = "ADD TIME"
                return
            end

            local res = _G.SupabaseReq("/s7x_keys?code=eq." .. codeInput, "GET")
            if res and res.Body then
                local decoded = HttpService:JSONDecode(res.Body)
                if type(decoded) == "table" and #decoded > 0 then
                    local keyData = decoded[1]
                    
                    if keyData.used == true then
                        RedeemStatus.Text = "THIS KEY HAS ALREADY BEEN REDEEMED!"
                        RedeemStatus.TextColor3 = Color3.fromRGB(255, 50, 50)
                    else
                        _G.SupabaseReq("/s7x_keys?code=eq." .. codeInput, "PATCH", { used = true, redeemed_by = tostring(lp.UserId) })
                        _G.S7xActiveKey = codeInput -- [ ATUALIZA O DAEMON EM TEMPO REAL ]
                        
                        -- O Segredo do Acúmulo de Tempo: 
                        -- Usa o tempo de expiração atual se ele ainda existir, ou usa a hora atual se a key anterior tiver zerado.
                        local baseTime = (testerExpiration and testerExpiration > os.time()) and testerExpiration or os.time()
                        local newExpiration = baseTime + durationSecs
                        
                        pcall(function()
                            testerExpiration = newExpiration
                            if writefile then
                                table.insert(redeemedCodes, codeInput)
                                local saveData = { expiration = testerExpiration, redeemedCodes = redeemedCodes }
                                writefile("S7x_Tester.json", HttpService:JSONEncode(saveData))
                            end
                        end)
                        
                        local addedHours = math.floor(durationSecs / 3600)
                        RedeemStatus.Text = "SUCCESS! ADDED " .. addedHours .. " HOURS TO YOUR ACCESS."
                        RedeemStatus.TextColor3 = Color3.fromRGB(0, 255, 100)
                        KeyInput.Text = ""
                        
                        -- Força a visualização e atualização do Display de Tempo no Menu
                        if GUI.TesterTimerFrame then GUI.TesterTimerFrame.Visible = true end
                    end
                else
                    RedeemStatus.Text = "INVALID OR NON-EXISTENT KEY!"
                    RedeemStatus.TextColor3 = Color3.fromRGB(255, 50, 50)
                end
            else
                RedeemStatus.Text = "ERROR CONTACTING SUPABASE"
                RedeemStatus.TextColor3 = Color3.fromRGB(255, 50, 50)
            end
            
            isAddingTime = false
            RedeemBtn.Text = "ADD TIME"
            
            -- Retorna o painel ao texto original após 4 segundos para manter o design fluído
            task.delay(4, function()
                if RedeemStatus and not isAddingTime then
                    RedeemStatus.Text = "Add more time to your current session."
                    RedeemStatus.TextColor3 = Color3.fromRGB(150, 150, 150)
                end
            end)
        end)
    end)

