    local function SwitchToView(isAbout)
        if isAbout then
            AboutContent.Visible = true
            TeamContent.Visible = false
            AboutBtn.Title.TextColor3 = Color3.fromRGB(255, 255, 255)
            AboutBtn.Icon.ImageColor3 = Color3.fromRGB(255, 255, 255)
            AboutBtn.Accent.Visible = true
            TeamBtn.Title.TextColor3 = Color3.fromRGB(150, 150, 150)
            TeamBtn.Icon.ImageColor3 = Color3.fromRGB(150, 150, 150)
            TeamBtn.Accent.Visible = false
        else
            AboutContent.Visible = false
            TeamContent.Visible = true
            
            -- Reseta sempre para a lista quando abre a aba Team
            TeamList.Visible = true
            TeamProfileView.Visible = false
            TeamContent.Size = UDim2.new(1, 0, 0, tlLayout.AbsoluteContentSize.Y + 40)

            TeamBtn.Title.TextColor3 = Color3.fromRGB(255, 255, 255)
            TeamBtn.Icon.ImageColor3 = Color3.fromRGB(255, 255, 255)
            TeamBtn.Accent.Visible = true
            AboutBtn.Title.TextColor3 = Color3.fromRGB(150, 150, 150)
            AboutBtn.Icon.ImageColor3 = Color3.fromRGB(150, 150, 150)
            AboutBtn.Accent.Visible = false
        end
    end

    AboutBtn.MouseButton1Click:Connect(function() SwitchToView(true) end)
    TeamBtn.MouseButton1Click:Connect(function() SwitchToView(false) end)
    
    -- Inicia na aba About
    SwitchToView(true)
end)

