            if userCustomData_tagUI and userCustomData_tagUI.CustomName and userCustomData_tagUI.CustomName ~= "" then 
                displayName_tagUI = userCustomData_tagUI.CustomName 
            else 
                displayName_tagUI = "Custom" 
            end
        elseif _G.CustomTagsConfig and _G.CustomTagsConfig[tag_name] and _G.CustomTagsConfig[tag_name].CustomName and _G.CustomTagsConfig[tag_name].CustomName ~= "" then 
