RefreshAurasUI = function()
    for _, v in pairs(GUI.AurasFrame:GetChildren()) do
        if v:IsA("Frame") or v:IsA("UIGridLayout") or v:IsA("UIListLayout") or v:IsA("UIPadding") then v:Destroy() end
    end
    
    local layout = Instance.new("UIGridLayout", GUI.AurasFrame)
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.CellPadding = UDim2.new(0, 12, 0, 12)
    layout.CellSize = UDim2.new(0.47, 0, 0, 65)

    local padding = Instance.new("UIPadding", GUI.AurasFrame)
    padding.PaddingTop = UDim.new(0, 15)
    padding.PaddingBottom = UDim.new(0, 30)

    local isAdmin_ui = false
    local unlockedAuras_ui = {["None"] = true}
    local myRank = GetFirebaseRank(game.Players.LocalPlayer)
    
    local function processAuraRank(r)
        if not r then return end
        if r == "Creator" or r == "Co-Owner" then r = "Owner" end
        if r == "Developers" or r == "Dev" then r = "Developer" end

        if TagAdminRoles and TagAdminRoles[r] then isAdmin_ui = true end
        
        if r == "Owner" then
            unlockedAuras_ui["Contributor"] = true;
            unlockedAuras_ui["Influencer"] = true; 
            unlockedAuras_ui["Ultimate"] = true; unlockedAuras_ui["Supreme"] = true; unlockedAuras_ui["Owner"] = true
        elseif r == "Supreme" then
            unlockedAuras_ui["Contributor"] = true;
            unlockedAuras_ui["Influencer"] = true; 
            unlockedAuras_ui["Ultimate"] = true; unlockedAuras_ui["Supreme"] = true
        elseif r == "Ultimate" then
            unlockedAuras_ui["Contributor"] = true;
            unlockedAuras_ui["Influencer"] = true; unlockedAuras_ui["Ultimate"] = true
        elseif r == "Influencer" then
            unlockedAuras_ui["Contributor"] = true;
            unlockedAuras_ui["Influencer"] = true
        elseif r == "Contributor" then
            unlockedAuras_ui["Contributor"] = true
        end
    end

    processAuraRank(myRank)
    
    if myRank == "Owner" or myRank == "Co-Owner" or myRank == "Creator" then
        unlockedAuras_ui["Custom"] = true
    end
    
    local userAuraData = _G.CustomAurasConfig and _G.CustomAurasConfig[tostring(game.Players.LocalPlayer.UserId)]
    if userAuraData and userAuraData.Unlocked then
        for k, v in pairs(userAuraData.Unlocked) do
            local aName = type(k) == "number" and v or k
            if v == true or v == "true" or type(k) == "number" then
                unlockedAuras_ui[aName] = true
            end
        end
    end

    if isAdmin_ui and myRank ~= "Friends" then
        unlockedAuras_ui["Contributor"] = true;
        unlockedAuras_ui["Influencer"] = true; 
        unlockedAuras_ui["Ultimate"] = true; unlockedAuras_ui["Supreme"] = true
    end

    local displayOrder_ui = {"None", "Contributor", "Influencer", "Ultimate", "Supreme", "Owner", "Custom"}
    local layoutOrder_ui = 1

    local auraColors = {
        ["None"] = Color3.fromRGB(150, 150, 150),
        ["Contributor"] = Color3.fromRGB(255, 85, 0),
        ["Influencer"] = Color3.fromRGB(255, 20, 147),
        ["Ultimate"] = Color3.fromRGB(0, 255, 255),
        ["Supreme"] = Color3.fromRGB(138, 43, 226),
        ["Owner"] = Color3.fromRGB(255, 40, 0),
        ["Custom"] = Color3.fromRGB(0, 255, 150)
    }

    for _, auraName_ui in ipairs(displayOrder_ui) do
        local aColor = auraColors[auraName_ui] or Color3.fromRGB(200, 200, 200)
        local card_ui = Instance.new("Frame", GUI.AurasFrame)
        card_ui.Name = "AuraCard"; card_ui.BackgroundColor3 = Color3.fromRGB(18, 18, 22); card_ui.LayoutOrder = layoutOrder_ui
        Instance.new("UICorner", card_ui).CornerRadius = UDim.new(0, 8)
        
        local strk_ui = Instance.new("UIStroke", card_ui)
        strk_ui.Name = "CardStroke"; strk_ui.Color = aColor; strk_ui.Thickness = 1.5; strk_ui.Transparency = 0.5
        
        local glow_ui = Instance.new("ImageLabel", card_ui)
        glow_ui.Name = "CardGlow"; glow_ui.BackgroundTransparency = 1; glow_ui.Position = UDim2.new(0, -15, 0, -15); glow_ui.Size = UDim2.new(1, 30, 1, 30);
        glow_ui.Image = "rbxassetid://1316045217"; glow_ui.ImageColor3 = aColor; glow_ui.ImageTransparency = 0.8; glow_ui.ZIndex = 0

        local title_ui = Instance.new("TextLabel", card_ui)
        title_ui.Name = "AuraTitle"; title_ui.Size = UDim2.new(1, 0, 0.45, 0); title_ui.Position = UDim2.new(0, 0, 0, 3);
        title_ui.BackgroundTransparency = 1; title_ui.ZIndex = 2
        
        local displayName_ui = auraName_ui
        if auraName_ui == "None" then displayName_ui = "UNEQUIP" end
        if auraName_ui == "Custom" then displayName_ui = "CUSTOMIZED" end

        title_ui.Text = string.upper(displayName_ui);
        title_ui.TextColor3 = aColor; title_ui.Font = Enum.Font.GothamBlack; title_ui.TextSize = 12

        local btn_ui = Instance.new("TextButton", card_ui)
        btn_ui.Name = "ActionBtn"; btn_ui.Size = UDim2.new(0.85, 0, 0.4, 0); btn_ui.Position = UDim2.new(0.075, 0, 0.5, 0);
        btn_ui.Font = Enum.Font.GothamBold; btn_ui.TextSize = 11; btn_ui.AutoButtonColor = false; btn_ui.ZIndex = 2
        Instance.new("UICorner", btn_ui).CornerRadius = UDim.new(0, 6)
        
        local stringVal = Instance.new("StringValue", btn_ui)
        stringVal.Name = "AuraRef"; stringVal.Value = auraName_ui

        if unlockedAuras_ui[auraName_ui] then
            if _G.EquippedAura == auraName_ui or (not _G.EquippedAura and auraName_ui == "None") then
                btn_ui.Text = "EQUIPPED"; btn_ui.BackgroundColor3 = aColor; btn_ui.TextColor3 = Color3.fromRGB(255, 255, 255);
                strk_ui.Transparency = 0; glow_ui.ImageTransparency = 0.5
            else
                btn_ui.Text = "EQUIP"; btn_ui.BackgroundColor3 = Color3.fromRGB(30, 30, 35); btn_ui.TextColor3 = Color3.fromRGB(200, 200, 210);
                strk_ui.Transparency = 0.6; glow_ui.ImageTransparency = 0.9
            end
            
            btn_ui.MouseButton1Click:Connect(function()
                _G.EquippedAura = auraName_ui
                local uidStr = tostring(game.Players.LocalPlayer.UserId)
                if not _G.CustomAurasConfig then _G.CustomAurasConfig = {} end
                if not _G.CustomAurasConfig[uidStr] then _G.CustomAurasConfig[uidStr] = {} end
                _G.CustomAurasConfig[uidStr].Equipped = auraName_ui

                for _, child in pairs(GUI.AurasFrame:GetChildren()) do
                    if child:IsA("Frame") and child.Name == "AuraCard" then
                        local actBtn = child:FindFirstChild("ActionBtn")
                        local cStrk = child:FindFirstChild("CardStroke")
                        local cGlow = child:FindFirstChild("CardGlow")
                        if actBtn and actBtn:FindFirstChild("AuraRef") then
                            local refColor = auraColors[actBtn.AuraRef.Value] or Color3.fromRGB(200, 200, 200)
                            if actBtn.AuraRef.Value == _G.EquippedAura then
                                actBtn.Text = "EQUIPPED"; actBtn.BackgroundColor3 = refColor; actBtn.TextColor3 = Color3.fromRGB(255, 255, 255);
                                if cStrk then cStrk.Transparency = 0 end; if cGlow then cGlow.ImageTransparency = 0.5 end
                            else
                                if unlockedAuras_ui[actBtn.AuraRef.Value] then
                                    actBtn.Text = "EQUIP"; actBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 35); actBtn.TextColor3 = Color3.fromRGB(200, 200, 210);
                                    if cStrk then cStrk.Transparency = 0.6 end; if cGlow then cGlow.ImageTransparency = 0.9 end
                                end
                            end
                        end
                    end
                end
                
                if type(ApplyS7xAura) == "function" then ApplyS7xAura(game.Players.LocalPlayer) end
                if type(SaveS7xSettings) == "function" then SaveS7xSettings() end
                if type(SendPresence) == "function" then task.spawn(SendPresence) end
                
                task.spawn(function()
                    pcall(function()
                        local myAuraData = _G.CustomAurasConfig[tostring(game.Players.LocalPlayer.UserId)] or {}
                        myAuraData.Equipped = auraName_ui
                        _G.SupabaseReq("/auras?on_conflict=id", "POST", { id = tostring(game.Players.LocalPlayer.UserId), payload = myAuraData })
                    end)
                end)
            end)
        else
            btn_ui.Text = "LOCKED"; btn_ui.BackgroundColor3 = Color3.fromRGB(15, 15, 18); btn_ui.TextColor3 = Color3.fromRGB(100, 100, 110);
            title_ui.TextColor3 = Color3.fromRGB(100, 100, 110); strk_ui.Color = Color3.fromRGB(30, 30, 35);
            glow_ui.ImageTransparency = 1
        end
        layoutOrder_ui = layoutOrder_ui + 1
    end
    layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() GUI.AurasFrame.CanvasSize = UDim2.new(0, 0, 0, layout.AbsoluteContentSize.Y + 40) end)
end

