        avatarHoldTick = tick()
        
        -- Anima a borda enchendo enquanto segura
        pcall(function() game:GetService("TweenService"):Create(GUI.AvatarStroke, TweenInfo.new(avatarHoldTime, Enum.EasingStyle.Linear), {Thickness = 5}):Play() end)
        
        task.spawn(function()
            while isAvatarHolding do
                if tick() - avatarHoldTick >= avatarHoldTime then
                    isAvatarHolding = false
                    local myId = tostring(game.Players.LocalPlayer.UserId)
                    
                    -- Copia o ID
                    pcall(function() if setclipboard then setclipboard(myId) end end)
                    if type(S7xNotify) == "function" then S7xNotify("ID COPIED", "Seu ID (" .. myId .. ") foi copiado!") end
                    
                    -- Feedback visual (Pulo do Avatar e reset da borda)
                    pcall(function() 
                        local ts = game:GetService("TweenService")
                        ts:Create(GUI.AvatarStroke, TweenInfo.new(0.2), {Thickness = 2.5}):Play()
                        ts:Create(GUI.AvatarContainer, TweenInfo.new(0.15, Enum.EasingStyle.Bounce), {Size = UDim2.new(0, 85, 0, 85), Position = UDim2.new(0, 10, 0.5, -42.5)}):Play()
                        task.delay(0.15, function() ts:Create(GUI.AvatarContainer, TweenInfo.new(0.15, Enum.EasingStyle.Bounce), {Size = UDim2.new(0, 75, 0, 75), Position = UDim2.new(0, 15, 0.5, -37.5)}):Play() end)
                    end)
                    break
                end
                game:GetService("RunService").Heartbeat:Wait()
            end
        end)
    end
end)

