local function UpdateHomeAnimatedAvatar(targetChar)
    if not targetChar then return end
    for _, v in ipairs(GUI.HomeWorldModel:GetChildren()) do v:Destroy() end
    targetChar.Archivable = true
    local clone = targetChar:Clone()
    for _, v in ipairs(clone:GetDescendants()) do
        if v:IsA("Script") or v:IsA("LocalScript") then v:Destroy() end
    end
    clone.Parent = GUI.HomeWorldModel
    clone:PivotTo(CFrame.new(0, 0, 0) * CFrame.Angles(0, math.pi, 0))
    local hrp = clone:FindFirstChild("Head") or clone.PrimaryPart
    if hrp then GUI.HomeCam.CFrame = CFrame.new(Vector3.new(0, 1.2, 4.5), Vector3.new(0, 1.2, 0)) end
    local hum = clone:FindFirstChild("Humanoid")
    if hum then
        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
        local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
        local animate = targetChar:FindFirstChild("Animate")
        if animate then
            local idle = animate:FindFirstChild("idle")
            local anim = idle and idle:FindFirstChildOfClass("Animation")
            if anim then pcall(function() animator:LoadAnimation(anim):Play() end) end
        end
    end
end
if game.Players.LocalPlayer.Character then UpdateHomeAnimatedAvatar(game.Players.LocalPlayer.Character) end
game.Players.LocalPlayer.CharacterAdded:Connect(function(char) task.wait(0.5) UpdateHomeAnimatedAvatar(char) end)
game.Players.LocalPlayer.CharacterAppearanceLoaded:Connect(function(char) UpdateHomeAnimatedAvatar(char) end)

