local function createTagButton(tagName)
    local btn = Instance.new("TextButton", tagListContainer)
    btn.BackgroundColor3 = (_G.EquippedTag == tagName or (not _G.EquippedTag and tagName == getMyTag())) and Color3.fromRGB(170, 0, 255) or Color3.fromRGB(20, 20, 25)
    btn.Text = string.upper(tagName)
    btn.TextColor3 = (_G.EquippedTag == tagName or (not _G.EquippedTag and tagName == getMyTag())) and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(200, 200, 200)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 11
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
    local strk = Instance.new("UIStroke", btn)
    strk.Color = (_G.EquippedTag == tagName or (not _G.EquippedTag and tagName == getMyTag())) and Color3.fromRGB(200, 100, 255) or Color3.fromRGB(45, 45, 55)

    btn.MouseButton1Click:Connect(function()
        _G.EquippedTag = tagName
        if type(SaveS7xSettings) == "function" then SaveS7xSettings() end
        if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(game.Players.LocalPlayer) end
        if type(_G.BroadcastInstantUpdate) == "function" then _G.BroadcastInstantUpdate() end
        
        for _, b in ipairs(tagListContainer:GetChildren()) do
            if b:IsA("TextButton") then
                local s = b:FindFirstChildOfClass("UIStroke")
                if b.Text == string.upper(tagName) then
                    game:GetService("TweenService"):Create(b, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(170, 0, 255), TextColor3 = Color3.fromRGB(255, 255, 255)}):Play()
                    if s then s.Color = Color3.fromRGB(200, 100, 255) end
                else
                    game:GetService("TweenService"):Create(b, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(20, 20, 25), TextColor3 = Color3.fromRGB(200, 200, 200)}):Play()
                    if s then s.Color = Color3.fromRGB(45, 45, 55) end
                end
            end
        end
    end)
end

-- ==========================================
-- [ MOTOR SUPREMO DE GESTÃO DE TAGS (STRICT LIMIT: 1 BASE + 1 CUSTOM) ]
-- ==========================================
_G.S7xRefreshMyTagsUI = function()
    if not tagListContainer then return end
    
    -- 1. Extermina todas as tags antigas da interface (Evita acúmulo de cargos antigos)
    for _, child in ipairs(tagListContainer:GetChildren()) do
        if child:IsA("TextButton") then child:Destroy() end
    end
    
    -- 2. Define o Cargo Base Absoluto do jogador em Tempo Real
    local myRank = "User"
    if type(GetFirebaseRank) == "function" then 
        myRank = GetFirebaseRank(game.Players.LocalPlayer) or "User" 
    end
    
    -- Normalização de nomenclaturas
    if myRank == "Members" then myRank = "Member" end
    if myRank == "Developers" or myRank == "Dev" then myRank = "Developer" end
    if myRank == "Creator" then myRank = "Owner" end

    -- 3. Injeta a Tag Padrão (Obrigatoriamente a 1ª Tag)
    createTagButton(myRank)
    
    -- 4. Verifica permissão ESTRITA para a Tag Custom (Apenas a 2ª Tag)
    local allowedCustom = {
        ["Contributor"] = true, ["Helper"] = true, ["Marketing"] = true, 
        ["Developer"] = true, ["Manager"] = true, ["Supervisor"] = true, 
        ["Co-Owner"] = true, ["Owner"] = true, ["Dev"] = true
    }
    
    local hasCustomAccess = allowedCustom[myRank] or false
    
    if hasCustomAccess then
        createTagButton("Custom")
    else
        -- Se foi rebaixado para Supreme/Ultimate/User, força o desequipamento da Custom
        if _G.EquippedTag == "Custom" then
            _G.EquippedTag = myRank
            if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(game.Players.LocalPlayer) end
            if type(_G.BroadcastInstantUpdate) == "function" then _G.BroadcastInstantUpdate() end
        end
    end

    -- Se a tag equipada não for nem a base nem a Custom, reseta e equipa a base
    if _G.EquippedTag ~= myRank and _G.EquippedTag ~= "Custom" then
        _G.EquippedTag = myRank
        if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(game.Players.LocalPlayer) end
    end

    -- 5. Atualiza as dimensões e cores para a nova estrutura de 1 a 2 botões
    tagListContainer.Size = UDim2.new(1, -30, 0, tagGrid.AbsoluteContentSize.Y)
    GUI.MyTagsCard.Size = UDim2.new(0.95, 0, 0, tagGrid.AbsoluteContentSize.Y + 85)
    if GUI.InicioFrame and GUI.HomeLayout then
        GUI.InicioFrame.CanvasSize = UDim2.new(0, 0, 0, GUI.HomeLayout.AbsoluteContentSize.Y + 40)
    end
    
    for _, b in ipairs(tagListContainer:GetChildren()) do
        if b:IsA("TextButton") then
            local s = b:FindFirstChildOfClass("UIStroke")
            local equipCheck = _G.EquippedTag or myRank
            
            if b.Text == string.upper(equipCheck) then
                b.BackgroundColor3 = Color3.fromRGB(170, 0, 255)
                b.TextColor3 = Color3.fromRGB(255, 255, 255)
                if s then s.Color = Color3.fromRGB(200, 100, 255) end
            else
                b.BackgroundColor3 = Color3.fromRGB(20, 20, 25)
                b.TextColor3 = Color3.fromRGB(200, 200, 200)
                if s then s.Color = Color3.fromRGB(45, 45, 55) end
            end
        end
    end
end

-- ==========================================
-- [ DAEMON DE SINCRONIZAÇÃO EM TEMPO REAL (ZERO DB SPAM) ]
-- ==========================================
-- Monitora a memória local a cada 2 segundos. Se você receber uma tag via
-- painel de dono ou sistema, a UI S7x percebe a mudança de RAM e recria os botões na hora.
if _G.S7xTagSyncDaemon then task.cancel(_G.S7xTagSyncDaemon) end
_G.S7xTagSyncDaemon = task.spawn(function()
    local lastRank = nil
    while task.wait(2) do
        pcall(function()
            if not tagListContainer or not tagListContainer.Parent then return end
            
            local currentRank = "User"
            if type(GetFirebaseRank) == "function" then 
                currentRank = GetFirebaseRank(game.Players.LocalPlayer) or "User" 
            end
            
            if currentRank == "Members" then currentRank = "Member" end
            if currentRank == "Developers" or currentRank == "Dev" then currentRank = "Developer" end
            if currentRank == "Creator" then currentRank = "Owner" end
            
            -- Se o cargo mudar silenciosamente no cache, re-renderiza a tela!
            if lastRank ~= currentRank then
                lastRank = currentRank
                if type(_G.S7xRefreshMyTagsUI) == "function" then
                    _G.S7xRefreshMyTagsUI()
                end
            end
        end)
    end
end)

-- Hooks nativos para garantir a chamada por outras funções
_G.S7xUnlockAndEquipTag = function(tagName)
    if tagName ~= "Custom" then _G.EquippedTag = tagName end
    if type(_G.S7xRefreshMyTagsUI) == "function" then _G.S7xRefreshMyTagsUI() end
    if type(SaveS7xSettings) == "function" then SaveS7xSettings() end
    if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(game.Players.LocalPlayer) end
    if type(_G.BroadcastInstantUpdate) == "function" then _G.BroadcastInstantUpdate() end
end

_G.S7xUnlockCustomTagUI = function()
    if type(_G.S7xRefreshMyTagsUI) == "function" then _G.S7xRefreshMyTagsUI() end
end

