_G.S7xSessionStart = _G.S7xSessionStart or tick()

task.spawn(function()
    local RS = game:GetService("RunService")
    local Stats = game:GetService("Stats")
    local frames, lastUpdate = 0, tick()
    
    RS.RenderStepped:Connect(function()
        local now = tick()
        frames = frames + 1
        
        if now - lastUpdate >= 1 then
            if GUI.FpsLabel and GUI.FpsLabel.Parent then
                local currentTag = getMyTag()
                local tagBaseColor = getBaseColor(currentTag)
                
                if GUI.PlayerTagLabel then
                    GUI.PlayerTagLabel.Text = string.upper(currentTag)
                    GUI.TagBadge.UIStroke.Color = tagBaseColor
                end
            
                local fps = math.floor(frames / (now - lastUpdate))
                GUI.FpsLabel.Text = "FPS: " .. fps
                local ping = math.round(game.Players.LocalPlayer:GetNetworkPing() * 1000)
                GUI.PingLabel.Text = "PING: " .. ping .. " MS"
                local mem = math.floor(Stats:GetTotalMemoryUsageMb())
                GUI.CpuLabel.Text = "MEM: " .. mem .. " MB"
                
                local sessionTime = now - _G.S7xSessionStart
                local h = math.floor(sessionTime / 3600)
                local m = math.floor((sessionTime % 3600) / 60)
                local s = math.floor(sessionTime % 60)
                GUI.SessionLabel.Text = string.format("TIME: %02d:%02d:%02d", h, m, s)
                
                frames = 0; lastUpdate = now
            end
        end
    end)
end)

