    -- [ SLIDERS DE AJUSTE COM AUTO-SAVE PROFISSIONAL ]
    local function createCursorSlider(labelText, minVal, maxVal, defaultVal, isAnchor, updateVarFunc)
        local frame = Instance.new("Frame", curSettings)
        frame.Size = UDim2.new(1, -10, 0, 28)
        frame.BackgroundColor3 = Color3.fromRGB(16, 16, 20)
        Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 4)
        Instance.new("UIStroke", frame).Color = Color3.fromRGB(45, 45, 55)

        local lbl = Instance.new("TextLabel", frame)
        lbl.Size = UDim2.new(0.4, 0, 1, 0)
        lbl.Position = UDim2.new(0, 10, 0, 0)
        lbl.BackgroundTransparency = 1
        lbl.Text = labelText
        lbl.TextColor3 = Color3.fromRGB(200, 200, 200)
        lbl.Font = Enum.Font.GothamMedium
        lbl.TextSize = 10
        lbl.TextXAlignment = Enum.TextXAlignment.Left

        local valLbl = Instance.new("TextLabel", frame)
        valLbl.Size = UDim2.new(0.15, 0, 1, 0)
        valLbl.Position = UDim2.new(0.85, -10, 0, 0)
        valLbl.BackgroundTransparency = 1
        valLbl.TextColor3 = Color3.fromRGB(170, 0, 255)
        valLbl.Font = Enum.Font.GothamBlack
        valLbl.TextSize = 10
        valLbl.TextXAlignment = Enum.TextXAlignment.Right

        local track = Instance.new("Frame", frame)
        track.Size = UDim2.new(0.4, 0, 0, 6)
        track.Position = UDim2.new(0.45, 0, 0.5, -3)
        track.BackgroundColor3 = Color3.fromRGB(10, 10, 12)
        Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

        local fill = Instance.new("Frame", track)
        local initialPct = (defaultVal - minVal) / (maxVal - minVal)
        fill.Size = UDim2.new(initialPct, 0, 1, 0)
        fill.BackgroundColor3 = Color3.fromRGB(170, 0, 255)
        Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)

        local knob = Instance.new("Frame", fill)
        knob.Size = UDim2.new(0, 12, 0, 12)
        knob.Position = UDim2.new(1, -6, 0.5, -6)
        knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)

        local btn = Instance.new("TextButton", track)
        btn.Size = UDim2.new(1, 20, 0, 28)
        btn.Position = UDim2.new(0, -10, 0.5, -14)
        btn.BackgroundTransparency = 1
        btn.Text = ""

        local function updateDisplay(val)
            if isAnchor then
                valLbl.Text = string.format("%.2f", val)
            else
                valLbl.Text = tostring(math.floor(val)) .. "px"
            end
        end
        updateDisplay(defaultVal)

        local dragging = false
        
        -- Evento Principal de Início (Garante Suporte a PC e Mobile)
        btn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
            end
        end)
        
        -- Evento Global de Término (Executa o Save com segurança absoluta)
        game:GetService("UserInputService").InputEnded:Connect(function(input) 
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then 
                if dragging then
                    dragging = false 
                    -- Executa o auto-save de forma assíncrona assim que você soltar a barra
                    task.spawn(function()
                        if type(SaveS7xSettings) == "function" then SaveS7xSettings() end
                    end)
                end
            end 
        end)
        
        -- Loop de Arrasto (Sem lag na imagem)
        game:GetService("RunService").Heartbeat:Connect(function()
            if dragging then
                local pct = math.clamp((game:GetService("UserInputService"):GetMouseLocation().X - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
                fill.Size = UDim2.new(pct, 0, 1, 0)
                local currentVal = minVal + (pct * (maxVal - minVal))
                if not isAnchor then currentVal = math.floor(currentVal) end
                updateDisplay(currentVal)
                updateVarFunc(currentVal)
            end
        end)
    end

    -- Criação dos Sliders injetando as variáveis globais direto e tratando valores Nulos
    createCursorSlider("SIZE (SCALE)", 20, 100, _G.S7xCursorSize or 50, false, function(val) 
        _G.S7xCursorSize = val 
        if GUI.CustomCursor then GUI.CustomCursor.Size = UDim2.new(0, val, 0, val) end
    end)
    
    createCursorSlider("CENTER (X AXIS)", 0.0, 1.0, _G.S7xCursorAnchorX or 0.5, true, function(val) 
        _G.S7xCursorAnchorX = val 
        if GUI.CustomCursor then GUI.CustomCursor.AnchorPoint = Vector2.new(val, _G.S7xCursorAnchorY or 0.5) end
    end)
    
    createCursorSlider("CENTER (Y AXIS)", 0.0, 1.0, _G.S7xCursorAnchorY or 0.5, true, function(val) 
        _G.S7xCursorAnchorY = val 
        if GUI.CustomCursor then GUI.CustomCursor.AnchorPoint = Vector2.new(_G.S7xCursorAnchorX or 0.5, val) end
    end)

