-- ==========================================
-- [ CARD 7: DESTROY ENGINE (UNLOAD SCRIPT) ]
-- ==========================================
_G.S7xUnloadEngine = function()
    -- 1. Notificação Visual (Despedida)
    pcall(function()
        if type(S7xNotify) == "function" then S7xNotify("SYSTEM OFFLINE", "Shutting down S7x Engine and restoring game...", 3) end
    end)
    
    -- 2. Remoção da Nuvem (Presence/Tags)
    pcall(function() if type(RemovePresence) == "function" then RemovePresence() end end)
    
    -- 3. Restauração de Física e Câmera do Jogador
    pcall(function()
        local lp = game:GetService("Players").LocalPlayer
        local char = lp.Character
        if char then
            local hum = char:FindFirstChild("Humanoid")
            if hum then
                hum.WalkSpeed = 16
                hum.UseJumpPower = true
                hum.JumpPower = 50
                hum.PlatformStand = false
                hum.CameraOffset = Vector3.new(0,0,0)
                hum.AutoRotate = true
                if hum.RigType == Enum.HumanoidRigType.R15 then
                    hum:ChangeState(Enum.HumanoidStateType.Landed)
                end
            end
            
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                hrp.Anchored = false
                hrp.Size = Vector3.new(2, 2, 1)
                hrp.Transparency = 1
                for _, v in ipairs(char:GetDescendants()) do
                    if v:IsA("BasePart") then
                        v.LocalTransparencyModifier = 0
                        v.Massless = false
                        v.CanCollide = true
                    end
                end
            end
        end
        
        workspace.Gravity = 196.2
        local cam = workspace.CurrentCamera
        cam.CameraType = Enum.CameraType.Custom
        cam.FieldOfView = 70
        local uis = game:GetService("UserInputService")
        uis.MouseBehavior = Enum.MouseBehavior.Default
        uis.MouseIconEnabled = true
    end)
    
    -- 4. Extermínio Visual (Tags, Auras, Highlight/ESP)
    _G.S7xTagVisible = false
    pcall(function()
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            local c = p.Character
            if c then
                local head = c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart")
                if head then
                    for _, v in ipairs(head:GetChildren()) do
                        if v.Name == "S7x_ProTag" then v:Destroy() end
                    end
                end
                local hrp = c:FindFirstChild("HumanoidRootPart")
                if hrp then
                    for _, v in ipairs(hrp:GetChildren()) do
                        if v.Name == "S7x_3DAura" then v:Destroy() end
                    end
                    hrp.Size = Vector3.new(2, 2, 1)
                    hrp.Transparency = 1
                end
                for _, v in ipairs(c:GetChildren()) do
                    if v:IsA("Highlight") and string.find(v.Name, "S7x") then v:Destroy() end
                end
            end
        end
    end)
    
    -- Limpa ESP via Drawing API (Otimizado)
    if type(_G.S7xClearAimbotESP) == "function" then pcall(_G.S7xClearAimbotESP) end
    pcall(function()
        if type(_G.S7xSafeDrawings) == "table" then
            for _, obj in pairs(_G.S7xSafeDrawings) do
                if obj.Remove then pcall(function() obj:Remove() end) end
                if obj.Destroy then pcall(function() obj:Destroy() end) end
            end
        end
        if cleardrawings then cleardrawings() end
    end)
    
    -- 5. Cancelamento de Threads e Loops Nativos
    local loopsToKill = {
        "S7xMenuDepthConn1", "S7xMenuDepthConn2", "S7xMenuDepthMonitor", 
        "S7xResizeLoop", "S7xCursorLoop", "S7xTagSyncDaemon", "S7xTagPersistenceDaemon",
        "S7xImortalLoop", "S7xAudioEngineLoop", "S7xTabVisibilityDaemon",
        "SpinLoopConn", "FeflipLoopConn", "AntiDeadLoop", "JumpConn", "NoclipConn",
        "SpeedConn", "FlyConn", "AntiFlingConn", "S7xAimbotLoopConn", "WoaClickConn",
        "AntiAfkConn", "AntiRagdollConn", "SpamMinesConn", "S7xUltimateAuthLoop", "S7xMobileOptimizer"
    }
    for _, loopName in ipairs(loopsToKill) do
        if _G[loopName] then
            pcall(function()
                if typeof(_G[loopName]) == "RBXScriptConnection" then _G[loopName]:Disconnect()
                elseif type(_G[loopName]) == "thread" then task.cancel(_G[loopName]) end
            end)
            _G[loopName] = nil
        end
    end

    if type(_G.S7xConnections) == "table" then
        for _, conn in pairs(_G.S7xConnections) do pcall(function() conn:Disconnect() end) end
    end
    if type(_G.S7xSpyConnectionsTable) == "table" then
        for _, conn in ipairs(_G.S7xSpyConnectionsTable) do pcall(function() conn:Disconnect() end) end
    end
    if _G.S7xKeybindConnection then pcall(function() _G.S7xKeybindConnection:Disconnect() end); _G.S7xKeybindConnection = nil end

    -- 6. Destruição Absoluta das Interfaces Gráficas
    local function killGuis(parent)
        if not parent then return end
        for _, g in ipairs(parent:GetChildren()) do
            if string.find(string.lower(g.Name), "s7x") or g.Name == "EliteScannerUI_VS7x" or g.Name == "MinimalFarm" or string.find(string.lower(g.Name), "fishing") then
                pcall(function() g:Destroy() end)
            end
        end
    end
    
    task.delay(0.5, function()
        pcall(function() killGuis(game:GetService("CoreGui")) end)
        pcall(function() killGuis(game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")) end)
        _G.S7xIsFullyLoaded = false
    end)
end

