local function togglePanel()
    if not _G.S7xIsFullyLoaded then return end -- Bloqueia a abertura forçada
    
    panelOpen = not panelOpen
    
    -- [ SISTEMA DE SOM DE INTERFACE (ABRIR/FECHAR) ]
    
    pcall(function()
        local sfx = Instance.new("Sound", game:GetService("CoreGui"))
        -- Se estiver abrindo toca o som 6895082404, se fechando toca 6895050519
        -- Se estiver abrindo toca o som 6895082404, se fechando toca 6895050519
        sfx.SoundId = panelOpen and "rbxassetid://6895082404" or "rbxassetid://6895050519" 
        sfx.Volume = 1.5
        sfx:Play()
        game:GetService("Debris"):AddItem(sfx, 2)
    end)


    if panelOpen then
        GUI.MainFrame.Size = UDim2.new(0, 0, 0, 0)
        GUI.MainFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
        GUI.MainFrame.Visible = true
        
        pcall(function()
            game:GetService("TweenService"):Create(GUI.MainFrame, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                Size = panelTargetSize,
                Position = UDim2.new(0.5, -290, 0.5, -265)
            }):Play()
        end)
    else
        local success = pcall(function()
            local tween = game:GetService("TweenService"):Create(GUI.MainFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
                Size = UDim2.new(0, 0, 0, 0),
                Position = UDim2.new(0.5, 0, 0.5, 0)
            })
            tween:Play()
            task.spawn(function()
                tween.Completed:Wait()
                if not panelOpen then GUI.MainFrame.Visible = false end
            end)
        end)
        
        -- Fallback de segurança caso o executor rejeite a animação
        if not success then
            GUI.MainFrame.Visible = false
        end
    end
end

