local function SafeTween(obj, time, props, style)
    task.spawn(function()
        pcall(function()
            local ts = game:GetService("TweenService")
            local ti = TweenInfo.new(time, style or Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
            ts:Create(obj, ti, props):Play()
        end)
    end)
end

