local function createButton(text, arg2, arg3)
    local parent = (typeof(arg2) == "Instance" and arg2) or arg3
    local iconId = (typeof(arg2) == "string" and arg2) or "6031091004"

    local btn = Instance.new("TextButton", parent)
    btn.Text = ""
    btn.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
    btn.Size = UDim2.new(0.9, 0, 0, 38)
    btn.AutoButtonColor = false
    
    btn.LayoutOrder = buttonOrderCount
    buttonOrderCount = buttonOrderCount + 1
    
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
    
    local strk = Instance.new("UIStroke", btn)
    strk.Color = Color3.fromRGB(40, 40, 40)
    strk.Thickness = 1
    
    local icon = Instance.new("ImageLabel", btn)
    icon.Size = UDim2.new(0, 16, 0, 16)
    icon.Position = UDim2.new(0, 15, 0.5, -8)
    icon.BackgroundTransparency = 1
    icon.Image = "rbxassetid://" .. iconId
    icon.ImageColor3 = Color3.fromRGB(255, 255, 255)

    local lbl = Instance.new("TextLabel", btn)
    lbl.Size = UDim2.new(1, -45, 1, 0)
    lbl.Position = UDim2.new(0, 40, 0, 0)
    lbl.BackgroundTransparency = 1
    
    -- MOTOR DE FORMATAÇÃO
    local cleanText = string.gsub(text, "[%z\1-\127\194-\244][\128-\191]*", function(c) return #c > 2 and "" or c end)
    lbl.Text = string.gsub(string.lower(cleanText), "(%a)([%w_']*)", function(first, rest) 
        return string.upper(first) .. rest 
    end)
    
    lbl.TextColor3 = Color3.fromRGB(200, 200, 200)
    lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 11
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    
    btn.MouseEnter:Connect(function()
        pcall(function()
            game:GetService("TweenService"):Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(25, 25, 25)}):Play()
            game:GetService("TweenService"):Create(lbl, TweenInfo.new(0.2), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play()
        end)
    end)
    btn.MouseLeave:Connect(function()
        pcall(function()
            game:GetService("TweenService"):Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(10, 10, 10)}):Play()
            game:GetService("TweenService"):Create(lbl, TweenInfo.new(0.2), {TextColor3 = Color3.fromRGB(200, 200, 200)}):Play()
        end)
    end)
    
    return btn
end

