_G.setToggleState = function(btn, isEnabled)
    local bg = btn:FindFirstChild("ToggleBG") or btn:FindFirstChild("SysToggleBG")
    local knob = bg and (bg:FindFirstChild("ToggleKnob") or bg:FindFirstChild("SysToggleKnob"))
    local lbl = btn:FindFirstChild("Title") or btn:FindFirstChildWhichIsA("TextLabel")
    local icon = btn:FindFirstChild("Icon")
    local sliderTrack = btn:FindFirstChild("S7xSliderTrack")
    
    if bg and knob then
        pcall(function()
            local ts = game:GetService("TweenService")
            if isEnabled then
                ts:Create(bg, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(255, 255, 255)}):Play()
                ts:Create(knob, TweenInfo.new(0.3, Enum.EasingStyle.Back), {Position = UDim2.new(1, -14, 0.5, -6), BackgroundColor3 = Color3.fromRGB(0, 0, 0)}):Play()
                if lbl then ts:Create(lbl, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play() end
                if icon then 
                    icon.Image = "rbxassetid://17238164448"
                    ts:Create(icon, TweenInfo.new(0.3), {ImageColor3 = Color3.fromRGB(170, 0, 255)}):Play()
                end
                if sliderTrack then sliderTrack.Visible = true end 
            else
                ts:Create(bg, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(30, 30, 35)}):Play()
                ts:Create(knob, TweenInfo.new(0.3, Enum.EasingStyle.Back), {Position = UDim2.new(0, 2, 0.5, -6), BackgroundColor3 = Color3.fromRGB(150, 150, 150)}):Play()
                if lbl then ts:Create(lbl, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(200, 200, 200)}):Play() end
                if icon then 
                    icon.Image = "rbxassetid://17238164393"
                    ts:Create(icon, TweenInfo.new(0.3), {ImageColor3 = Color3.fromRGB(200, 200, 200)}):Play()
                end
                if sliderTrack then sliderTrack.Visible = false end 
            end
        end)
    end
end
