    -- Criador de dupla keybind para o Click TP
    local function createTpKeybox(action, offsetX, defaultKey)
        local keyBox = Instance.new("TextBox", GUI.TpBtn)
        keyBox.Size = UDim2.new(0, 20, 0, 20)
        keyBox.Position = UDim2.new(1, offsetX, 0.5, -10)
        keyBox.BackgroundColor3 = Color3.fromRGB(20, 18, 25)
        keyBox.TextColor3 = Color3.fromRGB(170, 0, 255)
        keyBox.Font = Enum.Font.GothamBold
        keyBox.TextSize = 10
        keyBox.Text = bindKeys[action] and bindKeys[action].Name or defaultKey.Name
        keyBox.PlaceholderText = "..."
        Instance.new("UICorner", keyBox).CornerRadius = UDim.new(0, 4)
        local kbStrk = Instance.new("UIStroke", keyBox)
        kbStrk.Color = Color3.fromRGB(80, 40, 120)
        kbStrk.Thickness = 1

        local numToKey = {["0"]=Enum.KeyCode.Zero, ["1"]=Enum.KeyCode.One, ["2"]=Enum.KeyCode.Two, ["3"]=Enum.KeyCode.Three, ["4"]=Enum.KeyCode.Four, ["5"]=Enum.KeyCode.Five, ["6"]=Enum.KeyCode.Six, ["7"]=Enum.KeyCode.Seven, ["8"]=Enum.KeyCode.Eight, ["9"]=Enum.KeyCode.Nine}

        keyBox.FocusLost:Connect(function()
            local rawInput = string.upper(string.sub(keyBox.Text, 1, 1))
            local code = numToKey[rawInput]
            if not code then
                local s, r = pcall(function() return Enum.KeyCode[rawInput] end)
                if s then code = r end
            end
            if code and rawInput ~= "" then
                bindKeys[action] = code
                keyBox.Text = rawInput
                if type(S7xNotify) == "function" then S7xNotify("BIND SAVED", action .. " na tecla: " .. code.Name) end
                if type(SaveS7xSettings) == "function" then task.spawn(SaveS7xSettings) end
            else
                bindKeys[action] = defaultKey
                keyBox.Text = defaultKey.Name
            end
        end)
    end

    -- Cria o box de ativar/desativar na direita (-74) e o de segurar para teleportar na esquerda (-98)
    createTpKeybox("Tp", -74, Enum.KeyCode.T)
    createTpKeybox("TpTrigger", -98, Enum.KeyCode.LeftControl)
    
    _G.FreecamSpeed = _G.FreecamSpeed or 50
    addMiniSlider(GUI.FreeCamBtn, _G.FreecamSpeed, 300, function(val) _G.FreecamSpeed = val end)

