    _G.S7xAimbot = _G.S7xAimbot or { Enabled = false, FOV = 130, Smoothness = 0.85, TargetPart = "Head", Circle = nil, Text = nil, CurrentTarget = nil, Highlight = nil }
    
    pcall(function()
        if not _G.S7xAimbot.Circle then
            _G.S7xAimbot.Circle = Drawing.new("Circle")
            _G.S7xAimbot.Circle.Visible = false
            _G.S7xAimbot.Circle.Thickness = 1.5
            _G.S7xAimbot.Circle.Color = Color3.fromRGB(170, 0, 255)
