            _G.S7xAimbot.Text.Outline = true
            _G.S7xAimbot.Text.Color = Color3.fromRGB(255, 50, 50)
            _G.S7xAimbot.Text.Size = 15
            _G.S7xAimbot.Text.Font = 2
        end
    end)

    _G.ShowFovEnabled = false
    GUI.FovBtn.MouseButton1Click:Connect(function()
        _G.ShowFovEnabled = not _G.ShowFovEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.FovBtn, _G.ShowFovEnabled) end
        
        if _G.S7xAimbot.Circle then _G.S7xAimbot.Circle.Visible = _G.ShowFovEnabled end
        
        -- [ MOTOR DE CÂMERA DINÂMICO (ZOOM OUT / STRETCH) ]
        if _G.ShowFovEnabled then
            -- Converte a proporção do círculo (30-400) para o FOV nativo da tela (70-120)
            local mappedFOV = math.clamp(70 + ((_G.S7xAimbot.FOV - 30) / 370) * 50, 70, 120)
            pcall(function() 
                game:GetService("TweenService"):Create(workspace.CurrentCamera, TweenInfo.new(0.3, Enum.EasingStyle.Sine), {FieldOfView = mappedFOV}):Play() 
            end)
        else
            -- Retorna a câmera suavemente ao padrão (70) ao desligar
            pcall(function() 
                game:GetService("TweenService"):Create(workspace.CurrentCamera, TweenInfo.new(0.4, Enum.EasingStyle.Quart), {FieldOfView = 70}):Play() 
            end)
        end
    end)

    addMiniSlider(GUI.FovBtn, _G.S7xAimbot.FOV, 400, function(val) 
        _G.S7xAimbot.FOV = math.max(30, val) 
        if _G.S7xAimbot.Circle then _G.S7xAimbot.Circle.Radius = _G.S7xAimbot.FOV end
        
        -- [ ESTICA A TELA EM TEMPO REAL AO ARRASTAR A BARRA ]
        if _G.ShowFovEnabled then
            local mappedFOV = math.clamp(70 + ((val - 30) / 370) * 50, 70, 120)
            workspace.CurrentCamera.FieldOfView = mappedFOV
        end
    end)

    -- ==========================================
    -- [ MOTORES DE LÓGICA GLOBAIS ]
    -- ==========================================
    local RS = game:GetService("RunService")
    local player = game.Players.LocalPlayer
    
-- PHANTOM CLIP (NOCLIP ABSOLUTO PARA ITENS + ZERO MASSA + ANTI-FLING)
    _G.PhantomClipEnabled = false
    local phantomClipConn = nil
    
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude

    GUI.PhantomClipBtn.MouseButton1Click:Connect(function()
        _G.PhantomClipEnabled = not _G.PhantomClipEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.PhantomClipBtn, _G.PhantomClipEnabled) end

        if _G.PhantomClipEnabled then
            if phantomClipConn then phantomClipConn:Disconnect() end
            
            phantomClipConn = RS.Stepped:Connect(function()
                local myChar = player.Character
                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myHrp then return end

                local myPos = myHrp.Position

                for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                    if p ~= player and p.Character then
                        local char = p.Character
                        local tHrp = char:FindFirstChild("HumanoidRootPart")
                        
                        if tHrp and (tHrp.Position - myPos).Magnitude < 60 then
                            for _, child in ipairs(char:GetChildren()) do
                                if child:IsA("Tool") or child:IsA("Accessory") then
                                    -- OTIMIZAÇÃO: Altera apenas o Handle em vez de GetDescendants()
                                    local handle = child:FindFirstChild("Handle")
                                    if handle and handle:IsA("BasePart") then
                                        handle.CanCollide = false
                                        handle.Massless = true
                                        handle.CustomPhysicalProperties = PhysicalProperties.new(0, 0, 0, 0, 0)
                                        
                                        if handle.Velocity.Magnitude > 50 or handle.RotVelocity.Magnitude > 30 then
                                            handle.Velocity = Vector3.zero
                                            handle.RotVelocity = Vector3.zero
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                params.FilterDescendantsInstances = {myChar}
                local nearbyParts = workspace:GetPartBoundsInRadius(myPos, 12, params)
                
                for i = 1, #nearbyParts do
                    local part = nearbyParts[i]
                    if not part.Anchored then
                        local isItem = part:FindFirstAncestorWhichIsA("Tool") or part:FindFirstAncestorWhichIsA("Accessory")
                        local isFlinging = part.Velocity.Magnitude > 50 or part.RotVelocity.Magnitude > 30
                        
                        if isItem or isFlinging then
                            part.CanCollide = false
                            part.Massless = true
                            part.CustomPhysicalProperties = PhysicalProperties.new(0, 0, 0, 0, 0)
                            
                            if isFlinging then
                                part.Velocity = Vector3.zero
                                part.RotVelocity = Vector3.zero
                                part.AssemblyLinearVelocity = Vector3.zero
                                part.AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                    end
                end
            end)
            
            if type(S7xNotify) == "function" then S7xNotify("NOCLIP ITEM", "Física e Massa de Itens 100% Anulada (Otimizado).") end
        else
            if phantomClipConn then phantomClipConn:Disconnect(); phantomClipConn = nil end
            if type(S7xNotify) == "function" then S7xNotify("NOCLIP ITEM", "Colisão padrão restaurada.") end
        end
    end)

-- ==========================================
-- SISTEMA FACEBANG (ZERO DELAY WELD + MOBILE WIDGET + CLICK LOCK FIX)
-- ==========================================
_G.S7xFacebangArmed = false
_G.FbTarget = nil

-- Limpeza de segurança caso o script seja re-executado
if _G.FbAnimTrack then pcall(function() _G.FbAnimTrack:Stop() end); _G.FbAnimTrack = nil end
if _G.FbWeld then pcall(function() _G.FbWeld:Destroy() end); _G.FbWeld = nil end
if _G.FbMouseConn then pcall(function() _G.FbMouseConn:Disconnect() end); _G.FbMouseConn = nil end

_G.ClearFacebang = function()
    if _G.FbWeld then pcall(function() _G.FbWeld:Destroy() end); _G.FbWeld = nil end
    if _G.FbAnimTrack then pcall(function() _G.FbAnimTrack:Stop() end); _G.FbAnimTrack = nil end
    if _G.FbOriginalGravity then workspace.Gravity = _G.FbOriginalGravity; _G.FbOriginalGravity = nil end
    
    local localPlayer = game.Players.LocalPlayer
    local char = localPlayer.Character
    local hum = char and char:FindFirstChild("Humanoid")
    
    if hum then hum.PlatformStand = false end
    
    if char then
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                part.Massless = false
                if part.Name == "HumanoidRootPart" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "Head" then
                    part.CanCollide = true
                end
            end
        end
    end
    _G.FbTarget = nil
end

_G.S7xToggleFacebang = function()
    _G.S7xFacebangArmed = not _G.S7xFacebangArmed
    
    -- Atualiza o botão no painel visualmente (ON / OFF)
    if type(setToggleState) == "function" and GUI.FacebangBtn then 
        setToggleState(GUI.FacebangBtn, _G.S7xFacebangArmed) 
    end
    
    local isMob = game:GetService("UserInputService").TouchEnabled and not game:GetService("UserInputService").KeyboardEnabled
    if isMob and GUI.FacebangWidget then
        GUI.FacebangWidget.Visible = _G.S7xFacebangArmed
    end
    
    if not _G.S7xFacebangArmed then
        if _G.FbMouseConn then _G.FbMouseConn:Disconnect(); _G.FbMouseConn = nil end
        _G.ClearFacebang()
        if GUI.FbArmBtn then 
            GUI.FbArmBtn.BackgroundColor3 = Color3.fromRGB(30, 20, 20)
            GUI.FbArmBtn.TextColor3 = Color3.fromRGB(255, 100, 100)
        end
        if type(S7xNotify) == "function" then S7xNotify("FACEBANG", "Disarmed and Offline.") end
    else
        if GUI.FbArmBtn then 
            GUI.FbArmBtn.BackgroundColor3 = Color3.fromRGB(170, 0, 255)
            GUI.FbArmBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        end
        if type(S7xNotify) == "function" then S7xNotify("FACEBANG", "ARMED! Click/Tap a player to execute.") end
        
        local mouse = game.Players.LocalPlayer:GetMouse()
        if _G.FbMouseConn then _G.FbMouseConn:Disconnect() end
        
        -- Escuta o clique APENAS UMA VEZ
        _G.FbMouseConn = mouse.Button1Down:Connect(function()
            if not _G.S7xFacebangArmed then return end
            
            local target = mouse.Target
            local targetPlayer = nil
            
            if target and target.Parent then
                if target.Parent:FindFirstChild("Humanoid") then
                    targetPlayer = game:GetService("Players"):GetPlayerFromCharacter(target.Parent)
                elseif target.Parent.Parent:FindFirstChild("Humanoid") then
                    targetPlayer = game:GetService("Players"):GetPlayerFromCharacter(target.Parent.Parent)
                end
            end
            
            if targetPlayer and targetPlayer ~= game.Players.LocalPlayer then
                if _G.FbTarget == targetPlayer then
                    _G.ClearFacebang()
                    if type(S7xNotify) == "function" then S7xNotify("FACEBANG", "Stopped. Still Armed.") end
                else
                    _G.ClearFacebang()
                    _G.FbTarget = targetPlayer
                    
                    local localPlayer = game.Players.LocalPlayer
                    local myChar = localPlayer.Character
                    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    local myHum = myChar and myChar:FindFirstChild("Humanoid")
                    local tHrp = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                    
                    if myHrp and tHrp and myHum then
                        if type(S7xNotify) == "function" then S7xNotify("FACEBANG", "LOCKED ON: " .. targetPlayer.Name) end
                        
                        if not _G.FbOriginalGravity then _G.FbOriginalGravity = workspace.Gravity end
                        workspace.Gravity = 0
                        myHum.PlatformStand = true 
                        
                        for _, part in ipairs(myChar:GetDescendants()) do
                            if part:IsA("BasePart") then
                                part.Massless = true
                                part.CanCollide = false
                            end
                        end
                        
                        local isR6 = (myHum.RigType == Enum.HumanoidRigType.R6)
                        local animId = isR6 and "rbxassetid://148840371" or "rbxassetid://5918726674"
                        
                        local animation = Instance.new("Animation")
                        animation.AnimationId = animId
                        _G.FbAnimTrack = myHum:LoadAnimation(animation)
                        _G.FbAnimTrack:Play()
                        _G.FbAnimTrack:AdjustSpeed(isR6 and 3 or 1)
                        
                        _G.FbWeld = Instance.new("Weld")
                        _G.FbWeld.Name = "S7xFacebangWeld"
                        _G.FbWeld.Part0 = tHrp
                        _G.FbWeld.Part1 = myHrp
                        _G.FbWeld.C0 = CFrame.new(0, 2.3, -1.1) * CFrame.Angles(0, math.pi, 0)
                        _G.FbWeld.C1 = CFrame.new()
                        _G.FbWeld.Parent = myHrp
                        
                        task.spawn(function()
                            while _G.FbTarget == targetPlayer do
                                if not targetPlayer.Character or not targetPlayer.Character:FindFirstChild("HumanoidRootPart") or not localPlayer.Character or not localPlayer.Character:FindFirstChild("HumanoidRootPart") then
                                    _G.ClearFacebang()
                                    break
                                end
                                game:GetService("RunService").Heartbeat:Wait()
                            end
                        end)
                    end
                end
            end
        end)
    end
end

