-- ==========================================
-- SISTEMA BANGET (CLICK LOCK & ZERO DELAY SYNC - PC/MOBILE)
-- ==========================================
_G.S7xBangetArmed = false
local bgtTarget = nil
local bgtLoop = nil
local bgtAnimTrack = nil
local bgtOriginalGravity = nil
local bgtClickConn = nil

_G.S7xToggleBanget = function()
    _G.S7xBangetArmed = not _G.S7xBangetArmed
    if type(setToggleState) == "function" then setToggleState(GUI.BangetBtn, _G.S7xBangetArmed) end
    
    if not _G.S7xBangetArmed then
        -- Desarmado: Limpeza Total e Restauração da Física
        if bgtLoop then bgtLoop:Disconnect(); bgtLoop = nil end
        if bgtAnimTrack then bgtAnimTrack:Stop(); bgtAnimTrack = nil end
        if bgtClickConn then bgtClickConn:Disconnect(); bgtClickConn = nil end
        if bgtOriginalGravity then workspace.Gravity = bgtOriginalGravity; bgtOriginalGravity = nil end
        bgtTarget = nil
        
        if type(S7xNotify) == "function" then S7xNotify("BANGET", "Disarmed and Offline.") end
    else
        -- Armado: Prepara o gatilho de clique/toque na tela
        if type(S7xNotify) == "function" then S7xNotify("BANGET", "ARMED! Click/Tap a player to execute.") end
        
        local mouse = game.Players.LocalPlayer:GetMouse()
        bgtClickConn = mouse.Button1Down:Connect(function()
            if not _G.S7xBangetArmed then return end
            
            local target = mouse.Target
            local targetPlayer = nil
            
            -- Detecta se clicou no personagem de um jogador
            if target and target.Parent then
                if target.Parent:FindFirstChild("Humanoid") then
                    targetPlayer = game:GetService("Players"):GetPlayerFromCharacter(target.Parent)
                elseif target.Parent.Parent:FindFirstChild("Humanoid") then
                    targetPlayer = game:GetService("Players"):GetPlayerFromCharacter(target.Parent.Parent)
                end
            end
            
            if targetPlayer and targetPlayer ~= game.Players.LocalPlayer then
                if bgtTarget == targetPlayer then
                    -- Se clicou no mesmo jogador, DESLIGA a execução (mas mantém armado para o próximo)
                    if bgtLoop then bgtLoop:Disconnect(); bgtLoop = nil end
                    if bgtAnimTrack then bgtAnimTrack:Stop(); bgtAnimTrack = nil end
                    if bgtOriginalGravity then workspace.Gravity = bgtOriginalGravity; bgtOriginalGravity = nil end
                    bgtTarget = nil
                    
                    if type(S7xNotify) == "function" then S7xNotify("BANGET", "Stopped. Still Armed.") end
                else
                    -- Se clicou em um novo jogador, INICIA a execução com ZERO DELAY
                    if bgtLoop then bgtLoop:Disconnect(); bgtLoop = nil end
                    if bgtAnimTrack then bgtAnimTrack:Stop(); bgtAnimTrack = nil end
                    if not bgtOriginalGravity then bgtOriginalGravity = workspace.Gravity end
                    
                    bgtTarget = targetPlayer
                    if type(S7xNotify) == "function" then S7xNotify("BANGET", "LOCKED ON: " .. targetPlayer.Name) end
                    
                    local localPlayer = game.Players.LocalPlayer
                    local myHum = localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid")
                    
                    if myHum then
                        -- Removemos a gravidade para evitar que o Roblox puxe o player para baixo
                        workspace.Gravity = 0
                        
                        -- Injeta a animação original Híbrida
                        local animation = Instance.new("Animation")
                        animation.AnimationId = "rbxassetid://189854234"
                        bgtAnimTrack = myHum:LoadAnimation(animation)
                        bgtAnimTrack:Play()
                        
                        -- O SEGREDO DO ZERO DELAY: Matemática de Oscilação no "Stepped"
                        bgtLoop = game:GetService("RunService").Stepped:Connect(function()
                            -- Proteção anti-crash
                            if not bgtTarget or not bgtTarget.Character or not bgtTarget.Character:FindFirstChild("HumanoidRootPart") or not localPlayer.Character or not localPlayer.Character:FindFirstChild("HumanoidRootPart") then
                                if bgtLoop then bgtLoop:Disconnect(); bgtLoop = nil end
                                if bgtAnimTrack then bgtAnimTrack:Stop(); bgtAnimTrack = nil end
                                if bgtOriginalGravity then workspace.Gravity = bgtOriginalGravity; bgtOriginalGravity = nil end
                                bgtTarget = nil
                                return
                            end
                            
                            local cMyHrp = localPlayer.Character.HumanoidRootPart
                            local cTHrp = bgtTarget.Character.HumanoidRootPart
                            
                            -- Cálculos da Frequência de Impacto (Substitui o antigo TweenService)
                            -- Isso recria o movimento contínuo exato entre -2.5 e -1.3, mas colado no alvo.
                            local speed = 21 -- Frequência da batida (Similar ao Tween 0.15)
                            local amplitude = 0.6 -- Distância percorrida
                            local centerOffset = -1.9 -- Ponto central da posição (-1.3 a -2.5)
                            
                            -- math.sin gera a onda de movimento fluida frame a frame
                            local currentZ = centerOffset + (math.sin(tick() * speed) * amplitude)
                            
                            -- Prende o CFrame com Offset dinâmico e anula a velocidade do corpo para não haver tremores de física
                            cMyHrp.CFrame = cTHrp.CFrame * CFrame.new(0, 0, currentZ)
                            cMyHrp.Velocity = Vector3.zero
                            cMyHrp.RotVelocity = Vector3.zero
                        end)
                    end
                end
            end
        end)
    end
end
GUI.BangetBtn.MouseButton1Click:Connect(_G.S7xToggleBanget)
GUI.FacebangBtn.MouseButton1Click:Connect(_G.S7xToggleFacebang)

    -- ANTI-STUN SUPREME (QUEBRA-ATORDOAMENTO FÍSICO E DE VARIÁVEIS)
    _G.AntiStunEnabled = false
    local antiStunConn = nil

    GUI.AntiStunBtn.MouseButton1Click:Connect(function()
        _G.AntiStunEnabled = not _G.AntiStunEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.AntiStunBtn, _G.AntiStunEnabled) end

        if _G.AntiStunEnabled then
            if antiStunConn then antiStunConn:Disconnect() end
            
            -- Usamos Stepped para atropelar a engine do Roblox ANTES da simulação física
            antiStunConn = RS.Stepped:Connect(function()
                local char = player.Character
                if char then
                    local hum = char:FindFirstChild("Humanoid")
                    local hrp = char:FindFirstChild("HumanoidRootPart")

                    if hum then
                        -- 1. Previne lentidão extrema ou paralisia (Força o mínimo de 16 de velocidade)
                        if hum.WalkSpeed < 16 then hum.WalkSpeed = 16 end
                        
                        -- 2. Restaura capacidade de pular (Trata ambos os sistemas antigos e novos do Roblox)
                        if hum.UseJumpPower and hum.JumpPower < 50 then hum.JumpPower = 50 end
                        if not hum.UseJumpPower and hum.JumpHeight < 7.2 then hum.JumpHeight = 7.2 end
                        
                        -- 3. Quebra estados de Stun induzidos por animação ou scripts de combate
                        if hum.PlatformStand then hum.PlatformStand = false end
                        if hum.Sit then hum.Sit = false end
                        
                        -- 4. Força o personagem a levantar se o jogo tentar travá-lo no chão
                        local state = hum:GetState()
                        if state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Seated or state == Enum.HumanoidStateType.Ragdoll then
                            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        end
                    end

                    -- 5. Solta o jogador se o dev do mapa usar Anchored para prender
                    if hrp and hrp.Anchored then
                        -- Não desancora se o jogador ativou ferramentas do Hub que precisam do anchor (Ex: FakeLag, Freecam)
                        if not _G.FakeLagEnabled and not _G.S7xFreecamEnabled then
                            hrp.Anchored = false
                        end
                    end
                end
            end)
            if type(S7xNotify) == "function" then S7xNotify("ANTI STUN", "Combat restrictions bypassed.") end
        else
            if antiStunConn then antiStunConn:Disconnect(); antiStunConn = nil end
            if type(S7xNotify) == "function" then S7xNotify("ANTI STUN", "System disabled.") end
        end
    end)

    -- ==========================================
-- SISTEMA DE NOTIFICAÇÕES (TOAST INDUSTRIAL S7X B&W)
-- ==========================================
pcall(function()
    local core = game:GetService("CoreGui")
    local rs = game:GetService("RunService")
    
    -- Limpa notificações antigas
    if core:FindFirstChild("S7x_NotifyUI") then core.S7x_NotifyUI:Destroy() end
    
    local notifyGui = Instance.new("ScreenGui", core)
    notifyGui.Name = "S7x_NotifyUI"
    notifyGui.DisplayOrder = 9999999
    notifyGui.IgnoreGuiInset = true
    notifyGui.ResetOnSpawn = false

    local notifyContainer = Instance.new("Frame", notifyGui)
    notifyContainer.Name = "Container"
    notifyContainer.Size = UDim2.new(0, 240, 0.8, 0)
    notifyContainer.Position = UDim2.new(1, -260, 0.1, 0)
    notifyContainer.BackgroundTransparency = 1

    local layout = Instance.new("UIListLayout", notifyContainer)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
    layout.Padding = UDim.new(0, 10)

    _G.LastNotifyMsg = ""
    _G.LastNotifyTime = 0

    _G.S7xNotify = function(title, text, duration)
        local displayTime = duration or 3.5

        -- Prevenção de Spam
        if _G.LastNotifyMsg == text and (tick() - _G.LastNotifyTime) < 1 then return end
        _G.LastNotifyMsg = text
        _G.LastNotifyTime = tick()

        local notifs = {}
        for _, v in ipairs(notifyContainer:GetChildren()) do
            if v:IsA("Frame") then table.insert(notifs, v) end
        end
        if #notifs >= 4 then notifs[1]:Destroy() end

        -- Áudio Tátil Profissional
        pcall(function()
            local sfx = Instance.new("Sound", core)
            sfx.SoundId = "rbxassetid://6895050519"
            sfx.Volume = 1.2
            sfx:Play()
            game:GetService("Debris"):AddItem(sfx, 2)
        end)

        -- [ FIX: ALTURA DINÂMICA PARA TEXTOS LONGOS (TUTORIAIS) ]
        local strText = tostring(text)
        local isLong = string.len(strText) > 45
        local boxHeight = isLong and 90 or 50
        local labelHeight = isLong and 60 or 20

        -- Estrutura Visual B&W
        local notif = Instance.new("Frame", notifyContainer)
        notif.Size = UDim2.new(1, 80, 0, boxHeight) -- Inicia recuado para efeito Slide
        notif.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
        notif.BackgroundTransparency = 1
        notif.ClipsDescendants = true
        Instance.new("UICorner", notif).CornerRadius = UDim.new(0, 4)
        
        local strk = Instance.new("UIStroke", notif)
        strk.Color = Color3.fromRGB(80, 80, 80)
        strk.Thickness = 1.2
        strk.Transparency = 1
        
        local accent = Instance.new("Frame", notif)
        accent.Size = UDim2.new(0, 3, 1, 0)
        accent.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        accent.BorderSizePixel = 0
        accent.BackgroundTransparency = 1
        Instance.new("UICorner", accent).CornerRadius = UDim.new(0, 4)

        local tLbl = Instance.new("TextLabel", notif)
        tLbl.Size = UDim2.new(1, -20, 0, 18)
        tLbl.Position = UDim2.new(0, 12, 0, 6)
        tLbl.BackgroundTransparency = 1
        tLbl.Text = string.upper(tostring(title))
        tLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        tLbl.Font = Enum.Font.GothamBlack
        tLbl.TextSize = 11
        tLbl.TextXAlignment = Enum.TextXAlignment.Left
        tLbl.TextTransparency = 1
        
        local dLbl = Instance.new("TextLabel", notif)
        dLbl.Size = UDim2.new(1, -24, 0, labelHeight)
        dLbl.Position = UDim2.new(0, 12, 0, 24)
        dLbl.BackgroundTransparency = 1
        dLbl.Text = strText
        dLbl.TextColor3 = Color3.fromRGB(180, 180, 180)
        dLbl.Font = Enum.Font.GothamMedium
        dLbl.TextSize = 10
        dLbl.TextXAlignment = Enum.TextXAlignment.Left
        dLbl.TextYAlignment = isLong and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
        dLbl.TextWrapped = true -- O SEGREDO: Força a quebra de linha nas bordas!
        dLbl.TextTransparency = 1
        
        local progBg = Instance.new("Frame", notif)
        progBg.Size = UDim2.new(1, 0, 0, 2)
        progBg.Position = UDim2.new(0, 0, 1, -2)
        progBg.BackgroundColor3 = Color3.fromRGB(40, 40, 40)
        progBg.BorderSizePixel = 0
        progBg.BackgroundTransparency = 1

        local progFill = Instance.new("Frame", progBg)
        progFill.Size = UDim2.new(1, 0, 1, 0)
        progFill.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        progFill.BorderSizePixel = 0
        progFill.BackgroundTransparency = 1
        
        -- Animação de Entrada
        local ts = game:GetService("TweenService")
        pcall(function()
            ts:Create(notif, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, boxHeight), BackgroundTransparency = 0}):Play()
            ts:Create(strk, TweenInfo.new(0.4), {Transparency = 0}):Play()
            ts:Create(accent, TweenInfo.new(0.4), {BackgroundTransparency = 0}):Play()
            ts:Create(tLbl, TweenInfo.new(0.4), {TextTransparency = 0}):Play()
            ts:Create(dLbl, TweenInfo.new(0.4), {TextTransparency = 0}):Play()
            ts:Create(progBg, TweenInfo.new(0.4), {BackgroundTransparency = 0}):Play()
            ts:Create(progFill, TweenInfo.new(0.4), {BackgroundTransparency = 0}):Play()
            
            -- Drenagem da barra de progresso
            ts:Create(progFill, TweenInfo.new(displayTime, Enum.EasingStyle.Linear), {Size = UDim2.new(0, 0, 1, 0)}):Play()
        end)
        
        -- Animação de Saída
        task.delay(displayTime, function()
            if notif and notif.Parent then
                pcall(function()
                    ts:Create(notif, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.In), {Size = UDim2.new(1, 80, 0, boxHeight), BackgroundTransparency = 1}):Play()
                    ts:Create(strk, TweenInfo.new(0.3), {Transparency = 1}):Play()
                    ts:Create(accent, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                    ts:Create(tLbl, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
                    ts:Create(dLbl, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
                    ts:Create(progBg, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                    ts:Create(progFill, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                end)
                task.wait(0.4)
                if notif then notif:Destroy() end
            end
        end)
    end
    
    getgenv().S7xNotify = _G.S7xNotify
    S7xNotify = _G.S7xNotify
end)

