        -- RENDERIZADOR DE LISTA
        local function RenderList()
            for _, v in pairs(scrollList:GetChildren()) do if v:IsA("Frame") then v:Destroy() end end
            
            local filter = string.lower(searchBox.Text)
            local targetData = (activeTab == "MINE") and MySongs or DefaultSongs
            local filtered = {}
            
            for _, song in ipairs(targetData) do
                if filter == "" or string.find(string.lower(song.name), filter) or string.find(tostring(song.id), filter) then
                    table.insert(filtered, song)
                end
            end
            
            local maxPages = math.max(1, math.ceil(#filtered / 6))
            if currentPage > maxPages then currentPage = maxPages end
            lblPage.Text = tostring(currentPage)
            
            local startIdx = (currentPage - 1) * 6 + 1
            local endIdx = math.min(startIdx + 5, #filtered)
            
            for i = startIdx, endIdx do
                local song = filtered[i]
                local item = Instance.new("Frame", scrollList)
                item.Size = UDim2.new(1, 0, 0, 24)
                item.BackgroundColor3 = (i%2==0) and Color3.fromRGB(20, 20, 24) or Color3.fromRGB(15, 15, 18)
                item.BorderSizePixel = 0
                
                local lNum = Instance.new("TextLabel", item); lNum.Size = UDim2.new(0, 30, 1, 0); lNum.BackgroundTransparency = 1; lNum.Text = tostring(i); lNum.TextColor3 = Color3.fromRGB(255,255,255); lNum.Font = Enum.Font.GothamBold; lNum.TextSize = 12; lNum.TextXAlignment = Enum.TextXAlignment.Left
                local lName = Instance.new("TextLabel", item); lName.Size = UDim2.new(0, 250, 1, 0); lName.Position = UDim2.new(0, 40, 0, 0); lName.BackgroundTransparency = 1; lName.Text = song.name; lName.TextColor3 = Color3.fromRGB(255,255,255); lName.Font = Enum.Font.GothamBold; lName.TextSize = 11; lName.TextXAlignment = Enum.TextXAlignment.Left; lName.TextTruncate = Enum.TextTruncate.AtEnd
                local lID = Instance.new("TextLabel", item); lID.Size = UDim2.new(0, 100, 1, 0); lID.Position = UDim2.new(0, 300, 0, 0); lID.BackgroundTransparency = 1; lID.Text = song.id; lID.TextColor3 = Color3.fromRGB(200,200,200); lID.Font = Enum.Font.GothamMedium; lID.TextSize = 11; lID.TextXAlignment = Enum.TextXAlignment.Left
                
                local playB = Instance.new("TextButton", item)
                playB.Size = UDim2.new(0, 20, 0, 20); playB.Position = UDim2.new(1, -45, 0.5, -10)
                playB.BackgroundTransparency = 1; playB.Text = "▶"; playB.TextColor3 = Color3.fromRGB(255,255,255); playB.TextSize = 14
                
                playB.MouseButton1Click:Connect(function() PlaySong(song) end)
                if activeTab == "MINE" then
                    local delB = Instance.new("TextButton", item)
                    delB.Size = UDim2.new(0, 20, 0, 20); delB.Position = UDim2.new(1, -20, 0.5, -10)
                    delB.BackgroundTransparency = 1; delB.Text = "X"; delB.TextColor3 = Color3.fromRGB(255, 50, 50); delB.Font = Enum.Font.GothamBold; delB.TextSize = 12
                    delB.MouseButton1Click:Connect(function()
                        table.remove(MySongs, table.find(MySongs, song))
                        SaveMySongs(); RenderList()
                    end)
                end
            end
            scrollList.CanvasSize = UDim2.new(0, 0, 0, 150)
        end

