    _G.SchizoModeEnabled = false
    GUI.SchizoBtn.MouseButton1Click:Connect(function()
        _G.SchizoModeEnabled = not _G.SchizoModeEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.SchizoBtn, _G.SchizoModeEnabled) end
        
        if _G.SchizoModeEnabled then
            if type(S7xNotify) == "function" then S7xNotify("👁️ SCHIZO MODE", "Assombrando a sanidade do jogador mais próximo...") end
            
            task.spawn(function()
                while _G.SchizoModeEnabled do
                    pcall(function()
                        local myChar = player.Character
                        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                        local myHum = myChar and myChar:FindFirstChild("Humanoid")
                        
                        if myHrp and myHum then
                            -- Procura a vítima mais próxima (Raio de 100 studs)
                            local nearest, minDist = nil, 100 
                            for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                                if p ~= player and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                                    local dist = (p.Character.HumanoidRootPart.Position - myHrp.Position).Magnitude
                                    if dist < minDist then minDist = dist; nearest = p end
                                end
                            end

                            if nearest and nearest.Character then
                                local tHrp = nearest.Character:FindFirstChild("HumanoidRootPart")
                                if tHrp then
                                    local originalCFrame = myHrp.CFrame
                                    
                                    -- Teleporta EXATAMENTE para as costas do alvo com uma leve variação caótica
                                    myHrp.CFrame = tHrp.CFrame * CFrame.new(math.random(-2, 2), 0, 4)
                                    
                                    -- Força o personagem a dar um pulo (O Roblox tocará o som de impacto no chão na tela dele)
                                    myHum.Jump = true 
                                    
                                    -- Fica lá por apenas 0.15s (O suficiente para ele ouvir e ver um vulto periférico)
                                    task.wait(0.15) 
                                    
                                    if _G.SchizoModeEnabled and myHrp then
                                        -- Desaparece e volta para o esconderijo original instantaneamente
                                        myHrp.CFrame = originalCFrame
                                    end
                                end
                            end
                        end
                    end)
                    -- O segredo do terror: Intervalos caóticos e imprevisíveis entre 1.5 e 4 segundos
                    task.wait(math.random(15, 40) / 10) 
                end
            end)
        end
    end)

