    -- ==========================================
    _G.FeflipEnabled = false
    _G.FeflipExecuting = false 

    _G.S7xToggleFeflip = function()
        _G.FeflipEnabled = not _G.FeflipEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.FeflipBtn, _G.FeflipEnabled) end
        
        if not _G.FeflipEnabled then 
            _G.FeflipExecuting = false 
        else
            if type(S7xNotify) == "function" then 
                local k = bindKeys.Feflip and bindKeys.Feflip.Name or "UNBOUND"
                S7xNotify("FE FLIP ARMED", "Módulo armado! Segure ["..k.."] para pular e girar.") 
            end
        end
    end
    GUI.FeflipBtn.MouseButton1Click:Connect(_G.S7xToggleFeflip)
    
    if _G.FeflipLoopConn then _G.FeflipLoopConn:Disconnect() end
    _G.FeflipLoopConn = game:GetService("RunService").Stepped:Connect(function()
        if _G.FeflipEnabled and _G.FeflipExecuting and player.Character and player.Character:FindFirstChild("HumanoidRootPart") and player.Character:FindFirstChild("Humanoid") then
            local hrp = player.Character.HumanoidRootPart
            local hum = player.Character.Humanoid
            
            -- Desliga o auto-balanceamento do Roblox (Acaba com os tremores na tela e no boneco)
            hum.PlatformStand = true
            
            -- Usa Raycast absoluto em WorldSpace para detectar o chão com precisão (Mesmo de ponta-cabeça)
            local rayParams = RaycastParams.new()
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            rayParams.FilterDescendantsInstances = {player.Character}
            
            -- Raio de 4 studs disparado para baixo a partir do centro do personagem
            local ray = workspace:Raycast(hrp.Position, Vector3.new(0, -4, 0), rayParams)
            
            -- Se estiver encostando no chão e caindo, dispara o impulso perfeito do pulo
            if ray and hrp.Velocity.Y <= 0.1 then
                hrp.Velocity = Vector3.new(hrp.Velocity.X, 50, hrp.Velocity.Z)
            end
            
            -- Aplica o mortal fluido (15 graus)
            hrp.CFrame = hrp.CFrame * CFrame.Angles(math.rad(-15), 0, 0)
        end
    end)

