        local moods = {}
        local function saveData() pcall(function() writefile(SAVE_FILE, HttpSvc:JSONEncode(moods)) end) end
        local function loadData()
            local ok, content = pcall(function() return readfile(SAVE_FILE) end)
            if ok and content then
                local dok, decoded = pcall(function() return HttpSvc:JSONDecode(content) end)
                if dok and type(decoded) == "table" then
                    for _, entry in ipairs(decoded) do
                        if type(entry) == "table" and type(entry.id) == "number" then table.insert(moods, entry) end
                    end
                    return true
                end
            end
            return false
        end
        if not loadData() then
            for _, m in ipairs(defaultMoods) do table.insert(moods, {id=m.id, name=m.name, custom=false}) end
            saveData()
        end

        -- Lógica Núcleo Original Mantida Fielmente
        local curTrack = nil
        local curMoodId = nil
        local looped = false
        local cfg = {weight=1, speed=1, priority=Enum.AnimationPriority.Action4}

        local function applyToTrack(t)
            t.Priority = cfg.priority
            t.Looped = looped
            t:AdjustWeight(cfg.weight)
            t:AdjustSpeed(cfg.speed)
        end

        local function playMood(moodId)
            if curTrack then
                pcall(function() resetFace(char) end)
                pcall(function() curTrack:AdjustWeight(0) end)
                pcall(function() curTrack:Destroy() end)
                pcall(function() resetFace(char) end)
                curTrack = nil
            end
            
            curMoodId = moodId
            local animId = getAnimId(moodId)
            local a = Instance.new("Animation")
            a.AnimationId = animId
            
            local t = anim:LoadAnimation(a)
            applyToTrack(t)
            curTrack = t
            t:Play() -- O Play puro igual ao seu código
            
            if not looped then
                t.Stopped:Connect(function()
                    if curTrack == t and curMoodId == moodId then
                        t:Play()
                    end
                end)
            end
            
            if type(S7xNotify) == "function" then S7xNotify("FACE CHANGER", "Face applied successfully.") end
        end

        -- Persistência Anti-Morte Nativa do seu Script Original
        plr.CharacterAdded:Connect(function(c)
            char = c
            hum = c:WaitForChild("Humanoid", 5)
            if hum then anim = hum:WaitForChild("Animator", 5) end
            if curMoodId then
                task.wait(0.3)
                playMood(curMoodId)
            end
        end)

