            btn.TextColor3 = Color3.fromRGB(255, 255, 255)
            btn.Font = Enum.Font.GothamBold
            btn.TextSize = 10
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 4)
            
            btn.MouseButton1Click:Connect(function() onClick(btn) end)
            return btn
        end

        createSettingControl("SPEED (1.0x)", "1.0", false, function(b)
            cfg.speed = (cfg.speed >= 3) and 0.5 or cfg.speed + 0.5
            b.Text = tostring(cfg.speed)
            if curTrack then curTrack:AdjustSpeed(cfg.speed) end
        end)
        
        createSettingControl("WEIGHT", "1.0", false, function(b)
            cfg.weight = (cfg.weight >= 1) and 0.1 or cfg.weight + 0.3
            if cfg.weight > 1 then cfg.weight = 1 end
            b.Text = tostring(cfg.weight)
            if curTrack then curTrack:AdjustWeight(cfg.weight) end
        end)

