        end

        local function addMoodButton(moodEntry)
            local id = moodEntry.id
            local btn = Instance.new("ImageButton", scrollFrame)
            btn.BackgroundColor3 = Color3.fromRGB(25, 25, 30)
            btn.Image = "rbxthumb://type=Asset&id="..id.."&w=150&h=150"
            btn.ScaleType = Enum.ScaleType.Crop
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
            Instance.new("UIStroke", btn).Color = Color3.fromRGB(60, 60, 70)

            local nl = Instance.new("TextLabel", btn)
            nl.Size = UDim2.new(1, 0, 0, 20)
            nl.Position = UDim2.new(0, 0, 1, -20)
            nl.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            nl.BackgroundTransparency = 0.2
            nl.Text = moodEntry.name or tostring(id)
            nl.TextColor3 = Color3.fromRGB(255, 255, 255)
            nl.Font = Enum.Font.GothamBold
            nl.TextSize = 9
            nl.TextScaled = true
            Instance.new("UICorner", nl).CornerRadius = UDim.new(0, 6)

            btn.MouseButton1Click:Connect(function() playMood(id) end)
            
            if moodEntry.custom then
                local delBtn = Instance.new("TextButton", btn)
                delBtn.Size = UDim2.new(0, 20, 0, 20)
                delBtn.Position = UDim2.new(1, -22, 0, 2)
                delBtn.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
                delBtn.Text = "X"
                delBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                delBtn.Font = Enum.Font.GothamBold
                delBtn.TextSize = 10
                Instance.new("UICorner", delBtn).CornerRadius = UDim.new(0, 4)
                
                delBtn.MouseButton1Click:Connect(function()
                    for i, m in ipairs(moods) do if m.id == id then table.remove(moods, i) break end end
                    for i, b in ipairs(moodBtns) do if b == btn then table.remove(moodBtns, i) break end end
                    btn:Destroy()
                    saveData()
                    updateCanvas()
                end)
            end

            table.insert(moodBtns, btn)
            updateCanvas()
            return btn
        end

