    -- ==========================================
    -- SUPREME AUTO PARRY (BLADE BALL) + VISUALIZER
    -- ==========================================
    _G.AutoParryBB = false
    local autoParryVisualizerLoaded = false
    local autoParryConn = nil
    local autoParryBallConn = nil
    local isParried = false
    local parryCooldown = tick()
    local vim = game:GetService("VirtualInputManager")

    -- Função segura para achar a bola real
    local function getBladeBall()
        local ballsFolder = workspace:FindFirstChild("Balls")
        if ballsFolder then
            for _, ball in ipairs(ballsFolder:GetChildren()) do
                if ball:GetAttribute("realBall") then
                    return ball
                end
            end
        end
        return nil
    end

    local function resetBallConnection()
        if autoParryBallConn then
            autoParryBallConn:Disconnect()
            autoParryBallConn = nil
        end
    end

    -- Monitora a adição de novas bolas no mapa de forma segura
    local ballsFolder = workspace:FindFirstChild("Balls")
    if ballsFolder then
        ballsFolder.ChildAdded:Connect(function()
            if not _G.AutoParryBB then return end
            task.wait(0.1) 
            local ball = getBladeBall()
            if not ball then return end
            
            resetBallConnection()
            autoParryBallConn = ball:GetAttributeChangedSignal("target"):Connect(function()
                isParried = false 
            end)
        end)
    end

    -- Conecta a lógica ao seu botão do Painel
    GUI.AutoParryBtn.MouseButton1Click:Connect(function()
        _G.AutoParryBB = not _G.AutoParryBB
        if type(setToggleState) == "function" then setToggleState(GUI.AutoParryBtn, _G.AutoParryBB) end

        if _G.AutoParryBB then
            -- Notificação Híbrida (Usa a do Hub, se não achar, usa a StarterGui)
            if type(S7xNotify) == "function" then 
                S7xNotify("AUTO PARRY", "Executed (We also added visualizer.)") 
            else
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "S7x",
                    Text = "Auto Parry Executed (We also added visualizer.)",
                    Icon = "rbxassetid://135351041318579",
                    Duration = 10,
                    Button1 = "OK"
                })
            end

            -- Injeta o Visualizador APENAS UMA VEZ na sessão para evitar crash
            if not autoParryVisualizerLoaded then
                autoParryVisualizerLoaded = true
                pcall(function()
                    loadstring(game:HttpGet("https://scriptblox.com/raw/UPD-Blade-Ball-op-autoparry-with-visualizer-8652"))()
                end)
            end

            -- Conecta o motor PreSimulation (Processamento Antes do Frame = Zero Delay)
            if not autoParryConn then
                autoParryConn = game:GetService("RunService").PreSimulation:Connect(function()
                    if not _G.AutoParryBB then return end
                    
                    local char = game.Players.LocalPlayer.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    local ball = getBladeBall()
                    
                    if not ball or not hrp then return end
                    
                    -- Blindagem anti-erro na extração de velocidade
                    local speed = 0.001
                    local zoomies = ball:FindFirstChild("zoomies")
                    
                    if zoomies and zoomies:IsA("VectorForce") then
                        speed = zoomies.VectorVelocity.Magnitude
                    else
                        speed = ball.AssemblyLinearVelocity.Magnitude
                    end
                    if speed == 0 then speed = 0.001 end
                    
                    local distance = (hrp.Position - ball.Position).Magnitude
                    
                    -- Mantém sua matemática nativa de 0.55 (Mas respeita o slider do Hub se o usuário mexer)
                    local threshold = _G.ParryDistance and math.clamp(_G.ParryDistance / 100, 0.1, 1.5) or 0.55
                    
                    -- Lógica Suprema de Defesa
                    if ball:GetAttribute("target") == game.Players.LocalPlayer.Name and not isParried and (distance / speed) <= threshold then
                        -- Envia o Click e SOLTA rapidamente (evita bugar a câmera do jogo segurando o click)
                        vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)
                        task.delay(0.05, function() vim:SendMouseButtonEvent(0, 0, 0, false, game, 0) end)
                        
                        isParried = true
                        parryCooldown = tick()
                    end
                    
                    -- Reset de segurança automático
                    if isParried and (tick() - parryCooldown) >= 1 then
                        isParried = false
                    end
                end)
            end
        else
            -- Limpeza Cirúrgica: Desliga as conexões quando desativado para remover Lag/Stuttering
            if autoParryConn then
                autoParryConn:Disconnect()
                autoParryConn = nil
            end
            resetBallConnection()
            
            if type(S7xNotify) == "function" then 
                S7xNotify("AUTO PARRY", "Deactivated. Engine resources freed.") 
            end
        end
    end)

