-- [ MOTOR DE VFX ABSOLUTO E ÁUDIO 3D (SWIRL) ]
local function PlayDashEffect(pos, direction)
    task.spawn(function()
        -- 1. Âncora Física (Base para o Áudio e VFX)
        local anchor = Instance.new("Part")
        anchor.Transparency = 1
        anchor.Anchored = true
        anchor.CanCollide = false
        anchor.Size = Vector3.new(0.1, 0.1, 0.1)
        -- A âncora rotaciona para olhar na direção do movimento (crucial para o Swirl cortar o ar)
        anchor.CFrame = CFrame.new(pos, pos + direction)
        anchor.Parent = workspace
        
        -- 2. ÁUDIO 3D PROFISSIONAL (Volume 50%)
        local sfx = Instance.new("Sound")
        sfx.SoundId = "rbxassetid://140324602533286"
        sfx.Volume = 0.5 
        sfx.RollOffMode = Enum.RollOffMode.Linear
        sfx.RollOffMinDistance = 10
        sfx.RollOffMaxDistance = 80
        sfx.Parent = anchor
        sfx:Play()
        
        -- 3. MOTOR DO EFEITO SWIRL NATIVO (Sem Download)
        local att = Instance.new("Attachment", anchor)
        local pe = Instance.new("ParticleEmitter", att)
        pe.Texture = "rbxassetid://8096189152"
        
        pe.Color = ColorSequence.new(Color3.fromRGB(240, 69, 255))
        pe.LightEmission = 1
        pe.LightInfluence = 0
        pe.ZOffset = 10
        
        -- O SEGREDO DO CORTE:
        pe.Orientation = Enum.ParticleOrientation.VelocityPerpendicular 
        
        pe.Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 6), 
            NumberSequenceKeypoint.new(1, 0)
        })
        pe.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0), 
            NumberSequenceKeypoint.new(1, 1)
        })
        
        -- [ A CORREÇÃO CRÍTICA ]: VelocityPerpendicular exige que a partícula tenha velocidade.
        pe.Speed = NumberRange.new(40, 50) -- Dispara a lâmina rapidamente
        pe.Drag = 8 -- Freia a lâmina bruscamente no ar logo após o disparo
        pe.Lifetime = NumberRange.new(0.3, 0.4)
        pe.EmissionDirection = Enum.NormalId.Back -- Força a emissão para trás (costas do player)
        pe.Enabled = false
        
        pe:Emit(20) -- Dispara 20 partículas juntas para formar uma lâmina densa
        
        -- Limpa a memória
        game:GetService("Debris"):AddItem(anchor, 2)
    end)
end

-- Motor Principal do Dash (Global para Mobile e PC)
_G.S7xTriggerDash = function()
    if not _G.S7xDashEnabled then return end
    local char = game.Players.LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChild("Humanoid")
    
    if hrp and hum then 
        local startPos = hrp.Position
        local dashDirection = hum.MoveDirection
        
        -- Se o personagem estiver parado, força o dash para onde a câmera está olhando
        if dashDirection.Magnitude == 0 then
            dashDirection = hrp.CFrame.LookVector
        end
        
        -- Dispara o som e o Swirl 3D no local de SAÍDA
        PlayDashEffect(startPos, dashDirection)
        
        -- Aplica a força de impulso na direção correta
        hrp.Velocity = dashDirection * 100 + Vector3.new(0, hrp.Velocity.Y, 0) 
        
        -- [ FIX DA INVISIBILIDADE DEFINITIVO ]
        task.spawn(function()
            game:GetService("RunService").RenderStepped:Wait()
            pcall(function()
                workspace.CurrentCamera.CameraSubject = hum
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                        part.LocalTransparencyModifier = 0
                        if part.Transparency >= 1 then 
                            part.Transparency = 0 
                        end
                    end
                end
            end)
        end)
        
        if type(S7xNotify) == "function" then S7xNotify("ACTION", "Dash Used") end
        
        -- Feedback Visual da UI (Mobile)
        pcall(function()
            local ts = game:GetService("TweenService")
            ts:Create(GUI.DashStroke, TweenInfo.new(0.15, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, 0, true), {Thickness = 4}):Play()
            ts:Create(GUI.DashGlow, TweenInfo.new(0.15, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, 0, true), {ImageTransparency = 0}):Play()
        end)
    end
end

