-- [ MOTOR GERADOR DE CATEGORIAS PROFISSIONAIS ]
local function createUltimateCategory(titleTxt, iconId, layoutOrder)
    local container = Instance.new("Frame", targetUltimateTab)
    container.Size = UDim2.new(0.98, 0, 0, 0)
    container.BackgroundTransparency = 1
    container.LayoutOrder = layoutOrder

    local header = Instance.new("Frame", container)
    header.Size = UDim2.new(1, 0, 0, 30)
    header.BackgroundTransparency = 1

    if iconId then
        local icon = Instance.new("ImageLabel", header)
        icon.Size = UDim2.new(0, 22, 0, 22)
        icon.Position = UDim2.new(0, 10, 0.5, -11)
        icon.BackgroundTransparency = 1
        icon.Image = "rbxassetid://" .. iconId
        icon.ScaleType = Enum.ScaleType.Fit
        icon.ImageColor3 = Color3.fromRGB(255, 255, 255)
    end

    local title = Instance.new("TextLabel", header)
    title.Size = UDim2.new(1, iconId and -40 or -20, 1, 0)
    title.Position = UDim2.new(0, iconId and 35 or 10, 0, 0)
    title.BackgroundTransparency = 1
    title.Text = string.upper(titleTxt)
    title.TextColor3 = Color3.fromRGB(255, 255, 255)
    title.Font = Enum.Font.GothamBlack
    title.TextSize = 13
    title.TextXAlignment = Enum.TextXAlignment.Left

    local gridFrame = Instance.new("Frame", container)
    gridFrame.Size = UDim2.new(1, 0, 0, 0)
    gridFrame.Position = UDim2.new(0, 0, 0, 35)
    gridFrame.BackgroundTransparency = 1

    local grid = Instance.new("UIGridLayout", gridFrame)
    grid.HorizontalAlignment = Enum.HorizontalAlignment.Center
    grid.SortOrder = Enum.SortOrder.LayoutOrder
    grid.CellPadding = UDim2.new(0, 12, 0, 12)
    grid.CellSize = UDim2.new(0.47, 0, 0, 38)

    grid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        gridFrame.Size = UDim2.new(1, 0, 0, grid.AbsoluteContentSize.Y)
        container.Size = UDim2.new(1, 0, 0, grid.AbsoluteContentSize.Y + 40)
        targetUltimateTab.CanvasSize = UDim2.new(0, 0, 0, GUI.UltimateLayout.AbsoluteContentSize.Y + 40)
    end)

    return gridFrame
end

