task.spawn(function()
    while task.wait(1) do
        local role = "User"
        pcall(function() if type(GetFirebaseRank) == "function" then role = GetFirebaseRank(player) or "User" end end)
        
        local isPerm = false
        if TagAdminRoles and (TagAdminRoles[role] or role == "Supreme" or role == "Ultimate" or role == "Influencer") then
            isPerm = true
        end

        if isPerm then
            GUI.TesterTimerFrame.Visible = false
        elseif type(isTesterActive) == "function" and isTesterActive() then
            GUI.TesterTimerFrame.Visible = true
            local rem = testerExpiration - os.time()
            if rem > 0 then
                local h = math_floor(rem / 3600)
                local m = math_floor((rem % 3600) / 60)
                local s = rem % 60
                
                GUI.TesterTimerLbl.Text = string.format("EXPIRES: %02d:%02d:%02d", h, m, s)
                timerStroke.Color = Color3.fromRGB(170, 0, 255)
            else
                GUI.TesterTimerLbl.Text = "EXPIRED"
                timerStroke.Color = Color3.fromRGB(255, 50, 50) -- Fica vermelho alertando a expiração
                
                -- Se a aba Ultimate estiver aberta e a key expirar, invoca o UltimateBlockFrame
                if GUI.UltimateFrame and GUI.UltimateFrame.Visible then
                    if type(_G.hasUltimateAccess) == "function" and not _G.hasUltimateAccess(player) then
                        local blockFrame = GUI.MainFrame and GUI.MainFrame:FindFirstChild("UltimateBlockFrame")
                        if blockFrame then blockFrame.Visible = true end
                    end
                end
            end
        else
            GUI.TesterTimerFrame.Visible = false
        end
    end
end)


