Instance.new("UICorner", GUI.TomStopBtn).CornerRadius = UDim.new(1, 0)

-- Motor do Tomate
local function getTomatoRemote()
    local char = game.Players.LocalPlayer.Character
    local tool = char and char:FindFirstChild("Tomato") or game.Players.LocalPlayer.Backpack:FindFirstChild("Tomato")
    return tool and tool:FindFirstChild("RemoteEvent")
end

local function lockTomatoTarget()
    local mouse = game.Players.LocalPlayer:GetMouse()
    local target = mouse.Target
    local model = target and target:FindFirstAncestorOfClass("Model")
    
    if model and model:FindFirstChild("Humanoid") then
        tomatoTarget = model
        isTomatoSpamming = true
        if type(S7xNotify) == "function" then S7xNotify("TOMATO LOCK", "Atacando: " .. tomatoTarget.Name) end
        if SafeTween then 
            SafeTween(GUI.TomLockBtn, 0.3, {BackgroundColor3 = Color3.fromRGB(255, 50, 50), TextColor3 = Color3.fromRGB(255, 255, 255)})
            SafeTween(GUI.TomStopBtn, 0.3, {BackgroundColor3 = Color3.fromRGB(20, 20, 25), TextColor3 = Color3.fromRGB(150, 150, 160)})
        end
    else
        if type(S7xNotify) == "function" then S7xNotify("ERROR", "Mire em um jogador válido!") end
    end
end

local function stopTomatoTarget()
    tomatoTarget = nil
    isTomatoSpamming = false
    if type(S7xNotify) == "function" then S7xNotify("TOMATO STOP", "Ataque cancelado.") end
    if SafeTween then 
        SafeTween(GUI.TomLockBtn, 0.3, {BackgroundColor3 = Color3.fromRGB(30, 20, 20), TextColor3 = Color3.fromRGB(255, 100, 100)})
        SafeTween(GUI.TomStopBtn, 0.3, {BackgroundColor3 = Color3.fromRGB(255, 50, 50), TextColor3 = Color3.fromRGB(255, 255, 255)})
        task.delay(0.5, function() SafeTween(GUI.TomStopBtn, 0.3, {BackgroundColor3 = Color3.fromRGB(20, 20, 25), TextColor3 = Color3.fromRGB(150, 150, 160)}) end)
    end
end

GUI.TomLockBtn.MouseButton1Click:Connect(lockTomatoTarget)
GUI.TomStopBtn.MouseButton1Click:Connect(stopTomatoTarget)

GUI.TomatoBtn.MouseButton1Click:Connect(function()
    _G.TomatoSpamEnabled = not _G.TomatoSpamEnabled
    if type(setToggleState) == "function" then setToggleState(GUI.TomatoBtn, _G.TomatoSpamEnabled) end
    
    -- Detector Profissional de Hardware
    local isMob = game:GetService("UserInputService").TouchEnabled and not game:GetService("UserInputService").KeyboardEnabled

    -- Sistema de Notificação Blindado (Garante que a mensagem chegue na tela)
    local function FireNotify(title, text)
        if type(S7xNotify) == "function" then 
            S7xNotify(title, text) 
        else
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = title,
                    Text = text,
                    Duration = 6,
                    Icon = "rbxassetid://135351041318579" -- Ícone do S7x
                })
            end)
        end
    end

    if _G.TomatoSpamEnabled then
        if isMob then
            -- MODO MOBILE: Mostra o widget tático e oculta o aviso de teclas
            FireNotify("TOMATO SPAM", "Use os botões flutuantes para mirar e atacar.")
            if GUI.TomatoWidget then GUI.TomatoWidget.Visible = true end
        else
            -- MODO PC: Oculta o widget (já que usa teclado) e avisa as Hotkeys
            FireNotify("TOMATO SPAM", "Aperte T para atacar tomate, R para parar.")
            if GUI.TomatoWidget then GUI.TomatoWidget.Visible = false end
        end
    else
        -- Desligamento
        stopTomatoTarget()
        if GUI.TomatoWidget then GUI.TomatoWidget.Visible = false end
    end
end)

-- Keybinds de Teclado
game:GetService("UserInputService").InputBegan:Connect(function(input, gpe)
    if gpe or not _G.TomatoSpamEnabled then return end
    if input.KeyCode == Enum.KeyCode.T then lockTomatoTarget() end
    if input.KeyCode == Enum.KeyCode.R then stopTomatoTarget() end
end)

-- Loop de Ataque sem Cooldown
game:GetService("RunService").Heartbeat:Connect(function()
    if _G.TomatoSpamEnabled and isTomatoSpamming and tomatoTarget and tomatoTarget:FindFirstChild("Head") then
        local remote = getTomatoRemote()
        if remote then
            local posAlvo = tomatoTarget.Head.Position
            for i = 1, tomatesPorFrame do
                local origem = posAlvo + Vector3.new(0, 0.1, 0)
                remote:FireServer(origem, posAlvo)
            end
        end
    elseif isTomatoSpamming and (not tomatoTarget or not tomatoTarget.Parent) then
        stopTomatoTarget()
    end
end)

_G.S7xEmoteBugUI_Loaded = false
GUI.EmoteBugBtn.MouseButton1Click:Connect(function()
