        return 
    end
    _G.S7xEmoteBugUI_Loaded = true
    GUI.EmoteBugBtn.Text = "EMOTE BUG LOADED"
    
    -- O uso do task.spawn isola as variáveis e PROTEGE contra o limite de 200 locals do Roblox!
    task.spawn(function()
        local Services = setmetatable({}, { __index = function(_, name) return game:GetService(name) end })
        local Players = Services.Players
        local RunService = Services.RunService
        local UserInputService = Services.UserInputService
        local TweenService = Services.TweenService

        local lplayer = Players.LocalPlayer
        local character = lplayer.Character or lplayer.CharacterAdded:Wait()
        local humanoid = character:WaitForChild("Humanoid", 999)

        lplayer.CharacterAdded:Connect(function(newCharacter)
            character = newCharacter
            humanoid = character:WaitForChild("Humanoid", 999)
        end)

        local Settings = { ["Stop On Move"] = true, ["Fade In"] = 0.1, ["Fade Out"] = 0.1, ["Weight"] = 1, ["Speed"] = 1, ["Allow Invisible"] = true, ["Time Position"] = 0 }
        local CurrentTrack
        local lastPosition = character.PrimaryPart and character.PrimaryPart.Position or Vector3.new()

        local function extractIdFromInput(input)
            local num = tonumber(input)
            if num then return num end
            return tonumber(string.match(input, "rbxassetid://(%d+)") or string.match(input, "roblox%.com/catalog/(%d+)") or string.match(input, "roblox%.com/library/(%d+)") or string.match(input, "roblox%.com/asset/%?id=(%d+)")) or tonumber(input)
        end

        local function LoadTrack(id)
            if CurrentTrack then CurrentTrack:Stop(0) end
            local animId
            local ok, result = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(id)) end)
            if ok and result and #result > 0 then
                local anim = result[1]
                animId = anim:IsA("Animation") and anim.AnimationId or "rbxassetid://" .. tostring(id)
            else
                animId = "rbxassetid://" .. tostring(id)
            end

            local newAnim = Instance.new("Animation")
            newAnim.AnimationId = animId
            local newTrack = humanoid:LoadAnimation(newAnim)
            newTrack.Priority = Enum.AnimationPriority.Action4

            local weight = Settings["Weight"] == 0 and 0.001 or Settings["Weight"]
            newTrack:Play(Settings["Fade In"], weight, Settings["Speed"])
            CurrentTrack = newTrack
            CurrentTrack.TimePosition = math.clamp(Settings["Time Position"], 0, 1) * CurrentTrack.Length
            return newTrack
        end

        local function StopTrack()
            if CurrentTrack then CurrentTrack:Stop(Settings["Fade Out"]); CurrentTrack = nil end
        end

        -- [ DESIGN PREMIUM S7X APLICADO NA UI DO SCRIPT ]
        local screenGui = Instance.new("ScreenGui", Services.CoreGui)
