        title.Text = "✨ S7X EMOTE INJECTOR"
        title.Font = Enum.Font.GothamBlack
        title.TextSize = 14
        title.TextColor3 = Color3.fromRGB(170, 0, 255)

        local emoteBox = Instance.new("TextBox", mainFrame)
        emoteBox.Size = UDim2.new(1, -20, 0, 30)
        emoteBox.Position = UDim2.new(0, 10, 0, 40)
        emoteBox.BackgroundColor3 = Color3.fromRGB(20, 18, 25)
        emoteBox.Text = "93224413172183" -- AUTO PREENCHIDO COM O ID QUE VOCÊ PEDIU
        emoteBox.PlaceholderText = "Paste Emote ID..."
        emoteBox.TextColor3 = Color3.fromRGB(255, 255, 255)
        emoteBox.Font = Enum.Font.GothamBold
        emoteBox.TextSize = 12
        emoteBox.ClearTextOnFocus = false
        Instance.new("UICorner", emoteBox).CornerRadius = UDim.new(0, 6)
        Instance.new("UIStroke", emoteBox).Color = Color3.fromRGB(45, 25, 75)

        local btnContainer = Instance.new("Frame", mainFrame)
        btnContainer.Size = UDim2.new(1, -20, 0, 32)
        btnContainer.Position = UDim2.new(0, 10, 0, 80)
        btnContainer.BackgroundTransparency = 1

        local playButton = Instance.new("TextButton", btnContainer)
        playButton.Size = UDim2.new(0.48, 0, 1, 0)
        playButton.BackgroundColor3 = Color3.fromRGB(140, 0, 255)
        playButton.Text = "▶ PLAY EMOTE"
        playButton.TextColor3 = Color3.fromRGB(255, 255, 255)
        playButton.Font = Enum.Font.GothamBold
        playButton.TextSize = 11
        Instance.new("UICorner", playButton).CornerRadius = UDim.new(0, 6)

        local stopButton = Instance.new("TextButton", btnContainer)
        stopButton.Size = UDim2.new(0.48, 0, 1, 0)
        stopButton.Position = UDim2.new(0.52, 0, 0, 0)
        stopButton.BackgroundColor3 = Color3.fromRGB(30, 20, 25)
        stopButton.Text = "■ STOP"
        stopButton.TextColor3 = Color3.fromRGB(255, 100, 100)
        stopButton.Font = Enum.Font.GothamBold
        stopButton.TextSize = 11
        Instance.new("UICorner", stopButton).CornerRadius = UDim.new(0, 6)
        Instance.new("UIStroke", stopButton).Color = Color3.fromRGB(255, 50, 50)

        playButton.MouseButton1Click:Connect(function()
            local input = emoteBox.Text
            if input and input ~= "" then
                local id = extractIdFromInput(input)
                if id then CurrentTrack = LoadTrack(id) end
            end
        end)
        stopButton.MouseButton1Click:Connect(StopTrack)

        local scrollFrame = Instance.new("ScrollingFrame", mainFrame)
        scrollFrame.Size = UDim2.new(1, -20, 1, -125)
        scrollFrame.Position = UDim2.new(0, 10, 0, 120)
        scrollFrame.BackgroundTransparency = 1
        scrollFrame.ScrollBarThickness = 2
        scrollFrame.ScrollBarImageColor3 = Color3.fromRGB(140, 0, 255)
        
        local listLayout = Instance.new("UIListLayout", scrollFrame)
        listLayout.Padding = UDim.new(0, 6)
        listLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            scrollFrame.CanvasSize = UDim2.new(0, 0, 0, listLayout.AbsoluteContentSize.Y + 10)
        end)

        RunService.RenderStepped:Connect(function()
            if character.PrimaryPart then
                if Settings["Stop On Move"] and CurrentTrack and CurrentTrack.IsPlaying then
                    local moved = (character.PrimaryPart.Position - lastPosition).Magnitude > 0.1
                    local jumped = humanoid and humanoid:GetState() == Enum.HumanoidStateType.Jumping
                    if moved or jumped then StopTrack() end
                end
                lastPosition = character.PrimaryPart.Position
            end
        end)

        local function createSlider(name, min, max, default)
            Settings[name] = default or min
            local bg = Instance.new("Frame", scrollFrame)
            bg.Size = UDim2.new(1, -10, 0, 45)
            bg.BackgroundColor3 = Color3.fromRGB(20, 18, 25)
            Instance.new("UICorner", bg).CornerRadius = UDim.new(0, 6)
            Instance.new("UIStroke", bg).Color = Color3.fromRGB(45, 25, 75)

            local label = Instance.new("TextLabel", bg)
            label.Size = UDim2.new(0.5, -10, 0, 20)
            label.Position = UDim2.new(0, 10, 0, 5)
            label.BackgroundTransparency = 1
            label.Text = string.format("%s: %.2f", name, Settings[name])
            label.TextColor3 = Color3.fromRGB(220, 220, 230)
            label.Font = Enum.Font.GothamBold
            label.TextSize = 10
            label.TextXAlignment = Enum.TextXAlignment.Left

            local sliderBar = Instance.new("Frame", bg)
            sliderBar.Size = UDim2.new(1, -20, 0, 6)
            sliderBar.Position = UDim2.new(0, 10, 0, 30)
            sliderBar.BackgroundColor3 = Color3.fromRGB(15, 12, 18)
            Instance.new("UICorner", sliderBar).CornerRadius = UDim.new(1, 0)

            local sliderFill = Instance.new("Frame", sliderBar)
            sliderFill.Size = UDim2.new(0, 0, 1, 0)
            sliderFill.BackgroundColor3 = Color3.fromRGB(140, 0, 255)
            Instance.new("UICorner", sliderFill).CornerRadius = UDim.new(1, 0)

            local thumb = Instance.new("Frame", sliderBar)
            thumb.Size = UDim2.new(0, 12, 0, 12)
            thumb.AnchorPoint = Vector2.new(0.5, 0.5)
            thumb.Position = UDim2.new(0, 0, 0.5, 0)
            thumb.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Instance.new("UICorner", thumb).CornerRadius = UDim.new(1, 0)

            local function applyValue(value)
                Settings[name] = value
                label.Text = string.format("%s: %.2f", name, value)
                local rel = math.clamp((value - min) / (max - min), 0, 1)
                TweenService:Create(sliderFill, TweenInfo.new(0.15), {Size = UDim2.new(rel, 0, 1, 0)}):Play()
                TweenService:Create(thumb, TweenInfo.new(0.15), {Position = UDim2.new(rel, 0, 0.5, 0)}):Play()

                if CurrentTrack and CurrentTrack.IsPlaying then
                    if name == "Speed" then CurrentTrack:AdjustSpeed(Settings["Speed"])
                    elseif name == "Weight" then CurrentTrack:AdjustWeight(Settings["Weight"] == 0 and 0.001 or Settings["Weight"])
                    elseif name == "Time Position" and CurrentTrack.Length > 0 then CurrentTrack.TimePosition = math.clamp(value, 0, 1) * CurrentTrack.Length end
                end
            end

            local dragging = false
            local function updateInput(input)
                local relX = math.clamp((input.Position.X - sliderBar.AbsolutePosition.X) / sliderBar.AbsoluteSize.X, 0, 1)
                applyValue(math.floor((min + (max - min) * relX) * 100) / 100)
            end

            sliderBar.InputBegan:Connect(function(i) if i.UserInputType.Name:find("MouseButton1") or i.UserInputType.Name:find("Touch") then dragging = true; updateInput(i) end end)
            thumb.InputBegan:Connect(function(i) if i.UserInputType.Name:find("MouseButton1") or i.UserInputType.Name:find("Touch") then dragging = true; updateInput(i) end end)
            UserInputService.InputChanged:Connect(function(i) if dragging and (i.UserInputType.Name:find("MouseMovement") or i.UserInputType.Name:find("Touch")) then updateInput(i) end end)
            UserInputService.InputEnded:Connect(function(i) if dragging and (i.UserInputType.Name:find("MouseButton1") or i.UserInputType.Name:find("Touch")) then dragging = false end end)
            applyValue(Settings[name])
        end

        local function createToggle(name)
            local container = Instance.new("Frame", scrollFrame)
            container.Size = UDim2.new(1, -10, 0, 36)
            container.BackgroundColor3 = Color3.fromRGB(20, 18, 25)
            Instance.new("UICorner", container).CornerRadius = UDim.new(0, 6)
            Instance.new("UIStroke", container).Color = Color3.fromRGB(45, 25, 75)

            local label = Instance.new("TextLabel", container)
            label.Size = UDim2.new(0.7, -10, 1, 0)
            label.Position = UDim2.new(0, 10, 0, 0)
            label.BackgroundTransparency = 1
            label.Text = name
            label.TextColor3 = Color3.fromRGB(220, 220, 230)
            label.Font = Enum.Font.GothamBold
            label.TextSize = 11
            label.TextXAlignment = Enum.TextXAlignment.Left

            local toggleBtn = Instance.new("TextButton", container)
            toggleBtn.Size = UDim2.new(0, 45, 0, 22)
            toggleBtn.Position = UDim2.new(1, -55, 0.5, -11)
            toggleBtn.BackgroundColor3 = Settings[name] and Color3.fromRGB(140, 0, 255) or Color3.fromRGB(30, 20, 25)
            toggleBtn.Text = Settings[name] and "ON" or "OFF"
            toggleBtn.TextColor3 = Settings[name] and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(150, 150, 160)
            toggleBtn.Font = Enum.Font.GothamBold
            toggleBtn.TextSize = 10
            Instance.new("UICorner", toggleBtn).CornerRadius = UDim.new(0, 4)
            local strk = Instance.new("UIStroke", toggleBtn)
            strk.Color = Settings[name] and Color3.fromRGB(180, 50, 255) or Color3.fromRGB(255, 50, 50)

            toggleBtn.MouseButton1Click:Connect(function()
                Settings[name] = not Settings[name]
                if Settings[name] then
                    TweenService:Create(toggleBtn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(140, 0, 255), TextColor3 = Color3.fromRGB(255, 255, 255)}):Play()
                    TweenService:Create(strk, TweenInfo.new(0.3), {Color = Color3.fromRGB(180, 50, 255)}):Play()
                    toggleBtn.Text = "ON"
                else
                    TweenService:Create(toggleBtn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(30, 20, 25), TextColor3 = Color3.fromRGB(150, 150, 160)}):Play()
                    TweenService:Create(strk, TweenInfo.new(0.3), {Color = Color3.fromRGB(255, 50, 50)}):Play()
                    toggleBtn.Text = "OFF"
                end
            end)
        end

        createToggle("Stop On Move")
        createSlider("Time Position", 0, 1, Settings["Time Position"])
        createSlider("Speed", 0, 5, Settings["Speed"])
        createSlider("Weight", 0, 1, Settings["Weight"])
        createSlider("Fade In", 0, 2, Settings["Fade In"])
        createSlider("Fade Out", 0, 2, Settings["Fade Out"])
        createToggle("Allow Invisible")

        local originalCollisionStates = {}
        local lastFixClipState = Settings["Allow Invisible"]

        local function saveCollisionStates()
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then originalCollisionStates[part] = part.CanCollide end
            end
        end
        local function disableCollisionsExceptRootPart()
            if not Settings["Allow Invisible"] then return end
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then part.CanCollide = false end
            end
        end
        local function restoreCollisionStates()
            for part, canCollide in pairs(originalCollisionStates) do if part and part.Parent then part.CanCollide = canCollide end end
            originalCollisionStates = {}
        end

        saveCollisionStates()
        RunService.Stepped:Connect(function()
            if character and character.Parent then
                local currentFixClip = Settings["Allow Invisible"]
                if lastFixClipState ~= currentFixClip then
                    if currentFixClip then saveCollisionStates(); disableCollisionsExceptRootPart() else restoreCollisionStates() end
                    lastFixClipState = currentFixClip
                elseif currentFixClip then disableCollisionsExceptRootPart() end
            else restoreCollisionStates() end
        end)
    end)
end)

-- ==========================================
    -- [ MOTOR GRÁFICO: FPS ESP (DRAWING API) ]
    -- ==========================================
    _G.S7xFpsEspEnabled = false
    local FpsEspCache = {}
    local ESPCamera = workspace.CurrentCamera

    local function createFpsEsp(plr)
        local esp = {}
        pcall(function()
            -- Box Outline e Box Principal
            esp.BoxOutline = Drawing.new("Square"); esp.BoxOutline.Thickness = 3; esp.BoxOutline.Filled = false; esp.BoxOutline.Color = Color3.fromRGB(0,0,0)
            esp.Box = Drawing.new("Square"); esp.Box.Thickness = 1.5; esp.Box.Filled = false; esp.Box.Color = Color3.fromRGB(255, 50, 50)
            
            -- Barra de Vida (Fundo Preto + Preenchimento Gradiente)
            esp.HealthBg = Drawing.new("Line"); esp.HealthBg.Thickness = 4; esp.HealthBg.Color = Color3.fromRGB(0,0,0)
            esp.HealthBar = Drawing.new("Line"); esp.HealthBar.Thickness = 2; esp.HealthBar.Color = Color3.fromRGB(0,255,0)
            
            -- Linha Tracer
            esp.Tracer = Drawing.new("Line"); esp.Tracer.Thickness = 1.5; esp.Tracer.Color = Color3.fromRGB(255, 50, 50)
            
            -- Textos (Nick e Distância)
            esp.Name = Drawing.new("Text"); esp.Name.Text = plr.Name; esp.Name.Size = 13; esp.Name.Center = true; esp.Name.Outline = true; esp.Name.Color = Color3.fromRGB(255,255,255)
            esp.Dist = Drawing.new("Text"); esp.Dist.Size = 11; esp.Dist.Center = true; esp.Dist.Outline = true; esp.Dist.Color = Color3.fromRGB(200,200,200)
            
            FpsEspCache[plr] = esp
        end)
    end

    local function removeFpsEsp(plr)
        if FpsEspCache[plr] then
            for _, d in pairs(FpsEspCache[plr]) do pcall(function() d:Remove() end) end
            FpsEspCache[plr] = nil
        end
    end

    for _, p in pairs(game.Players:GetPlayers()) do
        if p ~= game.Players.LocalPlayer then createFpsEsp(p) end
    end
    game.Players.PlayerAdded:Connect(createFpsEsp)
    game.Players.PlayerRemoving:Connect(removeFpsEsp)

    -- Loop de Renderização Extrema (RenderStepped - 0 Latência)
    game:GetService("RunService").RenderStepped:Connect(function()
        for plr, esp in pairs(FpsEspCache) do
            local isVisible = false
            
            if _G.S7xFpsEspEnabled and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") and plr.Character:FindFirstChild("Humanoid") and plr.Character.Humanoid.Health > 0 then
                local isEnemy = true
                -- Verifica se são do mesmo time
                if plr.Team and game.Players.LocalPlayer.Team and plr.Team == game.Players.LocalPlayer.Team then 
                    isEnemy = false 
                end
                
                if isEnemy then
                    local hrp = plr.Character.HumanoidRootPart
                    local head = plr.Character:FindFirstChild("Head") or hrp
                    
                    local hrpPos, onScreen = ESPCamera:WorldToViewportPoint(hrp.Position)
                    if onScreen then
                        local headPos = ESPCamera:WorldToViewportPoint(head.Position + Vector3.new(0, 0.5, 0))
                        local legPos = ESPCamera:WorldToViewportPoint(hrp.Position - Vector3.new(0, 3, 0))
                        
                        local dist = (ESPCamera.CFrame.Position - hrp.Position).Magnitude
                        
                        -- [ O SEGREDO DO ESP: OPACIDADE DINÂMICA ]
                        -- O Range limite de cálculo é de 800 studs. Quando mais perto, alpha vira 1 (Full Visível)
                        local alpha = math.clamp(1 - (dist / 800), 0.15, 1)
                        
                        local height = math.abs(headPos.Y - legPos.Y)
                        local width = height * 0.6

                        pcall(function()
                            -- Posicionamento e Redimensionamento da Box
                            esp.Box.Size = Vector2.new(width, height)
                            esp.Box.Position = Vector2.new(hrpPos.X - width/2, headPos.Y)
                            esp.Box.Transparency = alpha
                            
                            esp.BoxOutline.Size = esp.Box.Size
                            esp.BoxOutline.Position = esp.Box.Position
                            esp.BoxOutline.Transparency = alpha

                            -- Barra de Vida Dinâmica e Alinhada à Box
                            local hpPct = math.clamp(plr.Character.Humanoid.Health / plr.Character.Humanoid.MaxHealth, 0, 1)
                            
                            esp.HealthBg.From = Vector2.new(hrpPos.X - width/2 - 6, headPos.Y)
                            esp.HealthBg.To = Vector2.new(hrpPos.X - width/2 - 6, legPos.Y)
                            esp.HealthBg.Transparency = alpha
                            
                            esp.HealthBar.From = Vector2.new(hrpPos.X - width/2 - 6, legPos.Y)
                            esp.HealthBar.To = Vector2.new(hrpPos.X - width/2 - 6, legPos.Y - (height * hpPct))
                            esp.HealthBar.Color = Color3.fromHSV(0.3 * hpPct, 1, 1) -- Transição de Vermelho p/ Verde
                            esp.HealthBar.Transparency = alpha

                            -- Tracer (Sai da parte debaixo do centro da tela para o pé do inimigo)
                            esp.Tracer.From = Vector2.new(ESPCamera.ViewportSize.X / 2, ESPCamera.ViewportSize.Y)
                            esp.Tracer.To = Vector2.new(hrpPos.X, legPos.Y)
                            esp.Tracer.Transparency = alpha

                            -- Textos de Nome e Distância
                            esp.Name.Position = Vector2.new(hrpPos.X, headPos.Y - 18)
                            esp.Name.Transparency = alpha
                            
                            esp.Dist.Text = math.floor(dist) .. "m"
                            esp.Dist.Position = Vector2.new(hrpPos.X, legPos.Y + 2)
                            esp.Dist.Transparency = alpha

                            isVisible = true
                        end)
                    end
                end
            end

            -- Liga ou desliga as linhas deste jogador baseado nas checagens
            pcall(function()
                for _, d in pairs(esp) do d.Visible = isVisible end
            end)
        end
    end)

    -- Função Global para Ligar/Desligar
    _G.S7xToggleFpsEsp = function()
        _G.S7xFpsEspEnabled = not _G.S7xFpsEspEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.FpsEspBtn, _G.S7xFpsEspEnabled) end
    end
    GUI.FpsEspBtn.MouseButton1Click:Connect(_G.S7xToggleFpsEsp)

    -- Motor Assíncrono de Hotkey Exclusiva (Não interfere no resto do HUB)
    if _G.FpsEspInputConn then _G.FpsEspInputConn:Disconnect() end
    _G.FpsEspInputConn = game:GetService("UserInputService").InputBegan:Connect(function(i, p)
        if p then return end
        if bindKeys.FpsEsp and i.KeyCode == bindKeys.FpsEsp then
            _G.S7xToggleFpsEsp()
            if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "FPS ESP (AIM LINES) Toggled") end
        end
    end)


   -- ==========================================
-- FLING NOTIFY (DETECTOR DE ATAQUE & ESP 60S PREMIUM)
-- ==========================================
_G.FlingNotifyEnabled = false
local flingNotifyConn = nil
local lastNearbyPlayer = nil
local flingEspCache = {}

local function applyFlingESP(targetPlayer)
    -- Limpa cache antigo se existir para não sobrepor (incluindo o loop de distância)
    if flingEspCache[targetPlayer.UserId] then
        pcall(function() flingEspCache[targetPlayer.UserId].hl:Destroy() end)
        pcall(function() flingEspCache[targetPlayer.UserId].bb:Destroy() end)
        if flingEspCache[targetPlayer.UserId].conn then flingEspCache[targetPlayer.UserId].conn:Disconnect() end
    end

    local char = targetPlayer.Character
    if not char then return end

    local head = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
    if not head then return end

    -- Highlight Profissional S7x (Raio-X Vermelho)
    local hl = Instance.new("Highlight")
    hl.Name = "S7x_FlingESP"
    hl.FillColor = Color3.fromRGB(255, 20, 20)
    hl.OutlineColor = Color3.fromRGB(255, 255, 255)
    hl.FillTransparency = 0.5
    hl.OutlineTransparency = 0.1
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Parent = char

    -- BillboardGui Premium (Painel Flutuante)
    local bb = Instance.new("BillboardGui")
    bb.Name = "S7x_FlingTag"
    bb.Size = UDim2.new(0, 150, 0, 130)
    bb.StudsOffset = Vector3.new(0, 1.8, 0)
    bb.AlwaysOnTop = true
    bb.Active = true 
    bb.Parent = head

    -- Avatar Redondo (Clicável)
    local btnAvatar = Instance.new("ImageButton", bb)
    btnAvatar.Name = "AvatarBtn"
    btnAvatar.Size = UDim2.new(0, 44, 0, 44)
    btnAvatar.Position = UDim2.new(0.5, -22, 0, 0)
    btnAvatar.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
    btnAvatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. targetPlayer.UserId .. "&w=150&h=150"
    btnAvatar.AutoButtonColor = false
    Instance.new("UICorner", btnAvatar).CornerRadius = UDim.new(1, 0)
    
    local stroke = Instance.new("UIStroke", btnAvatar)
    stroke.Name = "Stroke"
    stroke.Thickness = 2.5
    stroke.Color = Color3.fromRGB(255, 50, 50) -- Vermelho Perigo

    -- Animação de Hover
    btnAvatar.MouseEnter:Connect(function() pcall(function() game:GetService("TweenService"):Create(btnAvatar, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Size = UDim2.new(0, 54, 0, 54), Position = UDim2.new(0.5, -27, 0, -5)}):Play() end) end)
    btnAvatar.MouseLeave:Connect(function() pcall(function() game:GetService("TweenService"):Create(btnAvatar, TweenInfo.new(0.2, Enum.EasingStyle.Quint), {Size = UDim2.new(0, 44, 0, 44), Position = UDim2.new(0.5, -22, 0, 0)}):Play() end) end)
    
    -- Motor de Clique (Segurar copia Nick / Clicar Teleporta)
    local isHolding = false; local holdStartTick = 0; local holdTimeRequired = 0.5 
    btnAvatar.InputBegan:Connect(function(input)
        if input.UserInputType.Name:find("MouseButton1") or input.UserInputType.Name:find("Touch") then
            isHolding = true; holdStartTick = tick()
            pcall(function() game:GetService("TweenService"):Create(stroke, TweenInfo.new(holdTimeRequired, Enum.EasingStyle.Linear), {Thickness = 5}):Play() end)
            task.spawn(function()
                while isHolding do
                    if tick() - holdStartTick >= holdTimeRequired then
                        isHolding = false
                        pcall(function() if setclipboard then setclipboard("@" .. targetPlayer.Name) end end)
                        if type(S7xNotify) == "function" then S7xNotify("USER COPIED", "Copied: @" .. targetPlayer.Name) end
                        pcall(function() local ts = game:GetService("TweenService"); ts:Create(stroke, TweenInfo.new(0.2), {Thickness = 2.5}):Play(); ts:Create(btnAvatar, TweenInfo.new(0.15, Enum.EasingStyle.Bounce), {Size = UDim2.new(0, 44, 0, 44), Position = UDim2.new(0.5, -22, 0, 0)}):Play() end)
                        break
                    end
                    game:GetService("RunService").Heartbeat:Wait()
                end
            end)
        end
    end)
    btnAvatar.InputEnded:Connect(function(input)
        if input.UserInputType.Name:find("MouseButton1") or input.UserInputType.Name:find("Touch") then
            local heldDuration = tick() - holdStartTick; isHolding = false 
            pcall(function() game:GetService("TweenService"):Create(stroke, TweenInfo.new(0.2), {Thickness = 2.5}):Play() end)
            if heldDuration < holdTimeRequired then
                local mHrp = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                local tHrp = char:FindFirstChild("HumanoidRootPart")
                if mHrp and tHrp then mHrp.CFrame = tHrp.CFrame * CFrame.new(0, 0, 2) end
            end
        end
    end)

    -- Texto com Informações
    local lbl = Instance.new("TextLabel", bb)
    lbl.Name = "L"
    lbl.Size = UDim2.new(1, 0, 0, 60)
    lbl.Position = UDim2.new(0, 0, 0, 48)
    lbl.BackgroundTransparency = 1
    lbl.Font = Enum.Font.GothamBlack
    lbl.TextSize = 12
    lbl.RichText = true
    lbl.TextYAlignment = Enum.TextYAlignment.Top
    
    local txtStroke = Instance.new("UIStroke", lbl)
    txtStroke.Color = Color3.fromRGB(0, 0, 0)
    txtStroke.Thickness = 1.5

    -- Loop para atualizar a Distância em Tempo Real
    local conn = game:GetService("RunService").RenderStepped:Connect(function()
        if not char or not char.Parent or not bb.Parent then return end
        local myHrp = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        local tHrp = char:FindFirstChild("HumanoidRootPart")
        local dist = (myHrp and tHrp) and math.floor((myHrp.Position - tHrp.Position).Magnitude) or 0
        
        lbl.Text = string.format("<font color='#ff3333'>⚠️ FLINGER</font>\n<font color='#ffffff'>%s</font>\n<font size='10' color='#bbbbbb'>@%s (%d)</font>\n<font color='#00ffcc'>%dm</font>", targetPlayer.DisplayName, targetPlayer.Name, targetPlayer.UserId, dist)
    end)

    flingEspCache[targetPlayer.UserId] = {hl = hl, bb = bb, conn = conn}

    -- Auto-Destruição estendida para 60 segundos (1 minuto)
    task.delay(60, function()
        if flingEspCache[targetPlayer.UserId] then
            pcall(function() flingEspCache[targetPlayer.UserId].hl:Destroy() end)
            pcall(function() flingEspCache[targetPlayer.UserId].bb:Destroy() end)
            if flingEspCache[targetPlayer.UserId].conn then flingEspCache[targetPlayer.UserId].conn:Disconnect() end
            flingEspCache[targetPlayer.UserId] = nil
        end
    end)
end

GUI.FlingNotifyBtn.MouseButton1Click:Connect(function()
    _G.FlingNotifyEnabled = not _G.FlingNotifyEnabled
    if type(setToggleState) == "function" then setToggleState(GUI.FlingNotifyBtn, _G.FlingNotifyEnabled) end

    if _G.FlingNotifyEnabled then
        if type(S7xNotify) == "function" then S7xNotify("FLING NOTIFY", "Radar de anomalias físicas ativado.") end
        
        if flingNotifyConn then flingNotifyConn:Disconnect() end
        flingNotifyConn = game:GetService("RunService").Heartbeat:Connect(function()
            local myChar = game.Players.LocalPlayer.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHrp then return end

            local speed = myHrp.AssemblyLinearVelocity.Magnitude

            if speed < 150 then
                local closestDist = 18 
                lastNearbyPlayer = nil
                for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                    if p ~= game.Players.LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                        local dist = (p.Character.HumanoidRootPart.Position - myHrp.Position).Magnitude
                        if dist < closestDist then
                            closestDist = dist
                            lastNearbyPlayer = p
                        end
                    end
                end
            elseif speed >= 250 then 
                if lastNearbyPlayer then
                    local culprit = lastNearbyPlayer
                    lastNearbyPlayer = nil 
                    
                    if type(S7xNotify) == "function" then 
                        S7xNotify("⚠️ FLING DETECTADO", "Alvo agressor: " .. string.upper(culprit.Name), 8) 
                    end
                    
                    applyFlingESP(culprit)
                    task.wait(2)
                end
            end
        end)
    else
        if type(S7xNotify) == "function" then S7xNotify("FLING NOTIFY", "Radar desativado.") end
        if flingNotifyConn then flingNotifyConn:Disconnect(); flingNotifyConn = nil end
        
        -- Limpeza Segura
        for uid, esp in pairs(flingEspCache) do
            pcall(function() esp.hl:Destroy() end)
            pcall(function() esp.bb:Destroy() end)
            pcall(function() if esp.conn then esp.conn:Disconnect() end end)
        end
        flingEspCache = {}
    end
end)

