_G.ObservationHakiEnabled = false

local hakiFolder = targetParent:FindFirstChild("S7x_HakiFolder")
if not hakiFolder then
    hakiFolder = Instance.new("Folder", targetParent)
    hakiFolder.Name = "S7x_HakiFolder"
end

local hakiRadius = 50

-- MOTOR GLOBAL DE TEMPO DE SESSÃO E BANCO DE DADOS
_G.S7xSessionTracker = _G.S7xSessionTracker or {}

for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
    if not _G.S7xSessionTracker[p.UserId] then
        local backupTime = nil
        pcall(function()
            if type(playerJoinTimes) == "table" and playerJoinTimes[p.UserId] then backupTime = playerJoinTimes[p.UserId] end
        end)
        _G.S7xSessionTracker[p.UserId] = backupTime or os.time()
    end
end

game:GetService("Players").PlayerAdded:Connect(function(p)
    if not _G.S7xSessionTracker[p.UserId] then _G.S7xSessionTracker[p.UserId] = os.time() end
end)

local function GetExactSessionTime(plr)
    local joinTime = _G.S7xSessionTracker[plr.UserId] or os.time()
    local sessionTotal = os.time() - joinTime
    local sHours = math.floor(sessionTotal / 3600)
    local sMins = math.floor((sessionTotal % 3600) / 60)
    local sSecs = sessionTotal % 60
    return string.format("%02dh %02dm %02ds", sHours, sMins, sSecs)
end

local function GetDatabaseTime(plr)
    local timeStr = nil
    pcall(function()
        local ls = plr:FindFirstChild("leaderstats")
        if ls then
            local timeNames = {"Time", "Minutes", "Minutos", "Hours", "Horas", "Tempo", "TimePlayed", "PlayTime", "Mins"}
            for _, statName in ipairs(timeNames) do
                local stat = ls:FindFirstChild(statName)
                if stat then
                    local val = tonumber(stat.Value)
                    if val then
                        if val >= 1000 then
                            timeStr = string.format("%.2fK %s", val / 1000, statName:sub(1,3):upper())
                        else
                            timeStr = tostring(val) .. " " .. statName:sub(1,3):upper()
                        end
                        break
                    end
                end
            end
        end
    end)
    return timeStr or GetExactSessionTime(plr)
end

local function GetSafeIcon(tool)
    local icon = ""
    pcall(function()
        if tool and tool:IsA("Tool") and tool.TextureId and tool.TextureId ~= "" then icon = tool.TextureId end
    end)
    if icon ~= "" then return icon end
    return "rbxassetid://11598463991"
end

