                                infoLbl.TextSize = 10
                                infoLbl.TextColor3 = Color3.fromRGB(180, 180, 180)
                                infoLbl.TextXAlignment = Enum.TextXAlignment.Left
                                infoLbl.RichText = true
                                infoLbl.ZIndex = 2
                                
                                local hpBg = Instance.new("Frame", bg)
                                hpBg.Name = "HpBg"
                                hpBg.Size = UDim2.new(1, -10, 0, 12) 
                                hpBg.Position = UDim2.new(0, 5, 0, 38)
                                hpBg.BackgroundColor3 = Color3.fromRGB(30, 20, 30)
                                Instance.new("UICorner", hpBg).CornerRadius = UDim.new(0, 4)
