                                end
                                
                                local allTools = {}
                                local equippedTool = char:FindFirstChildOfClass("Tool")
                                if equippedTool then table.insert(allTools, {tool = equippedTool, equipped = true}) end
                                
                                local backpack = plr:FindFirstChild("Backpack")
                                if backpack then
                                    for _, item in ipairs(backpack:GetChildren()) do
                                        if item:IsA("Tool") then table.insert(allTools, {tool = item, equipped = false}) end
                                    end
                                end
                                
                                local invArea = bg:FindFirstChild("InvArea")
                                if invArea then
                                    for _, child in ipairs(invArea:GetChildren()) do
                                        if child:IsA("ImageLabel") then child:Destroy() end
                                    end
                                    
                                    local limit = math.min(#allTools, 14)
                                    for i = 1, limit do
