                                        local icon = Instance.new("ImageLabel", invArea)
                                        icon.Size = UDim2.new(0, 18, 0, 18)
                                        icon.BackgroundColor3 = Color3.fromRGB(15, 12, 18)
                                        icon.ScaleType = Enum.ScaleType.Fit
                                        icon.Image = GetSafeIcon(itemData.tool)
                                        
                                        local corner = Instance.new("UICorner", icon)
                                        corner.CornerRadius = UDim.new(0, 4)
                                        
                                        local stroke = Instance.new("UIStroke", icon)
                                        stroke.Thickness = 1.2
                                        if itemData.equipped then
                                            stroke.Color = Color3.fromRGB(170, 0, 255)
                                            icon.ZIndex = 4
                                            icon.BackgroundTransparency = 0
                                        else
                                            stroke.Color = Color3.fromRGB(60, 60, 70)
                                            icon.BackgroundTransparency = 0.5
                                            icon.ZIndex = 3
                                        end
                                    end
                                end
                            end
                        else
                            local hakiGui = hakiFolder:FindFirstChild("Haki_" .. plr.Name)
                            if hakiGui then hakiGui:Destroy() end
                        end
                    else
                        local hakiGui = hakiFolder:FindFirstChild("Haki_" .. plr.Name)
                        if hakiGui then hakiGui:Destroy() end
                    end
                end)
            end
        end
    end
end)

