        local function CreateModernForceBtn(name, xScale, forceVal, parent)
            local btn = Instance.new("TextButton", parent)
            btn.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            btn.Position = UDim2.new(xScale, 0, 0, 0)
            btn.Size = UDim2.new(0.32, 0, 1, 0)
            btn.Font = Enum.Font.GothamBold
            btn.Text = name
            btn.TextColor3 = Color3.fromRGB(150, 150, 150)
            btn.TextSize = 10
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 4)
            local s = Instance.new("UIStroke", btn)
            s.Color = Color3.fromRGB(80, 80, 80)
            
            btn.MouseButton1Click:Connect(function()
                CurrentForce = forceVal
                for _, child in pairs(parent:GetChildren()) do
                    if child:IsA("TextButton") then
                        child.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
                        child.TextColor3 = Color3.fromRGB(150, 150, 150)
                        child.UIStroke.Color = Color3.fromRGB(80, 80, 80)
                    end
                end
                btn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                btn.TextColor3 = Color3.fromRGB(0, 0, 0)
                btn.UIStroke.Color = Color3.fromRGB(255, 255, 255)
            end)
            
            if forceVal == Forces.Fling then
                btn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                btn.TextColor3 = Color3.fromRGB(0, 0, 0)
                s.Color = Color3.fromRGB(255, 255, 255)
            end
        end

        CreateModernForceBtn("Fraco", 0, Forces.Push, BtnContainer)
        CreateModernForceBtn("Forte", 0.34, Forces.Fling, BtnContainer)
        CreateModernForceBtn("CRASH", 0.68, Forces.Crash, BtnContainer)

        local ToggleButton = Instance.new("TextButton", MainFrame)
        ToggleButton.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        ToggleButton.Size = UDim2.new(1, 0, 0, 40)
        ToggleButton.Font = Enum.Font.GothamBlack
