        ToggleButton.LayoutOrder = 7
        Instance.new("UICorner", ToggleButton).CornerRadius = UDim.new(0, 6)

        BuyButton.MouseButton1Click:Connect(function()
            pcall(function() ReplicatedStorage.Modules.Events.RemoteEvent:FireServer("TryBuySeed") end)
            BuyButton.Text = "COMPRANDO..."
            task.wait(0.3)
            BuyButton.Text = "🌱 BUY SEED - 10 PRATAS"
        end)

        ModeButton.MouseButton1Click:Connect(function()
            isAttacking = false
            currentMode = (currentMode == "SEED_V2") and "SEED_V1" or "SEED_V2"
            ModeButton.Text = (currentMode == "SEED_V1") and "🌱 MODO: SEED V1" or "🌱 MODO: SEED V2"
        end)

        local function UpdateTargetDisplay(player)
            if player then
                TargetLabel.Text = "Alvo: " .. player.DisplayName
                TargetLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
                targetPlayer = player
            else
                TargetLabel.Text = "Nenhum alvo selecionado"
                TargetLabel.TextColor3 = Color3.fromRGB(150, 150, 150)
                targetPlayer = nil
                isAttacking = false
                ToggleButton.Text = "INICIAR SEED ATTACK"
                ToggleButton.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                ToggleButton.TextColor3 = Color3.fromRGB(0, 0, 0)
            end
        end

        local function TriggerAim()
            local target = Mouse.Target
            if target and target.Parent then
                local char = target.Parent
                if not char:FindFirstChild("Humanoid") then char = char.Parent end
                if char:FindFirstChild("Humanoid") then
                    local player = Players:GetPlayerFromCharacter(char)
                    if player and player ~= LocalPlayer then
                        NameBox.Text = player.Name 
                        UpdateTargetDisplay(player)
                    end
                end
            end
        end

        KeyBindBox:GetPropertyChangedSignal("Text"):Connect(function()
            KeyBindBox.Text = string.upper(string.sub(KeyBindBox.Text, 1, 1))
        end)

        NameBox:GetPropertyChangedSignal("Text"):Connect(function()
            local text = string.lower(NameBox.Text)
            if text == "" then UpdateTargetDisplay(nil) return end
            for _, player in pairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    if string.sub(string.lower(player.Name), 1, #text) == text or string.sub(string.lower(player.DisplayName), 1, #text) == text then
                        UpdateTargetDisplay(player)
                        break
                    end
                end
            end
        end)

        UserInputService.InputBegan:Connect(function(input, gp)
            if gp then return end
            if KeyBindBox.Text ~= "" then
                local success, keyCode = pcall(function() return Enum.KeyCode[KeyBindBox.Text] end)
                if success and input.KeyCode == keyCode then TriggerAim() end
            end
        end)

        ToolButton.MouseButton1Click:Connect(TriggerAim)

        ToggleButton.MouseButton1Click:Connect(function()
            if not targetPlayer then return end
            isAttacking = not isAttacking
            ToggleButton.Text = isAttacking and "PARAR ATAQUE" or "INICIAR SEED ATTACK"
            ToggleButton.BackgroundColor3 = isAttacking and Color3.fromRGB(255, 50, 50) or Color3.fromRGB(255, 255, 255)
            ToggleButton.TextColor3 = isAttacking and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(0, 0, 0)
        end)

        RunService.Heartbeat:Connect(function()
            if isAttacking and targetPlayer and targetPlayer.Character then
                local root = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                if root then
                    for _, obj in ipairs(Workspace:GetChildren()) do
                        if obj.Name == TargetObjectName then
                            local handle = obj:FindFirstChild("Handle")
                            if handle and handle:IsA("BasePart") then
                                pcall(function() handle:SetNetworkOwner(LocalPlayer) end)
                                handle.CanCollide = false
                                handle.CFrame = CFrame.new(root.Position)
                                handle.AssemblyLinearVelocity = Vector3.new(0, 1000, 0)
                                handle.AssemblyAngularVelocity = Vector3.new(CurrentForce, CurrentForce, CurrentForce)
                            end
                        end
                    end
                end
            end
        end) 
    end)
end)

