_G.WOA_Down = false

local function bindWoaInput(btn, varName)
    btn.InputBegan:Connect(function(i)
        if i.UserInputType.Name:find("Touch") or i.UserInputType.Name:find("MouseButton1") then
            _G[varName] = true
            pcall(function() game:GetService("TweenService"):Create(btn, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(170, 0, 255), TextColor3 = Color3.fromRGB(255, 255, 255)}):Play() end)
        end
    end)
    btn.InputEnded:Connect(function(i)
        if i.UserInputType.Name:find("Touch") or i.UserInputType.Name:find("MouseButton1") then
            _G[varName] = false
            pcall(function() game:GetService("TweenService"):Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(15, 12, 18), TextColor3 = Color3.fromRGB(170, 0, 255)}):Play() end)
        end
    end)
end
bindWoaInput(btnWoaUp, "WOA_Up")
bindWoaInput(btnWoaDown, "WOA_Down")

-- [ MOTOR PRINCIPAL ]
_G.S7xToggleWalkOnAir = function()
    _G.WalkOnAirEnabled = not _G.WalkOnAirEnabled
    
    -- Atualiza a UI visualmente no botão do menu
    if type(setToggleState) == "function" and GUI.WalkOnAirBtn then 
        setToggleState(GUI.WalkOnAirBtn, _G.WalkOnAirEnabled) 
    end
    
    local isMob = game:GetService("UserInputService").TouchEnabled and not game:GetService("UserInputService").KeyboardEnabled
    
    if _G.WalkOnAirEnabled then
        if isMob and GUI.WOAWidget then GUI.WOAWidget.Visible = true end
        
        local char = game.Players.LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        
        if hrp then woaBaseY = hrp.Position.Y - 3.2 end
        
        woaPart.Parent = workspace
        if woaLoop then woaLoop:Disconnect() end
        
        woaLoop = game:GetService("RunService").Stepped:Connect(function(_, dt)
            local c = game.Players.LocalPlayer.Character
            local h = c and c:FindFirstChild("HumanoidRootPart")
            local hum = c and c:FindFirstChild("Humanoid")
            
            if h and hum and hum.Health > 0 then
                local moveSpeed = 35 * dt 
                
                -- Lógica de Subida
                if game:GetService("UserInputService"):IsKeyDown(Enum.KeyCode.Space) or _G.WOA_Up then
                    woaBaseY = woaBaseY + moveSpeed
                    h.CFrame = h.CFrame * CFrame.new(0, moveSpeed, 0)
                    h.Velocity = Vector3.new(h.Velocity.X, 0, h.Velocity.Z)
                -- Lógica de Descida (FIX: Forçando o CFrame para baixo evitando o bug de física)
                elseif game:GetService("UserInputService"):IsKeyDown(Enum.KeyCode.LeftControl) or _G.WOA_Down then
                    woaBaseY = woaBaseY - moveSpeed
                    h.CFrame = h.CFrame * CFrame.new(0, -moveSpeed, 0)
                    h.Velocity = Vector3.new(h.Velocity.X, 0, h.Velocity.Z)
                end
                
                woaPart.CFrame = CFrame.new(h.Position.X, woaBaseY, h.Position.Z)
                
                -- Previne que o personagem acumule inércia de queda
                if h.Velocity.Y < -5 then
                    h.Velocity = Vector3.new(h.Velocity.X, 0, h.Velocity.Z)
                end
            end
        end)
        
        if type(S7xNotify) == "function" then S7xNotify("WALK ON AIR", "Gravidade burlada. Plataforma travada.") end
    else
        if GUI.WOAWidget then GUI.WOAWidget.Visible = false end
        if woaLoop then woaLoop:Disconnect(); woaLoop = nil end
        woaPart.Parent = nil
        if type(S7xNotify) == "function" then S7xNotify("WALK ON AIR", "Gravidade restaurada.") end
    end
end

