local autoTapeEnabled = false
GUI.AutoTapeBtn.MouseButton1Click:Connect(function()
    autoTapeEnabled = not autoTapeEnabled
    setToggleState(GUI.AutoTapeBtn, autoTapeEnabled)
    
    if autoTapeEnabled then
        local lang = game:GetService("LocalizationService").RobloxLocaleId
        local isPt = string.find(string.lower(lang), "pt")
        local tutMsg = isPt and "Essa função funciona quando alguem coloca fita em sua boca, ele retira a fita rapidamente." or "This function works when someone puts tape on your mouth, it removes the tape quickly."
        if type(S7xNotify) == "function" then S7xNotify("TUTORIAL", tutMsg, 20) end
        
        task.spawn(function()
            local remoteEvt = game:GetService("ReplicatedStorage"):WaitForChild("Modules"):WaitForChild("Events"):WaitForChild("RemoteEvent")
            while autoTapeEnabled do
                pcall(function() remoteEvt:FireServer("Untape") end)
                task.wait(0.5)
            end
        end)
    end
end)

local isVoidingAll = false
GUI.VoidAllBtn.MouseButton1Click:Connect(function()
    if isVoidingAll then return end
    isVoidingAll = true
    local origText = GUI.VoidAllBtn.Text
    GUI.VoidAllBtn.Text = "VOIDING..."
    
    task.spawn(function()
        local char = player.Character
        local myHrp = char and char:FindFirstChild("HumanoidRootPart")
        local myHum = char and char:FindFirstChild("Humanoid")
        
        if myHrp and myHum then
            local savedPos = myHrp.CFrame
            local oldPlatformStand = myHum.PlatformStand
            myHum.PlatformStand = true
            
            for _, target in ipairs(Players:GetPlayers()) do
                if target ~= player and target.Character and target.Character:FindFirstChild("HumanoidRootPart") then
                    local tHrp = target.Character.HumanoidRootPart
                    local t = tick()
                    while tick() - t < 0.4 do
                        RunService.Heartbeat:Wait()
                        if myHrp and tHrp then
                            myHrp.CFrame = tHrp.CFrame
                            myHrp.Velocity = Vector3.new(0, -9e8, 0)
                            myHrp.RotVelocity = Vector3.new(0, 0, 0)
                        else
                            break
                        end
                    end
                end
            end
            
            myHum.PlatformStand = oldPlatformStand
            myHrp.Velocity = Vector3.zero
            myHrp.RotVelocity = Vector3.zero
            myHrp.CFrame = savedPos
        end
        
        GUI.VoidAllBtn.Text = "DONE!"
        task.wait(1)
        if GUI.VoidAllBtn then GUI.VoidAllBtn.Text = origText end
        isVoidingAll = false
    end)
end)

