end)

-- Transformado em Global (_G) para a Hotkey do teclado nunca perder a referência
_G.TogglePTarget = function()
    if _G.RemoteFlingData.alvo then
        -- Destrava
        _G.RemoteFlingData.alvo = nil
        GUI.FloatPBtn.Text = "P\nLOCK"
        game:GetService("TweenService"):Create(GUI.FloatPBtn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(170, 0, 255)}):Play()
        GUI.RemoteStatusText.Text = "Procurando alvo..."
        GUI.RemoteStatusText.TextColor3 = Color3.fromRGB(200, 200, 200)
    else
        -- Trava no jogador mais próximo do mouse
        local mouse = game.Players.LocalPlayer:GetMouse()
        local mPos = mouse.Hit.Position
        local minDist = math.huge
        
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            if p ~= game.Players.LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                local dist = (p.Character.HumanoidRootPart.Position - mPos).Magnitude
                if dist < minDist then 
                    minDist = dist
                    _G.RemoteFlingData.alvo = p 
                end
            end
        end
        
        if _G.RemoteFlingData.alvo then 
            GUI.FloatPBtn.Text = "P\nUNLK"
            game:GetService("TweenService"):Create(GUI.FloatPBtn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(255, 50, 50)}):Play()
            GUI.RemoteStatusText.Text = "LOCKED: @" .. _G.RemoteFlingData.alvo.Name
            GUI.RemoteStatusText.TextColor3 = Color3.fromRGB(255, 50, 50)
        end
    end
end

GUI.FloatPBtn.MouseButton1Click:Connect(_G.TogglePTarget)

-- Loop do Motor Físico do Remote Fling (Desliga os antigos para não duplicar)
if _G.RemoteFlingConn then _G.RemoteFlingConn:Disconnect() end
_G.RemoteFlingConn = game:GetService("RunService").Heartbeat:Connect(function()
    if not _G.RemoteFlingData.ativo then return end
    local char = game.Players.LocalPlayer.Character
    if not char then return end

    local mouse = game.Players.LocalPlayer:GetMouse()
    mouse.TargetFilter = char 

    -- ATENÇÃO: Essa função depende do item "Remote Camera" equipado
    local remoteCamera = char:FindFirstChild("Remote Camera")
    if remoteCamera then
        local partesParaMover = {}
        local cameraFolder = remoteCamera:FindFirstChild("Camera")
        if cameraFolder and cameraFolder:FindFirstChild("RootPart") then table.insert(partesParaMover, cameraFolder.RootPart) end
        local engineFolder = remoteCamera:FindFirstChild("Engine")
        if engineFolder and engineFolder:FindFirstChild("Collision") then table.insert(partesParaMover, engineFolder.Collision) end

        local alvoPosicao = nil
        local modoAtaque = false

        if _G.RemoteFlingData.alvo and _G.RemoteFlingData.alvo.Character and _G.RemoteFlingData.alvo.Character:FindFirstChild("HumanoidRootPart") then
            alvoPosicao = _G.RemoteFlingData.alvo.Character.HumanoidRootPart.Position
            modoAtaque = true
        else
            alvoPosicao = mouse.Hit.Position + Vector3.new(0, 2, 0)
            -- Se o alvo morreu, quitou ou perdeu o HumanoidRootPart, destrava automaticamente!
            if _G.RemoteFlingData.alvo then 
                _G.TogglePTarget()
            end 
        end

        for _, peca in ipairs(partesParaMover) do
            peca.Anchored = false 
            peca.CanCollide = false 
            
            local vel = Vector3.new(25000, 25000, 25000)
            peca.AssemblyLinearVelocity = Vector3.new(0, 1000, 0)
            peca.AssemblyAngularVelocity = vel
            peca.Velocity = Vector3.new(0, 1000, 0)
            peca.RotVelocity = vel

            if modoAtaque then
                peca.CFrame = CFrame.new(alvoPosicao)
            else
                peca.CFrame = peca.CFrame:Lerp(CFrame.new(alvoPosicao), 0.2)
            end
        end
    end
end)

GUI.RejoinBtn.MouseButton1Click:Connect(function()
    local ts = game:GetService("TeleportService")
    local players = game:GetService("Players")
    local lp = players.LocalPlayer
    
    -- Notifica o usuário antes de sair
    if type(S7xNotify) == "function" then
        S7xNotify("SERVER ACTION", "Attempting to rejoin same server...")
    end
    
    task.wait(0.5) -- Pequeno delay para a notificação aparecer
    
    pcall(function()
        -- Se houver apenas 1 player, faz o teleporte comum para o Place
        if #players:GetPlayers() <= 1 then 
            ts:Teleport(game.PlaceId, lp) 
        else 
            -- Teleporta especificamente para o ID da instância atual (mesmo servidor) 
            ts:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp) 
        end
    end)
end)

GUI.AutoFishBtn.MouseButton1Click:Connect(function()
