        end
        return
    end
    
    _G.AutoFishLoaded = true
    local origText = GUI.AutoFishBtn.Text
    GUI.AutoFishBtn.Text = "LOADING..."
    
    task.spawn(function()
        local Players = game:GetService("Players")
