        local s_u7, u7 = pcall(require, ReplicatedFirst.Interface.State.InterfacesVisibility)
        local s_u10, u10 = pcall(require, ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Events"))
        local Remote = ReplicatedStorage.Modules.Events.RemoteEvent
        local s_events, EventsAPI = pcall(require, ReplicatedStorage.Modules.Events)

        -- ### CONFIGURAÇÕES & ESTADO ###
        local REPAIR_LOCATION = CFrame.new(4993.07, 180.11, -80.82) 
        local isProcessing = false 
        local isTeleporting = false

        _G.AutoFishing = _G.AutoFishing ~= nil and _G.AutoFishing or false
        _G.AutoCatch = _G.AutoCatch ~= nil and _G.AutoCatch or false
        _G.AutoRepair = _G.AutoRepair ~= nil and _G.AutoRepair or false
        _G.AutoSell = _G.AutoSell ~= nil and _G.AutoSell or false
        _G.ThrowPower = typeof(_G.ThrowPower) == "number" and _G.ThrowPower or 0.2

        local currentRodName = "Classic Rod"
        local currentRodIndex = 1
        local curDurability = 100
        local maxDurability = 100
        local lastClickTime = 0
        local lastThrowTime = 0
        local hadCatchIndicator = false
        local catchIndicatorCloseTime = 0

        -- Capacidade de Peixes & Gamepass
        local maxFishCapacity = 15
        local hasExtraCapacity = false
        local currentFishCount = 0

        local function getThrowPower()
            local p = tonumber(_G.ThrowPower)
            if not p or p < 0.1 then p = 0.1 end
            if p > 1.0 then p = 1.0 end
            return p
        end

        local function removeBlur()
            local blur = Lighting:FindFirstChild("Blur")
            if blur then blur:Destroy() end
        end

        local function hasPlayerBobber()
            local bobbers = workspace:FindFirstChild("Bobbers")
            if not bobbers then return false, nil end

            local userIdStr = tostring(LocalPlayer.UserId)
            local exactName = userIdStr .. ".bobber"
            local b = bobbers:FindFirstChild(exactName)
            if b and b.Parent == bobbers then return true, b end

            for _, child in ipairs(bobbers:GetChildren()) do
                if string.find(child.Name, userIdStr) and string.find(child.Name:lower(), "bobber") then
                    return true, child
                end
            end
            return false, nil
        end

        local function isHoldingRod()
            local char = LocalPlayer.Character
            if not char then return false, nil end
            for _, item in ipairs(char:GetChildren()) do
                if item:IsA("Tool") and (string.find(item.Name:lower(), "rod") or string.find(item.Name:lower(), "fish")) then
                    return true, item
                end
            end
            return false, nil
        end

        local function equipRodIfNeeded()
            local char = LocalPlayer.Character
            if not char then return false end
            if isHoldingRod() then return true end

            local backpack = LocalPlayer:FindFirstChild("Backpack")
            if backpack then
                for _, item in ipairs(backpack:GetChildren()) do
                    if item:IsA("Tool") and (string.find(item.Name:lower(), "rod") or string.find(item.Name:lower(), "fish")) then
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum then
                            hum:EquipTool(item)
                            task.wait(0.2)
                            return true
                        end
                    end
                end
            end
            return false
        end

        local function isCatchIndicatorActive()
            local gui = PlayerGui:FindFirstChild("CatchIndicator")
            if not gui then return false end
            if gui:IsA("ScreenGui") and not gui.Enabled then return false end
            for _, desc in ipairs(gui:GetDescendants()) do
                if desc:IsA("Frame") and desc.Visible and desc.AbsoluteSize.Y > 0 and desc.AbsoluteSize.Y < 150 then
                    return true
                end
            end
            return false
        end

        local function isHookMeterActive()
            local gui = PlayerGui:FindFirstChild("HookMeter")
            if not gui then return false end
            if gui:IsA("ScreenGui") and not gui.Enabled then return false end
            for _, desc in ipairs(gui:GetDescendants()) do
                if desc:IsA("GuiButton") and desc.Visible then
                    return true
                end
            end
            return false
        end

        local isFailingMinigame = false

        local function handleMinigameFailure()
            if isFailingMinigame or isProcessing or isTeleporting then return end
            if not _G.AutoCatch then return end
            isFailingMinigame = true

            local ok, err = pcall(function()
                local catchGui = PlayerGui:FindFirstChild("CatchIndicator")
                if catchGui then pcall(function() catchGui:Destroy() end) end
                local hookMeter = PlayerGui:FindFirstChild("HookMeter")
                if hookMeter then pcall(function() hookMeter:Destroy() end) end
                local catchRelease = PlayerGui:FindFirstChild("CatchOrReleaseIndicator")
                if catchRelease then pcall(function() catchRelease:Destroy() end) end
                removeBlur()

                if s_u7 and u7 then pcall(function() u7.InterfacesVisible(true) end) end
                if s_u5 and u5 then pcall(function() u5.Enabled(true) end) end

                local char = LocalPlayer.Character
                if char then
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    local holding, rodTool = isHoldingRod()
                    if hum and rodTool then
                        hum:UnequipTools()
                        task.wait(0.2)
                        hum:EquipTool(rodTool)
                        task.wait(0.2)
                    else
                        equipRodIfNeeded()
                        task.wait(0.2)
                    end
                end

                if s_events and EventsAPI then
                    EventsAPI:Fire("GetEquippedRod")
                    EventsAPI:Fire("SendFishingRods")
                end
                task.wait(0.15)
                lastThrowTime = os.clock()
                Remote:FireServer("Throw", getThrowPower())
            end)

            if not ok then warn("[AUTO FISH S7X] Erro ao recuperar de falha no minigame:", err) end
            isFailingMinigame = false
        end

