                local req = funcs and funcs:FindFirstChild("RequestPlayerData")
                local client = rs:FindFirstChild("Client")
                local warnViewer = client and client:FindFirstChild("WarnViewer")
                if req then return req:InvokeServer(warnViewer) end
            end)
            if success and type(data) == "table" then return data end
            return nil
        end

        local function updateCapacityAndFishCount(data)
            if not data then data = fetchPlayerData() end
            if data then
                hasExtraCapacity = false
