                    for _, gp in ipairs(data.gamepasses) do
                        if gp == "extraFishCapacity" then
                            hasExtraCapacity = true
                            break
                        end
                    end
                end
                maxFishCapacity = hasExtraCapacity and 50 or 15
                
                if data.fishingInfo and type(data.fishingInfo.fishes) == "table" then
                    currentFishCount = #data.fishingInfo.fishes
                end

                if data.fishingInfo then
                    if data.fishingInfo.equipped then currentRodName = tostring(data.fishingInfo.equipped) end
                    if type(data.fishingInfo.rods) == "table" then
                        for idx, rod in ipairs(data.fishingInfo.rods) do
                            if rod.Name == currentRodName then
                                currentRodIndex = idx
                                curDurability = tonumber(rod.Durability) or curDurability
                                maxDurability = math.max(maxDurability, curDurability)
