                    TweenService:Create(tKnob, TweenInfo.new(0.3, Enum.EasingStyle.Back), {Position = UDim2.new(0, 2, 0.5, -7), BackgroundColor3 = Color3.fromRGB(150, 150, 150)}):Play()
                end
                callback(state, lbl)
            end)
            return btn, lbl
        end

        local fishBtn, lblFish = createFishToggle("AUTO FISHING", _G.AutoFishing, function(s) _G.AutoFishing = s end)
        local catchBtn, lblCatch = createFishToggle("AUTO CATCH", _G.AutoCatch, function(s) 
