        sliderKnob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        Instance.new("UICorner", sliderKnob).CornerRadius = UDim.new(1, 0)

        local isDraggingSlider = false

        local function updateSliderVisual(power)
            local clamped = math.clamp(tonumber(power) or 0.2, 0.1, 1.0)
            clamped = math.floor((clamped * 100) + 0.5) / 100
            _G.ThrowPower = clamped
            local perc = math.clamp((clamped - 0.1) / (1.0 - 0.1), 0, 1)
            sliderLabel.Text = string.format("FORÇA DO CAST (THROW): %.2f", clamped)
            sliderFill.Size = UDim2.new(perc, 0, 1, 0)
            sliderKnob.Position = UDim2.new(perc, -7, 0.5, -7)
        end

        local function setSliderFromInput(inputX)
            local barPos = sliderBar.AbsolutePosition.X
            local barSize = sliderBar.AbsoluteSize.X
            if barSize <= 0 then return end
            local perc = math.clamp((inputX - barPos) / barSize, 0, 1)
            local rawVal = 0.1 + (perc * (1.0 - 0.1))
            local val = math.floor((rawVal * 100) + 0.5) / 100
            updateSliderVisual(val)
        end

        local function onSliderInputStart(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDraggingSlider = true
                setSliderFromInput(input.Position.X)
            end
        end

        sliderBar.InputBegan:Connect(onSliderInputStart)
        sliderFrame.InputBegan:Connect(onSliderInputStart)

        UserInputService.InputChanged:Connect(function(input)
            if isDraggingSlider and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                setSliderFromInput(input.Position.X)
            end
        end)

        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDraggingSlider = false
            end
        end)

        updateSliderVisual(_G.ThrowPower or 0.2)

        local hideHudTask, hideNoticeTask

        local function updateFishHUD()
            if not fishCountLabel then return end
            local capTag = hasExtraCapacity and " [50 CAP]" or " [15 CAP]"
            fishCountLabel.Text = string.format("PEIXES: %d / %d%s", currentFishCount, maxFishCapacity, capTag)
            if currentFishCount >= maxFishCapacity then
                fishCountLabel.TextColor3 = Color3.fromRGB(255, 80, 80)
            else
                fishCountLabel.TextColor3 = Color3.fromRGB(200, 200, 210)
            end
        end

        local function updateUI()
            if not lblFish or not lblSell then return end
            lblFish.Text = _G.AutoFishing and "AUTO FISHING: ON" or "AUTO FISHING: OFF"
            lblCatch.Text = _G.AutoCatch and "AUTO CATCH: ON" or "AUTO CATCH: OFF"
            lblRepair.Text = _G.AutoRepair and "AUTO REPAIR: ON" or "AUTO REPAIR: OFF"
            
            local capText = hasExtraCapacity and "50" or "15"
            lblSell.Text = _G.AutoSell and string.format("AUTO SELL: ON (%d/%s)", currentFishCount, capText) or "AUTO SELL: OFF"
            updateFishHUD()
        end

        local function updateDuraHUD(cur, max)
            local targetMax = math.max(max or 100, cur or 100)
            maxDurability = math.max(maxDurability, targetMax)
            local perc = math.clamp(cur / maxDurability, 0, 1)
            duraText.Text = string.format("%s | %.1f / %d (%d%%)", currentRodName:upper(), cur, maxDurability, math.floor(perc * 100))
            barFill.BackgroundColor3 = perc > 0.25 and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(255, 50, 50)
            updateFishHUD()
            hudFrame.Visible = true
            TweenService:Create(barFill, TweenInfo.new(0.4), {Size = UDim2.new(perc, 0, 1, 0)}):Play()
            if hideHudTask then task.cancel(hideHudTask) end
            hideHudTask = task.delay(5, function() hudFrame.Visible = false end)
        end

        local function showCatchNotice(name)
            fishTitle.Text = tostring(name):upper()
            catchNotify.Visible = true
            if hideNoticeTask then task.cancel(hideNoticeTask) end
            hideNoticeTask = task.delay(3.5, function() catchNotify.Visible = false end)
        end

        -- ================================================================= --
        -- ### ROTINA SEGURA DE REPARO E AUTO VENDA (TELEPORTE COMBINADO) ###
        -- ================================================================= --
        local function performRepairAndSell(doRepair, doSell)
            if isTeleporting then return end
            if not doRepair and not doSell then return end
            isTeleporting = true

            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root then
                isTeleporting = false
                return
            end

            local oldPos = root.CFrame
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            root.CFrame = REPAIR_LOCATION
            task.wait(0.6)

            if doRepair then
                Remote:FireServer("RepairFishingRod", currentRodIndex)
                task.wait(0.8)
            end

            if doSell then
                Remote:FireServer("SellAllFishes")
                task.wait(0.8)
                currentFishCount = 0
                updateUI()
                task.spawn(function()
                    updateCapacityAndFishCount()
                    updateUI()
                end)
            end

            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            root.CFrame = oldPos
            task.wait(0.6)

            removeBlur()

            isTeleporting = false
            lastThrowTime = os.clock()

            if _G.AutoCatch then
                equipRodIfNeeded()
                if s_events and EventsAPI then
                    EventsAPI:Fire("GetEquippedRod")
                    EventsAPI:Fire("SendFishingRods")
                end
                task.wait(0.3)
                Remote:FireServer("Throw", getThrowPower())
                lastThrowTime = os.clock()
            end
        end

        -- ================================================================= --
        -- ### 1. MOTOR DE PESCA E MINIGAMES COM DETECÇÃO CONTÍNUA ###
        -- ================================================================= --
        local function SolvePhysicalCircle(UIElement)
            if not _G.AutoFishing then return end
            task.wait(math.random(40, 75) / 100)
            
            if not UIElement or not UIElement.Parent then return end

            local CenterX = UIElement.AbsolutePosition.X + (UIElement.AbsoluteSize.X / 2)
            local CenterY = UIElement.AbsolutePosition.Y + (UIElement.AbsoluteSize.Y / 2)
            local Inset, _ = GuiService:GetGuiInset()
            
            VirtualInputManager:SendMouseButtonEvent(CenterX, CenterY, 0, true, game, 1)
            task.wait(0.02)
            VirtualInputManager:SendMouseButtonEvent(CenterX, CenterY, 0, false, game, 1)

            local OffsetY = CenterY + Inset.Y
            VirtualInputManager:SendMouseButtonEvent(CenterX, OffsetY, 0, true, game, 1)
            task.wait(0.02)
            VirtualInputManager:SendMouseButtonEvent(CenterX, OffsetY, 0, false, game, 1)
        end

        PlayerGui.DescendantAdded:Connect(function(Descendant)
            if not _G.AutoFishing then return end
            if Descendant:IsA("GuiButton") then
                local Parent = Descendant.Parent
                while Parent and Parent ~= PlayerGui do
                    if Parent.Name == "HookMeter" then
                        if not Descendant:GetAttribute("Solved") then
                            Descendant:SetAttribute("Solved", true)
                            task.spawn(SolvePhysicalCircle, Descendant)
                        end
                        break
                    end
                    Parent = Parent.Parent
                end
            end
        end)

        RunService.RenderStepped:Connect(function()
            if not _G.AutoFishing then return end
            
            local catchGui = PlayerGui:FindFirstChild("CatchIndicator")
            local isActive = false
            local validFrames = {}

            if catchGui and (not catchGui:IsA("ScreenGui") or catchGui.Enabled) then
                for _, element in ipairs(catchGui:GetDescendants()) do
                    if element:IsA("Frame") and element.Visible and element.AbsoluteSize.Y > 0 and element.AbsoluteSize.Y < 150 then
                        table.insert(validFrames, element)
                    end
                end
                if #validFrames >= 2 then
                    isActive = true
                end
            end

            if not isActive then
                if hadCatchIndicator then
                    hadCatchIndicator = false
                    catchIndicatorCloseTime = os.clock()
                    task.delay(0.6, function()
                        if _G.AutoCatch and not isProcessing and not isTeleporting then
                            handleMinigameFailure()
                        end
                    end)
                end
                return
            end
            hadCatchIndicator = true

            table.sort(validFrames, function(a, b) return a.AbsoluteSize.X < b.AbsoluteSize.X end)

            local Indicator = validFrames[1]
            local TargetBox = validFrames[2]

            local indicatorCenter = Indicator.AbsolutePosition.X + (Indicator.AbsoluteSize.X / 2)
            local targetStart = TargetBox.AbsolutePosition.X
            local targetEnd = targetStart + TargetBox.AbsoluteSize.X

            if indicatorCenter >= targetStart and indicatorCenter <= targetEnd then
                if os.clock() - lastClickTime > 0.25 then
                    lastClickTime = os.clock()
                    VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                    task.wait(0.04)
                    VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                end
            end
        end)

        -- ================================================================= --
        -- ### 2. AUTO CATCH, REPARO E AUTO VENDA (FLUXO BLINDADO) ###
        -- ================================================================= --
        if s_u10 and u10 and u10.Bind then
            u10:Bind("FishCaught", function(fishName)
                local blur = game:GetService("Lighting"):FindFirstChild("Blur")
                if blur then blur:Destroy() end

                catchIndicatorCloseTime = 0
                if isProcessing then return end
                isProcessing = true

                local ok, err = pcall(function()
                    local innerBlur = game:GetService("Lighting"):FindFirstChild("Blur")
                    if innerBlur then innerBlur:Destroy() end

                    if s_events and EventsAPI then
                        EventsAPI:Fire("GetEquippedRod")
                        EventsAPI:Fire("SendFishingRods")
                    end
                    task.wait(0.3)

                    updateDuraHUD(curDurability, maxDurability)
                    showCatchNotice(fishName)
                    
                    if _G.AutoCatch then
                        task.wait(0.8)
                        Remote:FireServer("FishDecision", true)
                        
                        currentFishCount = currentFishCount + 1
                        updateUI()
                        
                        task.wait(2.2) 
                        if PlayerGui:FindFirstChild("CatchOrReleaseIndicator") then 
                            PlayerGui.CatchOrReleaseIndicator:Destroy() 
                        end

                        local postBlur = game:GetService("Lighting"):FindFirstChild("Blur")
                        if postBlur then postBlur:Destroy() end

                        if s_u7 and u7 then pcall(function() u7.InterfacesVisible(true) end) end
                        if s_u5 and u5 then pcall(function() u5.Enabled(true) end) end
                        
                        local needRepair = false
                        if _G.AutoRepair and (curDurability <= 12) then needRepair = true end

                        local needSell = false
                        if _G.AutoSell and (currentFishCount >= maxFishCapacity) then needSell = true end

                        if needRepair or needSell then
                            performRepairAndSell(needRepair, needSell)
                        else
                            if _G.AutoCatch then
                                equipRodIfNeeded()
                                task.wait(0.2)
                                lastThrowTime = os.clock()
                                Remote:FireServer("Throw", getThrowPower())
                            end
                        end
                    end
                end)

                if not ok then
                    warn("[AUTO FISH S7X] Erro em FishCaught:", err)
                    if _G.AutoCatch then
                        task.wait(1.5)
                        lastThrowTime = os.clock()
                        Remote:FireServer("Throw", getThrowPower())
                    end
                end

                isProcessing = false 
            end)
        end

        if Remote then
            Remote.OnClientEvent:Connect(function(sub, pay)
                if sub == "EquippedRodChanged" then 
                    currentRodName = pay 
                elseif sub == "FishingRodsChanged" and currentRodName then
                    for i, r in ipairs(pay) do 
                        if r.Name == currentRodName then 
                            currentRodIndex = i
                            curDurability = tonumber(r.Durability) or 0
                            maxDurability = math.max(maxDurability, curDurability)
                            break 
                        end 
                    end
                end
            end)
        end

        -- ================================================================= --
        -- ### 3. MONITORAMENTO ATIVO DA BOIA NO WORKSPACE ###
        -- ================================================================= --
        local function setupCharacter(char)
            if not char then return end
            char.ChildAdded:Connect(function(child)
                if child:IsA("Tool") and (string.find(child.Name:lower(), "rod") or string.find(child.Name:lower(), "fish")) then
                    task.wait(0.3)
                    if _G.AutoCatch and not isTeleporting and not isProcessing and not isFailingMinigame then
                        local inWater = hasPlayerBobber()
                        if not inWater then
                            if s_events and EventsAPI then
                                EventsAPI:Fire("GetEquippedRod")
                                EventsAPI:Fire("SendFishingRods")
                            end
                            task.wait(0.15)
                            Remote:FireServer("Throw", getThrowPower())
                            lastThrowTime = os.clock()
                        end
                    end
                end
            end)
        end

        if LocalPlayer.Character then setupCharacter(LocalPlayer.Character) end
        LocalPlayer.CharacterAdded:Connect(setupCharacter)

        task.spawn(function()
            while true do
                task.wait(1.0)
                if _G.AutoCatch then
                    local now = os.clock()
                    local hookMeterActive = isHookMeterActive()
                    local catchIndicatorActive = isCatchIndicatorActive()
                    local catchRelease = PlayerGui:FindFirstChild("CatchOrReleaseIndicator")

                    if hookMeterActive and _G.AutoFishing then
                        local hm = PlayerGui:FindFirstChild("HookMeter")
                        if hm then
                            for _, desc in ipairs(hm:GetDescendants()) do
                                if desc:IsA("GuiButton") and not desc:GetAttribute("Solved") then
                                    desc:SetAttribute("Solved", true)
                                    task.spawn(SolvePhysicalCircle, desc)
                                    break
                                end
                            end
                        end
                    end

                    if catchRelease and not isProcessing and (now - lastThrowTime > 4.5) then
                        pcall(function() catchRelease:Destroy() end)
                        removeBlur()
                        if s_u7 and u7 then pcall(function() u7.InterfacesVisible(true) end) end
                        if s_u5 and u5 then pcall(function() u5.Enabled(true) end) end
                    end

                    if _G.AutoSell and currentFishCount >= maxFishCapacity and not isTeleporting and not hookMeterActive and not catchIndicatorActive and not isProcessing then
                        performRepairAndSell(false, true)
                    end

                    if catchIndicatorCloseTime > 0 and (now - catchIndicatorCloseTime >= 1.0) and not isProcessing and not isTeleporting and not isFailingMinigame then
                        catchIndicatorCloseTime = 0
                        task.spawn(handleMinigameFailure)
                    end

                    local isBusy = isProcessing or isTeleporting or isFailingMinigame or hookMeterActive or catchIndicatorActive
                    if not isBusy then
                        local inWater = hasPlayerBobber()
                        if not inWater then
                            equipRodIfNeeded()
                            if s_events and EventsAPI then
                                EventsAPI:Fire("GetEquippedRod")
                                EventsAPI:Fire("SendFishingRods")
                            end
                            lastThrowTime = now
                            Remote:FireServer("Throw", getThrowPower())
                        end
                    end
                end
            end
        end)

        task.spawn(function()
            while true do
                updateCapacityAndFishCount()
                updateUI()
                task.wait(30)
            end
        end)

        sellNowBtn.MouseButton1Click:Connect(function()
            if not isTeleporting then
                task.spawn(function()
                    sellNowBtn.Text = "VENDENDO..."
                    performRepairAndSell(false, true)
                    sellNowBtn.Text = "VENDER PEIXES AGORA"
                    updateUI()
                end)
            end
        end)

        updateCapacityAndFishCount()
        updateUI()
        
        GUI.AutoFishBtn.Text = "AUTO FISH OPENED"
    end)
end)


-----------------------------------------
--- ABA CHARACTER (MOVEMENT & SKIN CUSTOM) - S7X PREMIUM
-----------------------------------------
task.spawn(function()
    local targetConfigTab = GUI.ConfigFrame
    local ts = game:GetService("TweenService")
    local rs = game:GetService("RunService")
    local player = game.Players.LocalPlayer

    -- [ 1. LIMPEZA E CONFIGURAÇÃO DO LAYOUT MESTRE ]
    for _, v in ipairs(targetConfigTab:GetChildren()) do
        if v:IsA("UIGridLayout") or v:IsA("UIListLayout") or v:IsA("UIPadding") or v:IsA("Frame") or v:IsA("TextLabel") then 
            v:Destroy()
        end
    end

    local MainLayout = Instance.new("UIListLayout", targetConfigTab)
    MainLayout.SortOrder = Enum.SortOrder.LayoutOrder
    MainLayout.Padding = UDim.new(0, 15)
    MainLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center

    Instance.new("UIPadding", targetConfigTab).PaddingTop = UDim.new(0, 15)

    -- ==========================================
    -- [ NAVEGAÇÃO DE SUB-ABAS (PRETO ABSOLUTO) ]
    -- ==========================================
    local SubNavContainer = Instance.new("Frame", targetConfigTab)
    SubNavContainer.Size = UDim2.new(0.95, 0, 0, 35)
    SubNavContainer.BackgroundColor3 = Color3.fromRGB(10, 10, 12)
    SubNavContainer.LayoutOrder = 1
    Instance.new("UICorner", SubNavContainer).CornerRadius = UDim.new(0, 8)
    Instance.new("UIStroke", SubNavContainer).Color = Color3.fromRGB(45, 45, 55)

    local NavLayout = Instance.new("UIListLayout", SubNavContainer)
    NavLayout.FillDirection = Enum.FillDirection.Horizontal
    NavLayout.SortOrder = Enum.SortOrder.LayoutOrder
    NavLayout.Padding = UDim.new(0, 4)
    NavLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    NavLayout.VerticalAlignment = Enum.VerticalAlignment.Center

    local function createNavBtn(text, isActive)
        local btn = Instance.new("TextButton", SubNavContainer)
        btn.Size = UDim2.new(0.48, 0, 0.8, 0)
        btn.BackgroundColor3 = isActive and Color3.fromRGB(25, 25, 30) or Color3.fromRGB(15, 15, 18)
        btn.Text = text
        btn.TextColor3 = Color3.fromRGB(255, 255, 255)
        btn.Font = Enum.Font.GothamBold
        btn.TextSize = 11
        btn.AutoButtonColor = false
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
        if isActive then
            local strk = Instance.new("UIStroke", btn)
            strk.Color = Color3.fromRGB(170, 0, 255)
            strk.Thickness = 1.2
        end
        return btn
    end

    local MovementNavBtn = createNavBtn("MOVEMENT", true)
    local SkinNavBtn = createNavBtn("SKIN CUSTOM", false)

    -- ==========================================
    -- [ CONTAINERS DE CONTEÚDO ]
    -- ==========================================
    local MovementContainer = Instance.new("Frame", targetConfigTab)
    MovementContainer.Size = UDim2.new(1, 0, 0, 0)
    MovementContainer.BackgroundTransparency = 1
    MovementContainer.LayoutOrder = 2

    local SkinContainer = Instance.new("Frame", targetConfigTab)
    SkinContainer.Size = UDim2.new(1, 0, 0, 0)
    SkinContainer.BackgroundTransparency = 1
    SkinContainer.Visible = false
    SkinContainer.LayoutOrder = 2

    local MovLayout = Instance.new("UIListLayout", MovementContainer)
    MovLayout.SortOrder = Enum.SortOrder.LayoutOrder
    MovLayout.Padding = UDim.new(0, 25)
    MovLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    MovLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() 
        MovementContainer.Size = UDim2.new(1, 0, 0, MovLayout.AbsoluteContentSize.Y)
        if MovementContainer.Visible then targetConfigTab.CanvasSize = UDim2.new(0, 0, 0, MovLayout.AbsoluteContentSize.Y + 60) end
    end)

    local SkinLayout = Instance.new("UIListLayout", SkinContainer)
    SkinLayout.SortOrder = Enum.SortOrder.LayoutOrder
    SkinLayout.Padding = UDim.new(0, 15)
    SkinLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    SkinLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() 
        SkinContainer.Size = UDim2.new(1, 0, 0, SkinLayout.AbsoluteContentSize.Y)
        if SkinContainer.Visible then targetConfigTab.CanvasSize = UDim2.new(0, 0, 0, SkinLayout.AbsoluteContentSize.Y + 60) end
    end)

    local function switchSubTab(showMov)
        local tInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint)
        if showMov then
            MovementContainer.Visible = true; SkinContainer.Visible = false
            ts:Create(MovementNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(25, 25, 30)}):Play()
            ts:Create(SkinNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(15, 15, 18)}):Play()
            if not MovementNavBtn:FindFirstChildOfClass("UIStroke") then Instance.new("UIStroke", MovementNavBtn).Color = Color3.fromRGB(170, 0, 255) end
            if SkinNavBtn:FindFirstChildOfClass("UIStroke") then SkinNavBtn:FindFirstChildOfClass("UIStroke"):Destroy() end
            targetConfigTab.CanvasSize = UDim2.new(0, 0, 0, MovLayout.AbsoluteContentSize.Y + 60)
        else
            MovementContainer.Visible = false; SkinContainer.Visible = true
            ts:Create(SkinNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(25, 25, 30)}):Play()
            ts:Create(MovementNavBtn, tInfo, {BackgroundColor3 = Color3.fromRGB(15, 15, 18)}):Play()
            if not SkinNavBtn:FindFirstChildOfClass("UIStroke") then Instance.new("UIStroke", SkinNavBtn).Color = Color3.fromRGB(170, 0, 255) end
            if MovementNavBtn:FindFirstChildOfClass("UIStroke") then MovementNavBtn:FindFirstChildOfClass("UIStroke"):Destroy() end
            targetConfigTab.CanvasSize = UDim2.new(0, 0, 0, SkinLayout.AbsoluteContentSize.Y + 60)
        end
    end

    MovementNavBtn.MouseButton1Click:Connect(function() switchSubTab(true) end)
    SkinNavBtn.MouseButton1Click:Connect(function() switchSubTab(false) end)

    -- ==========================================
    -- [ SUB-ABA: MOVEMENT (RESTORED) ]
    -- ==========================================
    local function CreateMovementGroup(titleText, layoutOrder)
        local container = Instance.new("Frame", MovementContainer)
        container.Size = UDim2.new(0.98, 0, 0, 0)
        container.BackgroundTransparency = 1
        container.LayoutOrder = layoutOrder
        
        local grid = Instance.new("UIGridLayout", container)
        grid.HorizontalAlignment = Enum.HorizontalAlignment.Center
        grid.SortOrder = Enum.SortOrder.LayoutOrder
        grid.CellPadding = UDim2.new(0, 12, 0, 16)
        grid.CellSize = UDim2.new(0.47, 0, 0, 38)
        
        grid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            container.Size = UDim2.new(1, 0, 0, grid.AbsoluteContentSize.Y)
        end)
        return container
    end

    local MovimCardContainer = CreateMovementGroup("MOVEMENT", 1)
    GUI.FlyBtn        = createToggleButton("FLY", MovimCardContainer)
    GUI.SpeedBtn      = createToggleButton("SPEED", MovimCardContainer)
    GUI.JumpBtn       = createToggleButton("JUMP", MovimCardContainer)
    GUI.NoclipBtn     = createToggleButton("NOCLIP", MovimCardContainer)
    GUI.WalkOnAirBtn  = createToggleButton("WALKAIR", MovimCardContainer)
    GUI.ShiftLockBtn  = createToggleButton("SHIFT LOCK", MovimCardContainer)
    GUI.GravityBtn    = createToggleButton("GRAVITY", MovimCardContainer)
    GUI.AntiAfkBtn    = createToggleButton("ANTIAFK", MovimCardContainer) -- Movido para cá para fechar a grade perfeitamente

    if _G.WoaClickConn then pcall(function() _G.WoaClickConn:Disconnect() end) end
    _G.WoaClickConn = GUI.WalkOnAirBtn.MouseButton1Click:Connect(function() if type(_G.S7xToggleWalkOnAir) == "function" then _G.S7xToggleWalkOnAir() end end)
    
    -- [ LÓGICA DO GRAVITY ]
    _G.GravityEnabled = false
    _G.S7xToggleGravity = function()
        _G.GravityEnabled = not _G.GravityEnabled
        if type(setToggleState) == "function" then setToggleState(GUI.GravityBtn, _G.GravityEnabled) end
        
        if _G.GravityEnabled then
            workspace.Gravity = _G.GravityValue or 196.2
            if type(S7xNotify) == "function" then S7xNotify("GRAVITY", "Gravidade customizada aplicada.") end
        else
            workspace.Gravity = 196.2 
            if type(S7xNotify) == "function" then S7xNotify("GRAVITY", "Gravidade restaurada ao padrão.") end
        end
    end
    GUI.GravityBtn.MouseButton1Click:Connect(_G.S7xToggleGravity)

    -- A Seção UTILITIES foi removida para não quebrar a simetria do layout

    local CheckCardContainer = CreateMovementGroup("CHECKPOINTS", 2) -- Ordem do layout atualizada para 2
    GUI.SaveCheckBtn  = createButton("SAVE CHECKPOINT", CheckCardContainer)
    GUI.ClearCheckBtn = createButton("CLEAR CHECKPOINT", CheckCardContainer)
    GUI.RespawnBtn    = createButton("RESPAWN", CheckCardContainer)

    -- [ ATRIBUIÇÃO DE KEYBINDS NAS CAIXINHAS ]
    addKeybindBox(GUI.FlyBtn, "Fly")
    addKeybindBox(GUI.SpeedBtn, "Speed")
    addKeybindBox(GUI.JumpBtn, "Jump")
    addKeybindBox(GUI.NoclipBtn, "Noclip")
    addKeybindBox(GUI.WalkOnAirBtn, "WalkOnAir")
    addKeybindBox(GUI.GravityBtn, "Gravity") -- [ NOVO ]: Atalho do Gravity

    -- [ ATRIBUIÇÃO DE SLIDERS EMBUTIDOS ]
    addMiniSlider(GUI.FlyBtn, flySpeedValue, 150, function(val) flySpeedValue = val end)
    addMiniSlider(GUI.SpeedBtn, walkSpeedValue, 150, function(val) walkSpeedValue = val end)
    addMiniSlider(GUI.JumpBtn, jumpPowerValue, 150, function(val) jumpPowerValue = val end)
    
    -- Mini Slider do Gravity (Aparece ao ativar o botão e atualiza em Tempo Real)
    _G.GravityValue = _G.GravityValue or 196
    addMiniSlider(GUI.GravityBtn, _G.GravityValue, 300, function(val) 
        _G.GravityValue = val 
        -- Só atualiza a gravidade imediatamente se a alavanca estiver "ON"
        if _G.GravityEnabled then
            workspace.Gravity = val
        end
    end)

    --- ==========================================
    -- [ SUB-ABA: SKIN CUSTOM (INTERACTIVE 3D & AUDIO NODES) ]
    -- ==========================================
    
    -- [ 1. VISUALIZADOR 3D INTERATIVO COM MOUSE DRAG ]
    local AvatarViewCard = Instance.new("Frame", SkinContainer)
    AvatarViewCard.Size = UDim2.new(0.95, 0, 0, 190)
    AvatarViewCard.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
    AvatarViewCard.LayoutOrder = 1
    Instance.new("UICorner", AvatarViewCard).CornerRadius = UDim.new(0, 8)
    Instance.new("UIStroke", AvatarViewCard).Color = Color3.fromRGB(45, 45, 55)

