    local targetRotation = 0

    -- [ SISTEMA DE INDICADORES HOLOGRÁFICOS NO CORPO (NEON NODES) ]
    local function attachAudioNode(parentPart, color, yOffset, sizeVec)
        if not parentPart then return end
        local node = Instance.new("Part")
        node.Name = "S7x_AudioIndicator"
        node.Material = Enum.Material.Neon
        node.Color = color
        node.Size = sizeVec or Vector3.new(0.6, 0.12, 0.6)
        node.CanCollide = false
        node.Anchored = false
        node.CastShadow = false
        node.TopSurface = Enum.SurfaceType.Smooth
        node.BottomSurface = Enum.SurfaceType.Smooth
        
        local mesh = Instance.new("SpecialMesh", node)
        mesh.MeshType = Enum.MeshType.Cylinder
        
        local weld = Instance.new("WeldConstraint")
        node.CFrame = parentPart.CFrame * CFrame.new(0, yOffset or -0.8, 0) * CFrame.Angles(0, 0, math.rad(90))
        weld.Part0 = parentPart
        weld.Part1 = node
        weld.Parent = node
        node.Parent = parentPart
    end

    local function refreshCloneAudioIndicators(clone)
        if not clone then return end
        for _, desc in ipairs(clone:GetDescendants()) do
            if desc.Name == "S7x_AudioIndicator" then desc:Destroy() end
        end

        local sounds = _G.S7xCustomSounds or {}

        -- 1. Passos e Corrida: Ilumina as articulações dos pés/pernas (Púrpura Neon)
        if sounds.Walk or sounds.Run then
            local leftLeg = clone:FindFirstChild("LeftFoot") or clone:FindFirstChild("Left Leg")
            local rightLeg = clone:FindFirstChild("RightFoot") or clone:FindFirstChild("Right Leg")
            local footOffset = clone:FindFirstChild("LeftFoot") and -0.35 or -0.85
            
            attachAudioNode(leftLeg, Color3.fromRGB(170, 0, 255), footOffset)
            attachAudioNode(rightLeg, Color3.fromRGB(170, 0, 255), footOffset)
        end

        -- 2. Salto: Ilumina a região do quadril/tronco de impulsão (Laranja Neon)
        if sounds.Jump then
            local torso = clone:FindFirstChild("LowerTorso") or clone:FindFirstChild("Torso")
            attachAudioNode(torso, Color3.fromRGB(255, 120, 0), -0.2, Vector3.new(1.1, 0.15, 1.1))
        end
    end

    local function updateLiveSkin()
        for _, v in ipairs(skinWorldModel:GetChildren()) do v:Destroy() end
        local char = player.Character
        if char then
            char.Archivable = true
            local clone = char:Clone()
            for _, v in ipairs(clone:GetDescendants()) do 
                if v:IsA("Script") or v:IsA("LocalScript") then v:Destroy() end 
            end
            clone.Parent = skinWorldModel
            
            local hrp = clone:FindFirstChild("HumanoidRootPart") or clone.PrimaryPart
            if hrp then hrp.CFrame = CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(currentRotation), 0) end
            
            local hum = clone:FindFirstChild("Humanoid")
            if hum then
                hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
                local animate = char:FindFirstChild("Animate")
                if animate then
                    local idle = animate:FindFirstChild("idle")
                    local anim = idle and idle:FindFirstChildOfClass("Animation")
                    if anim then pcall(function() animator:LoadAnimation(anim):Play() end) end
                end
            end

            refreshCloneAudioIndicators(clone)
        end
    end
    updateLiveSkin()
    player.CharacterAdded:Connect(function() task.wait(1) updateLiveSkin() end)
    player.CharacterAppearanceLoaded:Connect(function() task.wait(0.5) updateLiveSkin() end)

