    local function createSoundDropdown(categoryName, dbList)
        -- Container Mestre que segura o Dropdown + A Caixa Custom
        local blockContainer = Instance.new("Frame", SoundCard)
        blockContainer.Size = UDim2.new(0.9, 0, 0, 68) 
        blockContainer.BackgroundTransparency = 1
        
