        customStroke.Color = Color3.fromRGB(45, 45, 55)

        customBox.Focused:Connect(function() pcall(function() ts:Create(customStroke, TweenInfo.new(0.3), {Color = Color3.fromRGB(170, 0, 255)}):Play() end) end)
        customBox.FocusLost:Connect(function(enterPressed)
            pcall(function() ts:Create(customStroke, TweenInfo.new(0.3), {Color = Color3.fromRGB(45, 45, 55)}):Play() end)
            local rawNum = customBox.Text:match("%d+")
