                lbl.Text = categoryName .. ": Custom (" .. rawNum .. ")"
                if type(SaveS7xSettings) == "function" then task.spawn(SaveS7xSettings) end
                for _, clone in ipairs(skinWorldModel:GetChildren()) do refreshCloneAudioIndicators(clone) end
                if type(S7xNotify) == "function" then S7xNotify("SAVED", categoryName .. " Audio ID atualizado.") end
            end
        end)

        for i, data in ipairs(dbList) do
