    -- [ MOTOR DE ÁUDIO 3D NATIVO E DINÂMICO (S7X FIXED AUDIO) ]
    if _G.S7xAudioEngineLoop then pcall(function() _G.S7xAudioEngineLoop:Disconnect() end) end
    _G.S7xAudioEngineLoop = rs.Heartbeat:Connect(function()
        local char = player.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChild("Humanoid")
        
        if hrp and hum then
            local sRunning = hrp:FindFirstChild("Running")
            local sJumping = hrp:FindFirstChild("Jumping")

            -- [ PROTEÇÃO ANTI-SOM NO AR ]: Silencia TUDO (Passos, Corrida e Pulo) enquanto voa
            if _G.S7xFlyEnabled or _G.WalkOnAirEnabled then
                if sRunning then 
                    sRunning.Volume = 0 
                    sRunning.PlaybackSpeed = 0 
                end
                if sJumping then
                    sJumping.Volume = 0
                end
            else
                -- [ RESTAURAÇÃO AUTOMÁTICA ]: O jogador parou de voar, devolve os sons!
                if sRunning then
                    -- Devolve o volume nativo caso estivesse mudo
                    if sRunning.Volume == 0 then
                        -- Se for áudio customizado usa volume 1, se for nativo do Roblox usa 0.65
                        sRunning.Volume = (_G.S7xCustomSounds.Walk or _G.S7xCustomSounds.Run) and 1 or 0.65
                    end
                    
                    -- Calcula a velocidade do áudio dinamicamente de acordo com a velocidade do boneco
                    sRunning.PlaybackSpeed = 1.85 * (hum.WalkSpeed / 16)

                    local speed = hum.MoveDirection.Magnitude > 0 and hum.WalkSpeed or 0
                    local targetId = nil
                    
                    if speed > 18 and _G.S7xCustomSounds.Run then
                        targetId = "rbxassetid://" .. _G.S7xCustomSounds.Run
                    elseif speed > 0 and _G.S7xCustomSounds.Walk then
                        targetId = "rbxassetid://" .. _G.S7xCustomSounds.Walk
                    end
                    
                    if targetId and sRunning.SoundId ~= targetId then
                        sRunning.SoundId = targetId
                    end
                end

                if sJumping then
                    -- Restaura o volume do pulo
                    if sJumping.Volume == 0 then
                        sJumping.Volume = 1
                    end
                    
                    if _G.S7xCustomSounds.Jump then
                        local targetId = "rbxassetid://" .. _G.S7xCustomSounds.Jump
                        if sJumping.SoundId ~= targetId then
                            sJumping.SoundId = targetId
                        end
                    end
                end
            end
        end
    end)
end) -- [ FIX ]: Mantido o fechamento da thread isolada para não dar o erro <eof>.r.

