    local FavoritesDB = {}
    local RecentsDB = {}
    
    pcall(function()
        if readfile and isfile then
            if isfile(FAV_FILE) then FavoritesDB = HttpService:JSONDecode(readfile(FAV_FILE)) end
            if isfile(REC_FILE) then RecentsDB = HttpService:JSONDecode(readfile(REC_FILE)) end
        end
    end)
    
    local function SavePersonalData()
        task.spawn(function() pcall(function() if writefile then writefile(FAV_FILE, HttpService:JSONEncode(FavoritesDB)); writefile(REC_FILE, HttpService:JSONEncode(RecentsDB)) end end) end)
    end

    local function IsFavorite(name)
        for _, v in ipairs(FavoritesDB) do if string.lower(v.name) == string.lower(name) then return true end end
        return false
    end

    local function ToggleFavorite(data)
        for i, v in ipairs(FavoritesDB) do
            if string.lower(v.name) == string.lower(data.name) then
                table.remove(FavoritesDB, i); SavePersonalData(); return false
            end
        end
        table.insert(FavoritesDB, 1, data); SavePersonalData(); return true
    end

    local function AddToRecents(data)
        task.spawn(function()
            for i, v in ipairs(RecentsDB) do if string.lower(v.name) == string.lower(data.name) then table.remove(RecentsDB, i) break end end
            table.insert(RecentsDB, 1, data)
            if #RecentsDB > 50 then table.remove(RecentsDB, 51) end 
            SavePersonalData()
        end)
    end

    _G.S7xCurrentAnimData = nil
    local function resolveAnimationMappings(bundledItems)
        local mappings = {}
        if type(bundledItems) ~= "table" then return mappings end
        for _, assetIds in pairs(bundledItems) do
            for _, assetId in pairs(assetIds) do
                local success, objects = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(assetId)) end)
                if success and objects then
                    local function searchTree(parent, parentPath)
                        for _, child in pairs(parent:GetChildren()) do
                            if child:IsA("Animation") then
                                local pathParts = string.split(parentPath .. "." .. child.Name, ".")
                                local weightVals = {}
                                for _, wChild in ipairs(child:GetChildren()) do
                                    if wChild:IsA("NumberValue") and wChild.Name == "Weight" then table.insert(weightVals, wChild.Value) end
                                end
                                table.insert(mappings, { category = pathParts[#pathParts - 1], name = pathParts[#pathParts], animationId = child.AnimationId, weights = weightVals })
                            elseif #child:GetChildren() > 0 then
                                searchTree(child, parentPath .. "." .. child.Name)
                            end
                        end
                    end
                    for _, obj in pairs(objects) do
                        searchTree(obj, obj.Name)
                        obj.Parent = workspace
                        task.delay(1, function() if obj then obj:Destroy() end end)
                    end
                end
            end
        end
        return mappings
    end

    _G.S7xApplyAnimations = function(animationData)
        task.spawn(function()
            local char = player.Character
            local hum = char and char:FindFirstChild("Humanoid")
            local animate = char and char:FindFirstChild("Animate")
            if not hum or not animate then return end
            if hum.RigType == Enum.HumanoidRigType.R6 then if type(S7xNotify) == "function" then S7xNotify("ERROR", "Requeres R15 body!") end return end
            _G.S7xCurrentAnimData = animationData
            local bundledItems = animationData.bundledItems
            for _, track in pairs(hum:GetPlayingAnimationTracks()) do track:Stop() end
            local mappings = resolveAnimationMappings(bundledItems)
            if #mappings == 0 then return end
            local sorted = {}
            for _, m in ipairs(mappings) do if string.lower(m.category) == "idle" then table.insert(sorted, 1, m) else table.insert(sorted, m) end end
            local function applyAnimToObject(animObj, animId, weights)
                if not animObj or not animObj:IsA("Animation") then return end
                animObj.AnimationId = animId
                if weights ~= nil then
                    for _, child in ipairs(animObj:GetChildren()) do if child:IsA("NumberValue") and child.Name == "Weight" then child:Destroy() end end
                    for _, wVal in ipairs(weights) do local w = Instance.new("NumberValue"); w.Name = "Weight"; w.Value = wVal; w.Parent = animObj end
                end
            end
            local mappingMap = {}
            for _, m in ipairs(sorted) do
                local cat = string.lower(m.category)
                if not mappingMap[cat] then mappingMap[cat] = { folderName = m.category, items = {} } end
                mappingMap[cat].items[string.lower(m.name)] = m
            end
            animate.Disabled = true
            for cat, data in pairs(mappingMap) do
                local categoryFolder = animate:FindFirstChild(data.folderName)
                if categoryFolder then
                    local sourceByName = {}
                    for name, m in pairs(data.items) do sourceByName[name] = m end
                    for _, animObj in ipairs(categoryFolder:GetChildren()) do
                        if animObj:IsA("Animation") then
                            local lowerName = string.lower(animObj.Name)
                            local m = sourceByName[lowerName]
                            if m then sourceByName[lowerName] = nil; applyAnimToObject(animObj, m.animationId, m.weights); animObj.Name = m.name else animObj:Destroy() end
                        end
                    end
                    for _, m in pairs(sourceByName) do
                        local animObj = Instance.new("Animation"); animObj.Name = m.name; applyAnimToObject(animObj, m.animationId, m.weights); animObj.Parent = categoryFolder
                    end
                end
            end
            if hum.MoveDirection.Magnitude == 0 then animate.Disabled = false end
            if type(S7xNotify) == "function" then S7xNotify("SYNC", string.upper(animationData.name) .. " APPLIED!") end
        end)
    end

    _G.S7xPlayGlobalEmote = function(emoteData)
        task.spawn(function()
            local char = player.Character
            local hum = char and char:FindFirstChild("Humanoid")
            if not hum then return end
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do track:Stop() end
            local desc = hum:FindFirstChildOfClass("HumanoidDescription") or hum:GetAppliedDescription()
            if desc then
                local emotes = desc:GetEmotes()
                emotes[emoteData.name] = {tonumber(emoteData.id or emoteData.assetId)}
                desc:SetEmotes(emotes)
                local equipped = desc:GetEquippedEmotes()
                local hasSlot = false
                for _, v in ipairs(equipped) do if v.Name == emoteData.name then hasSlot = true; break end end
                if not hasSlot then table.insert(equipped, {Name = emoteData.name, Slot = #equipped + 1}); desc:SetEquippedEmotes(equipped) end
                local ok, track = pcall(function() return hum:PlayEmoteAndGetAnimTrackById(tonumber(emoteData.id or emoteData.assetId)) end)
                if ok and track then if type(S7xNotify) == "function" then S7xNotify("EMOTE", string.upper(emoteData.name)) end return end
            end
            local success, objects = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(emoteData.id or emoteData.assetId)) end)
            if success and objects and #objects > 0 then
                local internalId = nil
                for _, obj in ipairs(objects) do
                    if obj:IsA("Animation") then internalId = obj.AnimationId; break end
                    for _, child in ipairs(obj:GetDescendants()) do if child:IsA("Animation") then internalId = child.AnimationId; break end end
                end
                for _, o in ipairs(objects) do pcall(function() o:Destroy() end) end
                if internalId then
                    local animator = hum:FindFirstChildOfClass("Animator")
                    if animator then
                        local anim = Instance.new("Animation"); anim.AnimationId = internalId
                        local track = animator:LoadAnimation(anim); track.Priority = Enum.AnimationPriority.Action4; track:Play()
                        if type(S7xNotify) == "function" then S7xNotify("EMOTE", string.upper(emoteData.name)) end
                    end
                end
            end
        end)
    end

