    NextBtn.MouseButton1Click:Connect(function() if CurrentPage < TotalPages then RenderPage(CurrentPage + 1) end end)

   
    task.spawn(function()
        -- Motor de Download Seguro Multi-Executor
        local function SafeFetch(url)
            local res = nil
            pcall(function()
                if request then
                    local r = request({Url = url, Method = "GET"})
                    if r.StatusCode == 200 then res = r.Body end
                elseif http_request then
                    local r = http_request({Url = url, Method = "GET"})
                    if r.StatusCode == 200 then res = r.Body end
                elseif fluxus and fluxus.request then
                    local r = fluxus.request({Url = url, Method = "GET"})
                    if r.StatusCode == 200 then res = r.Body end
                else
                    res = game:HttpGet(url)
                end
            end)
            return res
        end

        local success, result = pcall(function()
            StatusText.Text = "DOWNLOADING EMOTES (0/10000)..."
            local res1 = SafeFetch("https://raw.githubusercontent.com/7yd7/sniper-Emote/refs/heads/test/EmoteSniper.json")
            if res1 then
                local list1 = HttpService:JSONDecode(res1)
                list1 = list1.data or list1
                for _, item in pairs(list1) do
                    if tonumber(item.id) then table.insert(MasterEmotesDB, {name = item.name, id = tonumber(item.id), type = "Emote"}) end
                end
            end
            
            StatusText.Text = "DOWNLOADING PACKAGES..."
            local res2 = SafeFetch("https://raw.githubusercontent.com/7yd7/sniper-Emote/refs/heads/test/AnimationSniper.json")
            if res2 then
                local list2 = HttpService:JSONDecode(res2)
                list2 = list2.data or list2
                for _, item in pairs(list2) do
                    if tonumber(item.id) then table.insert(MasterPackagesDB, {name = item.name, id = tonumber(item.id), bundledItems = item.bundledItems, type = "Package"}) end
                end
            end
            
            local res3 = SafeFetch("https://raw.githubusercontent.com/7yd7/sniper-Emote/refs/heads/test/AnimationSniperoffsale.json")
            if res3 then
                local list3 = HttpService:JSONDecode(res3)
                list3 = list3.data or list3
                for _, item in pairs(list3) do
                    if tonumber(item.id) then table.insert(MasterPackagesDB, {name = item.name, id = tonumber(item.id), bundledItems = item.bundledItems, type = "Package"}) end
                end
            end
        end)
        
        if success and (#MasterEmotesDB > 0 or #MasterPackagesDB > 0) then
            dbLoaded = true
            UpdateModeButtons()
            FilterAndRender("")
        else
            StatusText.Text = "DATABASE ERROR (BLOCKED BY EXECUTOR)"
            StatusText.TextColor3 = Color3.fromRGB(255, 50, 50)
            warn("[S7X ENGINE] Falha crítica no download do banco de dados: ", tostring(result))
        end
    end)

    EmotesBtn.MouseButton1Click:Connect(function() CurrentViewMode = "Emotes"; UpdateModeButtons(); CurrentPage = 1; FilterAndRender(SearchBox.Text) end)
    PkgsBtn.MouseButton1Click:Connect(function() CurrentViewMode = "Packages"; UpdateModeButtons(); CurrentPage = 1; FilterAndRender(SearchBox.Text) end)
    FavBtn.MouseButton1Click:Connect(function() CurrentViewMode = "Favorites"; UpdateModeButtons(); CurrentPage = 1; FilterAndRender(SearchBox.Text) end)

    local searchDebounce = 0
    SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
        searchDebounce = searchDebounce + 1
        local currentDebounce = searchDebounce
        task.delay(0.15, function()
            if searchDebounce == currentDebounce then
                CurrentPage = 1
                FilterAndRender(SearchBox.Text)
            end
        end)
    end)

    RestoreBtn.MouseButton1Click:Connect(function()
        _G.S7xCurrentAnimData = nil
        local char = player.Character
        if char and _G.S7xOriginalAnimate then
            local currentAnimate = char:FindFirstChild("Animate")
            if currentAnimate then currentAnimate:Destroy() end
            local cleanAnimate = _G.S7xOriginalAnimate:Clone()
            cleanAnimate.Parent = char
            cleanAnimate.Disabled = false
            
            local hum = char:FindFirstChild("Humanoid")
            if hum then
                local animator = hum:FindFirstChildOfClass("Animator")
                if animator then for _, track in ipairs(animator:GetPlayingAnimationTracks()) do track:Stop(0) end end
                hum:ChangeState(Enum.HumanoidStateType.Landed)
            end
            if type(S7xNotify) == "function" then S7xNotify("RESTORED", "Animações e Emotes parados.") end
            
            pcall(function()
                TweenService:Create(RestoreBtn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(255, 50, 50)}):Play()
                RestoreLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
