    local function UpdateTargetLiveAvatar(tPlayer)
        avatarUpdateTick = avatarUpdateTick + 1
        local currentTick = avatarUpdateTick
        
        task.spawn(function()
            TargetWorldModel:ClearAllChildren()
            if not tPlayer or not tPlayer.Character then return end
            
            local char = tPlayer.Character
            char.Archivable = true
            local clone = char:Clone()
            
            if avatarUpdateTick ~= currentTick then
                clone:Destroy()
                return
            end
            
            for _, v in ipairs(clone:GetDescendants()) do
                if v:IsA("Script") or v:IsA("LocalScript") then v:Destroy() end
            end
            
            clone.Parent = TargetWorldModel
            clone:PivotTo(CFrame.new(0, 0, 0) * CFrame.Angles(0, math.pi, 0))
            
            local hrp = clone:FindFirstChild("Head") or clone.PrimaryPart
            if hrp then
                TargetCam.CFrame = CFrame.new(Vector3.new(0, 1.2, 4.5), Vector3.new(0, 1.2, 0))
            end
            
            local cloneHum = clone:FindFirstChild("Humanoid")
            local realHum = char:FindFirstChild("Humanoid")
            
            if cloneHum and realHum then
                cloneHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                currentCloneAnimator = cloneHum:FindFirstChildOfClass("Animator") or Instance.new("Animator", cloneHum)
                local realAnimator = realHum:FindFirstChildOfClass("Animator")
                
                if realAnimator then
                    for _, track in ipairs(realAnimator:GetPlayingAnimationTracks()) do
                        if track.Animation then
                            pcall(function()
                                local newAnim = Instance.new("Animation")
                                newAnim.AnimationId = track.Animation.AnimationId
                                local newTrack = currentCloneAnimator:LoadAnimation(newAnim)
                                newTrack.Priority = track.Priority
                                newTrack:Play()
                                newTrack.TimePosition = track.TimePosition
                                newTrack:AdjustSpeed(track.Speed)
                            end)
                        end
                    end
                end
            end
        end)
    end

