            btn.MouseEnter:Connect(function() TweenService:Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(170, 0, 255)}):Play(); TweenService:Create(lbl, TweenInfo.new(0.2), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play() end)
            btn.MouseLeave:Connect(function() TweenService:Create(btn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(15, 15, 18)}):Play(); TweenService:Create(lbl, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(200, 200, 200)}):Play() end)
        end
        return btn
    end

    local function applyToggleVisual(btn, state)
        local lbl = btn:FindFirstChild("Title")
        if state then
            TweenService:Create(btn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(255, 255, 255)}):Play()
            if lbl then TweenService:Create(lbl, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(0, 0, 0)}):Play() end
        else
            TweenService:Create(btn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(15, 15, 18)}):Play()
            if lbl then TweenService:Create(lbl, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(200, 200, 200)}):Play() end
        end
    end

