        end
    end)

    local function StopTargetAnim()
        if activeTargetAnim then 
            activeTargetAnim:Stop()
            activeTargetAnim = nil 
        end
    end

    local function PlayTargetAnim(animId)
        local char = game.Players.LocalPlayer.Character
        local hum = char and char:FindFirstChild("Humanoid")
        local animator = hum and hum:FindFirstChildOfClass("Animator")
        
        if animator then
            StopTargetAnim()
            pcall(function()
                local anim = Instance.new("Animation")
                anim.AnimationId = "rbxassetid://" .. tostring(animId)
                activeTargetAnim = animator:LoadAnimation(anim)
                activeTargetAnim.Priority = Enum.AnimationPriority.Action4
                activeTargetAnim:Play(0)
            end)
        end
    end

    local function clearTargetState()
        for _, conn in ipairs(targetAttachConns) do
            if conn then conn:Disconnect() end
        end
        table.clear(targetAttachConns)
        
        StopTargetAnim()
        workspace.FallenPartsDestroyHeight = origFallenHeight
        
        local char = game.Players.LocalPlayer.Character
        local hum = char and char:FindFirstChild("Humanoid")
        if hum then 
            hum.Sit = false 
            hum.PlatformStand = false 
        end
        
        if char then
            for _, v in ipairs(char:GetChildren()) do
                if v:IsA("BasePart") then
                    v.Massless = false
                    v.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.3, 0.5, 1, 1)
                    if v.Name == "HumanoidRootPart" or v.Name == "Torso" or v.Name == "UpperTorso" or v.Name == "Head" then
                        v.CanCollide = true
                    end
                end
            end
        end
        
        if currentTargetState == "Push" then applyToggleVisual(PushBtn, false) end
        if currentTargetState == "Headsit" then applyToggleVisual(HeadsitBtn, false) end
        if currentTargetState == "Shoulders" then applyToggleVisual(ShouldersBtn, false) end
        if currentTargetState == "RevShoulders" then applyToggleVisual(RevShouldersBtn, false) end -- NOVO
        if currentTargetState == "FrontSit" then applyToggleVisual(FrontSitBtn, false) end
        if currentTargetState == "Stand" then applyToggleVisual(StandBtn, false) end
        if currentTargetState == "Backpack" then applyToggleVisual(BackpackBtn, false) end
        if currentTargetState == "Doggy" then applyToggleVisual(DoggyBtn, false) end
        if currentTargetState == "Drag" then applyToggleVisual(DragBtn, false) end
        if currentTargetState == "TargetFling" then applyToggleVisual(TargetFlingBtn, false) end
        
        currentTargetState = nil
    end

    local function startTargetAction(actionName, btn, animId, targetPartName, offsetCFrame, customLogic)
        if currentTargetState == actionName then clearTargetState() return end
        if not spectatingPlayer then 
            if type(S7xNotify) == "function" then S7xNotify("ERROR", "Selecione um alvo primeiro!") end
            return 
        end 
        
        clearTargetState()
        currentTargetState = actionName
        applyToggleVisual(btn, true)

        local myChar = game.Players.LocalPlayer.Character
        local myHum = myChar and myChar:FindFirstChild("Humanoid")
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")

        if not myChar or not myHum or not myHrp then return end

        local finalAnimId = animId
        -- [ ADICIONADO ]: Se for RevShoulders, ele vai puxar a animação de sentar (igual Shoulders normal)
        if actionName == "Headsit" or actionName == "Shoulders" or actionName == "RevShoulders" or actionName == "Backpack" or actionName == "FrontSit" then
            finalAnimId = (myHum.RigType == Enum.HumanoidRigType.R15) and 2506281703 or 178130996
        end

        if finalAnimId then PlayTargetAnim(finalAnimId) end

        myHum.PlatformStand = true
        workspace.FallenPartsDestroyHeight = -9999999 
        for _, v in ipairs(myChar:GetChildren()) do
            if v:IsA("BasePart") then 
                v.CanCollide = false 
                v.Massless = true 
                v.CustomPhysicalProperties = PhysicalProperties.new(0,0,0,0,0)
            end
        end

        local function attachLogic()
            if not spectatingPlayer or not spectatingPlayer.Character or not spectatingPlayer.Character:FindFirstChild("HumanoidRootPart") then
                clearTargetState()
                if type(S7xNotify) == "function" then S7xNotify("TARGET LOST", "O alvo desconectou ou morreu.") end
                return
            end

            local tChar = spectatingPlayer.Character
            local tPart = tChar:FindFirstChild(targetPartName) or tChar:FindFirstChild("Torso") or tChar:FindFirstChild("HumanoidRootPart")
            local tHrp = tChar:FindFirstChild("HumanoidRootPart")
            
            if myHrp and tPart and tHrp then 
                if customLogic then
                    customLogic(myHrp, tHrp)
                else
                    myHrp.CFrame = tPart.CFrame * offsetCFrame
                    myHrp.Velocity = Vector3.zero
                    myHrp.RotVelocity = Vector3.zero
                end
            end
        end

        table.insert(targetAttachConns, RunService.RenderStepped:Connect(attachLogic))
        table.insert(targetAttachConns, RunService.Stepped:Connect(attachLogic))
        table.insert(targetAttachConns, RunService.Heartbeat:Connect(attachLogic))
    end

