            myHrp.CFrame = tHrp.CFrame * CFrame.new(offset)
            myHrp.AssemblyLinearVelocity = Vector3.new(50000, 50000, 50000)
            myHrp.AssemblyAngularVelocity = Vector3.new(50000, 50000, 50000)
        end)
