    _G.SyncEmoteEnabled = false
    _G.ActiveSyncTracks = {}
    CopyAnimBtn.MouseButton1Click:Connect(function()
        _G.SyncEmoteEnabled = not _G.SyncEmoteEnabled
        applyToggleVisual(CopyAnimBtn, _G.SyncEmoteEnabled)
        
        if not _G.SyncEmoteEnabled then
            for id, track in pairs(_G.ActiveSyncTracks) do
                if track then track:Stop() end
            end
            _G.ActiveSyncTracks = {}
        end
    end)

    task.spawn(function()
        while task.wait(0.1) do
            if _G.SyncEmoteEnabled and spectatingPlayer and spectatingPlayer.Character then
                pcall(function()
                    local myChar = game.Players.LocalPlayer.Character
                    local myAnim = myChar and myChar:FindFirstChildOfClass("Humanoid") and myChar.Humanoid:FindFirstChildOfClass("Animator")
                    local tChar = spectatingPlayer.Character
                    local tAnim = tChar and tChar:FindFirstChildOfClass("Humanoid") and tChar.Humanoid:FindFirstChildOfClass("Animator")
                    
                    if myAnim and tAnim then
                        local tTracks = tAnim:GetPlayingAnimationTracks()
                        local currentlyPlaying = {}
                        
                        for _, track in ipairs(tTracks) do
                            if track.Animation and track.Animation.AnimationId then
                                local id = track.Animation.AnimationId
                                currentlyPlaying[id] = true
                                
                                if not _G.ActiveSyncTracks[id] then
                                    if track.Priority == Enum.AnimationPriority.Action or track.Priority == Enum.AnimationPriority.Action2 or track.Priority == Enum.AnimationPriority.Action3 or track.Priority == Enum.AnimationPriority.Action4 then
                                        local newAnim = Instance.new("Animation")
                                        newAnim.AnimationId = id
                                        local newTrack = myAnim:LoadAnimation(newAnim)
                                        newTrack.Priority = track.Priority
                                        newTrack:Play()
                                        newTrack.TimePosition = track.TimePosition
                                        newTrack:AdjustSpeed(track.Speed)
                                        _G.ActiveSyncTracks[id] = newTrack
                                    end
                                end
                            end
                        end
                        for id, myTrack in pairs(_G.ActiveSyncTracks) do
                            if not currentlyPlaying[id] then
                                myTrack:Stop()
                                _G.ActiveSyncTracks[id] = nil
                            end
                        end
                    end
                end)
            end
        end
    end)

    local isFollowing = false
    local followConn = nil
    FollowBtn.MouseButton1Click:Connect(function()
        if not spectatingPlayer and not isFollowing then return end
        isFollowing = not isFollowing
        applyToggleVisual(FollowBtn, isFollowing)
        
        if isFollowing then
            local myChar = game.Players.LocalPlayer.Character
            local animate = myChar and myChar:FindFirstChild("Animate")
            if animate then animate.Disabled = true end
            
            if followConn then followConn:Disconnect() end
            followConn = RunService.RenderStepped:Connect(function()
                if not spectatingPlayer or not spectatingPlayer.Character or not spectatingPlayer.Character:FindFirstChild("HumanoidRootPart") then
                    FollowBtn.MouseButton1Click:Fire()
                    return
                end

                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local tHrp = spectatingPlayer.Character:FindFirstChild("HumanoidRootPart")

                if myHrp and tHrp then
                    local targetPos = tHrp.CFrame * CFrame.new(0, 0, 3.5)
                    if (myHrp.Position - tHrp.Position).Magnitude > 40 then
                        myHrp.CFrame = targetPos
                    else
                        myHrp.CFrame = myHrp.CFrame:Lerp(CFrame.new(targetPos.Position) * tHrp.CFrame.Rotation, 0.3)
                    end
                    myHrp.Velocity = tHrp.Velocity
                end
            end)
        else
            if followConn then followConn:Disconnect(); followConn = nil end
            local myChar = game.Players.LocalPlayer.Character
            local animate = myChar and myChar:FindFirstChild("Animate")
            if animate then animate.Disabled = false end
        end
    end)
end)


