-- Lógica Principal de Ativação do Painel
GUI.FlashbackBtn.MouseButton1Click:Connect(function()
    _G.S7xFlashback.Enabled = not _G.S7xFlashback.Enabled
    if type(setToggleState) == "function" then setToggleState(GUI.FlashbackBtn, _G.S7xFlashback.Enabled) end
    
    if not _G.S7xFlashback.Enabled then 
        _G.S7xFlashback.History = {} 
    end
    
    -- Exibe o controle remoto apenas para usuários Mobile
    local isMob = game:GetService("UserInputService").TouchEnabled and not game:GetService("UserInputService").KeyboardEnabled
    if isMob and GUI.FlashbackWidget then
        GUI.FlashbackWidget.Visible = _G.S7xFlashback.Enabled
    end
end)

-- Motor Físico de Gravação (Heartbeat)
game:GetService("RunService").Heartbeat:Connect(function()
    if _G.S7xFlashback.Enabled and _G.S7xFlashback.Recording and not _G.S7xFlashback.Rewinding and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
        local hrp = player.Character.HumanoidRootPart
        table.insert(_G.S7xFlashback.History, 1, {cf = hrp.CFrame, vel = hrp.Velocity})
        
        -- Limite de histórico para não estourar a RAM do celular (150 frames)
        if #_G.S7xFlashback.History > 150 then
            table.remove(_G.S7xFlashback.History, #_G.S7xFlashback.History)
        end
    end
end)

-- Função Global de Retorno no Tempo (Linkada à Hotkey do PC e ao Botão Mobile)
triggerFlashback = function() 
    if not _G.S7xFlashback.Enabled or _G.S7xFlashback.Rewinding or #_G.S7xFlashback.History == 0 then return end
    local char = player.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    
    _G.S7xFlashback.Rewinding = true
    
    -- Desliga colisões para não travar nas paredes enquanto volta
    local originalCollisions = {}
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then 
            originalCollisions[part] = part.CanCollide
            part.CanCollide = false 
        end
    end
    
    -- Retrocesso Suave (RenderStepped)
    for i = 1, #_G.S7xFlashback.History do
        if not hrp or not hrp.Parent then break end
        hrp.CFrame = _G.S7xFlashback.History[i].cf
        hrp.Velocity = _G.S7xFlashback.History[i].vel
        game:GetService("RunService").RenderStepped:Wait()
    end
    
    -- Restaura colisões normais
    if char and char.Parent then
        for part, state in pairs(originalCollisions) do
            if part and part.Parent then part.CanCollide = state end
        end
    end
    
    _G.S7xFlashback.History = {}
    _G.S7xFlashback.Rewinding = false
end

-- Conecta a função global ao novo botão Mobile
GUI.RewindBtn.MouseButton1Click:Connect(triggerFlashback)

