local isFarming = false
GUI.FarmBtn.MouseButton1Click:Connect(function()
    isFarming = not isFarming
    setToggleState(GUI.FarmBtn, isFarming)
    
    if isFarming then 
        task.spawn(function()
            while isFarming do
                local eggs = workspace:FindFirstChild("Eggs")
                local char = player.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                
                if hrp and eggs then
                    for _, obj in pairs(eggs:GetChildren()) do
                        if not isFarming then break end
                        
                        if obj:IsA("Model") and string_find(obj.Name, "Egg") then
                            local targetPart = obj:FindFirstChildWhichIsA("BasePart", true)
                            if targetPart then
                                hrp.Velocity = Vector3.new(0,0,0)
                                hrp.RotVelocity = Vector3.new(0,0,0)
                                
                                for _, desc in ipairs(obj:GetDescendants()) do
                                    if desc:IsA("ProximityPrompt") then
                                        pcall(function() fireproximityprompt(desc, 0, true) end)
                                    elseif desc:IsA("ClickDetector") then
                                        pcall(function() fireclickdetector(desc) end)
                                    end
                                end

                                local elapsed = 0
                                while elapsed < 2.5 and isFarming do
                                    if hrp then hrp.CFrame = targetPart.CFrame * CFrame.new(0, 7, 0) * CFrame.Angles(0, elapsed * 4, 0) end
                                    elapsed = elapsed + task.wait(0.05)
                                end
                            end
                        end
                    end
                end
                task.wait(0.1)
            end
        end) 
    end
end)

GUI.CollectBtn.MouseButton1Click:Connect(function()
    task.spawn(function()
        pcall(function()
            local VirtualInputManager = game:GetService("VirtualInputManager")
            local Workspace = game:GetService("Workspace")
            local LocalPlayer = Players.LocalPlayer 
            local TARGET_PATH = Workspace:FindFirstChild("Map") and Workspace.Map:FindFirstChild("Butterflies")
            if not TARGET_PATH then return end
            local TARGET_NAME = "Butterfly"
            local COOLDOWN_DELAY = 5.0
            local POST_TP_DELAY = 0.5
            local MAX_SYNC_WAIT = 2.0 
            local TargetQueue = {}
            local isRunning = true
            local skipRequested = false
            local originalPos = LocalPlayer.Character:WaitForChild("HumanoidRootPart").CFrame

            local ScreenGuiFarm = Instance.new("ScreenGui", LocalPlayer:WaitForChild("PlayerGui", 999))
            ScreenGuiFarm.Name = "MinimalFarm"
            local Main = Instance.new("Frame", ScreenGuiFarm)
            Main.Size = UDim2.new(0, 220, 0, 110)
            if GUI.MainFrame and GUI.MainFrame.Visible then Main.Position = UDim2.new(0, GUI.MainFrame.AbsolutePosition.X + GUI.MainFrame.AbsoluteSize.X + 15, 0, GUI.MainFrame.AbsolutePosition.Y) else Main.Position = UDim2.new(0.5, -110, 0.85, 0) end
            Main.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
            Instance.new("UICorner", Main).CornerRadius = UDim.new(0, 8)
            Instance.new("UIStroke", Main).Color = Color3.fromRGB(170, 0, 255)
            
            local Status = Instance.new("TextLabel", Main)
            Status.Size = UDim2.new(1, 0, 0.4, 0); Status.Text = "WAITING"; Status.TextColor3 = Color3.fromRGB(200, 200, 200); Status.BackgroundTransparency = 1; Status.TextSize = 14; Status.Font = Enum.Font.GothamMedium
            local Counter = Instance.new("TextLabel", Main)
            Counter.Position = UDim2.new(0, 0, 0.35, 0); Counter.Size = UDim2.new(1, 0, 0.3, 0); Counter.Text = "0 TARGETS"; Counter.TextColor3 = Color3.fromRGB(170, 0, 255); Counter.BackgroundTransparency = 1; Counter.TextSize = 20; Counter.Font = Enum.Font.GothamBold
            local BtnContainer = Instance.new("Frame", Main)
            BtnContainer.Position = UDim2.new(0.05, 0, 0.7, 0); BtnContainer.Size = UDim2.new(0.9, 0, 0.25, 0); BtnContainer.BackgroundTransparency = 1
            local UIList = Instance.new("UIListLayout", BtnContainer); UIList.FillDirection = Enum.FillDirection.Horizontal; UIList.Padding = UDim.new(0, 5); UIList.HorizontalAlignment = Enum.HorizontalAlignment.Center
            
            local SkipBtn = Instance.new("TextButton", BtnContainer); SkipBtn.Size = UDim2.new(0.48, 0, 1, 0); SkipBtn.Text = "SKIP"; SkipBtn.BackgroundColor3 = Color3.fromRGB(28, 28, 28); SkipBtn.TextColor3 = Color3.fromRGB(200, 200, 200); SkipBtn.Font = Enum.Font.GothamBold; SkipBtn.TextSize = 10; Instance.new("UICorner", SkipBtn).CornerRadius = UDim.new(0, 6)
            local StopBtn = Instance.new("TextButton", BtnContainer); StopBtn.Size = UDim2.new(0.48, 0, 1, 0); StopBtn.Text = "STOP"; StopBtn.BackgroundColor3 = Color3.fromRGB(150, 0, 0); StopBtn.TextColor3 = Color3.fromRGB(200, 200, 200); StopBtn.Font = Enum.Font.GothamBold; StopBtn.TextSize = 10; Instance.new("UICorner", StopBtn).CornerRadius = UDim.new(0, 6)
            
            SkipBtn.MouseButton1Click:Connect(function() skipRequested = true end)
            StopBtn.MouseButton1Click:Connect(function() isRunning = false end)

            task.spawn(function()
                while isRunning do
                    TargetQueue = {}
                    for _, obj in ipairs(TARGET_PATH:GetChildren()) do if obj.Name == TARGET_NAME then table.insert(TargetQueue, obj) end end
                    local total = #TargetQueue
                    Counter.Text = total .. " TARGETS"
                    if total > 0 then
                        for i, target in ipairs(TargetQueue) do
                            if not isRunning then break end
                            skipRequested = false
                            if target and target.Parent then
                                local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                                if root then
                                    Status.Text = "SEARCHING..."; root.CFrame = (target:IsA("BasePart") and target.CFrame or target:FindFirstChildWhichIsA("BasePart").CFrame) * CFrame.new(0, 2, 0)
                                    task.wait(POST_TP_DELAY)
                                    Status.Text = "COLLECTING..."; VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 0); task.wait(0.05); VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 0)
                                    local startWait = tick()
                                    repeat task.wait(0.1) until not target.Parent or (tick() - startWait > MAX_SYNC_WAIT)
                                    Counter.Text = (total - i) .. " TARGETS"
                                    for t = COOLDOWN_DELAY, 1, -1 do if skipRequested or not isRunning then break end; Status.Text = "NEXT IN " .. t .. "S"; task.wait(1) end
                                end
                            end
                        end
                    else
                        for t = 1, 3 do if not isRunning then break end; Status.Text = "WAITING RESPAWN..."; task.wait(1) end
                    end
                end
                Status.Text = "RETURNING..."; task.wait(1)
                local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if root and originalPos then root.CFrame = originalPos end
                Status.Text = "FINISHED"; task.wait(1); if ScreenGuiFarm then ScreenGuiFarm:Destroy() end
            end)
