-- ==========================================
-- [ TOUCH FLING PRO FIX ]
-- ==========================================
_G.S7xTouchFlingEnabled = false
_G.S7xMovel = 0.1

local function touchFlingLoop()
    while _G.S7xTouchFlingEnabled do
        game:GetService("RunService").Heartbeat:Wait()
        local hrp = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            local vel = hrp.Velocity
            hrp.Velocity = vel * 10000 + Vector3.new(0, 10000, 0)
            game:GetService("RunService").RenderStepped:Wait()
            hrp.Velocity = vel
            game:GetService("RunService").Stepped:Wait()
            hrp.Velocity = vel + Vector3.new(0, _G.S7xMovel, 0)
            _G.S7xMovel = -_G.S7xMovel
        end
    end
end

_G.S7xToggleTouchFling = function()
    _G.S7xTouchFlingEnabled = not _G.S7xTouchFlingEnabled
    if type(setToggleState) == "function" then setToggleState(GUI.TouchFling, _G.S7xTouchFlingEnabled) end
    if _G.S7xTouchFlingEnabled then 
        _G.TouchFlingThread = coroutine.create(touchFlingLoop)
        coroutine.resume(_G.TouchFlingThread) 
    end
end
GUI.TouchFling.MouseButton1Click:Connect(_G.S7xToggleTouchFling)

-- ==========================================
-- [ ANTI FLING PRO FIX ]
-- ==========================================
_G.S7xAntiFlingEnabled = false

_G.S7xToggleAntiFling = function()
    _G.S7xAntiFlingEnabled = not _G.S7xAntiFlingEnabled
    if type(setToggleState) == "function" then setToggleState(GUI.AntiFling, _G.S7xAntiFlingEnabled) end
    
    if _G.S7xAntiFlingEnabled then
        if _G.AntiFlingConn then _G.AntiFlingConn:Disconnect() end
        _G.AntiFlingConn = game:GetService("RunService").Stepped:Connect(function()
            for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                if p ~= game.Players.LocalPlayer and p.Character then
                    for _, v in ipairs(p.Character:GetChildren()) do
                        if v:IsA("BasePart") then
                            if v.CanCollide then v.CanCollide = false end
                            if v.RotVelocity.Magnitude > 50 or v.Velocity.Magnitude > 250 then 
                                v.RotVelocity = Vector3.zero
                                v.Velocity = Vector3.zero 
                            end
                        elseif v:IsA("Accessory") then
                            local handle = v:FindFirstChild("Handle")
                            if handle and handle:IsA("BasePart") then
                                if handle.CanCollide then handle.CanCollide = false end
                                if handle.RotVelocity.Magnitude > 50 or handle.Velocity.Magnitude > 250 then 
                                    handle.RotVelocity = Vector3.zero
                                    handle.Velocity = Vector3.zero 
                                end
                            end
                        end
                    end
                end
            end
        end)
    else
        if _G.AntiFlingConn then _G.AntiFlingConn:Disconnect(); _G.AntiFlingConn = nil end
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            if p ~= game.Players.LocalPlayer and p.Character then
                for _, v in ipairs(p.Character:GetChildren()) do
                    if v:IsA("BasePart") and (v.Name == "Torso" or v.Name == "UpperTorso" or v.Name == "LowerTorso" or v.Name == "Head") then 
                        v.CanCollide = true 
                    end
                end
            end
        end
    end
end
GUI.AntiFling.MouseButton1Click:Connect(_G.S7xToggleAntiFling)

-----------------------------------------
-- ANTI FLING V2 (DEFLECTOR SHIELD & OWN-FLING BYPASS)
-----------------------------------------
_G.AntiFlingV2Enabled = false
local antiFlingV2Conns = {}
local lastSafeCFrame = nil

local function ClearAntiFlingV2()
    for _, conn in ipairs(antiFlingV2Conns) do
        if conn then conn:Disconnect() end
    end
    table.clear(antiFlingV2Conns)
    lastSafeCFrame = nil
end

-- Transformado em Função Global para a Hotkey conseguir acionar
_G.ToggleAntiFlingV2 = function()
    _G.AntiFlingV2Enabled = not _G.AntiFlingV2Enabled
    if type(setToggleState) == "function" then setToggleState(GUI.AntiFlingV2Btn, _G.AntiFlingV2Enabled) end
    
    if _G.AntiFlingV2Enabled then
        ClearAntiFlingV2()
        local RS = game:GetService("RunService")
        
        -- [1] ESCUDO DEFLETOR (Stepped - Antes da física)
        table.insert(antiFlingV2Conns, RS.Stepped:Connect(function()
            local char = game.Players.LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            
            if hrp then
                local overlap = OverlapParams.new()
                overlap.FilterType = Enum.RaycastFilterType.Exclude
                overlap.FilterDescendantsInstances = {char}
                
                local parts = workspace:GetPartBoundsInRadius(hrp.Position, 8, overlap)
                for _, part in ipairs(parts) do
                    if not part.Anchored and part:IsA("BasePart") then
                        local speed = part.AssemblyLinearVelocity.Magnitude
                        local rotSpeed = part.AssemblyAngularVelocity.Magnitude
                        
                        if speed > 30 or rotSpeed > 30 then
                            part.CanCollide = false 
                            part.AssemblyLinearVelocity = Vector3.new(0, -99999, 0)
                            part.AssemblyAngularVelocity = Vector3.zero
                        end
                    end
                end
            end
        end))

        -- [2] MOTOR DE BACKUP (Heartbeat - Depois da física)
        table.insert(antiFlingV2Conns, RS.Heartbeat:Connect(function()
            local char = game.Players.LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChild("Humanoid")
            
            if hrp and hum and hum.Health > 0 then
                local myFlingActive = false
                pcall(function()
                    local touchKnob = GUI.TouchFling:FindFirstChild("ToggleBG") and GUI.TouchFling.ToggleBG:FindFirstChild("ToggleKnob")
                    local targetKnob = GUI.TargetFlingBtn:FindFirstChild("ToggleBG") and GUI.TargetFlingBtn.ToggleBG:FindFirstChild("ToggleKnob")
                    
                    if _G.FlingAuraEnabled then myFlingActive = true end
                    if touchKnob and touchKnob.Position.X.Offset > 10 then myFlingActive = true end
                    if targetKnob and targetKnob.Position.X.Offset > 10 then myFlingActive = true end
                    if _G.RemoteFlingData and _G.RemoteFlingData.ativo then myFlingActive = true end
                end)

                local speed = hrp.AssemblyLinearVelocity.Magnitude
                
                if speed > 150 and not myFlingActive then 
                    if lastSafeCFrame then
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        hrp.AssemblyAngularVelocity = Vector3.zero
                        hrp.CFrame = lastSafeCFrame
                    end
                elseif speed < 40 and hum.FloorMaterial ~= Enum.Material.Air and not myFlingActive then
                    local rayParams = RaycastParams.new()
                    rayParams.FilterType = Enum.RaycastFilterType.Exclude
                    rayParams.FilterDescendantsInstances = {char}
                    
                    local result = workspace:Raycast(hrp.Position, Vector3.new(0, -6, 0), rayParams)
                    if result and result.Instance and result.Instance.Anchored then
                        lastSafeCFrame = hrp.CFrame
                    end
                end
            end
        end))
        
        if type(S7xNotify) == "function" then S7xNotify("ANTI FLING V2", "Deflector Shield & Bypass Active.") end
    else
        ClearAntiFlingV2()
        if type(S7xNotify) == "function" then S7xNotify("ANTI FLING V2", "System Offline.") end
    end
end

-- Conecta a função global ao clique do botão
GUI.AntiFlingV2Btn.MouseButton1Click:Connect(_G.ToggleAntiFlingV2)
