--- SISTEMA FLING AURA (AURA DA MORTE)
-----------------------------------------
_G.FlingAuraEnabled = false

GUI.FlingAuraBtn.MouseButton1Click:Connect(function()
    _G.FlingAuraEnabled = not _G.FlingAuraEnabled
    setToggleState(GUI.FlingAuraBtn, _G.FlingAuraEnabled)
