task.spawn(function()
    local RunService = game:GetService("RunService")
    local auraRadius = 15 -- Raio de proteção da aura (15 studs)
    
    RunService.Heartbeat:Connect(function()
        if _G.FlingAuraEnabled and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
            local myHrp = player.Character.HumanoidRootPart
            local myHum = player.Character:FindFirstChild("Humanoid")
            
            -- Procura vítimas ao redor
            local vitimas = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= player and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                    local tHrp = p.Character.HumanoidRootPart
                    -- Se a distância for menor ou igual ao raio, a pessoa é marcada para ejetar
                    if (myHrp.Position - tHrp.Position).Magnitude <= auraRadius then
                        table.insert(vitimas, tHrp)
                    end
                end
            end
            
            -- Se tiver alguém na área, executa o impacto instantâneo
            if #vitimas > 0 then
                local savedCF = myHrp.CFrame
                local oldStand = myHum and myHum.PlatformStand or false
                if myHum then myHum.PlatformStand = true end
                
                for _, tHrp in ipairs(vitimas) do
                    -- Teleporta para o alvo aplicando torque e força extrema
                    myHrp.CFrame = tHrp.CFrame * CFrame.new(math.random(-1,1), 0, math.random(-1,1))
                    myHrp.Velocity = Vector3.new(50000, 50000, 50000)
                    myHrp.RotVelocity = Vector3.new(50000, 50000, 50000)
                    
                    -- Aguarda o motor físico calcular a pancada no alvo
                    RunService.RenderStepped:Wait() 
                end
                
                -- Devolve seu personagem pro lugar original sem nenhum arranhão
                myHrp.CFrame = savedCF
                myHrp.Velocity = Vector3.zero
                myHrp.RotVelocity = Vector3.zero
                if myHum then myHum.PlatformStand = oldStand end
            end
        end
    end)
end)
