--- SISTEMA SHIFT LOCK SUPREMO (PC & MOBILE AUTO-LOCK)
-----------------------------------------
S7xIsShiftLocked = false
S7xShiftConn_RS = nil

S7xDisableShiftLock = function()
    S7xIsShiftLocked = false
    
    -- Desliga o loop de rotação instantaneamente
    if S7xShiftConn_RS then 
        S7xShiftConn_RS:Disconnect()
        S7xShiftConn_RS = nil 
    end
    
    -- Restaura câmera e mouse para o padrão
    pcall(function()
        game:GetService("UserInputService").MouseBehavior = Enum.MouseBehavior.Default
        local char = game.Players.LocalPlayer.Character
        local hum = char and char:FindFirstChild("Humanoid")
        if hum then
            hum.CameraOffset = Vector3.new(0, 0, 0)
            hum.AutoRotate = true -- Devolve a rotação normal de caminhada
        end
    end)
end

GUI.ShiftLockBtn.MouseButton1Click:Connect(function()
    S7xIsShiftLocked = not S7xIsShiftLocked
    if type(setToggleState) == "function" then setToggleState(GUI.ShiftLockBtn, S7xIsShiftLocked) end
    
    if S7xIsShiftLocked then
        if type(S7xNotify) == "function" then S7xNotify("SHIFT LOCK", "Câmera e movimento travados.") end
        
        -- Ajuste imediato do deslocamento da câmera
        pcall(function()
            local char = game.Players.LocalPlayer.Character
            local hum = char and char:FindFirstChild("Humanoid")
            if hum then 
                hum.CameraOffset = Vector3.new(1.75, 0, 0) 
                hum.AutoRotate = false -- Desliga a rotação base para evitar conflitos
            end
        end)

        -- Previne loops duplicados
        if S7xShiftConn_RS then S7xShiftConn_RS:Disconnect() end
        
        -- Motor de travamento (Garante que o corpo siga a câmera a cada frame)
        S7xShiftConn_RS = game:GetService("RunService").RenderStepped:Connect(function()
            if S7xIsShiftLocked then
                pcall(function()
                    -- Força o mouse no centro da tela (Dispositivos Mobile ignoram isso nativamente, o que é perfeito)
                    game:GetService("UserInputService").MouseBehavior = Enum.MouseBehavior.LockCenter
                    
                    local char = game.Players.LocalPlayer.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    local hum = char and char:FindFirstChild("Humanoid")
                    local cam = workspace.CurrentCamera
                    
                    if hrp and hum and hum.Health > 0 then
                        -- Extrai a direção da câmera e força o personagem a olhar para lá
                        local lookVector = cam.CFrame.LookVector
                        local targetLook = Vector3.new(lookVector.X, 0, lookVector.Z).Unit
                        hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + targetLook)
                    end
                end)
            end
        end)
    else
        -- Desligamento Total do Módulo
        S7xDisableShiftLock()
        if type(S7xNotify) == "function" then S7xNotify("SHIFT LOCK", "Sistema desligado.") end
    end
end)

-- Sistema de Persistência (Evita bugs na câmera caso o jogador morra com o Shift Lock ativado)
game.Players.LocalPlayer.CharacterAdded:Connect(function(char)
    if S7xIsShiftLocked then
        local hum = char:WaitForChild("Humanoid", 3)
        if hum then 
            hum.CameraOffset = Vector3.new(1.75, 0, 0)
            hum.AutoRotate = false
        end
    end
end)

-- ==========================================
-- SISTEMA ANTI-AFK SUPREMO (CRASH-PROOF & AUTO-START)
-- ==========================================
antiAfkEnabled = false 
afkConn = nil

local function ToggleAntiAfk(state)
    antiAfkEnabled = state
    -- Atualiza a UI (Alavanca)
    if type(setToggleState) == "function" then setToggleState(GUI.AntiAfkBtn, antiAfkEnabled) end
    
    if antiAfkEnabled then
        -- [ CAMADA 1 ]: Bloqueio Silencioso (Zero Simulação, Zero Bugs)
        -- Desativa o gatilho de inatividade do próprio Roblox direto na memória
        pcall(function()
            if getconnections then
                for _, conn in pairs(getconnections(game.Players.LocalPlayer.Idled)) do
                    conn:Disable()
                end
            end
        end)

        -- [ CAMADA 2 ]: Fallback Seguro (Caso o executor não suporte a Camada 1)
        if not afkConn then
            afkConn = game.Players.LocalPlayer.Idled:Connect(function() 
                task.spawn(function()
                    pcall(function()
                        local vu = game:GetService("VirtualUser")
                        -- Dá um leve toque virtual no botão direito sem roubar a câmera ou o mouse
                        vu:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
                        task.wait(0.1)
                        vu:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
                    end)
                end)
            end)
        end
    else
        -- Restaura as conexões de inatividade nativas do jogo
        pcall(function()
            if getconnections then
                for _, conn in pairs(getconnections(game.Players.LocalPlayer.Idled)) do
                    conn:Enable()
                end
            end
        end)
        
        -- Limpeza cirúrgica da memória
        if afkConn then 
            afkConn:Disconnect()
            afkConn = nil 
        end
    end
end

-- Evento de clique manual do usuário
GUI.AntiAfkBtn.MouseButton1Click:Connect(function()
    ToggleAntiAfk(not antiAfkEnabled)
end)

-- Auto-Start: Ativa o Anti-AFK silenciosamente 1 segundo após o painel injetar
task.spawn(function()
    task.wait(1)
    if not antiAfkEnabled then
        ToggleAntiAfk(true)
    end
end)
