-- =========================================================================
-- A SEQUÊNCIA DE INICIALIZAÇÃO PROFISSIONAL (TRANSPARENT HUD BOOTSTRAPPER)
-- =========================================================================
task.spawn(function()
    -- 1. Bloqueio Inicial Absoluto
    _G.S7xIsFullyLoaded = false
    if GUI.OpenBtn then GUI.OpenBtn.Visible = false end
    if GUI.MainFrame then GUI.MainFrame.Visible = false end

    -- 2. Criação do Contêiner (Transparente e Flutuante)
    local BootFrame = Instance.new("Frame", GUI.ScreenGui)
    BootFrame.Size = UDim2.new(0, 360, 0, 260) 
    BootFrame.Position = UDim2.new(0.5, -180, 0.5, -130)
    BootFrame.BackgroundTransparency = 1 
    
    -- 3. Sistema de Preenchimento da Logo (Efeito Água Roxa Descendente)
    local LogoBase = Instance.new("ImageLabel", BootFrame)
    LogoBase.Size = UDim2.new(0, 160, 0, 160) 
    LogoBase.Position = UDim2.new(0.5, -80, 0.5, -80)
    LogoBase.BackgroundTransparency = 1
    LogoBase.Image = "rbxassetid://98669326744803"
    LogoBase.ImageColor3 = Color3.fromRGB(0, 0, 0) -- Fundo silhueta escura
    LogoBase.ImageTransparency = 0.5 -- Sombra de fundo suave
    LogoBase.ScaleType = Enum.ScaleType.Fit
    LogoBase.ZIndex = 2

    -- Container de corte ancorado no topo (Para descer igual água)
    local LogoFillContainer = Instance.new("Frame", LogoBase)
    LogoFillContainer.Size = UDim2.new(1, 0, 0, 0)
    LogoFillContainer.Position = UDim2.new(0, 0, 0, 0)
    LogoFillContainer.AnchorPoint = Vector2.new(0, 0)
    LogoFillContainer.BackgroundTransparency = 1
    LogoFillContainer.ClipsDescendants = true
    LogoFillContainer.ZIndex = 3

    local LogoBright = Instance.new("ImageLabel", LogoFillContainer)
    LogoBright.Size = UDim2.new(0, 160, 0, 160)
    LogoBright.Position = UDim2.new(0, 0, 0, 0)
    LogoBright.AnchorPoint = Vector2.new(0, 0)
    LogoBright.BackgroundTransparency = 1
    LogoBright.Image = "rbxassetid://98669326744803"
    LogoBright.ImageColor3 = Color3.fromRGB(100, 0, 255) 
    LogoBright.ImageTransparency = 0.4
    LogoBright.ScaleType = Enum.ScaleType.Fit

    -- Áudio do Carregamento (Sincronizado de 10s)
    local loadSfx
    pcall(function()
        loadSfx = Instance.new("Sound", game:GetService("CoreGui"))
        loadSfx.SoundId = "rbxassetid://9038803355"
        loadSfx.Volume = 1
        loadSfx:Play()
        game:GetService("Debris"):AddItem(loadSfx, 11) 
    end)

    -- 4. Lógica Matemática de Sincronização (EXATOS 10 SEGUNDOS)
    local percentValue = Instance.new("NumberValue")
    percentValue.Value = 0

    percentValue:GetPropertyChangedSignal("Value"):Connect(function()
        local pct = math.clamp(percentValue.Value / 100, 0, 1)
        
        -- [ EFEITO ÁGUA ROXA DESCE ]
        LogoFillContainer.Size = UDim2.new(1, 0, pct, 0)
        local rColor = 100 + (70 * pct)
        LogoBright.ImageColor3 = Color3.fromRGB(rColor, 0, 255)
        LogoBright.ImageTransparency = 0.4 - (0.4 * pct)
    end)

    local ts = game:GetService("TweenService")
    
    local loadingTween = ts:Create(percentValue, TweenInfo.new(10, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut), {Value = 100})
    loadingTween:Play()
    loadingTween.Completed:Wait()
    
    task.wait(0.2)

    -- 5. Ocultação Suave (Fade Out)
    local fadeOutInfo = TweenInfo.new(0.5, Enum.EasingStyle.Quint)
    ts:Create(BootFrame, fadeOutInfo, {Size = UDim2.new(0, 380, 0, 280), Position = UDim2.new(0.5, -190, 0.5, -140)}):Play()
    ts:Create(LogoBase, fadeOutInfo, {ImageTransparency = 1}):Play()
    ts:Create(LogoBright, fadeOutInfo, {ImageTransparency = 1}):Play()
    
    if loadSfx then
        ts:Create(loadSfx, TweenInfo.new(0.5), {Volume = 0}):Play()
    end

    task.wait(0.5)
    if BootFrame then BootFrame:Destroy() end
    if loadSfx then loadSfx:Destroy() end

    _G.S7xIsFullyLoaded = true 
    
    if GUI.OpenBtn then 
        GUI.OpenBtn.Visible = true
        GUI.OpenBtn.BackgroundTransparency = 1
        if GUI.OpenBtnIcon then GUI.OpenBtnIcon.ImageTransparency = 1 end
        
        ts:Create(GUI.OpenBtn, TweenInfo.new(0.5, Enum.EasingStyle.Sine), {BackgroundTransparency = 0}):Play()
        if GUI.OpenBtnIcon then ts:Create(GUI.OpenBtnIcon, TweenInfo.new(0.5), {ImageTransparency = 0}):Play() end
    end
    
    if type(resetTabs) == "function" then
        resetTabs()
        if GUI.InicioFrame then GUI.InicioFrame.Visible = true end
        GUI.InicioTabBtn:SetAttribute("IsSelected", true) 
        pcall(function()
            ts:Create(GUI.InicioTabBtn, TweenInfo.new(0), {TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 0.4}):Play()
            local ind = GUI.InicioTabBtn:FindFirstChild("Indicator")
            if ind then ind.Size = UDim2.new(0, 4, 0.7, 0) end
        end)
    end
    
    if type(togglePanel) == "function" then togglePanel() end
end)



