-- ==========================================
-- SISTEMA DE REDIMENSIONAMENTO MULTI-DIRECIONAL (PERFECT SCALE FIX)
-- ==========================================
if GUI.ResizeBtn then pcall(function() GUI.ResizeBtn:Destroy() end) end

GUI.ResizeBtn = Instance.new("TextButton", GUI.MainFrame)
GUI.ResizeBtn.Size = UDim2.new(0, 35, 0, 35) -- Área de toque otimizada
GUI.ResizeBtn.Position = UDim2.new(1, -35, 1, -35)
GUI.ResizeBtn.BackgroundTransparency = 1
GUI.ResizeBtn.Text = "◢"
GUI.ResizeBtn.TextColor3 = Color3.fromRGB(170, 0, 255)
GUI.ResizeBtn.TextSize = 22
GUI.ResizeBtn.ZIndex = 10000

local isResizing = false
local dragStartMouse = nil
local startSize = nil
local startPos = nil

local uis = game:GetService("UserInputService")
local rs = game:GetService("RunService")
local cam = workspace.CurrentCamera

-- Início do redimensionamento (Gatilho inicial)
GUI.ResizeBtn.InputBegan:Connect(function(input) 
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then 
        isResizing = true
        dragStartMouse = uis:GetMouseLocation()
        -- Lemos o Offset exato e não o AbsoluteSize para blindar o cálculo contra o UIScale
        startSize = Vector2.new(GUI.MainFrame.Size.X.Offset, GUI.MainFrame.Size.Y.Offset)
        startPos = GUI.MainFrame.Position
    end 
end)

-- Fim do redimensionamento (Salva as posições globais)
uis.InputEnded:Connect(function(input) 
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then 
        if isResizing then
            isResizing = false
            if GUI.MainFrame then
                _G.S7xPanelTargetSize = GUI.MainFrame.Size
                _G.S7xPanelTargetPos = GUI.MainFrame.Position
            end
        end
    end 
end)

-- [ O SEGREDO DO ZERO LAG E MULTI-DIREÇÃO ]:
-- Roda no Heartbeat lendo o mouse globalmente. Nunca perde um frame ou desvia o cursor.
if _G.S7xResizeLoop then _G.S7xResizeLoop:Disconnect() end
_G.S7xResizeLoop = rs.Heartbeat:Connect(function()
    if isResizing and GUI.MainFrame then
        local currentMouse = uis:GetMouseLocation()
        local deltaX = currentMouse.X - dragStartMouse.X
        local deltaY = currentMouse.Y - dragStartMouse.Y
        
        -- [ BLINDAGEM MATEMÁTICA ]: Extrai a escala atual para sincronizar o Mouse com a Interface
        local currentScale = 1
        local scaleObj = GUI.MainFrame:FindFirstChildOfClass("UIScale")
        if scaleObj then currentScale = scaleObj.Scale end

        -- Converte o movimento real do mouse (pixels da tela) para o tamanho interno do Frame
        local scaledDeltaX = deltaX / currentScale
        local scaledDeltaY = deltaY / currentScale

        -- Limites de Segurança Livres
        local minX, minY = 450, 350 
        local maxX, maxY = (cam.ViewportSize.X * 0.95) / currentScale, (cam.ViewportSize.Y * 0.95) / currentScale
        
        local rawNewX = startSize.X + scaledDeltaX
        local rawNewY = startSize.Y + scaledDeltaY
        
        local newX = math.clamp(rawNewX, minX, maxX)
        local newY = math.clamp(rawNewY, minY, maxY)
        
        local appliedDeltaX = newX - startSize.X
        local appliedDeltaY = newY - startSize.Y
        
        -- Compensa a posição global para travar o canto superior esquerdo no lugar exato
        -- (Isso neutraliza a expansão natural do AnchorPoint 0.5)
        local offsetX = (appliedDeltaX * currentScale) / 2
        local offsetY = (appliedDeltaY * currentScale) / 2
        
        local newSize = UDim2.new(0, newX, 0, newY)
        local newPos = UDim2.new(
            startPos.X.Scale, startPos.X.Offset + offsetX,
            startPos.Y.Scale, startPos.Y.Offset + offsetY
        )
        
        GUI.MainFrame.Size = newSize
        GUI.MainFrame.Position = newPos
        
        -- Salva temporariamente as variáveis para a animação de abrir/fechar respeitar esse tamanho
        _G.S7xPanelTargetSize = newSize
        _G.S7xPanelTargetPos = newPos
    end
end)

-- ==========================================
-- VARIÁVEIS SEGURAS DE TAMANHO E POSIÇÃO (BLINDADO)
-- ==========================================
-- Mobile: 75% de Largura e 92% de Altura
_G.S7xPanelTargetSize = isMobile and UDim2.new(0.75, 0, 0.92, 0) or UDim2.new(0, 530, 0, 480)
_G.S7xPanelTargetPos = UDim2.new(0.5, 0, 0.5, 0)

local panelOpen = false
local isTweening = false -- Trava de segurança anti-bug

-- ==========================================
-- MOTOR DE ANIMAÇÃO DO PAINEL (MEMÓRIA DE POSIÇÃO)
-- ==========================================
togglePanel = function(forceClose)
    if not _G.S7xIsFullyLoaded or isTweening then return end 
    isTweening = true -- Trava de segurança
    
    if forceClose == true then
        panelOpen = false
    else
        panelOpen = not panelOpen
    end
    
    local ts = game:GetService("TweenService")
    
    -- [ OTIMIZAÇÃO PRO: SOUND POOLING ]
    -- Cria os sons de interface apenas 1 vez na memória e os recicla, zerando o impacto de GC (Garbage Collection).
    if not _G.S7xPanelSFX_Open then
        local core = game:GetService("CoreGui")
        _G.S7xPanelSFX_Open = Instance.new("Sound", core); _G.S7xPanelSFX_Open.SoundId = "rbxassetid://6895082404"; _G.S7xPanelSFX_Open.Volume = 1.5
        _G.S7xPanelSFX_Close = Instance.new("Sound", core); _G.S7xPanelSFX_Close.SoundId = "rbxassetid://6895050519"; _G.S7xPanelSFX_Close.Volume = 1.5
    end

    pcall(function()
        if panelOpen then
            _G.S7xPanelSFX_Open.TimePosition = 0
            _G.S7xPanelSFX_Open:Play()
        else
            _G.S7xPanelSFX_Close.TimePosition = 0
            _G.S7xPanelSFX_Close:Play()
        end
    end)

    -- Proteção contra tamanho corrompido
    if _G.S7xPanelTargetSize.X.Offset < 100 and not isMobile then
        _G.S7xPanelTargetSize = UDim2.new(0, 530, 0, 480)
    end

    if panelOpen then
        -- [ ABRINDO O PAINEL ]
        if GUI.OpenBtn then
            pcall(function()
                ts:Create(GUI.OpenBtn, TweenInfo.new(0.2, Enum.EasingStyle.Sine), {BackgroundTransparency = 1}):Play()
                if GUI.OpenBtnIcon then ts:Create(GUI.OpenBtnIcon, TweenInfo.new(0.2), {ImageTransparency = 1}):Play() end
                local strk = GUI.OpenBtn:FindFirstChildOfClass("UIStroke")
                if strk then ts:Create(strk, TweenInfo.new(0.2), {Transparency = 1}):Play() end
                task.delay(0.2, function() if GUI.OpenBtn then GUI.OpenBtn.Visible = false end end)
            end)
        end

        -- Inicia do tamanho zero na posição salva (onde foi arrastado por último)
        GUI.MainFrame.Size = UDim2.new(0, 0, 0, 0)
        GUI.MainFrame.Position = _G.S7xPanelTargetPos
        GUI.MainFrame.Visible = true
        
        -- Anima APENAS O TAMANHO. O AnchorPoint 0.5 faz ele crescer a partir do centro dele mesmo!
        local tweenOpen = ts:Create(GUI.MainFrame, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
            Size = _G.S7xPanelTargetSize
        })
        
        tweenOpen:Play()
        task.spawn(function()
            tweenOpen.Completed:Wait()
            isTweening = false 
        end)
    else
        -- [ FECHANDO O PAINEL ]
        
        -- O SEGREDO PROFISSIONAL: Salva a posição exata onde o jogador arrastou ANTES de fechar!
        _G.S7xPanelTargetPos = GUI.MainFrame.Position

        if GUI.OpenBtn then
            GUI.OpenBtn.Visible = true
            pcall(function()
                ts:Create(GUI.OpenBtn, TweenInfo.new(0.3, Enum.EasingStyle.Sine), {BackgroundTransparency = 0}):Play()
                if GUI.OpenBtnIcon then ts:Create(GUI.OpenBtnIcon, TweenInfo.new(0.3), {ImageTransparency = 0}):Play() end
                local strk = GUI.OpenBtn:FindFirstChildOfClass("UIStroke")
                if strk then ts:Create(strk, TweenInfo.new(0.3), {Transparency = 0}):Play() end
            end)
        end

        -- Anima apenas o tamanho para 0, fazendo-o ser "sugado" pro exato lugar em que está
        local tweenClose = ts:Create(GUI.MainFrame, TweenInfo.new(0.35, Enum.EasingStyle.Exponential, Enum.EasingDirection.In), {
            Size = UDim2.new(0, 0, 0, 0)
        })
        
        tweenClose:Play()
        task.spawn(function()
            tweenClose.Completed:Wait()
            if not panelOpen then GUI.MainFrame.Visible = false end
            isTweening = false 
        end)
    end
end

