            game:GetService("TweenService"):Create(toggleKnob, TweenInfo.new(0.3, Enum.EasingStyle.Back), {Position = UDim2.new(0, 2, 0.5, -7), BackgroundColor3 = Color3.fromRGB(100, 100, 100)}):Play()
            game:GetService("TweenService"):Create(lbl, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(200, 200, 200)}):Play()
        end

        local isMob = game:GetService("UserInputService").TouchEnabled and not game:GetService("UserInputService").KeyboardEnabled

        if _G.MagicStickEnabled then
