                if type(GetFirebaseRank) == "function" then rank = GetFirebaseRank(game.Players.LocalPlayer) or "User" end
                
                local canSeeMagic = {
                    ["Supreme"] = true, ["Contributor"] = true, ["Marketing"] = true,
