        if input.KeyCode == bindKeys.MagicAttack then lockMagicTarget() end
        if input.KeyCode == bindKeys.MagicStop then stopMagicTarget() end
    end)

    -- [ 8. MOTOR FÍSICO DE ATAQUE SEM DELAY ]
    game:GetService("RunService").Heartbeat:Connect(function()
        if _G.MagicStickEnabled and _G.MagicSpam and _G.MagicTarget and _G.MagicTarget:FindFirstChild("Head") and _G.MagicTarget:FindFirstChild("Humanoid") then
            if _G.MagicTarget.Humanoid.Health <= 0 then
                stopMagicTarget()
                if type(S7xNotify) == "function" then S7xNotify("💀 ALVO ELIMINADO", "Sistema desativado automaticamente.") end
                return
            end
            
            local remote = getMagicStickRemote()
            if remote then
                local posAlvo = _G.MagicTarget.Head.Position
                -- Dispara 5 vezes no mesmo Frame para garantir instakill ignorando paredes
                for i = 1, 5 do 
                    remote:FireServer(posAlvo + Vector3.new(0, 0.1, 0), posAlvo)
                end
            end
        elseif _G.MagicStickEnabled and _G.MagicSpam and (not _G.MagicTarget or not _G.MagicTarget.Parent) then
            stopMagicTarget()
            if type(S7xNotify) == "function" then S7xNotify("⚠️ ALVO PERDIDO", "O jogador saiu do mapa ou reseta.") end
        end
    end)
end)

