        if _G.PaintBallEnabled and _G.PaintSpam and _G.PaintTarget and _G.PaintTarget:FindFirstChild("Head") and _G.PaintTarget:FindFirstChild("Humanoid") then
            if _G.PaintTarget.Humanoid.Health <= 0 then
                stopPaintTarget()
                if type(S7xNotify) == "function" then S7xNotify("💀 ALVO ELIMINADO", "Sistema desativado automaticamente.") end
                return
            end
            
            local remote = getPaintBallRemote()
            if remote then
                local posAlvo = _G.PaintTarget.Head.Position
                -- Dispara 5 vezes no mesmo Frame para garantir instakill
                for i = 1, 5 do 
                    remote:FireServer(posAlvo)
                end
            end
        elseif _G.PaintBallEnabled and _G.PaintSpam and (not _G.PaintTarget or not _G.PaintTarget.Parent) then
            stopPaintTarget()
            if type(S7xNotify) == "function" then S7xNotify("⚠️ ALVO PERDIDO", "O jogador saiu do mapa ou resetou.") end
        end
    end)
end)


-- ==========================================
-- [ MOTOR DE VFX ABSOLUTO E ÁUDIO 3D (CLICK TP) ]
-- ==========================================
_G.S7xTpEnabled = false
_G.S7xTpKeyHeld = false

-- Variável da tecla de Gatilho (Padrão: LeftControl)
bindKeys.TpTrigger = bindKeys.TpTrigger or Enum.KeyCode.LeftControl

local function toggleTp() 
    _G.S7xTpEnabled = not _G.S7xTpEnabled
    if type(setToggleState) == "function" then setToggleState(GUI.TpBtn, _G.S7xTpEnabled) end 
    
    if _G.S7xTpEnabled then
        if type(S7xNotify) == "function" then 
            local kToggle = bindKeys.Tp and bindKeys.Tp.Name or "UNBOUND"
            local kTrigger = bindKeys.TpTrigger and bindKeys.TpTrigger.Name or "LCTRL"
            S7xNotify("CLICK TP", "Armado! Segure [" .. kTrigger .. "] e clique para teleportar.")
        end
    else
        _G.S7xTpKeyHeld = false
        pcall(function()
            if _G.S7xTpChargeSound then _G.S7xTpChargeSound:Destroy(); _G.S7xTpChargeSound = nil end
        end)
    end
end
GUI.TpBtn.MouseButton1Click:Connect(toggleTp)

local function PlayTpEffect(pos)
    task.spawn(function()
        local anchor = Instance.new("Part")
        anchor.Transparency = 1
        anchor.Anchored = true
        anchor.CanCollide = false
        anchor.Size = Vector3.new(0.1, 0.1, 0.1)
        anchor.CFrame = CFrame.new(pos)
        anchor.Parent = workspace 
        
        local sfx = Instance.new("Sound")
        sfx.SoundId = "rbxassetid://138819213201245"
        sfx.Volume = 0.5 
        sfx.RollOffMode = Enum.RollOffMode.Linear 
        sfx.RollOffMinDistance = 15 
        sfx.RollOffMaxDistance = 100 
        sfx.Parent = anchor 
        sfx:Play()
        
        local att = Instance.new("Attachment", anchor)
        
        local function createLayer(textureId, sizeSeq, speed, emitCount, extraSetup)
            local pe = Instance.new("ParticleEmitter", att)
            pe.Texture = textureId
            pe.Color = ColorSequence.new(Color3.fromRGB(170, 0, 255)) 
            pe.LightEmission = 1 
            pe.LightInfluence = 0
            pe.ZOffset = 10 
            pe.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1)})
            pe.Size = sizeSeq
            pe.Speed = speed
            pe.Lifetime = NumberRange.new(0.4, 0.7)
            pe.EmissionDirection = Enum.NormalId.Top
            pe.Drag = 4
            pe.Enabled = false
            
            if extraSetup then extraSetup(pe) end
            pe:Emit(emitCount)
        end

        createLayer("rbxassetid://6660412891", NumberSequence.new({NumberSequenceKeypoint.new(0, 2), NumberSequenceKeypoint.new(1, 0)}), NumberRange.new(20, 35), 40, function(p) p.SpreadAngle = Vector2.new(360, 360) end)
        createLayer("rbxassetid://8047533775", NumberSequence.new({NumberSequenceKeypoint.new(0, 5), NumberSequenceKeypoint.new(1, 15)}), NumberRange.new(5, 10), 10, function(p) p.SpreadAngle = Vector2.new(360, 360); p.Orientation = Enum.ParticleOrientation.VelocityParallel end)
        createLayer("rbxassetid://8047796070", NumberSequence.new({NumberSequenceKeypoint.new(0, 6), NumberSequenceKeypoint.new(1, 0)}), NumberRange.new(15, 25), 15, function(p) p.SpreadAngle = Vector2.new(0, 0) end)
        
        game:GetService("Debris"):AddItem(anchor, 3)
    end)
end

-- Click TP Protegido (Custom Key + CLICK no PC ou TOUCH no Mobile)
_G.S7xConnections.TpClick = mouse.Button1Down:Connect(function() 
    if _G.S7xTpEnabled and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then 
        local uis = game:GetService("UserInputService")
        local isMobile = uis.TouchEnabled and not uis.KeyboardEnabled
        
        -- Busca a tecla que o usuário configurou, ou usa LeftControl por padrão
        local triggerKey = bindKeys.TpTrigger or Enum.KeyCode.LeftControl
        
        -- Condição: Dispositivo Mobile OU tecla customizada (TpTrigger) pressionada no PC
        if isMobile or uis:IsKeyDown(triggerKey) then
            local char = player.Character
            local hrp = char.HumanoidRootPart
            local targetPos = mouse.Hit.Position + Vector3.new(0, 3.8, 0) 
            
            if type(PlayTpEffect) == "function" then PlayTpEffect(hrp.Position) end 
            hrp.CFrame = CFrame.new(targetPos)
            if type(PlayTpEffect) == "function" then PlayTpEffect(targetPos) end    
        end
    end 
end)

-- Player Scanner Protegido
_G.S7xConnections.ScannerClick = mouse.Button1Down:Connect(function()
    if playerScannerActive then
        local target = mouse.Target
        if target and target.Parent and target.Parent:FindFirstChild("Humanoid") then
            local tPlayer = Players:GetPlayerFromCharacter(target.Parent)
            if tPlayer and tPlayer ~= player then
                showPlayerInfo(tPlayer)
            end
        end
    end
end)

-- Hitbox Rendering Protegido e Otimizado
local lastHitboxTick = 0
_G.S7xConnections.HitboxLoop = RunService.RenderStepped:Connect(function()
    if hitboxEnabled then
        local currentTick = tick()
        -- O SEGREDO: Atualiza o Hitbox a 30 FPS em vez de 60/144 FPS. 
        -- Ninguém nota a diferença visual, mas corta o uso de CPU pela metade.
        if currentTick - lastHitboxTick < 0.033 then return end 
        lastHitboxTick = currentTick

        local plrList = Players:GetPlayers()
        for i = 1, #plrList do
            local p = plrList[i]
            if p ~= player and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                if hrp and hrp.Size.X ~= hitboxSizeValue then -- Só aplica se o tamanho estiver errado (evita reescrever propriedades à toa)
                    hrp.Size = Vector3.new(hitboxSizeValue, hitboxSizeValue, hitboxSizeValue)
                    hrp.Transparency = hbTransp
                    hrp.BrickColor = BrickColor.new(Color3.fromRGB(hbR, hbG, hbB))
                    hrp.Material = Enum.Material.Neon
                    hrp.CanCollide = false
                end
            end
        end
    end
end)
-- Jump Power Protegido
_G.S7xConnections.JumpLoop = RunService.RenderStepped:Connect(function() 
    if jumpEnabled and player.Character and player.Character:FindFirstChild("Humanoid") then 
        player.Character.Humanoid.UseJumpPower = true
        player.Character.Humanoid.JumpPower = jumpPowerValue 
    end 
end)

-- Walk Speed Protegido
_G.S7xConnections.SpeedLoop = RunService.RenderStepped:Connect(function() 
    if speedEnabled and player.Character and player.Character:FindFirstChild("Humanoid") then 
        player.Character.Humanoid.WalkSpeed = walkSpeedValue 
    end 
end)
-----------------------------------------
--- SISTEMA DE ESP SUPREMO (AUTODETECT ROLES & ZERO LAG REAL)
-----------------------------------------
task.spawn(function()
    local espEnabled = false
    local espFolder = Instance.new("Folder", GUI.ScreenGui)
    espFolder.Name = "S7x_ESP_Folder"
    local espCooldown = false
    local roleCache = {}
    local friendCache = {} 

    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local function fetchPlayerRole(plr)
        if roleCache[plr.UserId] then return end
        roleCache[plr.UserId] = {role = "Loading...", color = Color3.fromRGB(255, 255, 255), hex = "#FFFFFF"}
        task.spawn(function()
            pcall(function() friendCache[plr.UserId] = LocalPlayer:IsFriendsWith(plr.UserId) end)
            local success, role = pcall(function() return plr:GetRoleInGroup(34157675) end)
            if success and role and role ~= "Guest" then
                local checkR = string.lower(role)
                if checkR == "member" or checkR == "members" then
                    roleCache[plr.UserId] = {role = "User", color = Color3.fromRGB(255, 255, 255), hex = "#FFFFFF"}
                    return
                end
                local c = Color3.fromRGB(255, 255, 255)
                local h = "#FFFFFF"
                if string.find(checkR, "influencer") then c = Color3.fromRGB(255, 20, 147); h = "#FF1493"
                elseif string.find(checkR, "contributor") then c = Color3.fromRGB(255, 100, 0); h = "#FF6400"
                elseif string.find(checkR, "marketing") or string.find(checkR, "social mod") or string.find(checkR, "helper") or string.find(checkR, "supervisor") or string.find(checkR, "manager") or string.find(checkR, "developer") or string.find(checkR, "owner") then 
                    c = Color3.fromRGB(255, 0, 0); h = "#FF0000"
                end
                roleCache[plr.UserId] = {role = role, color = c, hex = h}
            else
                roleCache[plr.UserId] = {role = "User", color = Color3.fromRGB(255, 255, 255), hex = "#FFFFFF"}
            end
        end)
    end

    for _, p in ipairs(Players:GetPlayers()) do if p ~= LocalPlayer then fetchPlayerRole(p) end end
    Players.PlayerAdded:Connect(function(p) fetchPlayerRole(p) end)
    Players.PlayerRemoving:Connect(function(p)
        roleCache[p.UserId] = nil; friendCache[p.UserId] = nil 
        if espFolder:FindFirstChild(p.Name) then espFolder[p.Name]:Destroy() end
    end)

    local function GetDynamicGameRole(plr)
            local foundRole = nil
            pcall(function()
                local ls = plr:FindFirstChild("leaderstats")
                if ls then
                    local roleNames = {"Role", "Cargo", "Rank", "Class", "Job", "Team", "Trabalho", "Profissao"}
                    for _, name in ipairs(roleNames) do
                        local val = ls:FindFirstChild(name)
                        if val and (val:IsA("StringValue") or val:IsA("ObjectValue")) and tostring(val.Value) ~= "" then
                            foundRole = tostring(val.Value); return
                        end
                    end
                end
                if not foundRole and plr.Team and plr.Team.Name ~= "Neutral" then foundRole = plr.Team.Name; return end
                if not foundRole and plr.Character then
                    local head = plr.Character:FindFirstChild("Head") or plr.Character:FindFirstChild("HumanoidRootPart")
                    if head then
                        for _, bb in ipairs(head:GetChildren()) do
                            if bb:IsA("BillboardGui") and bb.Name ~= "S7x_ProTag" and bb.Name ~= "Haki_" .. plr.Name then
                                for _, txt in ipairs(bb:GetDescendants()) do
                                    if txt:IsA("TextLabel") and txt.Text ~= "" and txt.Text ~= plr.Name and txt.Text ~= plr.DisplayName then
                                        local cleanText = string.gsub(string.gsub(txt.Text, "<[^>]+>", ""), "\n", " ")
                                        if not tonumber(cleanText) and string.len(cleanText) > 2 and string.len(cleanText) < 20 then
                                            foundRole = cleanText; return
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end)
            return foundRole
        end

        -- [ OTIMIZAÇÃO PRO: BACKGROUND ROLE CACHE ]
        -- Move a função super pesada que varre o corpo do player para uma thread morta que roda só a cada 3 segundos.
        task.spawn(function()
            while task.wait(3) do
                for _, plr in ipairs(Players:GetPlayers()) do
                    if roleCache[plr.UserId] then
                        roleCache[plr.UserId].gameRole = GetDynamicGameRole(plr)
                    end
                end
            end
        end)

        _G.S7xToggleESP = function()
            if espCooldown then return end
            espCooldown = true; espEnabled = not espEnabled
            if type(setToggleState) == "function" then setToggleState(GUI.EspBtn, espEnabled) end
            if not espEnabled then espFolder:ClearAllChildren() end
            task.delay(1, function() espCooldown = false end)
        end
        GUI.EspBtn.MouseButton1Click:Connect(_G.S7xToggleESP)

        task.spawn(function()
            while task.wait(0.1) do
                if not espEnabled then continue end
                local myChar = LocalPlayer.Character
                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                
                for _, v in ipairs(Players:GetPlayers()) do
                    if v ~= LocalPlayer then
                        local char = v.Character
                        local head = char and char:FindFirstChild("Head")
                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                        local hum = char and char:FindFirstChild("Humanoid")
                        
                        if char and head and hrp and hum and hum.Health > 0 then
                            local b = espFolder:FindFirstChild(v.Name)
                            local hl = espFolder:FindFirstChild(v.Name .. "_HL")
                            
                            if not b then
                                b = Instance.new("BillboardGui", espFolder)
                                b.Name = v.Name; b.Size = UDim2.new(0, 150, 0, 130); b.AlwaysOnTop = true; b.StudsOffset = Vector3.new(0, 1.8, 0); b.Active = true 
                                
                                local btnAvatar = Instance.new("ImageButton", b)
                                btnAvatar.Name = "AvatarBtn"; btnAvatar.Size = UDim2.new(0, 44, 0, 44); btnAvatar.Position = UDim2.new(0.5, -22, 0, 0); btnAvatar.BackgroundColor3 = Color3.fromRGB(15, 15, 20); btnAvatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. v.UserId .. "&w=150&h=150"; btnAvatar.AutoButtonColor = false
                                Instance.new("UICorner", btnAvatar).CornerRadius = UDim.new(1, 0)
                                local stroke = Instance.new("UIStroke", btnAvatar); stroke.Name = "Stroke"; stroke.Thickness = 2.5
                                
                                btnAvatar.MouseEnter:Connect(function() pcall(function() game:GetService("TweenService"):Create(btnAvatar, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Size = UDim2.new(0, 54, 0, 54), Position = UDim2.new(0.5, -27, 0, -5)}):Play() end) end)
                                btnAvatar.MouseLeave:Connect(function() pcall(function() game:GetService("TweenService"):Create(btnAvatar, TweenInfo.new(0.2, Enum.EasingStyle.Quint), {Size = UDim2.new(0, 44, 0, 44), Position = UDim2.new(0.5, -22, 0, 0)}):Play() end) end)
                                
                                local isHolding = false; local holdStartTick = 0; local holdTimeRequired = 0.5 
                                btnAvatar.InputBegan:Connect(function(input)
                                    if input.UserInputType.Name:find("MouseButton1") or input.UserInputType.Name:find("Touch") then
                                        isHolding = true; holdStartTick = tick()
                                        pcall(function() game:GetService("TweenService"):Create(stroke, TweenInfo.new(holdTimeRequired, Enum.EasingStyle.Linear), {Thickness = 5}):Play() end)
                                        task.spawn(function()
                                            while isHolding do
                                                if tick() - holdStartTick >= holdTimeRequired then
                                                    isHolding = false
                                                    pcall(function() if setclipboard then setclipboard("@" .. v.Name) end end)
                                                    if type(S7xNotify) == "function" then S7xNotify("USER COPIED", "Copied: @" .. v.Name) end
                                                    pcall(function() local ts = game:GetService("TweenService"); ts:Create(stroke, TweenInfo.new(0.2), {Thickness = 2.5}):Play(); ts:Create(btnAvatar, TweenInfo.new(0.15, Enum.EasingStyle.Bounce), {Size = UDim2.new(0, 44, 0, 44), Position = UDim2.new(0.5, -22, 0, 0)}):Play() end)
                                                    break
                                                end
                                                game:GetService("RunService").Heartbeat:Wait()
                                            end
                                        end)
                                    end
                                end)
                                btnAvatar.InputEnded:Connect(function(input)
                                    if input.UserInputType.Name:find("MouseButton1") or input.UserInputType.Name:find("Touch") then
                                        local heldDuration = tick() - holdStartTick; isHolding = false 
                                        pcall(function() game:GetService("TweenService"):Create(stroke, TweenInfo.new(0.2), {Thickness = 2.5}):Play() end)
                                        if heldDuration < holdTimeRequired then
                                            local mHrp = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                                            local tHrp = v.Character and v.Character:FindFirstChild("HumanoidRootPart")
                                            if mHrp and tHrp then mHrp.CFrame = tHrp.CFrame * CFrame.new(0, 0, 2) end
                                        end
                                    end
                                end)
                                
                                local lbl = Instance.new("TextLabel", b)
                                lbl.Name = "L"; lbl.Size = UDim2.new(1, 0, 0, 60); lbl.Position = UDim2.new(0, 0, 0, 48); lbl.BackgroundTransparency = 1; lbl.Font = Enum.Font.GothamBlack; lbl.TextSize = 12; lbl.RichText = true; lbl.TextYAlignment = Enum.TextYAlignment.Top
                                
                                local txtStroke = Instance.new("UIStroke", lbl)
                                txtStroke.Color = Color3.fromRGB(0, 0, 0)
                                txtStroke.Thickness = 1.5
                                txtStroke.Transparency = 0
                            end

                            if not hl then
                                hl = Instance.new("Highlight", espFolder)
                                hl.Name = v.Name .. "_HL"; hl.FillTransparency = 0.6; hl.OutlineTransparency = 0.1; hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                            end
                            
                            if b.Adornee ~= head then b.Adornee = head end
                            if hl.Adornee ~= char then hl.Adornee = char end
                            
                            local dist = myHrp and math.floor((myHrp.Position - hrp.Position).Magnitude) or 0
                            
                            if dist < (_G.S7xEspMinDistance or 40) then
                                if b.Enabled then b.Enabled = false end
                                if hl.Enabled then hl.Enabled = false end
                            else
                                if not b.Enabled then b.Enabled = true end
                                if not hl.Enabled then hl.Enabled = true end
                                
                                local s7xData = roleCache[v.UserId] or {role = "User", color = Color3.fromRGB(255,255,255), hex = "#FFFFFF", gameRole = nil}
                                local gameRole = s7xData.gameRole -- Puxado do cache leve
                                local isFriend = friendCache[v.UserId] or false
                                
                                -- [ OTIMIZAÇÃO DE PROPRIEDADES ]: Impede o envio inútil de dados pro Engine
                                local targetColor = isFriend and Color3.fromRGB(170, 0, 255) or s7xData.color
                                if hl.FillColor ~= targetColor then hl.FillColor = targetColor end
                                if hl.OutlineColor ~= Color3.fromRGB(255, 255, 255) then hl.OutlineColor = Color3.fromRGB(255, 255, 255) end

                                local btnAvatar = b:FindFirstChild("AvatarBtn")
                                local stroke = btnAvatar and btnAvatar:FindFirstChild("Stroke")
                                local lbl = b:FindFirstChild("L")

                                if btnAvatar and stroke and lbl then
                                    if stroke.Color ~= targetColor then stroke.Color = targetColor end
                                    
                                    -- [ OTIMIZAÇÃO TEXTUAL ]: O RichText só é recriado se a distância mudar matematicamente
                                    local currentRoleStr = (s7xData.role or "") .. (gameRole or "")
                                    local lastDist = b:GetAttribute("LastDist")
                                    local lastRoleStr = b:GetAttribute("LastRole")
                                    
                                    if lastDist ~= dist or lastRoleStr ~= currentRoleStr then
                                        b:SetAttribute("LastDist", dist)
                                        b:SetAttribute("LastRole", currentRoleStr)
                                        
                                        local roleText = ""
                                        if s7xData.role ~= "User" and s7xData.role ~= "Loading..." then roleText = roleText .. "<font color='"..s7xData.hex.."'>[" .. string.upper(s7xData.role) .. "]</font> " end
                                        if gameRole then roleText = roleText .. "<font color='#aaff00'>[" .. string.upper(gameRole) .. "]</font>" end
                                        if roleText == "" then roleText = "\n<font color='#aaaaaa'>[PLAYER]</font>" else roleText = "\n" .. roleText end
                                        local friendText = isFriend and " <font color='#aa00ff'>[FRIEND]</font>" or ""
                                        
                                        lbl.Text = string.format("<font color='#ffffff'>%s</font>%s\n<font size='10' color='#bbbbbb'>@%s</font>%s\n<font color='#00ffcc'>%dm</font>", v.DisplayName, friendText, v.Name, roleText, dist)
                                    end
                                end
                            end
                        else
                            local b = espFolder:FindFirstChild(v.Name)
                            local hl = espFolder:FindFirstChild(v.Name.."_HL")
                            if b then b:Destroy() end
                            if hl then hl:Destroy() end
                        end
                end
            end
        end
    end)
end)

