task.spawn(function()
    local targetTab = GUI.SysConfigFrame
    local ts = game:GetService("TweenService")
    local Lighting = game:GetService("Lighting")
    local Workspace = game:GetService("Workspace")

    -- Limpeza Profunda (Evita Duplicação de UI)
    targetTab:ClearAllChildren()
    for _, guiName in ipairs({"S7xKeybindsHUD", "S7xFPSOverlay"}) do
        local oldGui = game:GetService("CoreGui"):FindFirstChild(guiName)
        if oldGui then oldGui:Destroy() end
    end
    if _G.S7xStatusLoop then task.cancel(_G.S7xStatusLoop); _G.S7xStatusLoop = nil end
    if _G.S7xFpsLoopExt then _G.S7xFpsLoopExt:Disconnect(); _G.S7xFpsLoopExt = nil end

    local SysLayout = Instance.new("UIListLayout", targetTab)
    SysLayout.SortOrder = Enum.SortOrder.LayoutOrder
    SysLayout.Padding = UDim.new(0, 15)
    SysLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center

    local SysPadding = Instance.new("UIPadding", targetTab)
