    SysPadding.PaddingBottom = UDim.new(0, 30)

    SysLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        targetTab.CanvasSize = UDim2.new(0, 0, 0, SysLayout.AbsoluteContentSize.Y + 40)
    end)

    -- ==========================================
    -- MOTORES DE CRIAÇÃO (DESIGN PRETO E BRANCO)
    -- ==========================================
    local function createSectionCard(titleTxt, descTxt, layoutOrder)
