        desc.TextColor3 = Color3.fromRGB(150, 150, 150)
        desc.Font = Enum.Font.GothamMedium
        desc.TextSize = 10
        desc.TextXAlignment = Enum.TextXAlignment.Left

        local content = Instance.new("Frame", card)
        content.Size = UDim2.new(1, -20, 0, 10)
        content.Position = UDim2.new(0, 10, 0, 55)
        content.BackgroundTransparency = 1

        local layout = Instance.new("UIListLayout", content)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 8)
        
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            content.Size = UDim2.new(1, -20, 0, layout.AbsoluteContentSize.Y)
            card.Size = UDim2.new(0.95, 0, 0, layout.AbsoluteContentSize.Y + 70)
        end)

        return content
    end

    local function createGridToggle(parentGrid, text, defaultState, callback)
        local btn = Instance.new("TextButton", parentGrid)
        btn.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
        btn.Text = ""
        btn.AutoButtonColor = false
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
        Instance.new("UIStroke", btn).Color = Color3.fromRGB(80, 80, 80)

        local lbl = Instance.new("TextLabel", btn)
    lbl.Size = UDim2.new(1, -55, 1, 0) -- Limita o crescimento para não invadir a borda
