    -- Motor do Status HUD (Verifica quais botões estão ativados)
    if _G.S7xStatusLoop then task.cancel(_G.S7xStatusLoop); _G.S7xStatusLoop = nil end
    _G.S7xStatusLoop = task.spawn(function()
        local activeCache = {} 
        while task.wait(0.5) do
            if GUI.StatusHUD and GUI.StatusHUD.Visible then
                local currentActive = {}
                for _, frame in pairs(GUI.MainFrame:GetDescendants()) do
                    if frame:IsA("Frame") and (frame.Name == "SysToggleBG" or frame.Name == "ToggleBG") then
                        local knob = frame:FindFirstChild("SysToggleKnob") or frame:FindFirstChild("ToggleKnob")
                        if knob and (knob.Position.X.Offset > 10 or knob.Position.X.Scale > 0.5) then
                            local parentRow = frame.Parent
                            local titleLbl = parentRow:FindFirstChild("Title") or parentRow:FindFirstChildWhichIsA("TextLabel")
                            -- Filtra os próprios botões de configuração do HUD
                            if titleLbl and titleLbl.Text ~= "" and titleLbl.Text ~= "Show Key Status" and titleLbl.Text ~= "Streamer Mode" then
                                table.insert(currentActive, string.upper(titleLbl.Text))
                            end
                        end
                    end
                end
                
                local changed = false
                if #currentActive ~= #activeCache then changed = true else
                    for i, v in ipairs(currentActive) do if v ~= activeCache[i] then changed = true; break end end
                end

                if changed then
                    activeCache = currentActive
                    for _, v in pairs(GUI.StatusList:GetChildren()) do if v:IsA("Frame") then v:Destroy() end end
                    
                    for i, name in ipairs(currentActive) do
                        local item = Instance.new("Frame", GUI.StatusList)
                        item.Size = UDim2.new(1, -16, 0, 16)
                        item.Position = UDim2.new(0, 8, 0, 0)
                        item.BackgroundTransparency = 1
                        item.LayoutOrder = i
                        
                        local dot = Instance.new("Frame", item)
                        dot.Size = UDim2.new(0, 4, 0, 4)
                        dot.Position = UDim2.new(0, 5, 0.5, -2)
                        dot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                        Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
                        
                        local lbl = Instance.new("TextLabel", item)
                        lbl.Size = UDim2.new(1, -15, 1, 0)
                        lbl.Position = UDim2.new(0, 15, 0, 0)
                        lbl.BackgroundTransparency = 1
                        lbl.Text = name
                        lbl.TextColor3 = Color3.fromRGB(200, 200, 200)
                        lbl.Font = Enum.Font.GothamBold
                        lbl.TextSize = 10
                        lbl.TextXAlignment = Enum.TextXAlignment.Left
                    end
                end
            end
        end
    end)

