                extFpsGui.Name = "S7xFPSOverlay"
                local txt = Instance.new("TextLabel", extFpsGui)
                txt.Size = UDim2.new(0, 100, 0, 30); txt.Position = UDim2.new(0, 10, 0, 10)
                txt.BackgroundTransparency = 1; txt.TextColor3 = Color3.fromRGB(255, 255, 255)
                txt.Font = Enum.Font.GothamBlack; txt.TextSize = 14; txt.TextXAlignment = Enum.TextXAlignment.Left
                local rs = game:GetService("RunService")
                local frames, last = 0, tick()
                _G.S7xFpsLoopExt = rs.RenderStepped:Connect(function()
                    frames = frames + 1
                    local now = tick()
                    if now - last >= 1 then
                        txt.Text = "FPS: " .. frames
                        frames = 0; last = now
                    end
                end)
            end
        else
            if extFpsGui then extFpsGui:Destroy(); extFpsGui = nil end
            if _G.S7xFpsLoopExt then _G.S7xFpsLoopExt:Disconnect(); _G.S7xFpsLoopExt = nil end
        end
