    local Shaders = { "1 - Original", "2 - Sunset", "3 - Cold Blue", "4 - Emerald", "5 - Rose", "6 - Dream", "7 - Monochrome", "8 - Midnight" }

    local function ApplyShaderPreset(name)
        if type(_G.S7xClearAllShaders) == "function" then _G.S7xClearAllShaders() end
        local CC = Instance.new("ColorCorrectionEffect", Lighting)
        CC.Name = "S7x_CustomCC"
        
        if name == "1 - Original" then
            CC:Destroy(); Lighting.ClockTime = 14
        elseif name == "2 - Sunset" then
            Lighting.ClockTime = 17.5; CC.TintColor = Color3.fromRGB(255, 200, 180); CC.Saturation = 0.2
        elseif name == "3 - Cold Blue" then
            Lighting.ClockTime = 6; CC.TintColor = Color3.fromRGB(180, 220, 255); CC.Contrast = 0.1
        elseif name == "4 - Emerald" then
            CC.TintColor = Color3.fromRGB(180, 255, 200); CC.Saturation = 0.3
        elseif name == "5 - Rose" then
            CC.TintColor = Color3.fromRGB(255, 180, 210); CC.Saturation = 0.25
        elseif name == "6 - Dream" then
            CC.TintColor = Color3.fromRGB(230, 200, 255); CC.Saturation = 0.4; CC.Contrast = -0.1
            local B = Instance.new("BloomEffect", Lighting); B.Intensity = 0.8; B.Size = 24
        elseif name == "7 - Monochrome" then
            CC.Saturation = -1; CC.Contrast = 0.3
        elseif name == "8 - Midnight" then
            Lighting.ClockTime = 0; CC.TintColor = Color3.fromRGB(120, 140, 220); CC.Contrast = 0.1
        end
    end

