    createGridToggle(gfxGrid, "Cinematic Fog", false, function(state)
        if state then Lighting.FogEnd = 250; Lighting.FogStart = 20; Lighting.FogColor = Color3.fromRGB(15, 20, 30) else Lighting.FogEnd = 100000; Lighting.FogColor = Color3.fromRGB(192, 192, 192) end
    end)
    createGridToggle(gfxGrid, "Low Graphics", false, function(state) settings().Rendering.QualityLevel = state and 1 or Enum.QualityLevel.Automatic end)
    createGridToggle(gfxGrid, "Better Reflections", false, function(state)
