-- ==========================================
-- SISTEMA WAYPOINT MANAGER (MULTI-GAME SAVES)
-- ==========================================
task.spawn(function()
    local HttpService = game:GetService("HttpService")
    local WP_FILENAME = "S7x_Waypoints.json"
    local CurrentPlace = tostring(game.PlaceId)
    local SavedWaypoints = {}

    -- 1. Carregar dados salvos do JSON (Protegido por pcall)
    pcall(function()
        if readfile and isfile and isfile(WP_FILENAME) then
            local decoded = HttpService:JSONDecode(readfile(WP_FILENAME))
            if type(decoded) == "table" then
                SavedWaypoints = decoded
            end
        end
    end)
    -- Garante que a tabela do jogo atual exista
    if not SavedWaypoints[CurrentPlace] then SavedWaypoints[CurrentPlace] = {} end

    local function SaveWPData()
        pcall(function()
            if writefile then
                writefile(WP_FILENAME, HttpService:JSONEncode(SavedWaypoints))
            end
        end)
    end

    -- 2. Criação da Interface Flutuante S7x Premium
    local WP_UI = Instance.new("Frame", GUI.ScreenGui)
    WP_UI.Name = "S7xWaypointManager"
    WP_UI.Size = UDim2.new(0, 360, 0, 280)
    WP_UI.Position = UDim2.new(0.5, -180, 0.5, -140)
    WP_UI.BackgroundColor3 = Color3.fromRGB(16, 16, 20)
    WP_UI.Visible = false
    WP_UI.Active = true
    WP_UI.Draggable = true
    Instance.new("UICorner", WP_UI).CornerRadius = UDim.new(0, 10)
    
    local wpStroke = Instance.new("UIStroke", WP_UI)
    wpStroke.Color = Color3.fromRGB(170, 0, 255)
    wpStroke.Thickness = 1.5

    -- Header do Painel
    local headerWP = Instance.new("Frame", WP_UI)
    headerWP.Size = UDim2.new(1, 0, 0, 40)
    headerWP.BackgroundTransparency = 1
    
    local titleWP = Instance.new("TextLabel", headerWP)
    titleWP.Size = UDim2.new(1, -40, 1, 0)
    titleWP.Position = UDim2.new(0, 15, 0, 0)
    titleWP.BackgroundTransparency = 1
    titleWP.Text = "📍 WAYPOINT MANAGER"
    titleWP.TextColor3 = Color3.fromRGB(255, 255, 255)
    titleWP.Font = Enum.Font.GothamBlack
    titleWP.TextSize = 14
    titleWP.TextXAlignment = Enum.TextXAlignment.Left

    local closeWP = Instance.new("TextButton", headerWP)
    closeWP.Size = UDim2.new(0, 30, 0, 30)
    closeWP.Position = UDim2.new(1, -35, 0.5, -15)
    closeWP.BackgroundTransparency = 1
    closeWP.Text = "X"
    closeWP.TextColor3 = Color3.fromRGB(255, 50, 50)
    closeWP.Font = Enum.Font.GothamBold
    closeWP.TextSize = 14
    closeWP.MouseButton1Click:Connect(function() WP_UI.Visible = false end)

    -- Área de Criação de Novo Waypoint
    local inputArea = Instance.new("Frame", WP_UI)
    inputArea.Size = UDim2.new(1, -20, 0, 40)
    inputArea.Position = UDim2.new(0, 10, 0, 45)
    inputArea.BackgroundTransparency = 1

    local nameInput = Instance.new("TextBox", inputArea)
    nameInput.Size = UDim2.new(0.65, 0, 1, 0)
    nameInput.BackgroundColor3 = Color3.fromRGB(25, 25, 30)
    nameInput.TextColor3 = Color3.fromRGB(255, 255, 255)
    nameInput.PlaceholderText = "Location Name..."
    nameInput.Font = Enum.Font.GothamMedium
    nameInput.TextSize = 11
    nameInput.Text = ""
    Instance.new("UICorner", nameInput).CornerRadius = UDim.new(0, 6)
    Instance.new("UIStroke", nameInput).Color = Color3.fromRGB(50, 50, 60)

    local savePosBtn = Instance.new("TextButton", inputArea)
    savePosBtn.Size = UDim2.new(0.32, 0, 1, 0)
    savePosBtn.Position = UDim2.new(0.68, 0, 0, 0)
    savePosBtn.BackgroundColor3 = Color3.fromRGB(140, 0, 255)
    savePosBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    savePosBtn.Text = "SAVE POS"
    savePosBtn.Font = Enum.Font.GothamBold
    savePosBtn.TextSize = 11
    Instance.new("UICorner", savePosBtn).CornerRadius = UDim.new(0, 6)

    -- Lista de Localizações Salvas
    local wpList = Instance.new("ScrollingFrame", WP_UI)
    wpList.Size = UDim2.new(1, -20, 1, -105)
    wpList.Position = UDim2.new(0, 10, 0, 95)
    wpList.BackgroundTransparency = 1
    wpList.ScrollBarThickness = 2
    wpList.ScrollBarImageColor3 = Color3.fromRGB(170, 0, 255)
    
    local wpLayout = Instance.new("UIListLayout", wpList)
    wpLayout.Padding = UDim.new(0, 6)

    -- 3. Lógica de Renderização e Interação
    local function RenderWaypoints()
        for _, v in pairs(wpList:GetChildren()) do
            if v:IsA("Frame") then v:Destroy() end
        end
        
        local count = 0
        for wpName, coords in pairs(SavedWaypoints[CurrentPlace]) do
            count = count + 1
            local item = Instance.new("Frame", wpList)
            item.Size = UDim2.new(1, -10, 0, 35)
            item.BackgroundColor3 = Color3.fromRGB(22, 22, 26)
            Instance.new("UICorner", item).CornerRadius = UDim.new(0, 6)
            Instance.new("UIStroke", item).Color = Color3.fromRGB(45, 45, 55)

            local lbl = Instance.new("TextLabel", item)
            lbl.Size = UDim2.new(0.6, 0, 1, 0)
            lbl.Position = UDim2.new(0, 10, 0, 0)
            lbl.BackgroundTransparency = 1
            lbl.Text = wpName
            lbl.TextColor3 = Color3.fromRGB(220, 220, 220)
            lbl.Font = Enum.Font.GothamBold
            lbl.TextSize = 11
            lbl.TextXAlignment = Enum.TextXAlignment.Left

            -- Botão de Teleporte
            local tpBtn = Instance.new("TextButton", item)
            tpBtn.Size = UDim2.new(0, 50, 0, 25)
            tpBtn.Position = UDim2.new(1, -85, 0.5, -12.5)
            tpBtn.BackgroundColor3 = Color3.fromRGB(35, 35, 45)
            tpBtn.TextColor3 = Color3.fromRGB(0, 255, 150)
            tpBtn.Text = "TP"
            tpBtn.Font = Enum.Font.GothamBold
            tpBtn.TextSize = 10
            Instance.new("UICorner", tpBtn).CornerRadius = UDim.new(0, 4)
            
            tpBtn.MouseButton1Click:Connect(function()
                local hrp = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    -- Usa as coordenadas exatas mantendo a rotação
                    hrp.CFrame = CFrame.new(coords.X, coords.Y, coords.Z)
                    if type(S7xNotify) == "function" then S7xNotify("TELEPORTED", "Moved to: " .. wpName) end
                    pcall(function()
                        local sfx = Instance.new("Sound", workspace)
                        sfx.SoundId = "rbxassetid://138819213201245"
                        sfx.Volume = 0.5; sfx:Play()
                        game:GetService("Debris"):AddItem(sfx, 2)
                    end)
                end
            end)

            -- Botão de Exclusão
            local delBtn = Instance.new("TextButton", item)
            delBtn.Size = UDim2.new(0, 25, 0, 25)
            delBtn.Position = UDim2.new(1, -30, 0.5, -12.5)
            delBtn.BackgroundColor3 = Color3.fromRGB(35, 20, 25)
            delBtn.TextColor3 = Color3.fromRGB(255, 80, 80)
            delBtn.Text = "X"
            delBtn.Font = Enum.Font.GothamBold
            delBtn.TextSize = 11
            Instance.new("UICorner", delBtn).CornerRadius = UDim.new(0, 4)

            delBtn.MouseButton1Click:Connect(function()
                SavedWaypoints[CurrentPlace][wpName] = nil
                SaveWPData()
                RenderWaypoints()
            end)
        end
        wpList.CanvasSize = UDim2.new(0, 0, 0, count * 41)
    end

    savePosBtn.MouseButton1Click:Connect(function()
        local name = nameInput.Text
        if name == "" or string.match(name, "^%s*$") then 
            if type(S7xNotify) == "function" then S7xNotify("ERROR", "Invalid Waypoint Name.") end
            return 
        end
        
        local hrp = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if hrp then
            local pos = hrp.Position
            SavedWaypoints[CurrentPlace][name] = {X = pos.X, Y = pos.Y, Z = pos.Z}
            SaveWPData()
            nameInput.Text = ""
            RenderWaypoints()
            if type(S7xNotify) == "function" then S7xNotify("SAVED", "Waypoint '" .. name .. "' saved.") end
        end
    end)

    -- Gatilho do Botão da Aba Principal
    if GUI.WaypointBtn then
        GUI.WaypointBtn.MouseButton1Click:Connect(function()
            WP_UI.Visible = not WP_UI.Visible
            if WP_UI.Visible then RenderWaypoints() end
        end)
    end
end)

