    local function CheckHierarchy(targetRole)
        local myRank = "User"
        pcall(function() if type(GetFirebaseRank) == "function" then myRank = GetFirebaseRank(game.Players.LocalPlayer) or "User" end end)
        
        local RoleWeights = { 
            ["User"]=0, ["Member"]=5, ["Tester"]=10, ["Friends"]=15, 
            ["Influencer"]=20, ["Booster"]=25, ["Ultimate"]=30, ["Supreme"]=40, 
            ["Helper"]=50, ["Contributor"]=60, ["Marketing"]=65, ["Designer"]=70, 
            ["Supervisor"]=80, ["Manager"]=90, ["Developer"]=95, ["Dev"]=95, 
            ["Co-Owner"]=99, ["Owner"]=100, ["Creator"]=100 
        }
        
        local myWeight = RoleWeights[myRank] or 0
        local targetWeight = RoleWeights[targetRole] or 0
        
        if myWeight >= 100 then return true end
        if myWeight <= targetWeight then
            if type(S7xNotify) == "function" then S7xNotify("HIERARCHY ERROR", "Acesso negado sobre " .. string.upper(tostring(targetRole))) end
            return false
        end
        return true
    end

