        local query = searchInput.Text:gsub("%s+", "")
        if query == "" then return end
        
        searchBtn.Text = "..."
        task.spawn(function()
            local uid = query
            local tname = query
            
            if not tonumber(uid) then
                if string.sub(uid, 1, 1) == "@" then uid = string.sub(uid, 2) end
                tname = uid
                local success, res = pcall(function() return Players:GetUserIdFromNameAsync(uid) end)
                if success and res then uid = tostring(res) else uid = nil end
            else
                local success, res = pcall(function() return Players:GetNameFromUserIdAsync(tonumber(uid)) end)
                if success and res then tname = res end
            end

            if uid then
                targetUid = uid
                targetName = tname
                
                local res = _G.SupabaseReq("/users?id=eq." .. uid, "GET")
                targetRole = "User"
                if res and res.Body then
                    local dec = HttpService:JSONDecode(res.Body)
                    if type(dec) == "table" and #dec > 0 then
                        targetRole = dec[1].role or "User"
                    end
                end
                
                local resTag = _G.SupabaseReq("/tags?id=eq." .. uid, "GET")
                if resTag and resTag.Body then
                    local decTag = HttpService:JSONDecode(resTag.Body)
                    if type(decTag) == "table" and #decTag > 0 then
                        local payload = decTag[1].payload
                        if type(payload) == "string" then pcall(function() payload = HttpService:JSONDecode(payload) end) end
                        if type(payload) == "table" then
                            ctName.Text = payload.CustomName or ""
                            ctFont.Text = payload.Font or ""
                            ctEffect.Text = payload.Effect or ""
                            c1.Text = payload.Color1 or payload.Color or ""
                            c2.Text = payload.Color2 or ""
                            c3.Text = payload.Color3 or ""
                            c4.Text = payload.Color4 or ""
                            c5.Text = payload.Color5 or ""
                            cS.Text = payload.StrokeColor or ""
                        end
                    else
                        ctName.Text = ""; ctFont.Text = ""; ctEffect.Text = ""; c1.Text = ""; c2.Text = ""; c3.Text = ""; c4.Text = ""; c5.Text = ""; cS.Text = ""
                    end
                end

                RefreshTargetCard()
            else
                if type(S7xNotify) == "function" then S7xNotify("ERROR", "Usuário não encontrado.") end
            end
            searchBtn.Text = "SEARCH"
        end)
    end)

