    end)

    crmBtn.MouseButton1Click:Connect(function()
        local r = roleInput.Text
        if r == "" then return end
        
        crmBtn.Text = "..."
        task.spawn(function()
            _G.SupabaseReq("/users?id=eq." .. targetUid, "PATCH", { role = r })
            
            if tempInput.Visible and tempInput.Text ~= "" then
                local days = tonumber(tempInput.Text)
                if days then
                    local expTime = os.time() + (days * 86400)
                    local curPayload = {}
                    local resTag = _G.SupabaseReq("/tags?id=eq." .. targetUid, "GET")
                    if resTag and resTag.Body then
                        local dec = HttpService:JSONDecode(resTag.Body)
                        if type(dec) == "table" and #dec > 0 then
                            local p = dec[1].payload
                            if type(p) == "string" then pcall(function() p = HttpService:JSONDecode(p) end) end
                            if type(p) == "table" then curPayload = p end
                        end
                    end
                    curPayload.role_expire = expTime
                    curPayload.temp_role = r
                    _G.SupabaseReq("/tags?on_conflict=id", "POST", { id = targetUid, payload = curPayload })
                end
            else
                local curPayload = {}
                local resTag = _G.SupabaseReq("/tags?id=eq." .. targetUid, "GET")
                if resTag and resTag.Body then
                    local dec = HttpService:JSONDecode(resTag.Body)
                    if type(dec) == "table" and #dec > 0 then
                        local p = dec[1].payload
                        if type(p) == "string" then pcall(function() p = HttpService:JSONDecode(p) end) end
                        if type(p) == "table" then curPayload = p end
                    end
                end
                curPayload.role_expire = nil
                curPayload.temp_role = nil
                _G.SupabaseReq("/tags?on_conflict=id", "POST", { id = targetUid, payload = curPayload })
            end
            
            targetRole = r
            RefreshTargetCard()
            ModalOverlay.Visible = false
            crmBtn.Text = "CONFIRM"
            if type(S7xNotify) == "function" then S7xNotify("DATABASE", "Cargo atualizado via Supabase!") end
        end)
    end)

