            if tgtPlayer then
                if tgtPlayer.Character and tgtPlayer.Character:FindFirstChild("HumanoidRootPart") then
                    local tgtHrp = tgtPlayer.Character.HumanoidRootPart
                    myHrp.AssemblyLinearVelocity = Vector3.zero
                    pcall(function() 
                        local sfx = Instance.new("Sound", workspace)
                        sfx.SoundId = "rbxassetid://138819213201245"
