    GUI.LoadAdminPlayers = function()
        if refLbl.Text == "SCANNING..." then return end
        refLbl.Text = "SCANNING..."
        for _, v in pairs(GUI.AdminListContainer:GetChildren()) do
            if v:IsA("Frame") or v:IsA("TextButton") then v:Destroy() end
        end
        task.spawn(function()
            local res = _G.SupabaseReq("/presence?select=id,payload", "GET")
            if res and res.Body then
                local decoded = game:GetService("HttpService"):JSONDecode(res.Body)
                if type(decoded) == "table" and not decoded.error then
                    local currentTime = os.time()
                    for _, row in ipairs(decoded) do
                        local payload = row.payload
                        if type(payload) == "string" then pcall(function() payload = game:GetService("HttpService"):JSONDecode(payload) end) end
                        
                        if type(payload) == "table" then
                            local uid = tonumber(row.id)
                            local lastSeen = payload.Time or payload.t or 0
                            if (currentTime - lastSeen) <= 300 then
                                local s, username = pcall(function() return game:GetService("Players"):GetNameFromUserIdAsync(uid) end)
                                if not s then username = "Unknown" end
                                local tag = payload.Tag or payload.tg or "User"
                                local jobId = payload.job_id or payload.j or "Unknown"
                                GUI.RenderAdminPlayerCard(uid, username, jobId, tag)
                            end
                        end
                    end
                end
            end
            refLbl.Text = "SCAN S7X NETWORK"
        end)
    end

    GUI.RefreshAdminBtn.MouseButton1Click:Connect(GUI.LoadAdminPlayers)
    
    while task.wait(5) do
        pcall(function()
            local rank = "User"
            if type(GetFirebaseRank) == "function" then rank = GetFirebaseRank(game.Players.LocalPlayer) or "User" end
            local canSeeAdmin = { ["Supervisor"] = true, ["Co-Owner"] = true, ["Owner"] = true, ["Creator"] = true }
            if GUI.AdminTabBtn then GUI.AdminTabBtn.Visible = canSeeAdmin[rank] or false end
        end)
    end
end)


