if _G.S7xKeybindConnection then 
    _G.S7xKeybindConnection:Disconnect() 
    _G.S7xKeybindConnection = nil 
end

_G.S7xKeybindConnection = game:GetService("UserInputService").InputBegan:Connect(function(i, p)
    if p then return end
    -- [ BLOQUEIO DE SEGURANÇA ]: Impede as teclas de funcionarem antes do painel carregar
    if not _G.S7xIsFullyLoaded then return end
    
    if bindKeys.PanelToggle and i.KeyCode == bindKeys.PanelToggle then
        if type(togglePanel) == "function" then togglePanel() end 
    end

    if bindKeys.Feflip and i.KeyCode == bindKeys.Feflip then
        if _G.FeflipEnabled then
            _G.FeflipExecuting = true
        else
            if type(S7xNotify) == "function" then S7xNotify("FE FLIP", "Ative o módulo FeFlip no painel primeiro!") end
        end
    end

    -- ==========================================
-- MOTOR DE PARADA (HOTKEYS RELEASE)
-- ==========================================
if _G.S7xKeybindConnectionEnd then 
    _G.S7xKeybindConnectionEnd:Disconnect() 
    _G.S7xKeybindConnectionEnd = nil 
end

_G.S7xKeybindConnectionEnd = game:GetService("UserInputService").InputEnded:Connect(function(i, p)
    if p then return end
    if not _G.S7xIsFullyLoaded then return end

    -- Para de girar imediatamente quando o jogador solta a tecla
    if bindKeys.Feflip and i.KeyCode == bindKeys.Feflip then
        _G.FeflipExecuting = false
    end
end)

    if bindKeys.Gravity and i.KeyCode == bindKeys.Gravity then 
        if type(_G.S7xToggleGravity) == "function" then _G.S7xToggleGravity() end 
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Gravity toggled") end
    end

    if bindKeys.Banget and i.KeyCode == bindKeys.Banget then
        if type(_G.S7xToggleBanget) == "function" then _G.S7xToggleBanget() end
    end

    -- [ FIX: GATILHO DO WALK ON AIR ]
    if bindKeys.WalkOnAir and i.KeyCode == bindKeys.WalkOnAir then
        if type(_G.S7xToggleWalkOnAir) == "function" then 
            _G.S7xToggleWalkOnAir() 
            if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Walk On Air toggled") end
        end
    end

    if bindKeys.Facebang and i.KeyCode == bindKeys.Facebang then
        if type(_G.S7xToggleFacebang) == "function" then _G.S7xToggleFacebang() end
    end

    if bindKeys.Banget and i.KeyCode == bindKeys.Banget then
        if type(_G.S7xToggleBanget) == "function" then _G.S7xToggleBanget() end
    end


    if bindKeys.AntiFlingV2 and i.KeyCode == bindKeys.AntiFlingV2 then
        if type(_G.ToggleAntiFlingV2) == "function" then _G.ToggleAntiFlingV2() end
    end
    
    if bindKeys.Esp and i.KeyCode == bindKeys.Esp then 
        if type(_G.S7xToggleESP) == "function" then _G.S7xToggleESP() end
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "ESP toggled") end
    end
    
    if bindKeys.Tp and i.KeyCode == bindKeys.Tp then 
    if type(toggleTp) == "function" then toggleTp() end
    if _G.S7xTpEnabled and type(S7xNotify) == "function" then 
        S7xNotify("CLICK TP ARMED", "Hold CTRL + Click to TP (PC) | Tap to TP (Mobile)\nSegure CTRL + Clique (PC) | Toque na tela (Mobile)") 
    end
end

    if bindKeys.Flashback and i.KeyCode == bindKeys.Flashback then 
        if type(triggerFlashback) == "function" then triggerFlashback() end
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Flashback Rewind Triggered") end
    end
    
    -- [ FIX ]: Atalho para o Target Fling (Aba Specter)
    if bindKeys.TargetFling and i.KeyCode == bindKeys.TargetFling then
