    end
    
    if bindKeys.Invisible and i.KeyCode == bindKeys.Invisible then
        if type(ToggleInvisibility) == "function" then ToggleInvisibility() end
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Ghost Mode toggled") end
    end

    if bindKeys.FlingAura and i.KeyCode == bindKeys.FlingAura then
        _G.FlingAuraEnabled = not _G.FlingAuraEnabled
        pcall(function() if setToggleState then setToggleState(GUI.FlingAuraBtn, _G.FlingAuraEnabled) end end)
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Fling Aura toggled") end
    end

