        if type(_G.ToggleStreamerMode) == "function" then _G.ToggleStreamerMode() end
    end

    if bindKeys.Jitter and i.KeyCode == bindKeys.Jitter then
        _G.JitterEnabled = not _G.JitterEnabled
        pcall(function() if setToggleState then setToggleState(GUI.JitterBtn, _G.JitterEnabled) end end)
    end
    
    if bindKeys.Dash and i.KeyCode == bindKeys.Dash then
        if type(_G.S7xTriggerDash) == "function" then _G.S7xTriggerDash() end
    end
    
    if bindKeys.Fly and i.KeyCode == bindKeys.Fly then 
        if type(_G.S7xToggleFly) == "function" then _G.S7xToggleFly() end 
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Fly toggled") end
    end

    if bindKeys.Speed and i.KeyCode == bindKeys.Speed then 
        if type(_G.S7xToggleSpeed) == "function" then _G.S7xToggleSpeed() end 
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Speed toggled") end
    end
    
    if bindKeys.Jump and i.KeyCode == bindKeys.Jump then 
        if type(_G.S7xToggleJump) == "function" then _G.S7xToggleJump() end 
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Jump toggled") end
    end
    if bindKeys.Noclip and i.KeyCode == bindKeys.Noclip then 
        if type(_G.S7xToggleNoclip) == "function" then _G.S7xToggleNoclip() end 
        if type(S7xNotify) == "function" then S7xNotify("HOTKEY ACTIVATED", "Noclip toggled") end
    end
    local isUltimateAccess = true
    if type(_G.hasUltimateAccess) == "function" then
        isUltimateAccess = _G.hasUltimateAccess(game.Players.LocalPlayer)
    end

    if isUltimateAccess then
        if bindKeys.AntiFling and i.KeyCode == bindKeys.AntiFling then 
            if type(_G.S7xToggleAntiFling) == "function" then _G.S7xToggleAntiFling() end 
        end
        if bindKeys.Fling and i.KeyCode == bindKeys.Fling then 
            if type(_G.S7xToggleTouchFling) == "function" then _G.S7xToggleTouchFling() end 
        end
        if bindKeys.Spam and i.KeyCode == bindKeys.Spam then 
            if type(_G.toggleSpamEgg) == "function" then _G.toggleSpamEgg() end
        end
    end

    if bindKeys.Haki and i.KeyCode == bindKeys.Haki then
        if GUI.HakiBtn and GUI.HakiBtn.MouseButton1Click then GUI.HakiBtn.MouseButton1Click:Fire() end
    end
    -- [ FIX PROFISSIONAL ]: HOTKEY DA LETRA P ABSOLUTA (REMOTE FLING)
    if i.KeyCode == Enum.KeyCode.P then 
        if _G.RemoteFlingData and _G.RemoteFlingData.ativo then 
            if type(_G.TogglePTarget) == "function" then _G.TogglePTarget() end 
            local lockStatus = _G.RemoteFlingData.alvo and "LOCKED: " .. _G.RemoteFlingData.alvo.Name or "UNLOCKED"
            if type(S7xNotify) == "function" then S7xNotify("REMOTE FLING", lockStatus) end
        end
    end
end)

-- =========================================================================
-- 🛡️ MOTOR DE PERSISTÊNCIA VISUAL E BOOTSTRAPPER (ANTI-SKIN BUG FIX)
-- =========================================================================
task.spawn(function()
    -- 1. Hook para quando a skin e acessórios terminarem de carregar
    local function SetupCharacterPersistence(plr)
        -- Tenta aplicar assim que o boneco nasce (R15 inicial)
        plr.CharacterAdded:Connect(function(char)
            task.delay(0.5, function() 
                if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(plr) end
                if type(ApplyS7xAura) == "function" then ApplyS7xAura(plr) end
            end)
        end)
        
        -- O SEGREDO: Aplica DE NOVO quando a Skin termina de carregar.
        -- Muitos jogos (ou o catálogo) destroem e reconstroem o Head quando a skin é equipada.
        plr.CharacterAppearanceLoaded:Connect(function(char)
            task.delay(0.2, function()
                if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(plr) end
                if type(ApplyS7xAura) == "function" then ApplyS7xAura(plr) end
            end)
        end)
    end

    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
        SetupCharacterPersistence(p)
    end

    game:GetService("Players").PlayerAdded:Connect(function(p)
        SetupCharacterPersistence(p)
    end)
    
    -- 2. DAEMON DE BLINDAGEM CONTÍNUA (Garante que a tag NUNCA suma da cabeça)
    if _G.S7xTagPersistenceDaemon then task.cancel(_G.S7xTagPersistenceDaemon) end
    _G.S7xTagPersistenceDaemon = task.spawn(function()
        while task.wait(1.5) do
            pcall(function()
                if not _G.S7xTagVisible then return end
                
                for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                    local char = p.Character
                    if char then
                        local hum = char:FindFirstChild("Humanoid")
                        if hum and hum.Health > 0 then
                            local head = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
                            if head then
                                local tag = head:FindFirstChild("S7x_ProTag")
                                
                                -- Se o Roblox destruiu a tag sem permissão (trocando skin ou caindo o chapéu)
                                if not tag then
                                    if p == game.Players.LocalPlayer then
                                        -- Só aplica se o Hide Tags não estiver ligado
                                        if _G.MyTagPublic ~= false then
                                            if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(p) end
                                        end
                                    else
                                        -- Pros outros players, só aplica se estiverem no radar de presença
                                        local isActiveUser = (_G.S7xUsers and _G.S7xUsers[p.UserId]) or (_G.PresenceTags and _G.PresenceTags[p.UserId])
                                        if isActiveUser then
                                            if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(p) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end)
        end
    end)
end)

-- =========================================================================
-- 🛑 INICIALIZADOR SUPREMO & BOTÕES EXTRAS (ESCOPO ISOLADO) 🛑
-- =========================================================================
task.spawn(function()
    local char = game.Players.LocalPlayer.Character or game.Players.LocalPlayer.CharacterAdded:Wait()
    char:WaitForChild("HumanoidRootPart", 5)

    if type(UpdateSupabase) == "function" then
        UpdateSupabase()
        task.wait(0.2) 
    end

