            local myRank = (type(GetFirebaseRank) == "function" and GetFirebaseRank(game.Players.LocalPlayer)) or "User"
            local isMaster = (myRank == "Owner" or myRank == "Supreme" or myRank == "Developer" or myRank == "Co-Owner" or myRank == "Creator")
            
