task.spawn(function()
    local player = game:GetService("Players").LocalPlayer
    local uis = game:GetService("UserInputService")
    local rs = game:GetService("RunService")
    local ts = game:GetService("TweenService")
    local coreGui = game:GetService("CoreGui")
    local isMobile = uis.TouchEnabled and not uis.KeyboardEnabled

    -- [ 1. CRIAÇÃO DO CURSOR CUSTOMIZADO S7X ]
    if GUI.CustomCursor then GUI.CustomCursor:Destroy() end
    
    GUI.CustomCursor = Instance.new("ImageLabel", GUI.ScreenGui)
    GUI.CustomCursor.Name = "S7x_Cursor"
    GUI.CustomCursor.Size = UDim2.new(0, 50, 0, 50)
    GUI.CustomCursor.BackgroundTransparency = 1
    
    -- Inicia validando o JSON. Se não houver nada salvo, o padrão é "Default" (Nativo do usuário)
    _G.S7xCurrentCursor = _G.S7xCurrentCursor or "Default"
    if _G.S7xCurrentCursor ~= "Default" then
        GUI.CustomCursor.Image = "rbxassetid://" .. _G.S7xCurrentCursor
    end
    
    GUI.CustomCursor.ZIndex = 99999999
    GUI.CustomCursor.Visible = false
    GUI.CustomCursor.AnchorPoint = Vector2.new(0.5, 0.5) 

    local cursorScale = Instance.new("UIScale", GUI.CustomCursor)
    cursorScale.Scale = 1

    -- [ 2. LÓGICA DE RASTREAMENTO INTELIGENTE (NATIVE MOUSE FIX) ]
    local function isHovering(element, mousePos)
        if not element or not element.Visible then return false end
        local pos = element.AbsolutePosition
        local size = element.AbsoluteSize
        local inset = game:GetService("GuiService"):GetGuiInset()
        local myY = mousePos.Y - inset.Y
        return (mousePos.X >= pos.X and mousePos.X <= pos.X + size.X and
                myY >= pos.Y and myY <= pos.Y + size.Y)
    end

    local cursorStateActive = false
    local isRobloxMenuOpen = false

    game:GetService("GuiService").MenuOpened:Connect(function()
        isRobloxMenuOpen = true
        cursorStateActive = false
        uis.MouseIconEnabled = true
        if GUI.CustomCursor then GUI.CustomCursor.Visible = false end
    end)

    game:GetService("GuiService").MenuClosed:Connect(function()
        isRobloxMenuOpen = false
    end)

    if _G.S7xCursorLoop then _G.S7xCursorLoop:Disconnect() end
    _G.S7xCursorLoop = rs.RenderStepped:Connect(function()
        if isMobile or isRobloxMenuOpen then return end
        
        local mousePos = uis:GetMouseLocation()
        local inset = game:GetService("GuiService"):GetGuiInset()
        
        -- O SEGREDO: Se a preferência for Default, ele devolve o mouse pro Roblox e encerra a checagem
        if _G.S7xCurrentCursor == "Default" then
            if not uis.MouseIconEnabled then uis.MouseIconEnabled = true end
            if GUI.CustomCursor and GUI.CustomCursor.Visible then GUI.CustomCursor.Visible = false end
            cursorStateActive = false
            return
        end

        local overMain = isHovering(GUI.MainFrame, mousePos)
        local overBtn = isHovering(GUI.OpenBtn, mousePos)
        local overMini = isHovering(GUI.MiniMenu, mousePos)
        local overNotify = isHovering(GUI.NotifyContainer, mousePos)
        
        local shouldBeActive = (overMain or overBtn or overMini or overNotify)
        
        if shouldBeActive ~= cursorStateActive then
            cursorStateActive = shouldBeActive
            uis.MouseIconEnabled = not shouldBeActive
            if GUI.CustomCursor then GUI.CustomCursor.Visible = shouldBeActive end
        end
        
        if cursorStateActive and GUI.CustomCursor then
            GUI.CustomCursor.Position = UDim2.new(0, mousePos.X, 0, mousePos.Y - inset.Y)
        end
    end)

    -- [ 3. ANIMAÇÃO DE CLIQUE DO CURSOR (Pulinho Tátil) ]

    -- [ 3. ANIMAÇÃO DE CLIQUE DO CURSOR (Pulinho Tátil) ]
    uis.InputBegan:Connect(function(input, gp)
        if input.UserInputType == Enum.UserInputType.MouseButton1 and GUI.CustomCursor.Visible then
            pcall(function() ts:Create(cursorScale, TweenInfo.new(0.1, Enum.EasingStyle.Sine), {Scale = 0.8}):Play() end)
        end
    end)
    
    uis.InputEnded:Connect(function(input, gp)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            pcall(function() ts:Create(cursorScale, TweenInfo.new(0.25, Enum.EasingStyle.Bounce), {Scale = 1}):Play() end)
        end
    end)

    -- [ 4. MOTOR DE ÁUDIO ]
    local audioFolder = coreGui:FindFirstChild("S7x_AudioEngine") or Instance.new("Folder", coreGui)
    audioFolder.Name = "S7x_AudioEngine"

    local function createSFX(id, vol)
        local sfx = Instance.new("Sound", audioFolder)
        sfx.SoundId = "rbxassetid://" .. id
        sfx.Volume = vol
        return sfx
    end

    local hoverSFX = createSFX("6895079853", 0.2) 
    local clickSFX = createSFX("6895050519", 0.6) 
    local tabSFX = createSFX("6895082404", 0.8)   

    local function bindButtonEffects(btn)
        if not btn:IsA("GuiButton") then return end

        if not isMobile then
            btn.MouseEnter:Connect(function() pcall(function() hoverSFX:Play() end) end)
        end

        local uiScale = btn:FindFirstChild("S7x_ClickScale")
        if not uiScale then
            uiScale = Instance.new("UIScale")
            uiScale.Name = "S7x_ClickScale"
            uiScale.Parent = btn
        end

        local tDown = TweenInfo.new(0.1, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
        local tUp = TweenInfo.new(0.3, Enum.EasingStyle.Bounce, Enum.EasingDirection.Out)

        btn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                pcall(function() ts:Create(uiScale, tDown, {Scale = 0.92}):Play() end)
            end
        end)

        btn.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                pcall(function() ts:Create(uiScale, tUp, {Scale = 1}):Play() end)
            end
        end)

        btn.MouseLeave:Connect(function()
            pcall(function() ts:Create(uiScale, tUp, {Scale = 1}):Play() end)
        end)

        btn.MouseButton1Click:Connect(function()
            pcall(function()
                local isTabButton = btn.Parent and (btn.Parent.Name == "TabMenu" or btn.Parent.Name == "ScrollingFrame" and btn.Parent.Parent == GUI.MainFrame)
                if isTabButton then tabSFX:Play() else clickSFX:Play() end
            end)
        end)
    end

    -- Aplica os efeitos a todas as UIs geradas
    if GUI and GUI.ScreenGui then
        for _, element in ipairs(GUI.ScreenGui:GetDescendants()) do
            bindButtonEffects(element)
        end

        GUI.ScreenGui.DescendantAdded:Connect(function(element)
            bindButtonEffects(element)
        end)
    end
end)

