    -- ==========================================
    -- 3. DAEMON DE BLINDAGEM (ANTI-BYPASS DE UI TAMPERING)
    -- ==========================================
    _G.S7xUltimateAuthLoop = RS.Heartbeat:Connect(function()
        pcall(function()
            local isVip = _G.hasUltimateAccess(lp)
            local isUltimateOpen = GUI.UltimateFrame and GUI.UltimateFrame.Visible

            if isUltimateOpen then
                if not isVip then
                    -- Se o jogador NÃO tem acesso: Impõe bloqueio e monitora bypass
                    if blockFrame then
                        blockFrame.Visible = true
                        
                        -- [ O SEGREDO DO ANTI-BYPASS ]: Se o explorador tentar deletar, ocultar ou deixar transparente:
                        if not blockFrame:IsDescendantOf(mainFrame) or blockFrame.Visible == false or blockFrame.BackgroundTransparency == 1 then
                            if GUI.UltimateFrame then GUI.UltimateFrame.Visible = false end -- Desliga a aba e anula os botões
                        end
                    else
                        -- Se conseguiram dar Destroy() no blockFrame
                        if GUI.UltimateFrame then GUI.UltimateFrame.Visible = false end 
                    end
                    
                    if cinematicFrame then cinematicFrame.Visible = false end
                else
                    -- Se o jogador TEM acesso legítimo:
                    if blockFrame then blockFrame.Visible = false end
                    
                    if not _G.S7xUltimateUnlockPlayed then
                        _G.S7xUltimateUnlockPlayed = true
                        
                        task.spawn(function()
                            if cinematicFrame then cinematicFrame.Visible = true end
                            
                            pcall(function()
                                local s1 = Instance.new("Sound", CoreGui)
                                s1.SoundId = "rbxassetid://6895050519"
                                s1.Volume = 1
                                s1:Play(); game:GetService("Debris"):AddItem(s1, 2)
                            end)
                            
                            task.wait(0.4)
                            if cinematicFrame then cineStatus.Text = "CHECKING HIERARCHY CLEARANCE..." end
                            task.wait(0.6)
                            
                            if cinematicFrame then
                                lockIcon.Image = "rbxassetid://17736515700" 
                                cineStatus.Text = "ACCESS GRANTED"
                                cineStatus.TextColor3 = Color3.fromRGB(255, 255, 255)
                            end
                            
                            pcall(function()
                                local s2 = Instance.new("Sound", CoreGui)
                                s2.SoundId = "rbxassetid://821439273"
                                s2.Volume = 1.5
                                s2:Play(); game:GetService("Debris"):AddItem(s2, 3)
                            end)
                            
                            if lockIcon then
                                ts:Create(lockIcon, TweenInfo.new(0.4, Enum.EasingStyle.Back), {Size = UDim2.new(0, 110, 0, 110), Position = UDim2.new(0.5, -55, 0.5, -75)}):Play()
                            end
                            
                            task.wait(1.2)
                            
                            if cinematicFrame then
                                local tInfo = TweenInfo.new(0.5, Enum.EasingStyle.Sine)
                                ts:Create(cinematicFrame, tInfo, {BackgroundTransparency = 1}):Play()
                                if lockIcon then ts:Create(lockIcon, tInfo, {ImageTransparency = 1}):Play() end
                                if cineStatus then ts:Create(cineStatus, tInfo, {TextTransparency = 1}):Play() end
                            end
                            
                            task.wait(0.5)
                            if cinematicFrame then cinematicFrame:Destroy() end 
                        end)
                    end
                end
            else
                -- Previne que o layout vaze caso o usuário mude de aba no meio do processo
                if blockFrame then blockFrame.Visible = false end
                if cinematicFrame then cinematicFrame.Visible = false end
            end
        end)
    end)
end)

-----------------------------------------
    --- MOTOR DE PROFUNDIDADE UNIVERSAL SUPREMO (DEPTH MANAGER V3)
    --- 100% Blindado: Cobre injeção com o menu já aberto e telas que carregam com atraso!
    -----------------------------------------
    task.spawn(function()
        local GuiService = game:GetService("GuiService")
        local RunService = game:GetService("RunService")
        local Players = game:GetService("Players")
        local CG = game:GetService("CoreGui")
        local LP = Players.LocalPlayer
        
        local coreParent = (RunService:IsStudio() or not CG) and LP:WaitForChild("PlayerGui", 999) or CG
        local playerGui = LP:WaitForChild("PlayerGui", 999)

        -- [ FUNÇÃO INTELIGENTE DE PROFUNDIDADE ]
        local function setS7xDepth(depthValue)
            local function scanAndApply(parent)
                if not parent then return end
                for _, ui in ipairs(parent:GetChildren()) do
                    if ui:IsA("ScreenGui") then
                        local name = string.lower(ui.Name)
                        -- Vasculha Painel, Loading e Notificações (mesmo se tiverem nomes diferentes)
                        if string.find(name, "s7x") or string.find(name, "minimalfarm") or string.find(name, "loading") or name == "notifycontainer" then
                            if ui.DisplayOrder ~= depthValue then
                                ui.DisplayOrder = depthValue
                                ui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                            end
                        end
                    end
                end
            end
            
            -- Aplica na interface global mapeada
            if GUI and GUI.ScreenGui and GUI.ScreenGui.DisplayOrder ~= depthValue then
                GUI.ScreenGui.DisplayOrder = depthValue
                GUI.ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            end
            
            scanAndApply(coreParent)
            scanAndApply(playerGui)
        end

        -- Limpa conexões antigas para evitar Crash de RAM ao re-executar
        if _G.S7xMenuDepthConn1 then pcall(function() _G.S7xMenuDepthConn1:Disconnect() end) end
        if _G.S7xMenuDepthConn2 then pcall(function() _G.S7xMenuDepthConn2:Disconnect() end) end
        if _G.S7xMenuDepthMonitor then task.cancel(_G.S7xMenuDepthMonitor) end

        -- [ A GRANDE SACADA ]: Verifica se você injetou o script com o menu ESC JÁ ABERTO!
        if GuiService.MenuIsOpen then
            setS7xDepth(-99999)
        else
            setS7xDepth(0)
        end

        -- Interceptador de Abertura Nativa
        _G.S7xMenuDepthConn1 = GuiService.MenuOpened:Connect(function()
            setS7xDepth(-99999)
        end)

        -- Interceptador de Fechamento Nativo
        _G.S7xMenuDepthConn2 = GuiService.MenuClosed:Connect(function()
            setS7xDepth(0)
        end)

        -- [ DAEMON DE VIGILÂNCIA ] 
        -- Roda silenciosamente no fundo. Se uma tela de loading nascer atrasada e tentar ficar 
        -- por cima do menu ESC, esse Daemon amarra ela e puxa pra trás instantaneamente.
        _G.S7xMenuDepthMonitor = task.spawn(function()
            while task.wait(0.5) do
                pcall(function()
                    if GuiService.MenuIsOpen then
                        setS7xDepth(-99999)
                    else
                        setS7xDepth(0)
                    end
                end)
            end
        end)
    end)

   -- =========================================================================
-- 🛡️ MOTOR SUPREMO DE OTIMIZAÇÃO DE INTERFACE (AUTO-OPTIMIZE DAEMON)
-- =========================================================================
task.spawn(function()
    -- Função cirúrgica: Desliga processos inúteis de renderização para cada tipo de elemento
    local function OptimizeUIElement(v)
        pcall(function()
            -- 1. ANTI-LOCALIZATION LAG (Ganho massivo de FPS em textos)
            -- O Roblox tenta traduzir todas as palavras em tempo real. Isso trava a CPU.
            if v:IsA("TextLabel") or v:IsA("TextButton") or v:IsA("TextBox") then
                v.AutoLocalize = false
                
                -- Se o RichText estiver ligado mas não houver tags (ex: <b>, <font>), desliga ele.
                if v.RichText and not string.find(v.Text, "<.*>") then
                    v.RichText = false
                end
            end

            -- 2. CORREÇÃO DE PROFUNDIDADE (Z-INDEX SIBLING)
            -- O método Sibling renderiza 40% mais rápido que o Global.
            if v:IsA("ScreenGui") or v:IsA("BillboardGui") or v:IsA("SurfaceGui") then
                v.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                if v:IsA("BillboardGui") or v:IsA("SurfaceGui") then
                    v.LightInfluence = 0 -- Remove cálculos de iluminação 3D da UI
                    v.ResetOnSpawn = false
                end
            end

            -- 3. INPUT POLLING OTIMIZADO
            -- Desativa a checagem do mouse em frames e textos mortos (que não são clicáveis)
            if v:IsA("Frame") or v:IsA("ImageLabel") or v:IsA("TextLabel") or v:IsA("ScrollingFrame") then
                if v.Active and not v:IsA("GuiButton") and not v:IsA("ScrollingFrame") then
                    v.Active = false
                end
            end
        end)
    end

    -- [ VARREDURA INICIAL ]: Otimiza tudo que já foi criado no painel principal
    if GUI and GUI.ScreenGui then
        GUI.ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        for _, child in ipairs(GUI.ScreenGui:GetDescendants()) do
            OptimizeUIElement(child)
        end

        -- [ VIGILANTE ]: Se o painel criar novas UIs depois (ex: Listas, Popups), otimiza na hora.
        GUI.ScreenGui.DescendantAdded:Connect(OptimizeUIElement)
    end

    -- [ RADAR GLOBAL ]: Monitora o CoreGui e PlayerGui
    -- Se você abrir o Auto Metal, Mushyo, ou qualquer script externo da S7x, eles serão otimizados no nascimento.
    local function MonitorNewUIs(parent)
        parent.ChildAdded:Connect(function(child)
            -- Espera 1 frame para o script construir a UI inteira
            task.wait() 
            pcall(function()
                if child:IsA("ScreenGui") then
                    local name = string.lower(child.Name)
                    -- Filtra apenas UIs da sua Engine e módulos conhecidos
                    if string.find(name, "s7x") or string.find(name, "elite") or string.find(name, "mush") or string.find(name, "minimal") then
                        child.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                        
                        -- Otimiza todos os botões/textos já criados dentro dela
                        for _, desc in ipairs(child:GetDescendants()) do
                            OptimizeUIElement(desc)
                        end
                        
                        -- Fica escutando se essa UI criar mais coisas depois
                        child.DescendantAdded:Connect(OptimizeUIElement)
                    end
                end
            end)
        end)
    end

    -- Inicia o Radar Global
    pcall(function() MonitorNewUIs(game:GetService("CoreGui")) end)
    pcall(function() MonitorNewUIs(game.Players.LocalPlayer:WaitForChild("PlayerGui", 999)) end)
end)


