    }

    local myRank = "User"
    pcall(function() myRank = (type(GetFirebaseRank) == "function" and GetFirebaseRank(player)) or "User" end)
    local hasAccess = allowedRoles[myRank] or false

    do
        local BlockFrame = Instance.new("Frame", targetTab)
        BlockFrame.Size = UDim2.new(1, 0, 1, 0)
        BlockFrame.BackgroundColor3 = Color3.fromRGB(8, 8, 10)
        BlockFrame.ZIndex = 9999
        BlockFrame.Visible = not hasAccess
