        BlockText.TextColor3 = Color3.fromRGB(255, 50, 50)
        BlockText.Font = Enum.Font.GothamBlack
        BlockText.TextSize = 22
        BlockText.RichText = true
        BlockText.ZIndex = 10000
    end

    if not hasAccess then return end

    -- [ VARIÁVEIS DE ESTADO REAL-TIME ]
    local uidStr = tostring(player.UserId)
    local userCustomData = _G.CustomTagsConfig and _G.CustomTagsConfig[uidStr] or {}
    local currentCustomName = userCustomData.CustomName or ""
    local currentEffect = userCustomData.Effect or "Solid"
    local currentFont = userCustomData.Font or "GothamBlack"
    local cColor1 = userCustomData.Color1 or userCustomData.Color or "#FFFFFF"
    local cColor2 = userCustomData.Color2 or "#00E5FF"
    local cColor3 = userCustomData.Color3 or "#FF00FF"
    local cColor4 = userCustomData.Color4 or "#FFFF00"
    local cColor5 = userCustomData.Color5 or "#FF0000"
    local currentStroke = userCustomData.StrokeColor or "#000000"
    local cBgColorHex = userCustomData.BgColor or "#0C0C0F"
    local isBgRemoved = (userCustomData.BgTransparency == 1)
    local isBorderRemoved = (userCustomData.BorderEnabled == false)
    local isLineRemoved = (userCustomData.LineRemoved == true) -- NOVA VARIÁVEL
    local currentTextSize = tonumber(userCustomData.TextSize) or 15

    local function UpdateRealTimePreview()
        local displayTag = currentCustomName
        if displayTag == "" or string.match(displayTag, "^%s*$") then displayTag = myRank end
        if not _G.CustomTagsConfig then _G.CustomTagsConfig = {} end
        if not _G.CustomTagsConfig[uidStr] then _G.CustomTagsConfig[uidStr] = {} end
        
        local t = _G.CustomTagsConfig[uidStr]
        t.CustomName = displayTag; t.Effect = currentEffect; t.Font = currentFont
        t.Color1 = cColor1; t.Color2 = cColor2; t.Color3 = cColor3; t.Color4 = cColor4; t.Color5 = cColor5
        t.StrokeColor = currentStroke
        t.BgColor = cBgColorHex; t.BgTransparency = isBgRemoved and 1 or 0.25
        t.BorderEnabled = not isBorderRemoved; t.LineRemoved = isLineRemoved; t.TextSize = currentTextSize
        
        if displayTag ~= "" and type(_G.S7xUnlockCustomTagUI) == "function" then _G.S7xUnlockCustomTagUI() end
        if _G.EquippedTag == "Custom" then
            t.IsActive = true
            if type(ApplyOrUpdateTag) == "function" then ApplyOrUpdateTag(player) end
        end
    end

    -- [ 1. PROFILE E LIVE AVATAR ]
    do
        local ProfileCard = Instance.new("Frame", targetTab)
        ProfileCard.Size = UDim2.new(0.95, 0, 0, 80); ProfileCard.BackgroundColor3 = Color3.fromRGB(15, 15, 18); ProfileCard.LayoutOrder = 1
        Instance.new("UICorner", ProfileCard).CornerRadius = UDim.new(0, 8)
        local pStroke = Instance.new("UIStroke", ProfileCard)
        pStroke.Color = Color3.fromRGB(170, 0, 255); pStroke.Thickness = 1.5

        local Viewport = Instance.new("ViewportFrame", ProfileCard)
        Viewport.Size = UDim2.new(0, 60, 0, 60); Viewport.Position = UDim2.new(0, 15, 0.5, -30)
        Viewport.BackgroundColor3 = Color3.fromRGB(10, 10, 12); Viewport.Ambient = Color3.fromRGB(200, 200, 200); Viewport.LightColor = Color3.fromRGB(255, 255, 255)
        Instance.new("UICorner", Viewport).CornerRadius = UDim.new(1, 0); Instance.new("UIStroke", Viewport).Color = Color3.fromRGB(255, 255, 255)

        local WorldModel = Instance.new("WorldModel", Viewport)
        local Cam = Instance.new("Camera", Viewport); Viewport.CurrentCamera = Cam

        local function UpdateAnimatedAvatar()
            for _, v in ipairs(WorldModel:GetChildren()) do v:Destroy() end
            if player.Character then
                player.Character.Archivable = true
                local clone = player.Character:Clone()
                for _, v in ipairs(clone:GetDescendants()) do if v:IsA("Script") or v:IsA("LocalScript") then v:Destroy() end end
                clone.Parent = WorldModel
                clone:PivotTo(CFrame.new(0, 0, 0) * CFrame.Angles(0, math.pi, 0))
                local hrp = clone:FindFirstChild("Head") or clone.PrimaryPart
                if hrp then Cam.CFrame = CFrame.new(Vector3.new(0, 1.2, 4.5), Vector3.new(0, 1.2, 0)) end
                local hum = clone:FindFirstChild("Humanoid")
                if hum then
                    hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                    local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
                    local animate = player.Character:FindFirstChild("Animate")
                    if animate then
                        local idle = animate:FindFirstChild("idle")
                        local anim = idle and idle:FindFirstChildOfClass("Animation")
                        if anim then pcall(function() animator:LoadAnimation(anim):Play() end) end
                    end
                end
            end
        end
        UpdateAnimatedAvatar(); player.CharacterAdded:Connect(function() task.wait(1) UpdateAnimatedAvatar() end)

        local UserInfo = Instance.new("TextLabel", ProfileCard)
        UserInfo.Size = UDim2.new(1, -90, 1, 0); UserInfo.Position = UDim2.new(0, 85, 0, 0)
        UserInfo.BackgroundTransparency = 1; UserInfo.TextColor3 = Color3.fromRGB(255, 255, 255); UserInfo.Font = Enum.Font.GothamMedium; UserInfo.TextSize = 12
        UserInfo.TextXAlignment = Enum.TextXAlignment.Left; UserInfo.RichText = true
