            btn.UIStroke.Color = (currentEffect == eName) and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(45, 45, 55)
            btn.TextColor3 = (currentEffect == eName) and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(180, 180, 180)
