        eGridLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() EffectGridContainer.Size = UDim2.new(0.95, 0, 0, eGridLayout.AbsoluteContentSize.Y) end)

        local availableEffects = {"Solid", "Metallic", "Duo-chrome", "Rainbow", "Neon Pulse", "Cosmic", "Fire", "Gold Luxury"}
