            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6); Instance.new("UIStroke", btn).Color = Color3.fromRGB(45, 45, 55)
            btn.MouseButton1Click:Connect(function() currentEffect = eName; UpdateRealTimePreview(); refreshGridSelections() end)
            effectBtns[eName] = btn
        end
