    local ColorPickerModal, OpenColorPicker
    do
        ColorPickerModal = Instance.new("Frame", GUI.ScreenGui)
        ColorPickerModal.Size = UDim2.new(0, 260, 0, 280); ColorPickerModal.Position = UDim2.new(0.5, -130, 0.5, -140); ColorPickerModal.BackgroundColor3 = Color3.fromRGB(20, 20, 25); ColorPickerModal.Visible = false; ColorPickerModal.Active = true; ColorPickerModal.Draggable = true; ColorPickerModal.ZIndex = 1000
        Instance.new("UICorner", ColorPickerModal).CornerRadius = UDim.new(0, 8); Instance.new("UIStroke", ColorPickerModal).Color = Color3.fromRGB(100, 100, 110)

        local SVMap = Instance.new("ImageButton", ColorPickerModal)
