                Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6); Instance.new("UIStroke", row).Color = Color3.fromRGB(45, 45, 55)
                
                local nameLbl = Instance.new("TextLabel", row)
                nameLbl.Size = UDim2.new(0.6, 0, 1, 0); nameLbl.Position = UDim2.new(0, 15, 0, 0); nameLbl.BackgroundTransparency = 1; nameLbl.Font = Enum.Font.GothamBlack; nameLbl.TextSize = 13; nameLbl.TextXAlignment = Enum.TextXAlignment.Left; nameLbl.Text = string.upper(entry.Name)
                
                local cMain = _G.S7xParseColor(entry.Color1, Color3.fromRGB(255,255,255))
                local cStroke = _G.S7xParseColor(entry.Stroke, Color3.fromRGB(0,0,0))
                nameLbl.TextColor3 = cMain; nameLbl.TextStrokeColor3 = cStroke; nameLbl.TextStrokeTransparency = 0
                
                local restoreBtn = Instance.new("TextButton", row)
                restoreBtn.Size = UDim2.new(0, 80, 0, 26); restoreBtn.Position = UDim2.new(1, -90, 0.5, -13); restoreBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 30); restoreBtn.TextColor3 = Color3.fromRGB(255, 255, 255); restoreBtn.Font = Enum.Font.GothamBold; restoreBtn.TextSize = 10; restoreBtn.Text = "RESTORE"; restoreBtn.AutoButtonColor = false
                Instance.new("UICorner", restoreBtn).CornerRadius = UDim.new(0, 4); local rStrk = Instance.new("UIStroke", restoreBtn); rStrk.Color = Color3.fromRGB(60, 60, 70)
                restoreBtn.MouseEnter:Connect(function() pcall(function() ts:Create(restoreBtn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(170, 0, 255)}):Play(); ts:Create(rStrk, TweenInfo.new(0.2), {Color = Color3.fromRGB(255, 255, 255)}):Play() end) end)
                restoreBtn.MouseLeave:Connect(function() pcall(function() ts:Create(restoreBtn, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(25, 25, 30)}):Play(); ts:Create(rStrk, TweenInfo.new(0.2), {Color = Color3.fromRGB(60, 60, 70)}):Play() end) end)
                
                restoreBtn.MouseButton1Click:Connect(function()
                    NameInput.Text = entry.Name; currentEffect = entry.Effect or "Solid"; currentFont = entry.Font or "GothamBlack"
                    cColor1 = entry.Color1 or "#FFFFFF"; cColor2 = entry.Color2 or "#00E5FF"; cColor3 = entry.Color3 or "#FF00FF"; cColor4 = entry.Color4 or "#FFFF00"; cColor5 = entry.Color5 or "#FF0000"; currentStroke = entry.Stroke or "#000000"
                    
                    -- RESTORE COMPLETO DE VARIÁVEIS
                    cBgColorHex = entry.BgColor or "#0C0C0F"
                    isBgRemoved = entry.BgRemoved or false
                    isBorderRemoved = entry.BorderRemoved or false
                    isLineRemoved = entry.LineRemoved or false 
                    currentTextSize = entry.TextSize or 15
                    
                    refreshGridSelections(); UpdateRealTimePreview()
                    if type(S7xNotify) == "function" then S7xNotify("TAG RESTORED", "Configurações restauradas.") end
                end)
            end
            HistoryList.CanvasSize = UDim2.new(0, 0, 0, #tagHistory * 50)
        end
        RenderHistoryUI()

        SaveBtn.MouseButton1Click:Connect(function()
            SaveBtn.Text = "SAVING..."
            UpdateRealTimePreview()

            local newEntry = {
                Name = currentCustomName, Effect = currentEffect, Font = currentFont,
                Color1 = cColor1, Color2 = cColor2, Color3 = cColor3, Color4 = cColor4, Color5 = cColor5, Stroke = currentStroke,
                BgColor = cBgColorHex, BgRemoved = isBgRemoved, BorderRemoved = isBorderRemoved, LineRemoved = isLineRemoved, TextSize = currentTextSize
            }
            if #tagHistory == 0 or (tagHistory[1].Name ~= newEntry.Name or tagHistory[1].Effect ~= newEntry.Effect or tagHistory[1].Color1 ~= newEntry.Color1) then
                table.insert(tagHistory, 1, newEntry); if #tagHistory > 10 then table.remove(tagHistory, 11) end
                saveTagHistory(); RenderHistoryUI()
            end

            task.spawn(function()
                pcall(function()
                    local payload = _G.CustomTagsConfig[uidStr]
                    _G.SupabaseReq("/tags?on_conflict=id", "POST", { id = uidStr, payload = payload })
                end)
            end)
            task.wait(0.5); SaveBtn.Text = "SUCCESS!"; SaveBtn.BackgroundColor3 = Color3.fromRGB(0, 255, 100); SaveBtn.TextColor3 = Color3.fromRGB(0, 0, 0); task.wait(1.5); SaveBtn.Text = "SAVE TO CLOUD"; SaveBtn.BackgroundColor3 = Color3.fromRGB(140, 0, 255); SaveBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        end)
    end

    layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        targetTab.CanvasSize = UDim2.new(0, 0, 0, layout.AbsoluteContentSize.Y + 40)
    end)
end)


-- =========================================================================
-- 🛑 S7X ENGINE: OTIMIZAÇÃO DE MEMÓRIA E FECHAMENTO (MOBILE / IOS SAFE) 🛑
-- =========================================================================
task.spawn(function()
    local Stats = game:GetService("Stats")
    local RunService = game:GetService("RunService")
    
    -- Limpeza inicial controlada (Step longo em vez de Collect absoluto)
    for i = 1, 5 do 
        collectgarbage("step", 500) 
        RunService.RenderStepped:Wait() 
    end
    
    -- Daemon Otimizador de Memória Adaptativo
    -- Só força a limpeza se o Roblox ultrapassar 1GB de RAM (evita limpar o que não precisa)
    if _G.S7xMobileOptimizer then pcall(function() task.cancel(_G.S7xMobileOptimizer) end) end
    
    _G.S7xMobileOptimizer = task.spawn(function()
        while task.wait(5) do
            pcall(function()
                local memUsage = Stats:GetTotalMemoryUsageMb()
                if memUsage > 1000 then
                    -- Limpeza proporcional à emergência de memória
                    collectgarbage("step", 300)
                elseif memUsage > 600 then
                    collectgarbage("step", 100)
                end
            end)
        end
    end)

    print("\n=========================================")
    print("🚀 S7X ENGINE SUPREME -> CARREGADO")
    print("🛡️ ADAPTATIVE MEMORY SHIELD -> ATIVADO")
    print("=========================================\n")
    
    if type(S7xNotify) == "function" then
        S7xNotify("S7X ENGINE ONLINE", "Garbage Collector Dinâmico ativado. Loadstring concluído sem congelamento.", 6)
    end
end)
end)
